// 자동 생성 파일 - 영어단어장.csv에서 변환됨. 직접 수정하지 마세요.
// 재생성: python convert_csv.py
const WORDS = [{"id":1,"word":"overlook","ipa":"/ˌoʊvərˈlʊk/","meaning":"간과하다 <중요성을 파악하지 못하거나, 큰 관심 없이 대충 보아 넘기다>","example":"It's easy to overlook small errors when you're rushing.","deck":"vocab"},{"id":2,"word":"ungodly","ipa":"/ʌnˈɡɑdli/","meaning":"과도한, 터무니없는, 엄청난 <명사 앞에만 씀>","example":"She called me at an ungodly hour of the morning.","deck":"vocab"},{"id":3,"word":"let ~ out","ipa":"","meaning":"(울음소리, 신음소리 등을) 내다","example":"She let out a scream when she saw the spider.","deck":"vocab"},{"id":4,"word":"hack","ipa":"/hæk/","meaning":"(마구, 거칠게) ~을 자르다, 베다, 난도질하다","example":"He hacked the branches off the tree with a machete.","deck":"vocab"},{"id":5,"word":"hack","ipa":"/hæk/","meaning":"비법","example":"This kitchen hack saves me ten minutes every morning.","deck":"vocab"},{"id":6,"word":"rhinoceros","ipa":"/raɪˈnɑsərəs/","meaning":"코뿔소","example":"A rhinoceros charged across the dusty African plain.","deck":"vocab"},{"id":7,"word":"abduction","ipa":"/æbˈdʌkʃən/","meaning":"유괴","example":"The police investigated the child's abduction for months.","deck":"vocab"},{"id":8,"word":"perspiration","ipa":"/ˌpɜrspəˈreɪʃən/","meaning":"땀","example":"Perspiration dripped down his face during the workout.","deck":"vocab"},{"id":9,"word":"wreck","ipa":"/rɛk/","meaning":"(육체적, 정신적으로) 망가진 사람, 만신창이","example":"After the exams, I was a complete nervous wreck.","deck":"vocab"},{"id":10,"word":"wreck","ipa":"/rɛk/","meaning":"난파시키다","example":"The storm wrecked several boats along the coast.","deck":"vocab"},{"id":11,"word":"revolting","ipa":"/rɪˈvoʊltɪŋ/","meaning":"혐오스러운, 역겨운","example":"The smell coming from the fridge was absolutely revolting.","deck":"vocab"},{"id":12,"word":"indifference","ipa":"/ɪnˈdɪfərəns/","meaning":"(~에 대한) 무관심, 무심","example":"Her indifference to the news surprised everyone in the room.","deck":"vocab"},{"id":13,"word":"immersion","ipa":"/ɪˈmɜrʒən/","meaning":"몰입 교육 <교육학 용어. 모국어를 배제하고 학습 중인 언어로만 수업하는 방식>","example":"Language immersion helped her become fluent in just one year.","deck":"vocab"},{"id":14,"word":"could have sworn","ipa":"","meaning":"분명히 ~ 했었던 것 같은데, 확실히 ~ 했었는데 <사실은 그렇지 않을 때>","example":"I could have sworn I locked the door before leaving.","deck":"vocab"},{"id":15,"word":"be going to ~","ipa":"","meaning":"~해라, ~해야 하다 <명령할 때 쓰는 표현>","example":"You are going to apologize to your sister right now.","deck":"vocab"},{"id":16,"word":"timid","ipa":"/ˈtɪmɪd/","meaning":"소심한, 용기가 없는, 자신감이 없는","example":"The timid puppy hid behind the couch when guests arrived.","deck":"vocab"},{"id":17,"word":"rip","ipa":"/rɪp/","meaning":"(빠르고 거칠게) 뜯어내다, 떼어 내다","example":"He ripped the wrapping paper off the gift eagerly.","deck":"vocab"},{"id":18,"word":"rip","ipa":"/rɪp/","meaning":"(갑자기, 거칠게) 찢다","example":"She ripped the letter in half without reading it.","deck":"vocab"},{"id":19,"word":"sarcastic","ipa":"/sɑrˈkæstɪk/","meaning":"빈정대는, 비꼬는","example":"His sarcastic comment made everyone at the table laugh.","deck":"vocab"},{"id":20,"word":"intimidated","ipa":"/ɪnˈtɪmɪˌdeɪtɪd/","meaning":"겁먹은, 겁을 내는, 위축된, 주눅 든 <주로 서술적 용법으로 씀>","example":"She felt intimidated by the size of the crowd.","deck":"vocab"},{"id":21,"word":"candidly","ipa":"/ˈkændɪdli/","meaning":"솔직히, 숨김없이","example":"He spoke candidly about his struggles with anxiety.","deck":"vocab"},{"id":22,"word":"flee","ipa":"/fli/","meaning":"달아나다, 도망치다 <자동사>","example":"The villagers had to flee from the approaching wildfire.","deck":"vocab"},{"id":23,"word":"prehistoric","ipa":"/ˌprihɪˈstɔrɪk/","meaning":"선사 시대의","example":"Archaeologists discovered prehistoric tools inside the cave.","deck":"vocab"},{"id":24,"word":"collective intelligence","ipa":"/kəˌlɛktɪv ɪnˈtɛlɪdʒəns/","meaning":"집단 지성","example":"Wikipedia is a great example of collective intelligence at work.","deck":"vocab"},{"id":25,"word":"impede","ipa":"/ɪmˈpid/","meaning":"(진행을) 방해하다, 지연시키다","example":"Heavy snow impeded the rescue team's progress up the mountain.","deck":"vocab"},{"id":26,"word":"pertinent","ipa":"/ˈpɜrtɪnənt/","meaning":"(~와) 직접적인 관련이 있는, 적절히 관련된 <격식>","example":"Please include only pertinent information in your report.","deck":"vocab"},{"id":27,"word":"assailant","ipa":"/əˈseɪlənt/","meaning":"(특히 신체적) 공격을 가한 사람, 폭행범 <격식>","example":"The victim could not identify her assailant in the dark.","deck":"vocab"},{"id":28,"word":"meteor","ipa":"/ˈmitiər/","meaning":"유성, 별똥별","example":"We watched a bright meteor streak across the night sky.","deck":"vocab"},{"id":29,"word":"glimpse","ipa":"/ɡlɪmps/","meaning":"힐끗 보다, 언뜻 보다","example":"I only glimpsed her face before she disappeared into the crowd.","deck":"vocab"},{"id":30,"word":"advent","ipa":"/ˈædvɛnt/","meaning":"도래, 출현","example":"The advent of smartphones changed how we communicate forever.","deck":"vocab"},{"id":31,"word":"eradicate","ipa":"/ɪˈrædɪˌkeɪt/","meaning":"근절하다, 뿌리뽑다","example":"Scientists hope to eradicate malaria within a few decades.","deck":"vocab"},{"id":32,"word":"sacred","ipa":"/ˈseɪkrɪd/","meaning":"신성시되는, 신성불가침의","example":"In their culture, hospitality is considered a sacred duty.","deck":"vocab"},{"id":33,"word":"sacred","ipa":"/ˈseɪkrɪd/","meaning":"성스러운, 신성한","example":"The temple is a sacred site for millions of pilgrims.","deck":"vocab"},{"id":34,"word":"only","ipa":"/ˈoʊnli/","meaning":"(시간, 상황이) ~가 되어서야","example":"It was only after midnight that he finally came home.","deck":"vocab"},{"id":35,"word":"giggle","ipa":"/ˈɡɪɡəl/","meaning":"피식 웃음, 킥킥거림, 낄낄거림","example":"The children broke into a giggle during the quiet ceremony.","deck":"vocab"},{"id":36,"word":"laxative","ipa":"/ˈlæksətɪv/","meaning":"완하제 <배변을 쉽게 하는 약, 음식, 음료>","example":"The doctor prescribed a mild laxative for her constipation.","deck":"vocab"},{"id":37,"word":"reed","ipa":"/rid/","meaning":"갈대","example":"Tall reeds swayed gently along the edge of the pond.","deck":"vocab"},{"id":38,"word":"trespass","ipa":"/ˈtrɛspəs/","meaning":"(~을) 위반하다, 어기다, 죄를 범하다 <고어>","example":"Forgive us as we forgive those who trespass against us.","deck":"vocab"},{"id":39,"word":"trespass","ipa":"/ˈtrɛspəs/","meaning":"(~에) 무단 침입하다","example":"The hikers were fined for trespassing on private property.","deck":"vocab"},{"id":40,"word":"stick","ipa":"/stɪk/","meaning":"(보통 뾰족한 것을) 찌르다, 박다","example":"The nurse stuck the needle gently into my arm.","deck":"vocab"},{"id":41,"word":"ditch","ipa":"/dɪtʃ/","meaning":"버리다, 포기하다","example":"They decided to ditch the plan and start over completely.","deck":"vocab"},{"id":42,"word":"ditch","ipa":"/dɪtʃ/","meaning":"(사람을) 따돌리다 <같이 놀기로 해 놓고 일방적으로 약속을 어기고 가버리다>","example":"He ditched his friends to hang out with someone cooler.","deck":"vocab"},{"id":43,"word":"take each day as it comes","ipa":"","meaning":"(미래를 걱정하지 않고) 그날그날을 충실히 살다","example":"Since the diagnosis, she just tries to take each day as it comes.","deck":"vocab"},{"id":44,"word":"garnish","ipa":"/ˈɡɑrnɪʃ/","meaning":"(요리에) 고명을 얹다","example":"The chef garnished the plate with a sprig of parsley.","deck":"vocab"},{"id":45,"word":"in retrospect","ipa":"","meaning":"돌이켜 생각해 보면 <과거의 생각이 잘못된 것이었다는 것을 깨달았을 때>","example":"In retrospect, I should have accepted that job offer.","deck":"vocab"},{"id":46,"word":"speech recognition","ipa":"/ˌspitʃ ˌrɛkəɡˈnɪʃən/","meaning":"음성 인식 <무엇을 말하는지 컴퓨터로 인식하는 기술>","example":"Speech recognition software now transcribes meetings almost perfectly.","deck":"vocab"},{"id":47,"word":"nausea","ipa":"/ˈnɔziə/","meaning":"욕지기, 메스꺼움","example":"A wave of nausea hit her as the boat rocked.","deck":"vocab"},{"id":48,"word":"spook out","ipa":"","meaning":"놀라게 하다","example":"The abandoned hospital spooked us out completely.","deck":"vocab"},{"id":49,"word":"frustration","ipa":"/frʌsˈtreɪʃən/","meaning":"짜증, 분노, 좌절감, 불만 <원하는 걸 할 수 없을 때 드는 불쾌한 감정>","example":"He slammed the door in frustration after the argument.","deck":"vocab"},{"id":50,"word":"beloved","ipa":"/bɪˈlʌvɪd/","meaning":"(대단히) 사랑하는, 사랑받는 <명사 앞에만 씀. 격식 있는 표현>","example":"She dedicated the book to her beloved grandmother.","deck":"vocab"},{"id":51,"word":"crush","ipa":"/krʌʃ/","meaning":"눌러 부수다, 으스러뜨리다, 짜부라뜨리다","example":"He crushed the empty can with one hand.","deck":"vocab"},{"id":52,"word":"crush","ipa":"/krʌʃ/","meaning":"반한 상대, 푹 빠져있는 대상","example":"She's had a crush on him since high school.","deck":"vocab"},{"id":53,"word":"accuse","ipa":"/əˈkjuz/","meaning":"비난하다","example":"They accused him of stealing money from the register.","deck":"vocab"},{"id":54,"word":"homophobic","ipa":"/ˌhoʊməˈfoʊbɪk/","meaning":"동성애 공포증의, 동성애 혐오의","example":"The comedian was criticized for his homophobic remarks.","deck":"vocab"},{"id":55,"word":"peer pressure","ipa":"/ˈpɪr ˌprɛʃər/","meaning":"동료 집단으로부터 받는 사회적 압력","example":"Many teenagers start smoking because of peer pressure.","deck":"vocab"},{"id":56,"word":"verdict","ipa":"/ˈvɜrdɪkt/","meaning":"(배심원단의) 평결","example":"The jury reached a guilty verdict after three days.","deck":"vocab"},{"id":57,"word":"bland","ipa":"/blænd/","meaning":"특징 없는, 단조로운","example":"The movie was bland and forgettable from start to finish.","deck":"vocab"},{"id":58,"word":"bland","ipa":"/blænd/","meaning":"(맛이) 싱거운","example":"The soup tasted bland, so I added more salt.","deck":"vocab"},{"id":59,"word":"screw","ipa":"/skru/","meaning":"~를 속이다, ~에게 바가지를 씌우다 <속어>","example":"That mechanic totally screwed me on the repair bill.","deck":"vocab"},{"id":60,"word":"screw","ipa":"/skru/","meaning":"나사로 고정시키다","example":"He screwed the shelf firmly onto the wall.","deck":"vocab"},{"id":61,"word":"sinister","ipa":"/ˈsɪnɪstər/","meaning":"사악한","example":"There was something sinister about his quiet smile.","deck":"vocab"},{"id":62,"word":"dangle ~ in front of ~","ipa":"","meaning":"~에게 ~을 제시하다, ~를 ~으로 유혹하다","example":"They dangled a huge bonus in front of the employees.","deck":"vocab"},{"id":63,"word":"sluggish","ipa":"/ˈslʌɡɪʃ/","meaning":"굼뜬, 느릿느릿 움직이는, 부진한","example":"I always feel sluggish after eating a big lunch.","deck":"vocab"},{"id":64,"word":"open fire","ipa":"","meaning":"공격을 시작하다, 총격을 시작하다","example":"The soldiers opened fire as soon as the enemy appeared.","deck":"vocab"},{"id":65,"word":"presumably","ipa":"/prɪˈzuməbli/","meaning":"아마, 짐작건대","example":"He's not answering, so he's presumably still asleep.","deck":"vocab"},{"id":66,"word":"texture","ipa":"/ˈtɛkstʃər/","meaning":"(물체를 손으로 만졌을 때 느껴지는) 감촉, 질감","example":"I love the soft texture of this cashmere sweater.","deck":"vocab"},{"id":67,"word":"texture","ipa":"/ˈtɛkstʃər/","meaning":"(음식이 입 안에서 느껴지는) 식감, 질감","example":"The cake had a light, fluffy texture that melted instantly.","deck":"vocab"},{"id":68,"word":"mucus","ipa":"/ˈmjukəs/","meaning":"(코 등에서 나오는) 점액","example":"A cold usually produces a lot of mucus in your nose.","deck":"vocab"},{"id":69,"word":"indigenous","ipa":"/ɪnˈdɪdʒənəs/","meaning":"원산의, 토착의","example":"Kangaroos are indigenous to the continent of Australia.","deck":"vocab"},{"id":70,"word":"suffocate","ipa":"/ˈsʌfəˌkeɪt/","meaning":"질식시키다, 질식시켜 죽이다","example":"The thick smoke nearly suffocated the trapped residents.","deck":"vocab"},{"id":71,"word":"untangle","ipa":"/ʌnˈtæŋɡəl/","meaning":"(엉킨 것을) 풀다","example":"It took ages to untangle the knotted headphone wires.","deck":"vocab"},{"id":72,"word":"ingenious","ipa":"/ɪnˈdʒinjəs/","meaning":"매우 독창적인, 기발한","example":"She came up with an ingenious solution to the problem.","deck":"vocab"},{"id":73,"word":"unprecedented","ipa":"/ʌnˈprɛsɪˌdɛntɪd/","meaning":"전례 없는, 미증유의","example":"The pandemic caused unprecedented disruption to global travel.","deck":"vocab"},{"id":74,"word":"carbohydrate","ipa":"/ˌkɑrboʊˈhaɪdreɪt/","meaning":"탄수화물, 탄수화물 식품","example":"Bread and pasta are rich in carbohydrates.","deck":"vocab"},{"id":75,"word":"nurture","ipa":"/ˈnɜrtʃər/","meaning":"(희망, 야망, 믿음 등을 마음속으로) 키우다","example":"She nurtured a secret dream of becoming a painter.","deck":"vocab"},{"id":76,"word":"nurture","ipa":"/ˈnɜrtʃər/","meaning":"(화초나 풀밭 등을) 가꾸다, 보살피다","example":"He carefully nurtured the young seedlings in his garden.","deck":"vocab"},{"id":77,"word":"nurture","ipa":"/ˈnɜrtʃər/","meaning":"양육, 육성, 양성","example":"The debate over nature versus nurture continues today.","deck":"vocab"},{"id":78,"word":"pediatrician","ipa":"/ˌpidiəˈtrɪʃən/","meaning":"소아과 의사","example":"We took our newborn to the pediatrician for a checkup.","deck":"vocab"},{"id":79,"word":"coherent","ipa":"/koʊˈhɪrənt/","meaning":"일관성 있는, 논리 정연한, 조리 있는","example":"The essay lacked a coherent argument from beginning to end.","deck":"vocab"},{"id":80,"word":"coherent","ipa":"/koʊˈhɪrənt/","meaning":"(사람이) 조리 있게 말하는","example":"He was too drunk to give a coherent answer.","deck":"vocab"},{"id":81,"word":"wasted","ipa":"/ˈweɪstɪd/","meaning":"(술 또는 마약에) 엄청나게 취한 <엄청나게 취해 제정신이 아닌 상태>","example":"He got completely wasted at the party last night.","deck":"vocab"},{"id":82,"word":"stork","ipa":"/stɔrk/","meaning":"황새","example":"A stork built its nest on top of the chimney.","deck":"vocab"},{"id":83,"word":"destitute","ipa":"/ˈdɛstɪˌtut/","meaning":"극빈한, 궁핍한","example":"The war left thousands of families completely destitute.","deck":"vocab"},{"id":84,"word":"avenue","ipa":"/ˈævəˌnu/","meaning":"(목적을 이룰) 길, 방안, 수단","example":"We explored every avenue before deciding to sell the house.","deck":"vocab"},{"id":85,"word":"spur","ipa":"/spɜr/","meaning":"(말에) ~에 박차를 가하다","example":"The rider spurred his horse into a full gallop.","deck":"vocab"},{"id":86,"word":"avocation","ipa":"/ˌævoʊˈkeɪʃən/","meaning":"취미","example":"Painting is his avocation, though he works as an accountant.","deck":"vocab"},{"id":87,"word":"punctuation","ipa":"/ˌpʌŋktʃuˈeɪʃən/","meaning":"구두점 사용, 구두법","example":"Correct punctuation makes your writing much easier to read.","deck":"vocab"},{"id":88,"word":"flashback","ipa":"/ˈflæʃˌbæk/","meaning":"(영화, 연극 등에서) 회상 장면","example":"The film uses a flashback to reveal the hero's childhood.","deck":"vocab"},{"id":89,"word":"birth defect","ipa":"/ˈbɜrθ dɪˌfɛkt/","meaning":"선천적 장애, 선천적 결손증","example":"Doctors detected the birth defect during a routine ultrasound.","deck":"vocab"},{"id":90,"word":"cornstarch","ipa":"/ˈkɔrnˌstɑrtʃ/","meaning":"옥수수 전분, 옥수수 녹말","example":"Add a little cornstarch to thicken the sauce.","deck":"vocab"},{"id":91,"word":"make-up game","ipa":"/ˈmeɪkʌp ˌɡeɪm/","meaning":"재경기 <스포츠에서 악천후 등의 사정으로 연기되어 재편성된 경기>","example":"The rained-out match was rescheduled as a make-up game on Tuesday.","deck":"vocab"},{"id":92,"word":"mitten","ipa":"/ˈmɪtən/","meaning":"벙어리장갑, 손모아장갑","example":"She knitted a pair of woolen mittens for her son.","deck":"vocab"},{"id":93,"word":"autocomplete","ipa":"/ˈɔtoʊkəmˌplit/","meaning":"자동 완성 기능","example":"The autocomplete feature guessed my email address instantly.","deck":"vocab"},{"id":94,"word":"On your mark!","ipa":"","meaning":"(경주에서) 제자리에!","example":"On your mark, get set, go!","deck":"vocab"},{"id":95,"word":"dime","ipa":"/daɪm/","meaning":"땡전 한 푼 <부정문에 씀>","example":"I won't pay a single dime for such terrible service.","deck":"vocab"},{"id":96,"word":"bridal","ipa":"/ˈbraɪdəl/","meaning":"신부의, 결혼식의","example":"She looked stunning in her elegant white bridal gown.","deck":"vocab"},{"id":97,"word":"dwindle","ipa":"/ˈdwɪndəl/","meaning":"(점점) 줄어들다","example":"Their savings slowly dwindled during the long recession.","deck":"vocab"},{"id":98,"word":"lead","ipa":"/lid/","meaning":"(특정한 방식의 삶을) 살다, 영위하다","example":"After retiring, they lead a quiet life in the countryside.","deck":"vocab"},{"id":99,"word":"lead","ipa":"/lid/","meaning":"실마리, 단서","example":"Detectives followed every lead in the murder case.","deck":"vocab"},{"id":100,"word":"shatter","ipa":"/ˈʃætər/","meaning":"산산이 부수다, 산산조각 내다","example":"The glass vase shattered into a thousand pieces on the floor.","deck":"vocab"},{"id":101,"word":"faucet","ipa":"/ˈfɔsɪt/","meaning":"수도꼭지","example":"Please turn off the faucet so water doesn't waste.","deck":"vocab"},{"id":102,"word":"concession","ipa":"/kənˈsɛʃən/","meaning":"양보, 양해","example":"Neither side was willing to make any concession during talks.","deck":"vocab"},{"id":103,"word":"warmth","ipa":"/wɔrmθ/","meaning":"온기","example":"We gathered near the fire for its comforting warmth.","deck":"vocab"},{"id":104,"word":"autocratic","ipa":"/ˌɔtəˈkrætɪk/","meaning":"독재의, 독재적인","example":"The manager's autocratic style discouraged any team input.","deck":"vocab"},{"id":105,"word":"viable","ipa":"/ˈvaɪəbəl/","meaning":"(생물이) 생존 가능한","example":"The premature baby was born barely viable but survived.","deck":"vocab"},{"id":106,"word":"viable","ipa":"/ˈvaɪəbəl/","meaning":"실행 가능한","example":"Solar power is now a viable alternative to fossil fuels.","deck":"vocab"},{"id":107,"word":"wane","ipa":"/weɪn/","meaning":"약해지다, 줄어들다, 시들해지다","example":"Public interest in the show began to wane after season three.","deck":"vocab"},{"id":108,"word":"crotch","ipa":"/krɑtʃ/","meaning":"가랑이, 사타구니","example":"The jeans ripped right at the crotch when he bent down.","deck":"vocab"},{"id":109,"word":"fungus","ipa":"/ˈfʌŋɡəs/","meaning":"균류, 곰팡이류","example":"A strange fungus was growing on the damp bathroom wall.","deck":"vocab"},{"id":110,"word":"felony","ipa":"/ˈfɛləni/","meaning":"중죄, 중범죄, 흉악 범죄","example":"He was convicted of a felony and sentenced to prison.","deck":"vocab"},{"id":111,"word":"puke","ipa":"/pjuk/","meaning":"토하다","example":"The sick child puked all over the kitchen floor.","deck":"vocab"},{"id":112,"word":"from time to time","ipa":"","meaning":"가끔, 이따금","example":"We still meet for coffee from time to time.","deck":"vocab"},{"id":113,"word":"substantial","ipa":"/səbˈstænʃəl/","meaning":"(양, 가치, 중요성이) 상당한","example":"The company reported a substantial profit this quarter.","deck":"vocab"},{"id":114,"word":"goopy","ipa":"/ˈɡupi/","meaning":"끈적거리는, 끈적끈적한 <속어>","example":"The kids covered their hands in goopy slime.","deck":"vocab"},{"id":115,"word":"desperate","ipa":"/ˈdɛspərɪt/","meaning":"~을 간절히 필요로 하는, 간절히 원하는","example":"After the long hike, we were desperate for water.","deck":"vocab"},{"id":116,"word":"desperate","ipa":"/ˈdɛspərɪt/","meaning":"절박한, 절실한","example":"He made a desperate attempt to save the drowning dog.","deck":"vocab"},{"id":117,"word":"setting","ipa":"/ˈsɛtɪŋ/","meaning":"(연극, 소설 등의) 배경","example":"The novel's setting is a small town in the 1950s.","deck":"vocab"},{"id":118,"word":"what ~ like","ipa":"","meaning":"(상태, 형편, 사람이) 어떠한가","example":"What is your new apartment like?","deck":"vocab"},{"id":119,"word":"sensational","ipa":"/sɛnˈseɪʃənəl/","meaning":"세상을 놀라게 할 만한, 선풍적인, 돌풍을 일으키는 <엄청난 관심을 끄는>","example":"The young singer made a sensational debut on national television.","deck":"vocab"},{"id":120,"word":"rehash","ipa":"/ˈriˌhæʃ/","meaning":"재탕하다 <많이 바꾸거나 개선하지 않고 그대로 재사용하다>","example":"The sequel just rehashed the same tired jokes.","deck":"vocab"},{"id":121,"word":"disorient","ipa":"/dɪsˈɔriɛnt/","meaning":"~의 방향 감각을 잃게 하다","example":"The thick fog disoriented the hikers completely.","deck":"vocab"},{"id":122,"word":"GPA","ipa":"/ˌdʒi pi ˈeɪ/","meaning":"평균 평점 <각 과목의 성적 평점을 평균한 것. grade point average>","example":"She maintained a perfect GPA throughout college.","deck":"vocab"},{"id":123,"word":"cap and trade","ipa":"","meaning":"탄소배출권 거래제","example":"The government introduced a cap and trade system to cut emissions.","deck":"vocab"},{"id":124,"word":"fix-up","ipa":"/ˈfɪksˌʌp/","meaning":"소개팅, 맞선","example":"My friend arranged a fix-up with her coworker.","deck":"vocab"},{"id":125,"word":"palpable","ipa":"/ˈpælpəbəl/","meaning":"뚜렷한, 감지할 수 있는, 손에 만져질 듯한","example":"The tension in the courtroom was almost palpable.","deck":"vocab"},{"id":126,"word":"whichever","ipa":"/wɪˈtʃɛvər/","meaning":"어느 것이든, 어느 것을 ~하든","example":"Choose whichever dessert you like best.","deck":"vocab"},{"id":127,"word":"just in case","ipa":"","meaning":"만약을 대비해서, 혹시 모르니까","example":"Bring an umbrella just in case it rains later.","deck":"vocab"},{"id":128,"word":"overall","ipa":"/ˌoʊvərˈɔl/","meaning":"대체로, 전반적으로","example":"Overall, the trip was a wonderful experience.","deck":"vocab"},{"id":129,"word":"dirt","ipa":"/dɜrt/","meaning":"좋지 않은 정보, 추문","example":"The reporter dug up some dirt on the senator.","deck":"vocab"},{"id":130,"word":"in a hurry","ipa":"","meaning":"바쁜, 급한 <형용사적 용법>","example":"She was in a hurry and forgot her keys.","deck":"vocab"},{"id":131,"word":"clergy","ipa":"/ˈklɜrdʒi/","meaning":"(특히 기독교의) 성직자들","example":"Members of the clergy led the community in prayer.","deck":"vocab"},{"id":132,"word":"debacle","ipa":"/dɪˈbɑkəl/","meaning":"대실패, 큰 낭패","example":"The product launch turned into a complete debacle.","deck":"vocab"},{"id":133,"word":"try one's hand","ipa":"","meaning":"(새로운 것을 처음으로) (~을) 시도해보다","example":"She decided to try her hand at pottery this summer.","deck":"vocab"},{"id":134,"word":"horde","ipa":"/hɔrd/","meaning":"(사람의) 떼, 무리, 패, 군중 <부정적인 어감으로 쓰는 경우가 많음>","example":"A horde of tourists crowded around the famous statue.","deck":"vocab"},{"id":135,"word":"trait","ipa":"/treɪt/","meaning":"(성격상의) 특성","example":"Patience is an important trait in a good teacher.","deck":"vocab"},{"id":136,"word":"imperative","ipa":"/ɪmˈpɛrətɪv/","meaning":"명령법, 명령형, 명령문 <문법 용어>","example":"In grammar, the imperative is used to give commands.","deck":"vocab"},{"id":137,"word":"imperative","ipa":"/ɪmˈpɛrətɪv/","meaning":"의무, 책무","example":"Protecting the environment is a moral imperative for us all.","deck":"vocab"},{"id":138,"word":"submissive","ipa":"/səbˈmɪsɪv/","meaning":"순종적인, 고분고분한","example":"The dog rolled over in a submissive gesture.","deck":"vocab"},{"id":139,"word":"harness","ipa":"/ˈhɑrnɪs/","meaning":"(동력원 등으로) 이용하다, 활용하다","example":"Engineers found new ways to harness solar energy efficiently.","deck":"vocab"},{"id":140,"word":"dust","ipa":"/dʌst/","meaning":"(천 등으로) 먼지를 닦다 <자동사>","example":"She dusted carefully around the fragile ornaments.","deck":"vocab"},{"id":141,"word":"what if ~?","ipa":"","meaning":"~면 어쩌지?, ~라면 어떻게 될까?","example":"What if we miss the last train home?","deck":"vocab"},{"id":142,"word":"what if ~?","ipa":"","meaning":"(제안을 나타내어) ~하면 어떨까?","example":"What if we ordered pizza instead of cooking tonight?","deck":"vocab"},{"id":143,"word":"amend","ipa":"/əˈmɛnd/","meaning":"(법 등을) 개정하다, 수정하다","example":"Congress voted to amend the outdated law.","deck":"vocab"},{"id":144,"word":"pluck","ipa":"/plʌk/","meaning":"(머리카락, 눈썹 등을) 뽑다","example":"She plucked her eyebrows carefully in front of the mirror.","deck":"vocab"},{"id":145,"word":"cryptic","ipa":"/ˈkrɪptɪk/","meaning":"수수께끼 같은, 아리송한","example":"He left a cryptic note that no one could understand.","deck":"vocab"},{"id":146,"word":"submit","ipa":"/səbˈmɪt/","meaning":"(~에) 굴복하다, (~에) 복종하다, (~을) 감수하다","example":"They refused to submit to the dictator's demands.","deck":"vocab"},{"id":147,"word":"take","ipa":"/teɪk/","meaning":"장악하다, 차지하다, 잡다","example":"The rebels took control of the capital overnight.","deck":"vocab"},{"id":148,"word":"take","ipa":"/teɪk/","meaning":"필요하다, 필요로 한다, 있어야 하다 <주어로 사람은 올 수 없음>","example":"It takes a lot of patience to raise a toddler.","deck":"vocab"},{"id":149,"word":"prosperity","ipa":"/prɑˈspɛrɪti/","meaning":"번영, 번성, 번창","example":"The nation enjoyed decades of peace and prosperity.","deck":"vocab"},{"id":150,"word":"put ~ off","ipa":"","meaning":"미루다, 연기하다","example":"Don't put off your homework until the last minute.","deck":"vocab"},{"id":151,"word":"resume","ipa":"/rɪˈzum/","meaning":"재개하다, 다시 시작하다","example":"They resumed the meeting after a short coffee break.","deck":"vocab"},{"id":152,"word":"intoxicated","ipa":"/ɪnˈtɑksɪˌkeɪtɪd/","meaning":"(술, 마약에) 취한","example":"He was clearly intoxicated when the police stopped him.","deck":"vocab"},{"id":153,"word":"intoxicated","ipa":"/ɪnˈtɑksɪˌkeɪtɪd/","meaning":"도취된, 몹시 들뜬","example":"She was intoxicated by the thrill of her first success.","deck":"vocab"},{"id":154,"word":"nocturnal","ipa":"/nɑkˈtɜrnəl/","meaning":"(동물이) 야행성의","example":"Owls are nocturnal creatures that hunt at night.","deck":"vocab"},{"id":155,"word":"presidency","ipa":"/ˈprɛzɪdənsi/","meaning":"대통령직, 대통령 임기, 회장직, 회장 임기","example":"His presidency was marked by major economic reforms.","deck":"vocab"},{"id":156,"word":"drastic","ipa":"/ˈdræstɪk/","meaning":"(주로 변화가) 급격한, 격렬한","example":"The company made drastic cuts to reduce its debts.","deck":"vocab"},{"id":157,"word":"stunt","ipa":"/stʌnt/","meaning":"(성장을) 방해하다, 발달을 저해하다","example":"Poor nutrition can stunt a child's growth.","deck":"vocab"},{"id":158,"word":"stunt","ipa":"/stʌnt/","meaning":"이목을 끄는 행동","example":"The marketing stunt attracted thousands of curious onlookers.","deck":"vocab"},{"id":159,"word":"put ~ foot down","ipa":"","meaning":"결연한 태도를 취하다, 단호히 반대하다","example":"Mom finally put her foot down about the late-night parties.","deck":"vocab"},{"id":160,"word":"break ~ in","ipa":"","meaning":"(특히 새 신을) 길을 들이다","example":"It took a week to break in my new hiking boots.","deck":"vocab"},{"id":161,"word":"sidekick","ipa":"/ˈsaɪdˌkɪk/","meaning":"조수","example":"Every superhero needs a loyal sidekick by his side.","deck":"vocab"},{"id":162,"word":"giveaway","ipa":"/ˈɡɪvəˌweɪ/","meaning":"(제품의 홍보 목적으로 끼워 주는) 증정품, 경품","example":"The store offered a free giveaway with every purchase.","deck":"vocab"},{"id":163,"word":"in one's book","ipa":"","meaning":"~의 기준에는","example":"In my book, honesty is the most important quality.","deck":"vocab"},{"id":164,"word":"since","ipa":"/sɪns/","meaning":"(의문문으로) 언제부터","example":"Since when do you enjoy waking up early?","deck":"vocab"},{"id":165,"word":"brainwash","ipa":"/ˈbreɪnˌwɑʃ/","meaning":"세뇌시키다","example":"The cult tried to brainwash its new members.","deck":"vocab"},{"id":166,"word":"sign language","ipa":"/ˈsaɪn ˌlæŋɡwɪdʒ/","meaning":"수어, 수화, 수화언어","example":"She learned sign language to communicate with her deaf brother.","deck":"vocab"},{"id":167,"word":"plain","ipa":"/pleɪn/","meaning":"숨김없는, 솔직한, 있는 그대로의","example":"Let me be plain with you about the risks involved.","deck":"vocab"},{"id":168,"word":"plain","ipa":"/pleɪn/","meaning":"이해하기 쉬운, 분명한","example":"The instructions were written in plain, simple English.","deck":"vocab"},{"id":169,"word":"annexation","ipa":"/ˌænɛkˈseɪʃən/","meaning":"(영토의) 합병","example":"The annexation of the territory sparked international outrage.","deck":"vocab"},{"id":170,"word":"psychotic","ipa":"/saɪˈkɑtɪk/","meaning":"정신병의, 정신이상의","example":"The patient suffered a psychotic episode and was hospitalized.","deck":"vocab"},{"id":171,"word":"ignorant","ipa":"/ˈɪɡnərənt/","meaning":"무지한, 무식한, 무학의","example":"He remained completely ignorant of the danger he faced.","deck":"vocab"},{"id":172,"word":"reciprocal","ipa":"/rɪˈsɪprəkəl/","meaning":"상호 간의","example":"The two countries signed a reciprocal trade agreement.","deck":"vocab"},{"id":173,"word":"recite","ipa":"/rɪˈsaɪt/","meaning":"(열거하듯) 죽 말하다, 나열하다","example":"He recited a long list of complaints about his job.","deck":"vocab"},{"id":174,"word":"recite","ipa":"/rɪˈsaɪt/","meaning":"암송하다, 낭송하다, 낭독하다","example":"The student recited the poem beautifully from memory.","deck":"vocab"},{"id":175,"word":"pose","ipa":"/poʊz/","meaning":"(위험, 문제 등이) ~이 되다","example":"The chemical spill poses a serious threat to wildlife.","deck":"vocab"},{"id":176,"word":"deficiency","ipa":"/dɪˈfɪʃənsi/","meaning":"(필수적인 것의) 결핍, 부족, 결핍증","example":"A vitamin D deficiency can weaken your bones.","deck":"vocab"},{"id":177,"word":"that's the way the cookie crumbles","ipa":"","meaning":"세상사가 다 그런 거야","example":"We lost the contract, but that's the way the cookie crumbles.","deck":"vocab"},{"id":178,"word":"warfare","ipa":"/ˈwɔrˌfɛr/","meaning":"전투, ~전, 전쟁","example":"Modern warfare relies heavily on drones and technology.","deck":"vocab"},{"id":179,"word":"objectionable","ipa":"/əbˈdʒɛkʃənəbəl/","meaning":"불쾌한, 무례한 <격식 있는 표현>","example":"The committee removed several objectionable passages from the book.","deck":"vocab"},{"id":180,"word":"implicate","ipa":"/ˈɪmplɪˌkeɪt/","meaning":"(~에) ~가 연루되었음을 보여주다","example":"The emails implicated several executives in the fraud scheme.","deck":"vocab"},{"id":181,"word":"facilitate","ipa":"/fəˈsɪlɪˌteɪt/","meaning":"가능하게 하다, 용이하게 하다, 쉽게 하다","example":"A good moderator can facilitate a productive discussion.","deck":"vocab"},{"id":182,"word":"formula","ipa":"/ˈfɔrmjələ/","meaning":"(아기들 먹이는) 분유","example":"She fed the newborn formula every three hours.","deck":"vocab"},{"id":183,"word":"take ~ out","ipa":"","meaning":"~을 죽이다, ~을 없애다 <비격식>","example":"The sniper was ordered to take out the target quietly.","deck":"vocab"},{"id":184,"word":"disclose","ipa":"/dɪsˈkloʊz/","meaning":"(눈에 안 보이던 것을) 드러내다 <격식>","example":"The curtain rose to disclose a beautifully decorated stage.","deck":"vocab"},{"id":185,"word":"disclose","ipa":"/dɪsˈkloʊz/","meaning":"밝히다, 공개하다, 폭로하다","example":"The company refused to disclose its financial records.","deck":"vocab"},{"id":186,"word":"pneumonia","ipa":"/nuˈmoʊnjə/","meaning":"폐렴","example":"He was hospitalized with severe pneumonia last winter.","deck":"vocab"},{"id":187,"word":"worsen","ipa":"/ˈwɜrsən/","meaning":"악화시키다","example":"Her condition worsened rapidly during the night.","deck":"vocab"},{"id":188,"word":"on the wane","ipa":"","meaning":"줄어드는 중인, 시들해지는 중인","example":"The politician's popularity is clearly on the wane.","deck":"vocab"},{"id":189,"word":"knock ~ over","ipa":"","meaning":"쳐서 넘어뜨리다","example":"The cat knocked over the vase and shattered it.","deck":"vocab"},{"id":190,"word":"embarrass","ipa":"/ɪmˈbærəs/","meaning":"당황스럽게 만들다, 어색하게 만들다, 부끄럽게 만들다, 곤란하게 만들다","example":"He embarrassed her by telling that story in public.","deck":"vocab"},{"id":191,"word":"devise","ipa":"/dɪˈvaɪz/","meaning":"~을 생각해 내다, 창안하다, 고안하다","example":"They devised a clever plan to increase sales.","deck":"vocab"},{"id":192,"word":"assess","ipa":"/əˈsɛs/","meaning":"가늠하다, 재다, 검토 평가하다","example":"The teacher will assess each student's progress this month.","deck":"vocab"},{"id":193,"word":"extent","ipa":"/ɪkˈstɛnt/","meaning":"(크기, 중요성, 심각성 등의) 정도, 규모","example":"The full extent of the damage was not yet known.","deck":"vocab"},{"id":194,"word":"slip one's mind","ipa":"","meaning":"잊어 버리다, 생각나지 않다","example":"I meant to call you, but it slipped my mind.","deck":"vocab"},{"id":195,"word":"acute","ipa":"/əˈkjut/","meaning":"격심한, 극심한","example":"She felt an acute pain in her lower back.","deck":"vocab"},{"id":196,"word":"collarbone","ipa":"/ˈkɑlərˌboʊn/","meaning":"쇄골(鎖骨)","example":"He broke his collarbone falling off his bicycle.","deck":"vocab"},{"id":197,"word":"comatose","ipa":"/ˈkoʊməˌtoʊs/","meaning":"혼수상태인 <의학 용어>","example":"The patient remained comatose for several weeks after the crash.","deck":"vocab"},{"id":198,"word":"illustration","ipa":"/ˌɪləˈstreɪʃən/","meaning":"(무엇에 대한 진실을 보여주는) 실례, 예, 보기","example":"Her story is a perfect illustration of hard work paying off.","deck":"vocab"},{"id":199,"word":"dominant","ipa":"/ˈdɑmɪnənt/","meaning":"우세한, 지배적인","example":"The company holds a dominant position in the market.","deck":"vocab"},{"id":200,"word":"pen","ipa":"/pɛn/","meaning":"(가축의) 우리","example":"The farmer led the sheep back into their pen.","deck":"vocab"},{"id":201,"word":"gourmet","ipa":"/ɡɔːrˈmeɪ/","meaning":"미식가의, 미식가를 위한","example":"She opened a gourmet restaurant featuring rare ingredients from around the world.","deck":"vocab"},{"id":202,"word":"make a fuss","ipa":"","meaning":"소란을 피우다, 호들갑 떨다","example":"Please don't make a fuss over such a small mistake.","deck":"vocab"},{"id":203,"word":"stand in","ipa":"","meaning":"(~를) 대신하다, 대신 일을 봐 주다","example":"Can you stand in for me at tomorrow's morning meeting?","deck":"vocab"},{"id":204,"word":"brag","ipa":"/bræɡ/","meaning":"(~을) 자랑하다","example":"He loves to brag about his expensive new sports car.","deck":"vocab"},{"id":205,"word":"click","ipa":"/klɪk/","meaning":"(~와) 마음이 통하다, 좋아하게 되다","example":"We clicked instantly and became close friends within a week.","deck":"vocab"},{"id":206,"word":"adrenaline","ipa":"/əˈdrɛnəlɪn/","meaning":"아드레날린 <부신 호르몬의 하나>","example":"The sudden scare sent a rush of adrenaline through my body.","deck":"vocab"},{"id":207,"word":"cut ~ short","ipa":"","meaning":"~을 일찍 끝내다, 짧게 끝내다","example":"We had to cut our vacation short because of the storm.","deck":"vocab"},{"id":208,"word":"citation","ipa":"/saɪˈteɪʃən/","meaning":"인용구, 인용문","example":"The essay includes a citation from a famous philosopher.","deck":"vocab"},{"id":209,"word":"deploy","ipa":"/dɪˈplɔɪ/","meaning":"(군대, 무기를) 배치하다 <전문 용어>","example":"The general decided to deploy troops along the northern border.","deck":"vocab"},{"id":210,"word":"deploy","ipa":"/dɪˈplɔɪ/","meaning":"(에어백 등이) 터지다, 전개되다","example":"The airbags deploy instantly when the car detects a crash.","deck":"vocab"},{"id":211,"word":"potent","ipa":"/ˈpoʊtənt/","meaning":"(술, 약물, 오염물질 등이) 강한, 독한","example":"This cough medicine is quite potent, so take only one spoonful.","deck":"vocab"},{"id":212,"word":"chunk","ipa":"/tʃʌŋk/","meaning":"큰 덩어리 <상당히 많은 양이나, 어떤 것의 큰 부분을 비유적으로 이르는 말>","example":"A large chunk of my salary goes toward paying rent.","deck":"vocab"},{"id":213,"word":"off the charts","ipa":"","meaning":"예상할 수 있는 범위를 훌쩍 뛰어 넘는","example":"Ticket sales for the concert were completely off the charts.","deck":"vocab"},{"id":214,"word":"stand","ipa":"/stænd/","meaning":"(사안에 대해) 입장에 있다, 의견을 가지고 있다","example":"Where do you stand on the new company policy?","deck":"vocab"},{"id":215,"word":"wardrobe","ipa":"/ˈwɔːrdroʊb/","meaning":"(한 개인이 가지고 있는) 소유 의상, 가진 옷","example":"She spent a fortune updating her entire summer wardrobe.","deck":"vocab"},{"id":216,"word":"wardrobe","ipa":"/ˈwɔːrdroʊb/","meaning":"옷장","example":"He hung his coat neatly inside the bedroom wardrobe.","deck":"vocab"},{"id":217,"word":"harsh","ipa":"/hɑːrʃ/","meaning":"(날씨, 생활환경이) 혹독한","example":"Farmers struggle to survive the harsh winters in this region.","deck":"vocab"},{"id":218,"word":"harsh","ipa":"/hɑːrʃ/","meaning":"가혹한, 냉혹한","example":"His harsh criticism left the young writer feeling discouraged.","deck":"vocab"},{"id":219,"word":"restore","ipa":"/rɪˈstɔːr/","meaning":"(이전의 상황, 감정으로) 회복시키다","example":"A good night's sleep helped restore my energy and mood.","deck":"vocab"},{"id":220,"word":"swimmingly","ipa":"/ˈswɪmɪŋli/","meaning":"순조롭게","example":"The project went swimmingly and we finished ahead of schedule.","deck":"vocab"},{"id":221,"word":"squeeze","ipa":"/skwiːz/","meaning":"(좁은 곳에) 비집고 들어가다","example":"She managed to squeeze into the crowded elevator before the doors closed.","deck":"vocab"},{"id":222,"word":"belittle","ipa":"/bɪˈlɪtl/","meaning":"하찮게 여기다, 업신여기다","example":"He tends to belittle his coworkers to feel more important.","deck":"vocab"},{"id":223,"word":"mumble","ipa":"/ˈmʌmbl/","meaning":"중얼거리다, 웅얼웅얼 말하다","example":"Please speak clearly and don't mumble during the presentation.","deck":"vocab"},{"id":224,"word":"hang up on ~","ipa":"","meaning":"(통화 중에 갑자기) ~의 전화를 끊어 버리다","example":"She got so angry that she hung up on me.","deck":"vocab"},{"id":225,"word":"amoral","ipa":"/eɪˈmɔːrəl/","meaning":"도덕관념이 없는","example":"The corrupt executive seemed completely amoral about his dishonest dealings.","deck":"vocab"},{"id":226,"word":"murmur","ipa":"/ˈmɜːrmər/","meaning":"속삭임, 소곤거림","example":"A soft murmur spread through the audience before the show began.","deck":"vocab"},{"id":227,"word":"shrug","ipa":"/ʃrʌɡ/","meaning":"(어깨를) 으쓱하다","example":"He gave a careless shrug when I asked about his plans.","deck":"vocab"},{"id":228,"word":"magnanimous","ipa":"/mæɡˈnænɪməs/","meaning":"(적이나 경쟁자 등에게) 도량이 넓은, 너그러운","example":"The champion was magnanimous in victory, praising his defeated rival.","deck":"vocab"},{"id":229,"word":"get down","ipa":"","meaning":"완전히 익히다, 완전히 익힐 때까지 연습하다","example":"It took weeks to get down the complicated dance routine.","deck":"vocab"},{"id":230,"word":"tremble","ipa":"/ˈtrɛmbl/","meaning":"(신체 부위가) 떨리다, 몸을 떨다 <자동사>","example":"Her hands began to tremble from the freezing cold wind.","deck":"vocab"},{"id":231,"word":"tremble","ipa":"/ˈtrɛmbl/","meaning":"(목소리가) 떨리다","example":"His voice started to tremble as he read the sad letter.","deck":"vocab"},{"id":232,"word":"mash","ipa":"/mæʃ/","meaning":"(음식을) 으깨다","example":"Mash the boiled potatoes until they are smooth and creamy.","deck":"vocab"},{"id":233,"word":"fasting","ipa":"/ˈfæstɪŋ/","meaning":"단식, 금식","example":"Many people practice fasting for both religious and health reasons.","deck":"vocab"},{"id":234,"word":"intermittent","ipa":"/ˌɪntərˈmɪtənt/","meaning":"간헐적인, 간간이 일어나는","example":"The hikers faced intermittent rain throughout the entire afternoon.","deck":"vocab"},{"id":235,"word":"rely on ~","ipa":"","meaning":"~에 의지하다, ~에 의존하다","example":"Farmers heavily rely on the weather for a good harvest.","deck":"vocab"},{"id":236,"word":"rely on ~","ipa":"","meaning":"~을 믿다, ~을 신뢰하다","example":"You can always rely on her to keep a secret.","deck":"vocab"},{"id":237,"word":"illiterate","ipa":"/ɪˈlɪtərət/","meaning":"(특정 분야에 대해) 잘 모르는, 무지한 <주로 명사나 부사와 함께 씀>","example":"He is completely computer illiterate and cannot send an email.","deck":"vocab"},{"id":238,"word":"rebel","ipa":"/ˈrɛbl/","meaning":"(규칙, 일반 통념 등에) 반항적인 사람, 반항아","example":"As a teenager, he was a rebel who ignored every rule.","deck":"vocab"},{"id":239,"word":"stakeholder","ipa":"/ˈsteɪkhoʊldər/","meaning":"주주","example":"Every stakeholder must approve the merger before it goes forward.","deck":"vocab"},{"id":240,"word":"denature","ipa":"/diːˈneɪtʃər/","meaning":"(에틸알코올, 단백질, 핵연료 등을) 변성시키다","example":"Heat is used to denature the proteins in the sample.","deck":"vocab"},{"id":241,"word":"denature","ipa":"/diːˈneɪtʃər/","meaning":"(단백질이) 변성되다, 변성하다","example":"The proteins denature quickly when exposed to high temperatures.","deck":"vocab"},{"id":242,"word":"bleak","ipa":"/bliːk/","meaning":"(날씨가) 으스스한, 으슬으슬한","example":"It was a bleak, grey morning with icy wind.","deck":"vocab"},{"id":243,"word":"bleak","ipa":"/bliːk/","meaning":"(상황이) 암울한, 절망적인","example":"The future looked bleak after the factory suddenly closed down.","deck":"vocab"},{"id":244,"word":"groom","ipa":"/ɡruːm/","meaning":"(동물이) ~의 털을 다듬다, 가죽을 다듬다","example":"The cat spent the afternoon grooming its soft fur.","deck":"vocab"},{"id":245,"word":"groom","ipa":"/ɡruːm/","meaning":"(사람이) ~의 털을 다듬다, 솔질하다","example":"She carefully groomed the horse before the big competition.","deck":"vocab"},{"id":246,"word":"digestive","ipa":"/daɪˈdʒɛstɪv/","meaning":"소화의","example":"Ginger tea can soothe minor digestive problems after a heavy meal.","deck":"vocab"},{"id":247,"word":"midwife","ipa":"/ˈmɪdwaɪf/","meaning":"산파, 조산사 <출산을 돕는 사람. 또는 비유적으로 어떤 일의 실현을 돕는 사람>","example":"The midwife helped deliver the baby safely at home.","deck":"vocab"},{"id":248,"word":"foster","ipa":"/ˈfɔːstər/","meaning":"발전시키다, 키우다, 조성하다","example":"Good teachers foster curiosity and creativity in their students.","deck":"vocab"},{"id":249,"word":"foster","ipa":"/ˈfɔːstər/","meaning":"수양~, 양~, 위탁~","example":"They decided to become foster parents for a young child.","deck":"vocab"},{"id":250,"word":"jittery","ipa":"/ˈdʒɪtəri/","meaning":"초조한 듯이 행동하는, 안절부절못하는, 초조한","example":"Too much coffee makes me jittery and unable to focus.","deck":"vocab"},{"id":251,"word":"poised","ipa":"/pɔɪzd/","meaning":"침착한","example":"She stayed poised and calm during the difficult interview.","deck":"vocab"},{"id":252,"word":"cop-out","ipa":"/ˈkɑːpˌaʊt/","meaning":"(책임 회피의) 핑계, 구실","example":"Blaming the weather is just a cop-out for your laziness.","deck":"vocab"},{"id":253,"word":"in disguise","ipa":"","meaning":"변장한, 가장한, 변장하여","example":"The spy entered the palace in disguise as a servant.","deck":"vocab"},{"id":254,"word":"assassination","ipa":"/əˌsæsɪˈneɪʃən/","meaning":"암살","example":"The president's assassination shocked the entire nation deeply.","deck":"vocab"},{"id":255,"word":"recession","ipa":"/rɪˈsɛʃən/","meaning":"경기 후퇴, 경기 침체, 불경기","example":"Many small businesses closed during the long economic recession.","deck":"vocab"},{"id":256,"word":"intricate","ipa":"/ˈɪntrɪkət/","meaning":"(여러 부분, 내용으로 되어 있어) 복잡한","example":"The watch contains an intricate mechanism of tiny gears.","deck":"vocab"},{"id":257,"word":"solid","ipa":"/ˈsɑːlɪd/","meaning":"완전히, 빈틈없이, 꽉 차게","example":"I waited two solid hours for the delayed train.","deck":"vocab"},{"id":258,"word":"solid","ipa":"/ˈsɑːlɪd/","meaning":"(사람이) 믿음직한","example":"He is a solid friend who never lets me down.","deck":"vocab"},{"id":259,"word":"knock it off!","ipa":"","meaning":"그만해, 집어치워, 그만둬 <비격식적인 표현>","example":"Knock it off! You two have been arguing all morning.","deck":"vocab"},{"id":260,"word":"puddle","ipa":"/ˈpʌdl/","meaning":"(특히 비 온 뒤의) 물웅덩이","example":"The children happily jumped in every puddle after the rain.","deck":"vocab"},{"id":261,"word":"eye-opening","ipa":"/ˈaɪˌoʊpənɪŋ/","meaning":"괄목할 만한, 놀랄 만한","example":"The documentary was an eye-opening look at ocean pollution.","deck":"vocab"},{"id":262,"word":"jerk ~ around","ipa":"","meaning":"거짓말로 속여서 ~를 가지고 놀다","example":"Stop jerking me around and tell me the truth.","deck":"vocab"},{"id":263,"word":"detached","ipa":"/dɪˈtætʃt/","meaning":"무심한, 거리를 두는","example":"He remained oddly detached during the emotional family reunion.","deck":"vocab"},{"id":264,"word":"fermentation","ipa":"/ˌfɜːrmɛnˈteɪʃən/","meaning":"발효, 발효 작용","example":"Fermentation gives the bread its rich, tangy flavor.","deck":"vocab"},{"id":265,"word":"physiology","ipa":"/ˌfɪziˈɑːlədʒi/","meaning":"생리 <생물체의 생물학적 기능과 작용. 또는 그 원리>","example":"Exercise changes the physiology of the human heart over time.","deck":"vocab"},{"id":266,"word":"physiology","ipa":"/ˌfɪziˈɑːlədʒi/","meaning":"생리학","example":"She studied physiology to understand how the body functions.","deck":"vocab"},{"id":267,"word":"preexisting","ipa":"/ˌpriːɪɡˈzɪstɪŋ/","meaning":"기존의, 이미 있는","example":"The insurance won't cover any preexisting medical conditions.","deck":"vocab"},{"id":268,"word":"appreciation","ipa":"/əˌpriːʃiˈeɪʃən/","meaning":"(상황에 대한 완전한) 이해, 인식","example":"Traveling gave me a deeper appreciation of different cultures.","deck":"vocab"},{"id":269,"word":"appreciation","ipa":"/əˌpriːʃiˈeɪʃən/","meaning":"진가를 알기, 올바른 인식","example":"He showed great appreciation for the fine details of the painting.","deck":"vocab"},{"id":270,"word":"dash","ipa":"/dæʃ/","meaning":"(급히) 서둘러 가다","example":"I had to dash to the station to catch my train.","deck":"vocab"},{"id":271,"word":"chewy","ipa":"/ˈtʃuːi/","meaning":"(음식이) 질긴, 꼭꼭 씹어 먹어야 하는","example":"The caramel candy was sweet but very chewy.","deck":"vocab"},{"id":272,"word":"diversified","ipa":"/daɪˈvɜːrsɪfaɪd/","meaning":"다양한, 각양각색의, 다각적인","example":"A diversified investment portfolio reduces your overall financial risk.","deck":"vocab"},{"id":273,"word":"connotation","ipa":"/ˌkɑːnəˈteɪʃən/","meaning":"함축, 함축된 의미","example":"The word 'cheap' often carries a negative connotation.","deck":"vocab"},{"id":274,"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃən/","meaning":"(특히 예술 작품의) 복제품, 복제화","example":"The museum sells a reproduction of the famous painting.","deck":"vocab"},{"id":275,"word":"divine","ipa":"/dɪˈvaɪn/","meaning":"신성한, 신의, 하느님의 <주로 명사 앞에 씀>","example":"Many cultures believe rulers once had divine power.","deck":"vocab"},{"id":276,"word":"precaution","ipa":"/prɪˈkɔːʃən/","meaning":"예방책, 예방 조치, 예방 수단","example":"Wear a helmet as a basic safety precaution while cycling.","deck":"vocab"},{"id":277,"word":"implicit","ipa":"/ɪmˈplɪsɪt/","meaning":"(믿음, 신뢰 등이) 절대적인, 무조건적인","example":"She placed implicit trust in her longtime business partner.","deck":"vocab"},{"id":278,"word":"impairment","ipa":"/ɪmˈpɛrmənt/","meaning":"(신체, 정신적) 장애","example":"The accident left him with a permanent hearing impairment.","deck":"vocab"},{"id":279,"word":"pesticide","ipa":"/ˈpɛstɪsaɪd/","meaning":"살충제, 농약","example":"Farmers sprayed pesticide to protect the crops from insects.","deck":"vocab"},{"id":280,"word":"glossary","ipa":"/ˈɡlɑːsəri/","meaning":"용어집, 용어 사전","example":"Check the glossary at the back for unfamiliar terms.","deck":"vocab"},{"id":281,"word":"respectful","ipa":"/rɪˈspɛktfl/","meaning":"존중하는, 존경심을 보이는, 경의를 표하는, 공손한","example":"The students were polite and respectful toward their teacher.","deck":"vocab"},{"id":282,"word":"horizon","ipa":"/həˈraɪzən/","meaning":"(사고, 지식, 흥미 등의) 시야, 한계, 범위 <주로 복수형으로 씀>","example":"Traveling abroad really broadened my horizons and worldview.","deck":"vocab"},{"id":283,"word":"for one thing","ipa":"","meaning":"우선 첫째로, 우선 한 가지 이유는","example":"I can't go; for one thing, I have no money.","deck":"vocab"},{"id":284,"word":"frosting","ipa":"/ˈfrɔːstɪŋ/","meaning":"(케이크나 과자 등을 장식하는) 크림, 프로스팅 <주로 미국에서 씀>","example":"She spread thick chocolate frosting over the birthday cake.","deck":"vocab"},{"id":285,"word":"vice","ipa":"/vaɪs/","meaning":"나쁜 버릇, 비행, 악습 <셀 수 있는 명사>","example":"Smoking is his only vice, otherwise he's quite healthy.","deck":"vocab"},{"id":286,"word":"vice","ipa":"/vaɪs/","meaning":"풍기단속반 <경찰의 부서 중에 성폭력, 도박, 마약 등이 관련된 범죄를 단속하는 부서>","example":"She joined the vice unit to fight illegal gambling.","deck":"vocab"},{"id":287,"word":"practically","ipa":"/ˈpræktɪkli/","meaning":"사실상, 거의","example":"The stadium was practically empty by the third quarter.","deck":"vocab"},{"id":288,"word":"incorporate","ipa":"/ɪnˈkɔːrpəreɪt/","meaning":"포함시키다, 통합시키다","example":"We should incorporate customer feedback into the new design.","deck":"vocab"},{"id":289,"word":"scramble","ipa":"/ˈskræmbl/","meaning":"서로 밀치기, 앞다투기, 쟁탈전을 벌이기","example":"There was a wild scramble for the last discounted tickets.","deck":"vocab"},{"id":290,"word":"spike","ipa":"/spaɪk/","meaning":"못, 못같이 뾰족한 것","example":"He cut his foot on a sharp metal spike.","deck":"vocab"},{"id":291,"word":"fluff","ipa":"/flʌf/","meaning":"시시한 것, 쓸데없는 것, 피상적인 것","example":"The magazine article was pure fluff with no real information.","deck":"vocab"},{"id":292,"word":"fluff","ipa":"/flʌf/","meaning":"부풀리다","example":"She fluffed the pillows before the guests arrived.","deck":"vocab"},{"id":293,"word":"sustain","ipa":"/səˈsteɪn/","meaning":"(피해 등을) 입다, 당하다 <격식 있는 표현>","example":"Several passengers sustained minor injuries in the bus accident.","deck":"vocab"},{"id":294,"word":"far-fetched","ipa":"/ˌfɑːrˈfɛtʃt/","meaning":"억지스러운, 가능성이 희박한, 믿기 어려운","example":"His excuse sounded far-fetched and nobody believed it.","deck":"vocab"},{"id":295,"word":"following","ipa":"/ˈfɑːloʊɪŋ/","meaning":"~ 후에, ~에 따라","example":"The office reopened following a week of renovations.","deck":"vocab"},{"id":296,"word":"charge","ipa":"/tʃɑːrdʒ/","meaning":"(~로) 기소하다, 고소하다","example":"Police decided to charge him with reckless driving.","deck":"vocab"},{"id":297,"word":"charge","ipa":"/tʃɑːrdʒ/","meaning":"기소, 공소, 혐의","example":"He faced a serious charge of tax fraud.","deck":"vocab"},{"id":298,"word":"live up to ~","ipa":"","meaning":"(다른 사람의 기대) ~에 부응하다","example":"The new movie failed to live up to the hype.","deck":"vocab"},{"id":299,"word":"illuminate","ipa":"/ɪˈluːmɪneɪt/","meaning":"(~에 불을) 비추다","example":"Bright spotlights illuminate the stage during the performance.","deck":"vocab"},{"id":300,"word":"take ~ over","ipa":"","meaning":"(정권, 정당 등을) ~을 장악하다, 탈취하다","example":"The rebels moved quickly to take the city over.","deck":"vocab"},{"id":301,"word":"take ~ over","ipa":"","meaning":"~을 대체하다","example":"Machines will take these tasks over within a decade.","deck":"vocab"},{"id":302,"word":"jar","ipa":"/dʒɑːr/","meaning":"(입구가 넓은) 병, 단지, 항아리","example":"She stored the homemade jam in a glass jar.","deck":"vocab"},{"id":303,"word":"period","ipa":"/ˈpɪriəd/","meaning":"(여성의) 생리","example":"She stayed home with cramps during her period.","deck":"vocab"},{"id":304,"word":"contemporary","ipa":"/kənˈtɛmpərɛri/","meaning":"현대의, 당대의","example":"The gallery features contemporary art from young local artists.","deck":"vocab"},{"id":305,"word":"try","ipa":"/traɪ/","meaning":"(법원에서) 재판하다, 심리하다","example":"The court will try the suspect early next month.","deck":"vocab"},{"id":306,"word":"walk ~ through ~","ipa":"","meaning":"~에게 ~을 차근차근 설명하다, 차근차근 알려 주다","example":"Let me walk you through the setup process step by step.","deck":"vocab"},{"id":307,"word":"seek","ipa":"/siːk/","meaning":"추구하다, 요구하다, 구하다, ~을 얻으려고 애쓰다","example":"Young graduates often seek advice from experienced mentors.","deck":"vocab"},{"id":308,"word":"sober","ipa":"/ˈsoʊbər/","meaning":"(사람 또는 사람의 행동이) 냉철한, 진지한","example":"He gave a sober assessment of the company's financial troubles.","deck":"vocab"},{"id":309,"word":"sober","ipa":"/ˈsoʊbər/","meaning":"술 취하지 않은","example":"He stayed sober at the party and drove everyone home.","deck":"vocab"},{"id":310,"word":"refreshment","ipa":"/rɪˈfrɛʃmənt/","meaning":"다과, 가벼운 음식물 <복수형으로 씀>","example":"Light refreshments will be served after the seminar.","deck":"vocab"},{"id":311,"word":"count ~ out","ipa":"","meaning":"(활동이나 계획에서) ~를 빼다","example":"If it involves camping, you can count me out.","deck":"vocab"},{"id":312,"word":"impulsive","ipa":"/ɪmˈpʌlsɪv/","meaning":"(사람, 행동이) 충동적인","example":"Buying that expensive watch was a very impulsive decision.","deck":"vocab"},{"id":313,"word":"implant","ipa":"/ˈɪmplænt/","meaning":"삽입하는 물질, 이식물, 삽입물, 보형물","example":"The surgeon inserted a metal implant into his knee.","deck":"vocab"},{"id":314,"word":"curb","ipa":"/kɜːrb/","meaning":"연석, 갓돌, 도로 경계석 <차도와 인도 또는 차도와 가로수 사이의 경계석>","example":"She parked too close to the curb and scratched the tire.","deck":"vocab"},{"id":315,"word":"panic attack","ipa":"/ˈpænɪk əˌtæk/","meaning":"공황 발작","example":"She had a panic attack right before the big exam.","deck":"vocab"},{"id":316,"word":"adequate","ipa":"/ˈædɪkwət/","meaning":"충분한, 적절한, 적당한","example":"Make sure you get adequate sleep before the long trip.","deck":"vocab"},{"id":317,"word":"unmoved","ipa":"/ʌnˈmuːvd/","meaning":"마음이 동요하지 않는, 냉정한","example":"He remained unmoved by their desperate pleas for help.","deck":"vocab"},{"id":318,"word":"who's to say","ipa":"","meaning":"누가 알겠어? <아무도 모른다는 뜻>","example":"Who's to say what the future might bring us?","deck":"vocab"},{"id":319,"word":"observe","ipa":"/əbˈzɜːrv/","meaning":"(축제, 생일 등을) 축하하다, 기념하다","example":"Our family observes Thanksgiving with a big dinner every year.","deck":"vocab"},{"id":320,"word":"ax","ipa":"/æks/","meaning":"해고하다, 자르다","example":"The company axed hundreds of workers during the crisis.","deck":"vocab"},{"id":321,"word":"take ~ off","ipa":"","meaning":"(얼마 기간) ~동안 일을 쉬다, 휴가를 내다","example":"I'm going to take a few days off next week.","deck":"vocab"},{"id":322,"word":"take ~ off","ipa":"","meaning":"(머리를) 자르다, 깎다","example":"The stylist took two inches off my hair.","deck":"vocab"},{"id":323,"word":"treason","ipa":"/ˈtriːzən/","meaning":"반역죄","example":"The officer was executed for committing treason against the crown.","deck":"vocab"},{"id":324,"word":"unsung","ipa":"/ˌʌnˈsʌŋ/","meaning":"찬양받지 못한, 칭송받지 못한, 유명해지지 못한, 이름 없는 <주로 명사 앞에 씀>","example":"Nurses are the unsung heroes of the entire hospital.","deck":"vocab"},{"id":325,"word":"faze","ipa":"/feɪz/","meaning":"당황시키다","example":"The loud boos didn't faze the experienced performer at all.","deck":"vocab"},{"id":326,"word":"take ~ for granted","ipa":"","meaning":"~을 당연시하다, ~이 고마운 줄을 모르다","example":"Don't take your parents' support for granted.","deck":"vocab"},{"id":327,"word":"forage","ipa":"/ˈfɔːrɪdʒ/","meaning":"(먹이를) (~를) 찾아 돌아다니다 <자동사>","example":"Bears often forage for berries in late summer.","deck":"vocab"},{"id":328,"word":"juvenile","ipa":"/ˈdʒuːvənaɪl/","meaning":"청소년의 (격식 있는 표현 또는 법률 용어)","example":"He was tried in a juvenile court because of his age.","deck":"vocab"},{"id":329,"word":"juvenile","ipa":"/ˈdʒuːvənaɪl/","meaning":"어린애 같은, 유치한 <부정적인 어감>","example":"His juvenile behavior at the meeting embarrassed everyone.","deck":"vocab"},{"id":330,"word":"dictator","ipa":"/ˈdɪkteɪtər/","meaning":"독재자","example":"The ruthless dictator silenced anyone who dared to oppose him.","deck":"vocab"},{"id":331,"word":"along these lines","ipa":"","meaning":"이와 비슷한, 이와 비슷하게","example":"We need a plan along these lines to succeed.","deck":"vocab"},{"id":332,"word":"depict","ipa":"/dɪˈpɪkt/","meaning":"(언어나 그림 등으로) 묘사하다","example":"The mural depicts the town's history in vivid colors.","deck":"vocab"},{"id":333,"word":"all in all","ipa":"","meaning":"대체로","example":"All in all, it was a productive and enjoyable trip.","deck":"vocab"},{"id":334,"word":"knuckle","ipa":"/ˈnʌkl/","meaning":"손가락 마디, 손가락 관절","example":"He cracked his knuckles nervously before the interview.","deck":"vocab"},{"id":335,"word":"pound","ipa":"/paʊnd/","meaning":"(심장 등이) 쿵쿵 뛰다, 두근거리다 <빠르고 세게 뛴다는 뜻>","example":"My heart was pounding as I opened the exam results.","deck":"vocab"},{"id":336,"word":"pound","ipa":"/paʊnd/","meaning":"치다, 두드리다 <주로 큰 소리를 내며 반복해서 세게 두드린다는 뜻>","example":"He pounded on the door, demanding to be let inside.","deck":"vocab"},{"id":337,"word":"thesis","ipa":"/ˈθiːsɪs/","meaning":"논지","example":"The author's central thesis is that kindness drives success.","deck":"vocab"},{"id":338,"word":"empathy","ipa":"/ˈɛmpəθi/","meaning":"감정이입, 공감","example":"Good nurses treat their patients with genuine empathy and care.","deck":"vocab"},{"id":339,"word":"slippery","ipa":"/ˈslɪpəri/","meaning":"파악하기 어려운, 다루기 힘든","example":"Truth can be a slippery concept in political debates.","deck":"vocab"},{"id":340,"word":"restrain","ipa":"/rɪˈstreɪn/","meaning":"(특히 물리력을 동원하여) 저지하다, 제지하다","example":"Two guards had to restrain the angry protester.","deck":"vocab"},{"id":341,"word":"elective","ipa":"/ɪˈlɛktɪv/","meaning":"(강좌, 과목이) 선택할 수 있는","example":"I chose photography as my elective course this semester.","deck":"vocab"},{"id":342,"word":"acquisitive","ipa":"/əˈkwɪzətɪv/","meaning":"욕심이 많은, 소유욕이 많은, 탐욕스러운","example":"Our acquisitive society constantly craves newer and bigger things.","deck":"vocab"},{"id":343,"word":"fix","ipa":"/fɪks/","meaning":"준비하다, 주선하다","example":"Let me fix you a sandwich before you leave.","deck":"vocab"},{"id":344,"word":"comprehensive","ipa":"/ˌkɑːmprɪˈhɛnsɪv/","meaning":"포괄적인, 종합적인","example":"The report offers a comprehensive overview of the whole industry.","deck":"vocab"},{"id":345,"word":"rain shower","ipa":"/ˈreɪn ˌʃaʊər/","meaning":"소나기","example":"A brief rain shower cooled the air this afternoon.","deck":"vocab"},{"id":346,"word":"distant","ipa":"/ˈdɪstənt/","meaning":"먼, 멀리 떨어져 있는","example":"We could see a distant mountain range on the horizon.","deck":"vocab"},{"id":347,"word":"restate","ipa":"/ˌriːˈsteɪt/","meaning":"다시 말하다, 고쳐 말하다","example":"Let me restate my point more clearly this time.","deck":"vocab"},{"id":348,"word":"engage","ipa":"/ɪnˈɡeɪdʒ/","meaning":"(~와) 교전을 시작하다, 싸우기 시작하다 <자동사>","example":"The two armies engaged at dawn near the river.","deck":"vocab"},{"id":349,"word":"engage","ipa":"/ɪnˈɡeɪdʒ/","meaning":"(~에) ~를 관여하게 하다, 참여시키다, 끌어들이다","example":"Skilled teachers know how to engage students in the lesson.","deck":"vocab"},{"id":350,"word":"engage","ipa":"/ɪnˈɡeɪdʒ/","meaning":"(~에) 관여하다, 참여하다, 종사하다, 하다","example":"She engages in volunteer work every weekend.","deck":"vocab"},{"id":351,"word":"resort","ipa":"/rɪˈzɔːrt/","meaning":"(특정 상황에서의) 수단","example":"Violence should always be the last resort in a conflict.","deck":"vocab"},{"id":352,"word":"have the floor","ipa":"","meaning":"(토론에서) 발언권을 갖다","example":"The senator now has the floor to present her argument.","deck":"vocab"},{"id":353,"word":"syllabus","ipa":"/ˈsɪləbəs/","meaning":"강의 계획서, 강의 개요, 수업 안내서","example":"The professor handed out the course syllabus on the first day.","deck":"vocab"},{"id":354,"word":"overpower","ipa":"/ˌoʊvərˈpaʊər/","meaning":"제압하다","example":"Three men tried to overpower the security guard at once.","deck":"vocab"},{"id":355,"word":"tumor","ipa":"/ˈtuːmər/","meaning":"종양(腫瘍)","example":"Doctors removed the small tumor during a two-hour surgery.","deck":"vocab"},{"id":356,"word":"on the trail","ipa":"","meaning":"(~을) 추적하여","example":"Detectives are hot on the trail of the missing jewels.","deck":"vocab"},{"id":357,"word":"boast","ipa":"/boʊst/","meaning":"뽐내다, 자랑하다","example":"He loves to boast about his children's achievements.","deck":"vocab"},{"id":358,"word":"teller","ipa":"/ˈtɛlər/","meaning":"(은행의) 창구 직원, 금전 출납계 직원","example":"The bank teller counted the cash quickly and accurately.","deck":"vocab"},{"id":359,"word":"spark","ipa":"/spɑːrk/","meaning":"촉발시키다, 유발하다, 불러일으키다","example":"The new tax law sparked widespread public protests.","deck":"vocab"},{"id":360,"word":"nagging","ipa":"/ˈnæɡɪŋ/","meaning":"(통증이나 의심 등이) 계속되는, 없어지지 않는","example":"I had a nagging pain in my lower back all day.","deck":"vocab"},{"id":361,"word":"nagging","ipa":"/ˈnæɡɪŋ/","meaning":"(주로 지속적인) 잔소리, 바가지","example":"Her constant nagging finally made him clean the garage.","deck":"vocab"},{"id":362,"word":"tiredness","ipa":"/ˈtaɪərdnəs/","meaning":"피곤함, 피로함","example":"A sudden wave of tiredness hit me after lunch.","deck":"vocab"},{"id":363,"word":"above all","ipa":"","meaning":"무엇보다도, 특히","example":"Above all, remember to stay calm during the emergency.","deck":"vocab"},{"id":364,"word":"along the way","ipa":"","meaning":"그 과정에서","example":"We learned many valuable lessons along the way.","deck":"vocab"},{"id":365,"word":"clap","ipa":"/klæp/","meaning":"(손뼉을) 치다 <타동사>","example":"The audience clapped loudly when the singer finished her song.","deck":"vocab"},{"id":366,"word":"clap","ipa":"/klæp/","meaning":"턱 갖다 대다","example":"He clapped a firm hand on my shoulder in support.","deck":"vocab"},{"id":367,"word":"suck it up","ipa":"","meaning":"(좋지 않은 일을 감정을 다스리며) 잘 받아들이다","example":"I know it's hard, but you just have to suck it up.","deck":"vocab"},{"id":368,"word":"takeaway","ipa":"/ˈteɪkəweɪ/","meaning":"핵심사항, 요점","example":"The main takeaway from the lecture was to plan ahead.","deck":"vocab"},{"id":369,"word":"granite","ipa":"/ˈɡrænɪt/","meaning":"화강암","example":"The kitchen features a beautiful polished granite countertop.","deck":"vocab"},{"id":370,"word":"barn","ipa":"/bɑːrn/","meaning":"곳간, 헛간, 외양간","example":"The farmer stored hay and tools inside the old barn.","deck":"vocab"},{"id":371,"word":"settle","ipa":"/ˈsɛtl/","meaning":"해결하다, 합의를 보다, 끝내다","example":"The two companies settled the dispute out of court.","deck":"vocab"},{"id":372,"word":"heretic","ipa":"/ˈhɛrətɪk/","meaning":"이단자","example":"The church condemned him as a dangerous heretic.","deck":"vocab"},{"id":373,"word":"evacuation","ipa":"/ɪˌvækjuˈeɪʃən/","meaning":"대피","example":"The fire alarm triggered an immediate evacuation of the building.","deck":"vocab"},{"id":374,"word":"exploit","ipa":"/ɪkˈsplɔɪt/","meaning":"(사람을) 착취하다, 이용해 먹다 <못마땅함>","example":"The factory was accused of exploiting its underpaid workers.","deck":"vocab"},{"id":375,"word":"exploit","ipa":"/ɪkˈsplɔɪt/","meaning":"~을 잘 활용하다","example":"Smart companies exploit new technology to gain an advantage.","deck":"vocab"},{"id":376,"word":"sting","ipa":"/stɪŋ/","meaning":"따끔거리다, 따갑다, 쓰리다","example":"The antiseptic will sting a little when applied to the cut.","deck":"vocab"},{"id":377,"word":"hold one's tongue","ipa":"","meaning":"입다물고 있다, 말을 삼가다, 잠자코 있다","example":"I wanted to argue but decided to hold my tongue.","deck":"vocab"},{"id":378,"word":"grow ~ out","ipa":"","meaning":"(머리카락, 수염 등을) ~을 자라게 놔두다","example":"She's trying to grow her bangs out this year.","deck":"vocab"},{"id":379,"word":"confrontation","ipa":"/ˌkɑːnfrənˈteɪʃən/","meaning":"대치, 대립","example":"He avoided a direct confrontation with his stubborn boss.","deck":"vocab"},{"id":380,"word":"get across","ipa":"","meaning":"알게 하다, 이해시키다","example":"It's difficult to get across in just a few words.","deck":"vocab"},{"id":381,"word":"shiver","ipa":"/ˈʃɪvər/","meaning":"떨다, 몸을 떨다","example":"I began to shiver as the temperature suddenly dropped.","deck":"vocab"},{"id":382,"word":"come out of the closet","ipa":"","meaning":"(동성애자를 비롯한 성소수자가) 커밍아웃하다","example":"He finally came out of the closet to his family.","deck":"vocab"},{"id":383,"word":"cringe","ipa":"/krɪndʒ/","meaning":"(겁이 나서) 움찔하다, 움츠리다","example":"She cringed in fear when the dog suddenly barked.","deck":"vocab"},{"id":384,"word":"cringe","ipa":"/krɪndʒ/","meaning":"민망해하다, 민망하다","example":"I cringe whenever I remember that embarrassing speech.","deck":"vocab"},{"id":385,"word":"will","ipa":"/wɪl/","meaning":"반드시 ~하다, ~해야 하다 <명령할 때 쓰는 표현>","example":"You will finish your homework before dinner, understood?","deck":"vocab"},{"id":386,"word":"prejudice","ipa":"/ˈprɛdʒədɪs/","meaning":"편견","example":"We must fight prejudice against people from different backgrounds.","deck":"vocab"},{"id":387,"word":"prey","ipa":"/preɪ/","meaning":"(사냥 동물의) 먹이, 사냥감","example":"The eagle swooped down and seized its unsuspecting prey.","deck":"vocab"},{"id":388,"word":"outreach","ipa":"/ˈaʊtriːtʃ/","meaning":"(주로 고객과의) 소통, 접촉 <관계 강화를 위해 소통 및 상담 등을 제공하는 활동>","example":"The clinic expanded its community outreach to rural areas.","deck":"vocab"},{"id":389,"word":"brittle","ipa":"/ˈbrɪtl/","meaning":"(기분, 정서가) 불안정한","example":"Her brittle mood shattered at the slightest criticism.","deck":"vocab"},{"id":390,"word":"prioritize","ipa":"/praɪˈɔːrətaɪz/","meaning":"우선시하다, 우선적으로 처리하다","example":"You should prioritize your health over your busy work schedule.","deck":"vocab"},{"id":391,"word":"you can say that again","ipa":"","meaning":"두말하면 잔소리지!, 정말 그래! <상대의 말에 전적으로 동의할 때 씀>","example":"'This coffee is terrible.' 'You can say that again!'","deck":"vocab"},{"id":392,"word":"irritated","ipa":"/ˈɪrɪteɪtɪd/","meaning":"짜증이 난, 화가 난","example":"She felt irritated by the constant noise from the street.","deck":"vocab"},{"id":393,"word":"juicy","ipa":"/ˈdʒuːsi/","meaning":"재미있는, 흥미진진한","example":"She shared some juicy gossip about the new manager.","deck":"vocab"},{"id":394,"word":"astonish","ipa":"/əˈstɑːnɪʃ/","meaning":"깜짝 놀라게 하다, 크게 놀라게 하다","example":"The magician's final trick astonished the entire audience.","deck":"vocab"},{"id":395,"word":"mundane","ipa":"/mʌnˈdeɪn/","meaning":"재미없는, 일상적인, 평범한","example":"He was tired of the mundane routine of office life.","deck":"vocab"},{"id":396,"word":"overrun","ipa":"/ˌoʊvərˈrʌn/","meaning":"~을 가득 채우다, ~에 급속히 퍼지게 하다 <수동태로 쓰는 경우가 많음>","example":"The abandoned garden was overrun with weeds and vines.","deck":"vocab"},{"id":397,"word":"immense","ipa":"/ɪˈmɛns/","meaning":"엄청난, 어마어마한","example":"Building the bridge required an immense amount of effort.","deck":"vocab"},{"id":398,"word":"dementia","ipa":"/dɪˈmɛnʃə/","meaning":"치매","example":"Her grandmother was recently diagnosed with early-stage dementia.","deck":"vocab"},{"id":399,"word":"treasury","ipa":"/ˈtrɛʒəri/","meaning":"(영국, 미국 및 일부 다른 국가들의) 재무부","example":"The Treasury announced new measures to control inflation.","deck":"vocab"},{"id":400,"word":"flawless","ipa":"/ˈflɔːləs/","meaning":"흠잡을 데 없는, 결점이 없는","example":"The gymnast delivered a flawless routine and won gold.","deck":"vocab"},{"id":401,"word":"fix ~ up","ipa":"","meaning":"~을 수리하다, ~을 단장하다","example":"We spent the weekend fixing up the old house together.","deck":"vocab"},{"id":402,"word":"pessimistic","ipa":"/ˌpɛsɪˈmɪstɪk/","meaning":"비관적인, 비관주의적인","example":"She tends to be pessimistic about her chances of promotion.","deck":"vocab"},{"id":403,"word":"incriminate","ipa":"/ɪnˈkrɪmɪˌneɪt/","meaning":"~이 유죄인 것처럼 보이게 하다","example":"He refused to say anything that might incriminate his friends.","deck":"vocab"},{"id":404,"word":"fly off the handle","ipa":"","meaning":"버럭 화를 내다","example":"My boss flew off the handle when he saw the mistake.","deck":"vocab"},{"id":405,"word":"would you mind","ipa":"","meaning":"~하면 안 될까요?","example":"Would you mind closing the window for me, please?","deck":"vocab"},{"id":406,"word":"hazy","ipa":"/ˈheɪzi/","meaning":"(기억 등이) 흐릿한, 모호한","example":"My memory of that night is a little hazy now.","deck":"vocab"},{"id":407,"word":"pathological","ipa":"/ˌpæθəˈlɑdʒɪkəl/","meaning":"병적인, 걷잡을 수 없는","example":"He has a pathological fear of being left alone.","deck":"vocab"},{"id":408,"word":"seal ~ off","ipa":"","meaning":"~을 봉쇄하다, 봉인하다","example":"Police sealed off the street after the accident.","deck":"vocab"},{"id":409,"word":"out of one's hair","ipa":"","meaning":"더 이상 ~를 귀찮게 굴지 않는","example":"I sent the kids outside to get them out of my hair.","deck":"vocab"},{"id":410,"word":"waist","ipa":"/weɪst/","meaning":"허리","example":"The dress fit perfectly around her waist.","deck":"vocab"},{"id":411,"word":"provided","ipa":"/prəˈvaɪdɪd/","meaning":"만약 ~라면","example":"You can borrow the car, provided you fill the tank.","deck":"vocab"},{"id":412,"word":"criterion","ipa":"/kraɪˈtɪriən/","meaning":"(판단이나 결정을 위한) 기준 <복수형은 criteria>","example":"Price is not the only criterion we use when hiring.","deck":"vocab"},{"id":413,"word":"separate","ipa":"/ˈsɛprɪt/","meaning":"관련 없는, 서로 다른, 별개의 <주로 명사 앞에 씀>","example":"These are two completely separate issues we must address.","deck":"vocab"},{"id":414,"word":"optimistic","ipa":"/ˌɑptɪˈmɪstɪk/","meaning":"낙관적인, 낙관하는","example":"The doctors remain optimistic about his full recovery.","deck":"vocab"},{"id":415,"word":"artery","ipa":"/ˈɑrtəri/","meaning":"동맥 <심장에서 피를 신체 각 부분에 보내는 혈관>","example":"The surgeon repaired the damaged artery during the operation.","deck":"vocab"},{"id":416,"word":"off-putting","ipa":"/ˈɔfˌpʊtɪŋ/","meaning":"정이 안 가는, 좋아하기 힘든","example":"His arrogant manner was rather off-putting at first.","deck":"vocab"},{"id":417,"word":"illegible","ipa":"/ɪˈlɛdʒəbəl/","meaning":"읽기 어려운, 판독이 불가능한","example":"The doctor's handwriting was completely illegible to the pharmacist.","deck":"vocab"},{"id":418,"word":"provision","ipa":"/prəˈvɪʒən/","meaning":"공급, 제공 <주로 단수형으로 씀>","example":"The charity handles the provision of food to refugees.","deck":"vocab"},{"id":419,"word":"compilation","ipa":"/ˌkɑmpɪˈleɪʃən/","meaning":"편집물, 모음집","example":"She released a compilation of her greatest hits last year.","deck":"vocab"},{"id":420,"word":"accomplished","ipa":"/əˈkɑmplɪʃt/","meaning":"기량이 뛰어난, 재주가 많은 <연습, 훈련을 통해서 도달한 경지를 나타냄>","example":"She is an accomplished pianist who studied for years.","deck":"vocab"},{"id":421,"word":"souvenir","ipa":"/ˌsuvəˈnɪr/","meaning":"(휴가지 등에서 사는) 기념품, 선물","example":"I bought a small souvenir to remember the trip.","deck":"vocab"},{"id":422,"word":"hospitalize","ipa":"/ˈhɑspɪtəˌlaɪz/","meaning":"입원시키다 <주로 수동태로 쓰임>","example":"He was hospitalized for a week after the crash.","deck":"vocab"},{"id":423,"word":"canal","ipa":"/kəˈnæl/","meaning":"운하, 수로","example":"Boats drifted slowly along the peaceful old canal.","deck":"vocab"},{"id":424,"word":"stoic","ipa":"/ˈstoʊɪk/","meaning":"불평불만을 얼굴로 드러내지 않는, 태연한","example":"She remained stoic despite the terrible news.","deck":"vocab"},{"id":425,"word":"on impulse","ipa":"","meaning":"충동적으로","example":"I bought the jacket on impulse without checking the price.","deck":"vocab"},{"id":426,"word":"flea market","ipa":"/ˈfli ˌmɑrkɪt/","meaning":"벼룩시장","example":"We found a beautiful antique lamp at the flea market.","deck":"vocab"},{"id":427,"word":"class act","ipa":"/ˈklæs ˌækt/","meaning":"일류의 것, 걸출한 사람","example":"The retiring coach was a real class act to the end.","deck":"vocab"},{"id":428,"word":"to begin with","ipa":"","meaning":"우선, 먼저 <말할 내용 중에 첫 번째 내용을 소개하면서 하는 말>","example":"To begin with, I'd like to thank everyone for coming.","deck":"vocab"},{"id":429,"word":"fertilize","ipa":"/ˈfɜrtəˌlaɪz/","meaning":"수정시키다","example":"Bees help fertilize the flowers as they gather nectar.","deck":"vocab"},{"id":430,"word":"force field","ipa":"/ˈfɔrs ˌfild/","meaning":"방어막, 포스 필드 <눈에 보이지 않는 힘이 작용하는 영역을 나타냄>","example":"In the movie, a force field protected the entire city.","deck":"vocab"},{"id":431,"word":"sanitize","ipa":"/ˈsænɪˌtaɪz/","meaning":"소독하다 <세균 포함 미생물의 양을 안전한 수준으로 낮춘다는 뜻>","example":"Please sanitize your hands before entering the kitchen.","deck":"vocab"},{"id":432,"word":"suffer","ipa":"/ˈsʌfər/","meaning":"~을 당하다, ~을 겪다 <타동사>","example":"The region suffered severe damage from the earthquake.","deck":"vocab"},{"id":433,"word":"instance","ipa":"/ˈɪnstəns/","meaning":"사례, 경우","example":"This is just one instance of the wider problem.","deck":"vocab"},{"id":434,"word":"abstract","ipa":"/ˈæbstrækt/","meaning":"추상적인","example":"I find abstract art difficult to fully understand.","deck":"vocab"},{"id":435,"word":"coaster","ipa":"/ˈkoʊstər/","meaning":"컵받침","example":"She placed her mug on a wooden coaster.","deck":"vocab"},{"id":436,"word":"cubicle","ipa":"/ˈkjubɪkəl/","meaning":"칸막이한 공간","example":"He spends all day working in a tiny cubicle.","deck":"vocab"},{"id":437,"word":"horrendous","ipa":"/hɔˈrɛndəs/","meaning":"참혹한, 끔찍한, 대단히 충격적인","example":"The traffic this morning was absolutely horrendous.","deck":"vocab"},{"id":438,"word":"successor","ipa":"/səkˈsɛsər/","meaning":"후임자, 계승자, 계승하는 것","example":"The CEO named her successor before stepping down.","deck":"vocab"},{"id":439,"word":"controversial","ipa":"/ˌkɑntrəˈvɜrʃəl/","meaning":"논란이 많은","example":"The new policy proved deeply controversial among voters.","deck":"vocab"},{"id":440,"word":"overrate","ipa":"/ˌoʊvərˈreɪt/","meaning":"과대평가하다","example":"Critics tend to overrate his early films.","deck":"vocab"},{"id":441,"word":"come over ~","ipa":"","meaning":"(격한 감정 등이) ~에게 밀려오다","example":"A wave of sadness came over me at the ceremony.","deck":"vocab"},{"id":442,"word":"crack up","ipa":"","meaning":"웃음을 터뜨리다, 빵 터지다","example":"Her joke made the whole class crack up.","deck":"vocab"},{"id":443,"word":"tactile","ipa":"/ˈtæktəl/","meaning":"(사람이 다른 사람과의) 신체 접촉을 좋아하는","example":"He's a very tactile person who loves hugging friends.","deck":"vocab"},{"id":444,"word":"cape","ipa":"/keɪp/","meaning":"망토","example":"The superhero wore a long red cape.","deck":"vocab"},{"id":445,"word":"so much for ~","ipa":"","meaning":"~는 글렀네, ~가 무슨 소용이야, ~는 무슨 <상황 등이 기대에 못 미쳤을 때 하는 말>","example":"It's raining again, so much for our picnic plans.","deck":"vocab"},{"id":446,"word":"account for ~","ipa":"","meaning":"(부분, 비율) ~을 차지하다","example":"Exports account for nearly half of the company's revenue.","deck":"vocab"},{"id":447,"word":"ridiculous","ipa":"/rɪˈdɪkjələs/","meaning":"웃기는, 말도 안 되는, 터무니없는","example":"The price they charged was absolutely ridiculous.","deck":"vocab"},{"id":448,"word":"torture","ipa":"/ˈtɔrtʃər/","meaning":"(주로 처벌하거나 정보를 얻기 위해) 고문하다","example":"The prisoners were tortured to reveal their secrets.","deck":"vocab"},{"id":449,"word":"paranoid","ipa":"/ˈpɛrəˌnɔɪd/","meaning":"피해망상적인","example":"He became paranoid that everyone was watching him.","deck":"vocab"},{"id":450,"word":"paranoid","ipa":"/ˈpɛrəˌnɔɪd/","meaning":"편집증 환자","example":"He acts like a paranoid, suspecting everyone of lying.","deck":"vocab"},{"id":451,"word":"scorching","ipa":"/ˈskɔrtʃɪŋ/","meaning":"극도로 더운, 뜨거운","example":"We stayed indoors during the scorching afternoon heat.","deck":"vocab"},{"id":452,"word":"sequel","ipa":"/ˈsikwəl/","meaning":"속편, 후속편 <책, 영화, 연극 등의 뒤이은 이야기>","example":"The movie's sequel was even better than the original.","deck":"vocab"},{"id":453,"word":"trustee","ipa":"/trʌsˈti/","meaning":"(자선 단체나 재단 등의) 이사","example":"She serves as a trustee of the local museum.","deck":"vocab"},{"id":454,"word":"ringtone","ipa":"/ˈrɪŋˌtoʊn/","meaning":"(휴대 전화의) 신호음, 벨 소리","example":"His loud ringtone interrupted the entire meeting.","deck":"vocab"},{"id":455,"word":"glow","ipa":"/ɡloʊ/","meaning":"(기쁨, 만족감을 동반한 은근한) 행복감","example":"She felt a warm glow of pride at the award.","deck":"vocab"},{"id":456,"word":"glow","ipa":"/ɡloʊ/","meaning":"건강한 혈색 <운동 후 또는 건강함으로 인해 생기는 얼굴의 발그레한 빛을 나타냄>","example":"After her run, her cheeks had a healthy glow.","deck":"vocab"},{"id":457,"word":"buzz","ipa":"/bʌz/","meaning":"입소문, 얘기, 화제 <비격식적인 표현>","example":"There's a lot of buzz about the new restaurant downtown.","deck":"vocab"},{"id":458,"word":"buzz","ipa":"/bʌz/","meaning":"(장소가) 활기가 넘치다, 부산스럽다","example":"The market was buzzing with shoppers on Saturday morning.","deck":"vocab"},{"id":459,"word":"howdy","ipa":"/ˈhaʊdi/","meaning":"안녕 <만났을 때 하는 인사. 흔히 유머>","example":"Howdy, folks, glad you could all make it!","deck":"vocab"},{"id":460,"word":"haggle","ipa":"/ˈhæɡəl/","meaning":"(물건 값을 두고) 흥정을 하다, 실랑이를 벌이다","example":"Tourists often haggle over prices in the market.","deck":"vocab"},{"id":461,"word":"article","ipa":"/ˈɑrtɪkəl/","meaning":"관사 <문법 용어. 영어의 관사에는 a, an, the가 있음>","example":"In English, 'the' is a definite article.","deck":"vocab"},{"id":462,"word":"fulfilling","ipa":"/fʊlˈfɪlɪŋ/","meaning":"성취감을 주는","example":"She finds her volunteer work incredibly fulfilling.","deck":"vocab"},{"id":463,"word":"in exchange","ipa":"","meaning":"그 대신, 답례로","example":"He fixed my bike, and I cooked dinner in exchange.","deck":"vocab"},{"id":464,"word":"go hand in hand","ipa":"","meaning":"(~와) 밀접한 관련이 있다","example":"Success and hard work usually go hand in hand.","deck":"vocab"},{"id":465,"word":"heartbreaking","ipa":"/ˈhɑrtˌbreɪkɪŋ/","meaning":"가슴이 터질 듯한, 애끓는 마음을 자아내는","example":"The documentary told a heartbreaking story of loss.","deck":"vocab"},{"id":466,"word":"aka","ipa":"","meaning":"~라고도 알려진 <also known as의 줄임말>","example":"My uncle Robert, aka Bob, is coming to visit.","deck":"vocab"},{"id":467,"word":"throw ~ up","ipa":"","meaning":"(~을) 토하다 <비격식적인 표현>","example":"The child felt sick and threw up after lunch.","deck":"vocab"},{"id":468,"word":"accompanied by ~","ipa":"","meaning":"~을 동반한, ~가 딸린","example":"The report was accompanied by detailed charts and graphs.","deck":"vocab"},{"id":469,"word":"go downhill","ipa":"","meaning":"더 나빠지다, 질이 떨어지다, 내리막으로 접어들다","example":"His health began to go downhill after the surgery.","deck":"vocab"},{"id":470,"word":"tip over","ipa":"","meaning":"넘어지다","example":"The vase tipped over and shattered on the floor.","deck":"vocab"},{"id":471,"word":"immaculate","ipa":"/ɪˈmækjələt/","meaning":"오점이 없는, 실수가 없는, 완벽한","example":"His exam performance was immaculate, without a single error.","deck":"vocab"},{"id":472,"word":"immaculate","ipa":"/ɪˈmækjələt/","meaning":"티끌 하나 없이 깨끗한","example":"Her kitchen was immaculate, without a speck of dust.","deck":"vocab"},{"id":473,"word":"overconfident","ipa":"/ˌoʊvərˈkɑnfɪdənt/","meaning":"지나치게 자신만만한","example":"He was overconfident and underestimated his opponent.","deck":"vocab"},{"id":474,"word":"confront","ipa":"/kənˈfrʌnt/","meaning":"(상황에) 맞서다, 직면하다 <문제나 곤란한 상황이 있다는 것을 인정하고 대처한다는 뜻>","example":"Sooner or later you must confront your problems directly.","deck":"vocab"},{"id":475,"word":"confront","ipa":"/kənˈfrʌnt/","meaning":"직면하게 만들다 <주로 수동태로 쓰임. 어려움이나 힘든 문제에 부딪히게 한다는 뜻>","example":"She was confronted with a difficult moral choice.","deck":"vocab"},{"id":476,"word":"confront","ipa":"/kənˈfrʌnt/","meaning":"(사람에) 정면으로 부딪치다, 맞서다 <싸우거나 논쟁하거나 하기 위해>","example":"He confronted his coworker about the missing money.","deck":"vocab"},{"id":477,"word":"debilitating","ipa":"/dɪˈbɪlɪˌteɪtɪŋ/","meaning":"(병, 질환이 사람을) 쇠약하게 하는 <명사 앞에 올 때만 선택적으로 씀>","example":"She suffers from a debilitating chronic illness.","deck":"vocab"},{"id":478,"word":"desensitize","ipa":"/diˈsɛnsɪˌtaɪz/","meaning":"둔감하게 만들다","example":"Violent films can desensitize viewers to real suffering.","deck":"vocab"},{"id":479,"word":"to what end","ipa":"","meaning":"무슨 목적으로, 무엇을 위해","example":"You keep lying, but to what end exactly?","deck":"vocab"},{"id":480,"word":"bungle","ipa":"/ˈbʌŋɡəl/","meaning":"~을 망치다, 엉망으로 하다, 서투르게 하다","example":"The team bungled the project and lost the client.","deck":"vocab"},{"id":481,"word":"numb","ipa":"/nʌm/","meaning":"(제대로 생각, 반응을 못하고) 멍한, 망연자실한","example":"She felt numb with shock after hearing the news.","deck":"vocab"},{"id":482,"word":"numb","ipa":"/nʌm/","meaning":"(추위 등으로 신체 부위가) 감각이 없는","example":"My fingers went numb in the freezing cold.","deck":"vocab"},{"id":483,"word":"proxy","ipa":"/ˈprɑksi/","meaning":"대리인","example":"He voted by proxy since he couldn't attend.","deck":"vocab"},{"id":484,"word":"percussion","ipa":"/pərˈkʌʃən/","meaning":"타악기","example":"He plays percussion in the school orchestra.","deck":"vocab"},{"id":485,"word":"choreographer","ipa":"/ˌkɔriˈɑɡrəfər/","meaning":"안무가","example":"The choreographer designed a stunning dance for the finale.","deck":"vocab"},{"id":486,"word":"fall over","ipa":"","meaning":"넘어지다","example":"The toddler kept falling over as he learned to walk.","deck":"vocab"},{"id":487,"word":"tackle","ipa":"/ˈtækəl/","meaning":"(스포츠 활동, 특히 낚시용) 도구","example":"He packed all his fishing tackle into the truck.","deck":"vocab"},{"id":488,"word":"tackle","ipa":"/ˈtækəl/","meaning":"씨름하다, 적극적으로 나서다, 매진하다 <최선을 다해 어려운 일을 처리하려 한다는 뜻>","example":"We need to tackle this problem head-on today.","deck":"vocab"},{"id":489,"word":"hen","ipa":"/hɛn/","meaning":"암탉","example":"The hen laid three eggs this morning.","deck":"vocab"},{"id":490,"word":"rooster","ipa":"/ˈrustər/","meaning":"수탉 <주로 미국에서 쓰는 표현>","example":"The rooster crowed loudly at dawn.","deck":"vocab"},{"id":491,"word":"ruling party","ipa":"/ˈrulɪŋ ˌpɑrti/","meaning":"여당","example":"The ruling party lost its majority in the election.","deck":"vocab"},{"id":492,"word":"asthma","ipa":"/ˈæzmə/","meaning":"천식","example":"She carries an inhaler because of her asthma.","deck":"vocab"},{"id":493,"word":"way to go!","ipa":"","meaning":"잘했어!","example":"You passed the exam? Way to go!","deck":"vocab"},{"id":494,"word":"undergo","ipa":"/ˌʌndərˈɡoʊ/","meaning":"(변화, 좋지 않은 일 등을) 겪다","example":"The city has undergone dramatic changes recently.","deck":"vocab"},{"id":495,"word":"undergo","ipa":"/ˌʌndərˈɡoʊ/","meaning":"(치료, 수술, 검사 등을) 받다","example":"He will undergo surgery on his knee next week.","deck":"vocab"},{"id":496,"word":"ruffle","ipa":"/ˈrʌfəl/","meaning":"(고르게 되어 있는 것을) 헝클다, 헝클어뜨리다","example":"The wind ruffled her neatly combed hair.","deck":"vocab"},{"id":497,"word":"ruffle","ipa":"/ˈrʌfəl/","meaning":"~의 신경을 건드리다, ~의 심기를 불편하게 하다, ~를 짜증나게 하다","example":"His rude comment clearly ruffled several people at the table.","deck":"vocab"},{"id":498,"word":"liability","ipa":"/ˌlaɪəˈbɪlɪti/","meaning":"골칫거리, 폐 끼치는 사람","example":"Without training, the new hire is more of a liability.","deck":"vocab"},{"id":499,"word":"compromise","ipa":"/ˈkɑmprəˌmaɪz/","meaning":"절충안, 타협안, 절충해서 나온 것 <셀 수 있는 명사>","example":"After hours of talks, they finally reached a compromise.","deck":"vocab"},{"id":500,"word":"compromise","ipa":"/ˈkɑmprəˌmaɪz/","meaning":"(원칙 등을) 굽히다, 양보하다","example":"She refused to compromise her principles for money.","deck":"vocab"},{"id":501,"word":"compromise","ipa":"/ˈkɑmprəˌmaɪz/","meaning":"(~에 대해) 타협하다","example":"The two sides agreed to compromise on the budget.","deck":"vocab"},{"id":502,"word":"play dumb","ipa":"","meaning":"(~에게) 시치미 떼다, 모른 척하다","example":"Don't play dumb; you know exactly what happened.","deck":"vocab"},{"id":503,"word":"dwell on ~","ipa":"","meaning":"~을 곱씹다, ~을 되씹다","example":"Try not to dwell on your past mistakes.","deck":"vocab"},{"id":504,"word":"night table","ipa":"/ˈnaɪt ˌteɪbəl/","meaning":"(침대 옆에 놓는) 협탁","example":"Her glasses were resting on the night table.","deck":"vocab"},{"id":505,"word":"blunt","ipa":"/blʌnt/","meaning":"(칼날 등이) 무딘","example":"The knife was too blunt to cut the bread.","deck":"vocab"},{"id":506,"word":"go through with ~","ipa":"","meaning":"~을 거치다, ~을 하다","example":"She wasn't sure she could go through with the plan.","deck":"vocab"},{"id":507,"word":"neck and neck","ipa":"","meaning":"막상막하인, 대등하게","example":"The two runners were neck and neck at the finish.","deck":"vocab"},{"id":508,"word":"flattered","ipa":"/ˈflætərd/","meaning":"으쓱해진","example":"I was flattered when they asked me to speak.","deck":"vocab"},{"id":509,"word":"curse","ipa":"/kɜrs/","meaning":"욕, 욕설, 악담","example":"He muttered a curse under his breath.","deck":"vocab"},{"id":510,"word":"homely","ipa":"/ˈhoʊmli/","meaning":"못생긴, 매력 없는 <미국식 표현>","example":"She described herself as homely, though her friends disagreed.","deck":"vocab"},{"id":511,"word":"represent","ipa":"/ˌrɛprɪˈzɛnt/","meaning":"보여주다, 제시하다, 표현하다","example":"The graph represents our sales growth over five years.","deck":"vocab"},{"id":512,"word":"incrementally","ipa":"/ˌɪnkrəˈmɛntəli/","meaning":"점진적으로, 조금씩 증가하여","example":"The software improves incrementally with each small update.","deck":"vocab"},{"id":513,"word":"turn oneself in","ipa":"","meaning":"자수하다","example":"After days on the run, he turned himself in.","deck":"vocab"},{"id":514,"word":"harass","ipa":"/həˈræs/","meaning":"(압력을 가하거나 불쾌한 말, 행동으로) 괴롭히다 <수동태로 자주 쓰임>","example":"She was harassed by anonymous phone calls for weeks.","deck":"vocab"},{"id":515,"word":"amnesia","ipa":"/æmˈniʒə/","meaning":"기억 상실, 기억 상실증","example":"After the accident, he suffered from temporary amnesia.","deck":"vocab"},{"id":516,"word":"on it","ipa":"","meaning":"할 마음이 있다, 바로 착수하겠다","example":"Don't worry about the report; I'm on it.","deck":"vocab"},{"id":517,"word":"cohesive","ipa":"/koʊˈhisɪv/","meaning":"화합하는, 응집력 있는, 결합력 있는","example":"A good leader keeps the team cohesive and focused.","deck":"vocab"},{"id":518,"word":"get by","ipa":"","meaning":"(~으로) 그럭저럭 해 나가다, 그럭저럭 살아가다","example":"They barely get by on his small salary.","deck":"vocab"},{"id":519,"word":"manipulative","ipa":"/məˈnɪpjələtɪv/","meaning":"교묘하게 조종하는, 조종하는 데 능한","example":"Her manipulative behavior slowly turned friends against each other.","deck":"vocab"},{"id":520,"word":"designate","ipa":"/ˈdɛzɪɡˌneɪt/","meaning":"지정하다","example":"They designated the room as a quiet study area.","deck":"vocab"},{"id":521,"word":"ashamed","ipa":"/əˈʃeɪmd/","meaning":"(~여서, ~해서) 부끄러운, 창피한, 수치스러운","example":"He felt deeply ashamed of his rude behavior.","deck":"vocab"},{"id":522,"word":"close","ipa":"/kloʊs/","meaning":"거의 ~할 것 같은, 곧 ~할 것 같은 <명사 앞에는 안 씀>","example":"We were close to finishing when the power failed.","deck":"vocab"},{"id":523,"word":"graffiti","ipa":"/ɡrəˈfiti/","meaning":"(공공장소에 하는) 낙서, 그래피티","example":"The wall was covered in colorful graffiti.","deck":"vocab"},{"id":524,"word":"metabolic","ipa":"/ˌmɛtəˈbɑlɪk/","meaning":"신진대사의, 대사 작용의 <생물학 용어>","example":"Exercise can boost your metabolic rate significantly.","deck":"vocab"},{"id":525,"word":"laugh ~ out of ~","ipa":"","meaning":"~를 비웃어서 ~에서 내쫓다","example":"They laughed him out of the room for his silly idea.","deck":"vocab"},{"id":526,"word":"canny","ipa":"/ˈkæni/","meaning":"영리한, 약삭빠른","example":"She made a canny investment that doubled her money.","deck":"vocab"},{"id":527,"word":"stipulate","ipa":"/ˈstɪpjəˌleɪt/","meaning":"~을 규정하다, 명기하다, 명문화하다","example":"The contract stipulates that payment is due monthly.","deck":"vocab"},{"id":528,"word":"shore","ipa":"/ʃɔr/","meaning":"(특히 해안을 끼고 있는) 국가, 나라 <복수형으로 씀. 문어적 표현>","example":"Sailors longed to return to their native shores.","deck":"vocab"},{"id":529,"word":"pull oneself together","ipa":"","meaning":"정신 똑바로 차리다, 진정하다, 냉정을 되찾다","example":"After crying, she pulled herself together and continued.","deck":"vocab"},{"id":530,"word":"hitman","ipa":"/ˈhɪtmæn/","meaning":"살인 청부업자 <비격식>","example":"The gangster hired a hitman to silence the witness.","deck":"vocab"},{"id":531,"word":"possess","ipa":"/pəˈzɛs/","meaning":"(이해할 수 없는 짓을 하도록) 홀리다","example":"Some madness must have possessed him to do that.","deck":"vocab"},{"id":532,"word":"possess","ipa":"/pəˈzɛs/","meaning":"(자질, 특징을) 지니다, 갖추고 있다","example":"She possesses all the qualities of a great leader.","deck":"vocab"},{"id":533,"word":"call for ~","ipa":"","meaning":"(사물을 주어로 하여) ~을 필요로 하다","example":"This recipe calls for two cups of flour.","deck":"vocab"},{"id":534,"word":"retrieve","ipa":"/rɪˈtriv/","meaning":"되찾다, 회수하다 <격식 있는 표현>","example":"He dove into the lake to retrieve his keys.","deck":"vocab"},{"id":535,"word":"retrieve","ipa":"/rɪˈtriv/","meaning":"~을 상기하다, 다시 생각해 내다","example":"She struggled to retrieve the name from her memory.","deck":"vocab"},{"id":536,"word":"retrieve","ipa":"/rɪˈtriv/","meaning":"불러오다, 다시 불러오다","example":"Click here to retrieve your saved documents.","deck":"vocab"},{"id":537,"word":"combo","ipa":"/ˈkɑmboʊ/","meaning":"조합, 결합, 조합된 것, 결합된 것","example":"The burger and fries combo is a great deal.","deck":"vocab"},{"id":538,"word":"retort","ipa":"/rɪˈtɔrt/","meaning":"쏘아붙이다, 말대꾸하다, 응수하다","example":"She retorted sharply that it was none of my business.","deck":"vocab"},{"id":539,"word":"move","ipa":"/muv/","meaning":"조치, 행동","example":"Quitting his job was a bold move.","deck":"vocab"},{"id":540,"word":"take offense","ipa":"","meaning":"(~에) 기분이 상하다, 불쾌하게 생각하다","example":"Please don't take offense at my honest opinion.","deck":"vocab"},{"id":541,"word":"mint","ipa":"/mɪnt/","meaning":"완전히 새것 같은, 제조 직후의 상태와 같은, 갓 발행된","example":"The old coin was in mint condition.","deck":"vocab"},{"id":542,"word":"mint","ipa":"/mɪnt/","meaning":"많은 돈 <비격식적인 표현>","example":"He must be earning a mint at that new firm.","deck":"vocab"},{"id":543,"word":"makeover","ipa":"/ˈmeɪkˌoʊvər/","meaning":"단장, 변신","example":"The tired living room got a complete makeover.","deck":"vocab"},{"id":544,"word":"gear","ipa":"/ɡɪr/","meaning":"(특정 활동에 필요한) 장비, 복장","example":"Remember to bring your hiking gear tomorrow.","deck":"vocab"},{"id":545,"word":"jaywalk","ipa":"/ˈdʒeɪˌwɔk/","meaning":"(도로를) 무단 횡단하다","example":"The officer fined him for jaywalking across the avenue.","deck":"vocab"},{"id":546,"word":"crescent","ipa":"/ˈkrɛsənt/","meaning":"초승달 모양의","example":"A thin crescent moon hung in the night sky.","deck":"vocab"},{"id":547,"word":"aversion","ipa":"/əˈvɜrʒən/","meaning":"(~에 대한) 혐오감, 아주 싫어함","example":"She has a strong aversion to spiders.","deck":"vocab"},{"id":548,"word":"pull","ipa":"/pʊl/","meaning":"(행사, 광고 등을) 취소하다, 거둬들이다","example":"The network pulled the ad after public complaints.","deck":"vocab"},{"id":549,"word":"majestic","ipa":"/məˈdʒɛstɪk/","meaning":"장엄한, 위풍당당한","example":"The majestic mountains towered above the valley.","deck":"vocab"},{"id":550,"word":"snippy","ipa":"/ˈsnɪpi/","meaning":"무뚝뚝한, 상냥하지 못한, 건방진, 까칠한","example":"He got snippy with me for no reason.","deck":"vocab"},{"id":551,"word":"mockery","ipa":"/ˈmɑkəri/","meaning":"조롱, 조소","example":"Her cruel mockery left him feeling humiliated.","deck":"vocab"},{"id":552,"word":"frantic","ipa":"/ˈfræntɪk/","meaning":"(사람이 두려움, 걱정 등으로) 제정신이 아닌","example":"The frantic mother searched everywhere for her child.","deck":"vocab"},{"id":553,"word":"sonogram","ipa":"/ˈsɑnəˌɡræm/","meaning":"초음파 사진","example":"The doctor showed us the baby's first sonogram.","deck":"vocab"},{"id":554,"word":"well-to-do","ipa":"/ˌwɛl tə ˈdu/","meaning":"부유한, 잘사는","example":"They grew up in a well-to-do neighborhood.","deck":"vocab"},{"id":555,"word":"as far as","ipa":"","meaning":"(부사절을 이끌어) ~하는 한","example":"As far as I know, the meeting is still on.","deck":"vocab"},{"id":556,"word":"as far as","ipa":"","meaning":"(거리, 범위 등이) ~까지","example":"We walked as far as the old bridge and back.","deck":"vocab"},{"id":557,"word":"sore loser","ipa":"/ˈsɔr ˌluzər/","meaning":"패배를 인정할 줄 모르는 사람","example":"Don't be such a sore loser about the game.","deck":"vocab"},{"id":558,"word":"don't start","ipa":"","meaning":"불평하지 마, 투덜거리지 마, 잔소리하지 마","example":"Don't start with me about the dishes again.","deck":"vocab"},{"id":559,"word":"that is it","ipa":"","meaning":"그만해, 더는 안 되겠어 <화가 나서 더 이상 못 참겠다는 뜻>","example":"That's it, I'm not tolerating this anymore!","deck":"vocab"},{"id":560,"word":"cheesy","ipa":"/ˈtʃizi/","meaning":"유치한, 진부한, 오글거리는, 촌스러운","example":"The movie's ending was so cheesy it made me groan.","deck":"vocab"},{"id":561,"word":"perspective","ipa":"/pərˈspɛktɪv/","meaning":"균형감, 균형 잡힌 관점","example":"Traveling gave her a fresh perspective on life.","deck":"vocab"},{"id":562,"word":"compatible","ipa":"/kəmˈpætəbəl/","meaning":"화합할 수 있는, 사이좋게 지낼 수 있는","example":"The new roommates turned out to be very compatible.","deck":"vocab"},{"id":563,"word":"formality","ipa":"/fɔrˈmælɪti/","meaning":"형식적인 일, 의례적인 일 <주로 단수형으로 씀>","example":"Signing the form is just a formality.","deck":"vocab"},{"id":564,"word":"motion","ipa":"/ˈmoʊʃən/","meaning":"(의회 등에서) 발의, 제의, 제안","example":"The committee voted to approve the motion.","deck":"vocab"},{"id":565,"word":"closet","ipa":"/ˈklɑzɪt/","meaning":"(집 구조의 일부분으로 설계된) 벽장, 붙박이장","example":"She hung her coat in the hallway closet.","deck":"vocab"},{"id":566,"word":"closet","ipa":"/ˈklɑzɪt/","meaning":"은밀한, 드러나지 않은, 본인만 알고 있는","example":"He's a closet fan of cheesy pop music.","deck":"vocab"},{"id":567,"word":"ruthless","ipa":"/ˈruθləs/","meaning":"무자비한, 가차 없는, 인정사정없는 <못마땅함>","example":"The dictator was ruthless in crushing all opposition.","deck":"vocab"},{"id":568,"word":"put ~ up","ipa":"","meaning":"~을 붙이다, ~을 내붙이다","example":"They put up posters advertising the concert.","deck":"vocab"},{"id":569,"word":"disciplinary action","ipa":"/ˈdɪsəplɪˌnɛri ˌækʃən/","meaning":"징계 처분, 징계 조치","example":"The employee faced disciplinary action for the violation.","deck":"vocab"},{"id":570,"word":"put ~ out","ipa":"","meaning":"내다, 발표하다, 발행하다","example":"The company put out a statement denying the rumors.","deck":"vocab"},{"id":571,"word":"put ~ out","ipa":"","meaning":"(불 등을) 끄다","example":"Firefighters quickly put out the blaze.","deck":"vocab"},{"id":572,"word":"glacier","ipa":"/ˈɡleɪʃər/","meaning":"빙하","example":"The glacier has retreated significantly over the decades.","deck":"vocab"},{"id":573,"word":"impatient","ipa":"/ɪmˈpeɪʃənt/","meaning":"짜증 난, 안달하는, 안달 난","example":"He grew impatient waiting for the late train.","deck":"vocab"},{"id":574,"word":"United States Attorney","ipa":"/juˌnaɪtɪd ˈsteɪts əˈtɜrni/","meaning":"미국 연방 검사","example":"The United States Attorney announced the indictment today.","deck":"vocab"},{"id":575,"word":"captivating","ipa":"/ˈkæptɪˌveɪtɪŋ/","meaning":"매혹적인","example":"She gave a captivating performance that held the audience.","deck":"vocab"},{"id":576,"word":"devastating","ipa":"/ˈdɛvəˌsteɪtɪŋ/","meaning":"대단히 파괴적인, 엄청난 손상을 가하는","example":"The flood had a devastating effect on the town.","deck":"vocab"},{"id":577,"word":"devastating","ipa":"/ˈdɛvəˌsteɪtɪŋ/","meaning":"엄청나게 충격적인","example":"Losing the championship was a devastating blow to the team.","deck":"vocab"},{"id":578,"word":"get down to ~","ipa":"","meaning":"~을 시작하다","example":"Let's stop chatting and get down to business.","deck":"vocab"},{"id":579,"word":"go down","ipa":"","meaning":"(~에) 기록되다, 기억되다","example":"This day will go down in history.","deck":"vocab"},{"id":580,"word":"see","ipa":"/si/","meaning":"상상하다, 예상하다, 보다","example":"I can't see him ever agreeing to that plan.","deck":"vocab"},{"id":581,"word":"pros and cons","ipa":"","meaning":"찬반양론","example":"We weighed the pros and cons before deciding.","deck":"vocab"},{"id":582,"word":"pros and cons","ipa":"","meaning":"장단점","example":"Every option has its pros and cons to consider.","deck":"vocab"},{"id":583,"word":"kick in","ipa":"","meaning":"효과가 나타나기 시작하다","example":"The painkillers finally started to kick in.","deck":"vocab"},{"id":584,"word":"up next","ipa":"","meaning":"다음 순서","example":"Up next, we have the weather forecast.","deck":"vocab"},{"id":585,"word":"impression","ipa":"/ɪmˈprɛʃən/","meaning":"흉내, 성대모사 <사람들을 웃기기 위해 유명인이나 동물, 사물의 소리나 행동을 따라 하는 것>","example":"He did a hilarious impression of the president.","deck":"vocab"},{"id":586,"word":"infant","ipa":"/ˈɪnfənt/","meaning":"초창기의, 초기의","example":"The company was still in its infant stages then.","deck":"vocab"},{"id":587,"word":"rule ~ out","ipa":"","meaning":"(사람이 생각, 계획, 해법 등을) ~을 배제하다 <불가능하거나 부적절하다고 여겨서>","example":"Doctors ruled out cancer after the tests.","deck":"vocab"},{"id":588,"word":"proficient","ipa":"/prəˈfɪʃənt/","meaning":"능통한, 능숙한, 능한","example":"She is proficient in three foreign languages.","deck":"vocab"},{"id":589,"word":"stall","ipa":"/stɔl/","meaning":"교착 상태에 빠지다, 지연되다","example":"Negotiations stalled over the question of wages.","deck":"vocab"},{"id":590,"word":"stall","ipa":"/stɔl/","meaning":"칸막이 안 <칸막이를 쳐서 만들어 놓은 샤워실이나 화장실 등을 나타냄>","example":"She waited for an empty stall in the restroom.","deck":"vocab"},{"id":591,"word":"tender","ipa":"/ˈtɛndər/","meaning":"입찰","example":"Several firms submitted a tender for the contract.","deck":"vocab"},{"id":592,"word":"brutally","ipa":"/ˈbrutəli/","meaning":"야만스럽게, 난폭하게, 짐승처럼, 잔인하게","example":"The soldiers brutally attacked the defenseless village.","deck":"vocab"},{"id":593,"word":"long face","ipa":"/ˈlɔŋ ˌfeɪs/","meaning":"시무룩한 얼굴, 우울한 표정","example":"Why the long face? Cheer up a little.","deck":"vocab"},{"id":594,"word":"gaze","ipa":"/ɡeɪz/","meaning":"(눈여겨 보는) 시선, 눈길, 응시 <주로 단수형으로 씀>","example":"She felt his steady gaze across the room.","deck":"vocab"},{"id":595,"word":"rephrase","ipa":"/riˈfreɪz/","meaning":"(뜻을 더 분명히 하기 위해) 바꾸어 말하다","example":"Let me rephrase that to make it clearer.","deck":"vocab"},{"id":596,"word":"puffy","ipa":"/ˈpʌfi/","meaning":"(눈, 얼굴 등이) 부어 있는","example":"Her eyes were puffy from crying all night.","deck":"vocab"},{"id":597,"word":"air","ipa":"/ɛr/","meaning":"방송되다","example":"The show first aired on television in 1995.","deck":"vocab"},{"id":598,"word":"turnover","ipa":"/ˈtɜrnˌoʊvər/","meaning":"(기업의 직원) 이직률","example":"The company struggles with high staff turnover.","deck":"vocab"},{"id":599,"word":"straight face","ipa":"/ˈstreɪt ˌfeɪs/","meaning":"진지한 표정, 정색","example":"I could barely keep a straight face during his speech.","deck":"vocab"},{"id":600,"word":"drive under the influence","ipa":"","meaning":"음주운전을 하다","example":"He was arrested for driving under the influence last night.","deck":"vocab"},{"id":601,"word":"take ~ up","ipa":"","meaning":"(특히 재미로) ~을 배우다, ~을 시작하다","example":"She decided to take painting up as a relaxing weekend hobby.","deck":"vocab"},{"id":602,"word":"take ~ up","ipa":"","meaning":"(직장, 작업, 임무, 역할 등을) 시작하다","example":"He will take up his new role as manager next Monday.","deck":"vocab"},{"id":603,"word":"resilient","ipa":"/rɪˈzɪliənt/","meaning":"(충격, 부상 등에 대해) 회복력 있는","example":"Children are often surprisingly resilient after difficult experiences.","deck":"vocab"},{"id":604,"word":"resilient","ipa":"/rɪˈzɪliənt/","meaning":"(물질이) 탄력 있는","example":"This resilient rubber quickly returns to its original shape.","deck":"vocab"},{"id":605,"word":"frail","ipa":"/freɪl/","meaning":"약한, 허약한, 부서지기 쉬운","example":"The frail old man could barely climb the stairs.","deck":"vocab"},{"id":606,"word":"rocky","ipa":"/ˈrɑki/","meaning":"고난이 많은, 험난한","example":"Their marriage went through a rocky period last year.","deck":"vocab"},{"id":607,"word":"brow","ipa":"/braʊ/","meaning":"이마 <문학적 표현>","example":"Sweat glistened on his furrowed brow in the heat.","deck":"vocab"},{"id":608,"word":"go over ~","ipa":"","meaning":"~을 다시 말하다, 반복하다","example":"Let's go over the plan once more before the meeting.","deck":"vocab"},{"id":609,"word":"vulnerability","ipa":"/ˌvʌlnərəˈbɪləti/","meaning":"상처받기 쉬움, 취약성","example":"The hacker exploited a vulnerability in the company's security system.","deck":"vocab"},{"id":610,"word":"cross","ipa":"/krɔs/","meaning":"짜증난, 약간 화가 난","example":"Please don't be cross with me for being late.","deck":"vocab"},{"id":611,"word":"check up on","ipa":"","meaning":"~을 확인하다","example":"I called to check up on my grandmother this morning.","deck":"vocab"},{"id":612,"word":"anthropologist","ipa":"/ˌænθrəˈpɑlədʒɪst/","meaning":"인류학자","example":"The anthropologist studied ancient tribal customs for many years.","deck":"vocab"},{"id":613,"word":"coffin","ipa":"/ˈkɔfɪn/","meaning":"(시체를 담는) 관 <어깨 쪽이 넓고 아래로 갈수록 좁아지는 형태>","example":"They lowered the wooden coffin slowly into the grave.","deck":"vocab"},{"id":614,"word":"account","ipa":"/əˈkaʊnt/","meaning":"(있었던 일에 대한) 설명, 이야기, 말","example":"She gave a detailed account of what happened that night.","deck":"vocab"},{"id":615,"word":"choosy","ipa":"/ˈtʃuzi/","meaning":"까다로운, 가리는 게 많은","example":"He is very choosy about the restaurants he visits.","deck":"vocab"},{"id":616,"word":"paramount","ipa":"/ˈpærəmaʊnt/","meaning":"다른 무엇보다 중요한, 가장 중요한","example":"Safety is paramount when working with heavy machinery.","deck":"vocab"},{"id":617,"word":"insolence","ipa":"/ˈɪnsələns/","meaning":"건방짐, 오만, 건방진 태도, 건방진 짓","example":"The teacher would not tolerate such insolence from students.","deck":"vocab"},{"id":618,"word":"spinal cord","ipa":"/ˈspaɪnəl ˌkɔrd/","meaning":"척수, 등골 <뇌와 연결되어 있고, 척추 내에 위치하는 중추 신경>","example":"The accident damaged his spinal cord and affected his legs.","deck":"vocab"},{"id":619,"word":"stutter","ipa":"/ˈstʌtər/","meaning":"말을 더듬다, 더듬거리다","example":"He tends to stutter when he feels nervous or anxious.","deck":"vocab"},{"id":620,"word":"husband","ipa":"/ˈhʌzbənd/","meaning":"절약하다","example":"They had to husband their resources during the long winter.","deck":"vocab"},{"id":621,"word":"live ~ down","ipa":"","meaning":"만회하다, 다른 사람들이 잊게 만들다 <주로 부정문으로 쓰임>","example":"He could never live down the embarrassing mistake he made.","deck":"vocab"},{"id":622,"word":"faculty","ipa":"/ˈfækəlti/","meaning":"(사람이 타고나는 신체적, 정신적) 능력, 기능","example":"Losing his sense of smell meant losing a vital faculty.","deck":"vocab"},{"id":623,"word":"faculty","ipa":"/ˈfækəlti/","meaning":"(대학의) 교수진, 교수들","example":"The university faculty voted to change the curriculum.","deck":"vocab"},{"id":624,"word":"jacked","ipa":"/dʒækt/","meaning":"(사람이) 근육질인","example":"After months at the gym, he got really jacked.","deck":"vocab"},{"id":625,"word":"put","ipa":"/pʊt/","meaning":"(감정, 영향 등을) 겪게 하다, 가하다, 주다","example":"The tragedy put her through tremendous emotional pain.","deck":"vocab"},{"id":626,"word":"put","ipa":"/pʊt/","meaning":"쓰다, 사용하다, 투입하다, 적용하다","example":"We should put these funds to better use.","deck":"vocab"},{"id":627,"word":"pest","ipa":"/pɛst/","meaning":"성가신 사람, 성가신 것 <비격식>","example":"Her little brother is such a pest during dinner.","deck":"vocab"},{"id":628,"word":"crumple","ipa":"/ˈkrʌmpəl/","meaning":"구기다","example":"He began to crumple the letter in frustration.","deck":"vocab"},{"id":629,"word":"hit the road","ipa":"","meaning":"길을 나서다, 떠나다","example":"It's getting late, so we should hit the road now.","deck":"vocab"},{"id":630,"word":"contentious","ipa":"/kənˈtɛnʃəs/","meaning":"(회의, 토론 등이) 격렬한 논쟁이 벌어지는","example":"The meeting became contentious when they discussed the budget.","deck":"vocab"},{"id":631,"word":"contentious","ipa":"/kənˈtɛnʃəs/","meaning":"많은 논쟁을 불러일으키는, 논쟁을 초래할","example":"Gun control remains a highly contentious issue in America.","deck":"vocab"},{"id":632,"word":"immature","ipa":"/ˌɪməˈtʊr/","meaning":"미성숙한, 치기 어린, 미숙한","example":"His immature behavior at the party embarrassed everyone.","deck":"vocab"},{"id":633,"word":"adamant","ipa":"/ˈædəmənt/","meaning":"요지부동의, 단호한","example":"She was adamant that she would not change her mind.","deck":"vocab"},{"id":634,"word":"overstate","ipa":"/ˌoʊvərˈsteɪt/","meaning":"(실제보다 더 중요한 것처럼) 과장하다","example":"Don't overstate the problem; it's not that serious.","deck":"vocab"},{"id":635,"word":"astonishingly","ipa":"/əˈstɑnɪʃɪŋli/","meaning":"놀랄 만큼, 놀랍게도, 몹시","example":"The test was astonishingly easy for most of the students.","deck":"vocab"},{"id":636,"word":"jersey","ipa":"/ˈdʒɜrzi/","meaning":"(운동 경기용) 셔츠","example":"He proudly wore his team's jersey to the game.","deck":"vocab"},{"id":637,"word":"vomit","ipa":"/ˈvɑmɪt/","meaning":"토하다, 게우다","example":"The rough boat ride made several passengers vomit.","deck":"vocab"},{"id":638,"word":"primarily","ipa":"/praɪˈmɛrəli/","meaning":"주로","example":"The museum is primarily funded by private donations.","deck":"vocab"},{"id":639,"word":"flipper","ipa":"/ˈflɪpər/","meaning":"(바다표범, 거북 등의) 지느러미발","example":"The seal used its powerful flippers to swim quickly.","deck":"vocab"},{"id":640,"word":"catfish","ipa":"/ˈkætfɪʃ/","meaning":"소셜미디어에서 거짓 신분을 만들어내거나 자신을 거짓 포장하는 사람","example":"She discovered the online date was actually a catfish.","deck":"vocab"},{"id":641,"word":"impound","ipa":"/ɪmˈpaʊnd/","meaning":"(경찰, 법정 등이) 압수하다, 몰수하다","example":"The police will impound your car if you park here.","deck":"vocab"},{"id":642,"word":"reptile","ipa":"/ˈrɛptaɪl/","meaning":"파충류","example":"A snake is a reptile that sheds its skin regularly.","deck":"vocab"},{"id":643,"word":"testify","ipa":"/ˈtɛstɪfaɪ/","meaning":"(~임을) 증명하다, (~의) 증거가 되다","example":"Her success testifies to years of hard work.","deck":"vocab"},{"id":644,"word":"testify","ipa":"/ˈtɛstɪfaɪ/","meaning":"(특히 법정에서) 증언하다, 진술하다","example":"He agreed to testify against the accused in court.","deck":"vocab"},{"id":645,"word":"gem","ipa":"/dʒɛm/","meaning":"보물, 보배 <특히 훌륭하거나 특별한 사람이나 사물을 비유적으로 이르는 말>","example":"This little cafe is a real gem in the neighborhood.","deck":"vocab"},{"id":646,"word":"spoil","ipa":"/spɔɪl/","meaning":"~를 응석받이로 키우다 <아이가 해 달라는 대로 다 해 주는 것>","example":"Grandparents often spoil their grandchildren with too many gifts.","deck":"vocab"},{"id":647,"word":"on hand","ipa":"","meaning":"구할 수 있는, 쉽게 사용할 수 있는","example":"Always keep some cash on hand for emergencies.","deck":"vocab"},{"id":648,"word":"team up","ipa":"","meaning":"(~와) 한 팀이 되다, 협력하다","example":"The two companies decided to team up on the project.","deck":"vocab"},{"id":649,"word":"long before ~","ipa":"","meaning":"~하기 훨씬 전에","example":"He had left the city long before the storm arrived.","deck":"vocab"},{"id":650,"word":"nauseous","ipa":"/ˈnɔʃəs/","meaning":"욕지기나는, 메스꺼운","example":"The smell of gasoline made her feel nauseous.","deck":"vocab"},{"id":651,"word":"over one's head","ipa":"","meaning":"~가 이해할 수 없는, 이해하기 힘든","example":"The advanced lecture was completely over my head.","deck":"vocab"},{"id":652,"word":"any minute","ipa":"","meaning":"지금 곧, 당장에라도, 금방이라도","example":"The bus should arrive any minute now.","deck":"vocab"},{"id":653,"word":"manslaughter","ipa":"/ˈmænslɔtər/","meaning":"과실치사 <과실 행위로 사람을 죽이는 일>","example":"He was convicted of manslaughter after the fatal accident.","deck":"vocab"},{"id":654,"word":"meet up","ipa":"","meaning":"만나다","example":"Let's meet up for coffee sometime next week.","deck":"vocab"},{"id":655,"word":"mandatory","ipa":"/ˈmændəˌtɔri/","meaning":"법에 정해진, 의무적인","example":"Wearing a seatbelt is mandatory in most countries.","deck":"vocab"},{"id":656,"word":"discontent","ipa":"/ˌdɪskənˈtɛnt/","meaning":"만족스럽지 않은, 불만인","example":"The workers grew discontent over their low wages.","deck":"vocab"},{"id":657,"word":"discontent","ipa":"/ˌdɪskənˈtɛnt/","meaning":"불만, 불만스러운 것","example":"There was growing discontent among the employees.","deck":"vocab"},{"id":658,"word":"tenderize","ipa":"/ˈtɛndəraɪz/","meaning":"(고기를) 부드럽게 만들다","example":"Marinate the meat overnight to tenderize it properly.","deck":"vocab"},{"id":659,"word":"overcast","ipa":"/ˈoʊvərkæst/","meaning":"구름이 뒤덮인, 흐린, 우중충한","example":"The sky was gray and overcast all afternoon.","deck":"vocab"},{"id":660,"word":"overdue","ipa":"/ˌoʊvərˈdu/","meaning":"벌써 행해졌어야 할, 이미 늦어진","example":"A serious reform of the system is long overdue.","deck":"vocab"},{"id":661,"word":"overdue","ipa":"/ˌoʊvərˈdu/","meaning":"(지불, 반납 등의) 기한이 지난","example":"The library book is two weeks overdue now.","deck":"vocab"},{"id":662,"word":"up in arms","ipa":"","meaning":"(~에) 격분한, 반기를 들고 일어나는","example":"Residents are up in arms about the new highway plan.","deck":"vocab"},{"id":663,"word":"squander","ipa":"/ˈskwɑndər/","meaning":"낭비하다, 허비하다","example":"He squandered his entire inheritance on gambling.","deck":"vocab"},{"id":664,"word":"intimate","ipa":"/ˈɪntəmət/","meaning":"(사람들이) 친한, 친밀한","example":"They have been intimate friends since childhood.","deck":"vocab"},{"id":665,"word":"intimate","ipa":"/ˈɪntəmət/","meaning":"분위기 있는","example":"The restaurant has a warm, intimate atmosphere.","deck":"vocab"},{"id":666,"word":"idiomatic","ipa":"/ˌɪdiəˈmætɪk/","meaning":"(모국어 화자가 듣기에 표현이) 자연스러운","example":"Her English sounds natural and idiomatic to native speakers.","deck":"vocab"},{"id":667,"word":"under siege","ipa":"","meaning":"(군대나 경찰 등에) 포위당한","example":"The castle was under siege for several months.","deck":"vocab"},{"id":668,"word":"uptight","ipa":"/ˌʌpˈtaɪt/","meaning":"불안해 하는, 긴장한, 화난","example":"He gets uptight whenever he has to speak publicly.","deck":"vocab"},{"id":669,"word":"uptight","ipa":"/ˌʌpˈtaɪt/","meaning":"(사람이) 앞뒤가 꽉 막힌","example":"Don't be so uptight; just relax and have fun.","deck":"vocab"},{"id":670,"word":"there is no point","ipa":"","meaning":"(~하는 것은) 의미가 없다, 무의미하다","example":"There is no point in arguing about it now.","deck":"vocab"},{"id":671,"word":"benchmark","ipa":"/ˈbɛntʃmɑrk/","meaning":"기준, 기준점","example":"This test sets a benchmark for future performance.","deck":"vocab"},{"id":672,"word":"move up","ipa":"","meaning":"일정을 당기다","example":"They decided to move up the wedding to June.","deck":"vocab"},{"id":673,"word":"discreet","ipa":"/dɪˈskrit/","meaning":"신중한, 조심스러운","example":"Please be discreet about what I told you.","deck":"vocab"},{"id":674,"word":"striking","ipa":"/ˈstraɪkɪŋ/","meaning":"굉장히 매력적인, 빼어난","example":"She has striking green eyes that everyone notices.","deck":"vocab"},{"id":675,"word":"word","ipa":"/wɜrd/","meaning":"찬성이요, 동감이요","example":"Word, that concert last night was absolutely amazing!","deck":"vocab"},{"id":676,"word":"deceptively","ipa":"/dɪˈsɛptɪvli/","meaning":"믿을 수 없게 <예상과 너무 다르다는 것을 강조하는 표현>","example":"The path looked deceptively easy at first glance.","deck":"vocab"},{"id":677,"word":"disrupt","ipa":"/dɪsˈrʌpt/","meaning":"파괴적으로 재창조하다, 혁신하다 <기술 분야에서 주로 쓰임>","example":"Their new app aims to disrupt the entire industry.","deck":"vocab"},{"id":678,"word":"come through","ipa":"","meaning":"(~을) 해내다, 완수하다","example":"I knew you would come through for us in the end.","deck":"vocab"},{"id":679,"word":"once in a lifetime","ipa":"","meaning":"(아주 특별하여) 평생 단 한 번뿐인","example":"This is a once in a lifetime opportunity to travel there.","deck":"vocab"},{"id":680,"word":"indecisive","ipa":"/ˌɪndɪˈsaɪsɪv/","meaning":"(사람이) 우유부단한","example":"He is so indecisive that choosing dinner takes forever.","deck":"vocab"},{"id":681,"word":"diner","ipa":"/ˈdaɪnər/","meaning":"(특히 식당에서) 식사하는 사람, 손님","example":"The waiter served each diner with a warm smile.","deck":"vocab"},{"id":682,"word":"astrology","ipa":"/əˈstrɑlədʒi/","meaning":"점성술","example":"She reads about astrology and checks her horoscope daily.","deck":"vocab"},{"id":683,"word":"drape","ipa":"/dreɪp/","meaning":"긴 커튼","example":"She pulled the heavy drapes closed at night.","deck":"vocab"},{"id":684,"word":"fall through","ipa":"","meaning":"(약속, 계획 등이) 깨지다, 실현되지 못하다","example":"Our vacation plans fell through at the last minute.","deck":"vocab"},{"id":685,"word":"immune","ipa":"/ɪˈmjun/","meaning":"(~이) 면제되는, (~을) 면하는","example":"No one is immune from criticism, not even the boss.","deck":"vocab"},{"id":686,"word":"immune","ipa":"/ɪˈmjun/","meaning":"(질병에) (~에) 면역성이 있는","example":"Vaccination makes you immune to many serious diseases.","deck":"vocab"},{"id":687,"word":"dunk","ipa":"/dʌŋk/","meaning":"(물이나 액체 등에) 적시기, 담그기","example":"He gave the biscuit a quick dunk in his tea.","deck":"vocab"},{"id":688,"word":"dunk","ipa":"/dʌŋk/","meaning":"덩크슛하다 <농구 용어>","example":"The player leaped high to dunk the basketball.","deck":"vocab"},{"id":689,"word":"immortal","ipa":"/ɪˈmɔrtəl/","meaning":"죽지 않는, 불사의, 불멸의","example":"In the myth, the gods were immortal and never aged.","deck":"vocab"},{"id":690,"word":"groovy","ipa":"/ˈɡruvi/","meaning":"멋진, 근사한 <구식 표현>","example":"That's a really groovy jacket you're wearing today.","deck":"vocab"},{"id":691,"word":"could use","ipa":"","meaning":"필요하다, ~가 있으면 좋겠다","example":"I could use a cup of coffee right about now.","deck":"vocab"},{"id":692,"word":"tumble","ipa":"/ˈtʌmbəl/","meaning":"굴러 떨어지다 <보통 심한 부상을 입지는 않았을 때 씀>","example":"She tumbled down the grassy hill, laughing the whole way.","deck":"vocab"},{"id":693,"word":"tumble","ipa":"/ˈtʌmbəl/","meaning":"폭삭 무너지다","example":"House prices tumbled during the economic crisis.","deck":"vocab"},{"id":694,"word":"skim","ipa":"/skɪm/","meaning":"(책, 신문 등을) 훑어보다","example":"I only had time to skim the newspaper this morning.","deck":"vocab"},{"id":695,"word":"recline","ipa":"/rɪˈklaɪn/","meaning":"(사람이) 비스듬히 눕다, 비스듬히 기대다","example":"He likes to recline on the sofa after a long day.","deck":"vocab"},{"id":696,"word":"set ~ off","ipa":"","meaning":"(폭탄, 폭죽 등을) 터뜨리다","example":"They set off fireworks to celebrate the new year.","deck":"vocab"},{"id":697,"word":"folk","ipa":"/foʊk/","meaning":"(복수형으로 쓰여) 사람들, 분들 <people보다 친근감이 있는 표현>","example":"The folks in this town are very friendly and kind.","deck":"vocab"},{"id":698,"word":"folk","ipa":"/foʊk/","meaning":"여러분 <복수형으로 쓰여 두 사람 이상을 친근하게 부를 때 쓰는 표현>","example":"Thanks for coming, folks; enjoy the show tonight!","deck":"vocab"},{"id":699,"word":"perseverance","ipa":"/ˌpɜrsəˈvɪrəns/","meaning":"인내, 인내심, 끈기","example":"Her perseverance eventually led to great success.","deck":"vocab"},{"id":700,"word":"grit","ipa":"/ɡrɪt/","meaning":"모래, 아주 작은 돌 조각들 <셀 수 없는 명사>","example":"He felt grit in his shoes after walking on the beach.","deck":"vocab"},{"id":701,"word":"grit","ipa":"/ɡrɪt/","meaning":"투지, 기개 <셀 수 없는 명사>","example":"It took real grit to finish the grueling marathon.","deck":"vocab"},{"id":702,"word":"ravage","ipa":"/ˈrævɪdʒ/","meaning":"황폐하게 만들다, 피폐하게 만들다, 유린하다, 파괴하다","example":"The wildfire ravaged thousands of acres of forest.","deck":"vocab"},{"id":703,"word":"go with ~","ipa":"","meaning":"~으로 고르다, ~으로 선택하다","example":"I think I'll go with the blue shirt for tonight.","deck":"vocab"},{"id":704,"word":"right as rain","ipa":"","meaning":"아주 건강한, 상태가 좋은","example":"After a good night's sleep, she felt right as rain.","deck":"vocab"},{"id":705,"word":"alumnus","ipa":"/əˈlʌmnəs/","meaning":"(대학의) 남자 졸업생, 동창생 <여성형은 alumna>","example":"As an alumnus, he donates to the university every year.","deck":"vocab"},{"id":706,"word":"reunion","ipa":"/riˈjunjən/","meaning":"모임, 동창회","example":"We attended our high school reunion last weekend.","deck":"vocab"},{"id":707,"word":"bully","ipa":"/ˈbʊli/","meaning":"(약자를) 괴롭히다, 왕따시키다, 협박하다","example":"The older kids used to bully him at school.","deck":"vocab"},{"id":708,"word":"bully","ipa":"/ˈbʊli/","meaning":"(약자를) 괴롭히는 사람","example":"The bully finally apologized for his cruel behavior.","deck":"vocab"},{"id":709,"word":"shadow of a doubt","ipa":"","meaning":"일말의 의심, 추호의 의심, 의심의 여지","example":"The evidence proved his guilt beyond a shadow of a doubt.","deck":"vocab"},{"id":710,"word":"get it together","ipa":"","meaning":"정신 차리다, 마음을 진정시키다","example":"You need to get it together before the big presentation.","deck":"vocab"},{"id":711,"word":"fart","ipa":"/fɑrt/","meaning":"지겨운 인간, 멍청한 인간","example":"That grumpy old fart never says hello to anyone.","deck":"vocab"},{"id":712,"word":"fart","ipa":"/fɑrt/","meaning":"방귀를 뀌다","example":"He accidentally farted loudly during the quiet meeting.","deck":"vocab"},{"id":713,"word":"intrigue","ipa":"/ɪnˈtriɡ/","meaning":"강한 흥미를 불러일으키다, 호기심을 동하게 만들다","example":"The mysterious letter intrigued her immediately.","deck":"vocab"},{"id":714,"word":"intrigue","ipa":"/ˈɪntriɡ/","meaning":"음모, 모의","example":"The novel is full of political intrigue and betrayal.","deck":"vocab"},{"id":715,"word":"lactose","ipa":"/ˈlæktoʊs/","meaning":"(화학에서) 젖당, 락토오스","example":"Many people cannot digest lactose found in milk.","deck":"vocab"},{"id":716,"word":"self-respect","ipa":"/ˌsɛlf rɪˈspɛkt/","meaning":"자기 존중, 자존심","example":"She kept her self-respect even in difficult times.","deck":"vocab"},{"id":717,"word":"brand new","ipa":"/ˌbrænd ˈnu/","meaning":"완전 새것인, 신품의","example":"He proudly showed off his brand new sports car.","deck":"vocab"},{"id":718,"word":"frustrate","ipa":"/ˈfrʌstreɪt/","meaning":"좌절감을 주다, 불만스럽게 만들다, 실망시키다","example":"The constant delays really frustrate the daily commuters.","deck":"vocab"},{"id":719,"word":"lame","ipa":"/leɪm/","meaning":"구차한, 설득력이 없는, 믿기 힘든","example":"That's a pretty lame excuse for being late again.","deck":"vocab"},{"id":720,"word":"lame","ipa":"/leɪm/","meaning":"구린, 촌스러운, 한심한, 찌질한","example":"The party was so lame that we left early.","deck":"vocab"},{"id":721,"word":"cardio","ipa":"/ˈkɑrdioʊ/","meaning":"심장 강화 운동, 유산소 운동","example":"She does thirty minutes of cardio every morning.","deck":"vocab"},{"id":722,"word":"tuck ~ in","ipa":"","meaning":"집어 넣다 <셔츠를 바지 안으로, 바지를 양말 안으로 집어 넣는 것>","example":"Please tuck in your shirt before the interview.","deck":"vocab"},{"id":723,"word":"stammer","ipa":"/ˈstæmər/","meaning":"말을 더듬다","example":"He began to stammer when the teacher called on him.","deck":"vocab"},{"id":724,"word":"school up","ipa":"","meaning":"(물고기가) 수면 가까이에 모여들다","example":"The tiny fish school up near the surface at dawn.","deck":"vocab"},{"id":725,"word":"anchovy","ipa":"/ˈæntʃoʊvi/","meaning":"멸치","example":"She added a few salty anchovies to the pizza.","deck":"vocab"},{"id":726,"word":"surmount","ipa":"/sərˈmaʊnt/","meaning":"(어려움, 장애 등을) ~을 극복하다 <격식 있는 표현>","example":"With effort, they surmounted every obstacle in their path.","deck":"vocab"},{"id":727,"word":"devour","ipa":"/dɪˈvaʊər/","meaning":"(특히 몹시 배가 고파서) 걸신 들린 듯 먹다","example":"The hungry children devoured the whole pizza in minutes.","deck":"vocab"},{"id":728,"word":"snap out of it","ipa":"","meaning":"기운을 차리다, 정신을 차리다 <부정적인 상황이나 기분에서 벗어날 때 쓰는 표현>","example":"Stop moping and snap out of it already!","deck":"vocab"},{"id":729,"word":"rustic","ipa":"/ˈrʌstɪk/","meaning":"시골풍의, 시골 특유의, 소박한 <긍정적인 어감>","example":"The cabin had a charming, rustic appearance.","deck":"vocab"},{"id":730,"word":"dare","ipa":"/dɛr/","meaning":"도전, 도전 과제","example":"He accepted the dare to jump into the cold lake.","deck":"vocab"},{"id":731,"word":"nemesis","ipa":"/ˈnɛməsɪs/","meaning":"오랜 적수, 최대의 적","example":"The detective finally confronted his old nemesis.","deck":"vocab"},{"id":732,"word":"disguise","ipa":"/dɪsˈɡaɪz/","meaning":"위장하다, 숨기다","example":"She tried to disguise her disappointment with a smile.","deck":"vocab"},{"id":733,"word":"cost","ipa":"/kɔst/","meaning":"~을 희생시키다, ~을 잃게 하다","example":"One careless mistake cost him his job.","deck":"vocab"},{"id":734,"word":"get out of ~","ipa":"","meaning":"(책임, 임무 등에서) ~에서 벗어나다, 회피하다","example":"He always tries to get out of doing the dishes.","deck":"vocab"},{"id":735,"word":"get out","ipa":"","meaning":"설마!, 말도 안 돼!, 뻥 치지 마! <믿을 수 없을 정도의 일이라는 뜻>","example":"You won the lottery? Get out, that's incredible!","deck":"vocab"},{"id":736,"word":"toast","ipa":"/toʊst/","meaning":"건배사, 건배 제의, 건배 <건배사를 포함하는 건배의 전 과정>","example":"He raised his glass and gave a heartfelt toast.","deck":"vocab"},{"id":737,"word":"confine","ipa":"/kənˈfaɪn/","meaning":"넣다, 가두다","example":"The prisoners were confined to their cells all day.","deck":"vocab"},{"id":738,"word":"confine","ipa":"/kənˈfaɪn/","meaning":"가두다","example":"They confined the dog to the backyard for safety.","deck":"vocab"},{"id":739,"word":"keep up with ~","ipa":"","meaning":"(연습이 필요한 일을) ~을 꾸준히 계속하다","example":"It's hard to keep up with piano practice while working.","deck":"vocab"},{"id":740,"word":"the other way around","ipa":"","meaning":"(상황이) 반대로","example":"I thought she called him, but it was the other way around.","deck":"vocab"},{"id":741,"word":"smock","ipa":"/smɑk/","meaning":"작업복, 덧옷","example":"The artist wore a paint-stained smock while working.","deck":"vocab"},{"id":742,"word":"din","ipa":"/dɪn/","meaning":"(오래 계속되는 크고 불쾌한) 소음","example":"The din of the traffic kept me awake all night.","deck":"vocab"},{"id":743,"word":"every single day","ipa":"","meaning":"단 하루도 빠짐없이 매일","example":"She exercises every single day without any exception.","deck":"vocab"},{"id":744,"word":"blush","ipa":"/blʌʃ/","meaning":"얼굴을 붉히다, 얼굴이 빨개지다","example":"She began to blush when he complimented her dress.","deck":"vocab"},{"id":745,"word":"gymnastics","ipa":"/dʒɪmˈnæstɪks/","meaning":"체조","example":"She has practiced gymnastics since she was five years old.","deck":"vocab"},{"id":746,"word":"orally","ipa":"/ˈɔrəli/","meaning":"구두로, 입을 통해서","example":"The medication should be taken orally twice a day.","deck":"vocab"},{"id":747,"word":"jet lag","ipa":"/ˈdʒɛt ˌlæɡ/","meaning":"시차증 <비행기 여행시 시차로 인한 피로감>","example":"After the long flight, he suffered from severe jet lag.","deck":"vocab"},{"id":748,"word":"rustle","ipa":"/ˈrʌsəl/","meaning":"바스락거리는 소리","example":"We heard the rustle of leaves in the evening wind.","deck":"vocab"},{"id":749,"word":"miserable","ipa":"/ˈmɪzərəbəl/","meaning":"항상 불평불만이 많은, 성질 나쁜, 항상 기분이 안 좋은 <망나니처럼 성격이 안 좋은 사람을 가리킬 때>","example":"That miserable old man complains about absolutely everything.","deck":"vocab"},{"id":750,"word":"~ and stuff","ipa":"","meaning":"~같은 것 <비격식. 구어체>","example":"We bought snacks and drinks and stuff for the party.","deck":"vocab"},{"id":751,"word":"off beat","ipa":"/ˈɔf ˌbit/","meaning":"엇박 <정박에 속하지 않은 박자>","example":"The drummer cleverly emphasized the off beat in the song.","deck":"vocab"},{"id":752,"word":"huggable","ipa":"/ˈhʌɡəbəl/","meaning":"껴안고 싶은, 껴안고 싶은 마음이 드는","example":"The teddy bear was soft and incredibly huggable.","deck":"vocab"},{"id":753,"word":"rehab","ipa":"/ˈrihæb/","meaning":"재활, 갱생 <마약 약물 중독, 질병, 장애 등으로부터 회복하는 과정>","example":"He spent three months in rehab to overcome his addiction.","deck":"vocab"},{"id":754,"word":"load up","ipa":"","meaning":"(비유적으로) (~을) 많이 섭취하다, 잔뜩 먹다","example":"Don't load up on bread before the main course arrives.","deck":"vocab"},{"id":755,"word":"maneuver","ipa":"/məˈnuvər/","meaning":"~을 잘 조종하다, ~을 잘 조종해서 이동시키다","example":"She carefully maneuvered the car into the tight space.","deck":"vocab"},{"id":756,"word":"maneuver","ipa":"/məˈnuvər/","meaning":"묘책, 계책, 술책","example":"It was a clever maneuver to win the negotiation.","deck":"vocab"},{"id":757,"word":"hygiene","ipa":"/ˈhaɪdʒin/","meaning":"위생","example":"Good personal hygiene helps prevent the spread of germs.","deck":"vocab"},{"id":758,"word":"feat","ipa":"/fit/","meaning":"(뛰어난) 솜씨, 재주, 위업, 개가 <호감>","example":"Climbing that mountain alone was an impressive feat.","deck":"vocab"},{"id":759,"word":"aviation","ipa":"/ˌeɪviˈeɪʃən/","meaning":"항공, 항공술","example":"He has worked in the aviation industry for decades.","deck":"vocab"},{"id":760,"word":"tyranny","ipa":"/ˈtɪrəni/","meaning":"횡포","example":"The people rose up against the king's tyranny.","deck":"vocab"},{"id":761,"word":"bribery","ipa":"/ˈbraɪbəri/","meaning":"뇌물 수수","example":"The official was arrested on charges of bribery.","deck":"vocab"},{"id":762,"word":"make up","ipa":"","meaning":"(~와) 화해하다","example":"The couple argued but quickly made up afterward.","deck":"vocab"},{"id":763,"word":"apologetic","ipa":"/əˌpɑləˈdʒɛtɪk/","meaning":"미안해하는, 사과하는","example":"He sent an apologetic email for missing the meeting.","deck":"vocab"},{"id":764,"word":"patronizing","ipa":"/ˈpeɪtrənaɪzɪŋ/","meaning":"잘난 체하는, 윗사람인 체하는","example":"I found his patronizing tone extremely annoying.","deck":"vocab"},{"id":765,"word":"threshold","ipa":"/ˈθrɛʃhoʊld/","meaning":"문지방","example":"She paused at the threshold before entering the room.","deck":"vocab"},{"id":766,"word":"what goes around comes around","ipa":"","meaning":"남에게 한 대로 되받게 되는 법, 뿌린 대로 거두는 법","example":"Be kind to others, because what goes around comes around.","deck":"vocab"},{"id":767,"word":"nod off","ipa":"","meaning":"(의도치 않게) 깜빡 졸다","example":"He kept nodding off during the boring afternoon lecture.","deck":"vocab"},{"id":768,"word":"in the limelight","ipa":"","meaning":"각광을 받아, 세상의 주목을 받아, 주목의 표적이 되어","example":"The young singer suddenly found herself in the limelight.","deck":"vocab"},{"id":769,"word":"phenomenal","ipa":"/fəˈnɑmənəl/","meaning":"경이적인, 경탄스러운","example":"The team's performance this season has been phenomenal.","deck":"vocab"},{"id":770,"word":"hope for the best","ipa":"","meaning":"잘 되기를 바라다 <잘못될 수 있다는 걸 알지만, 그래도 좋은 결과를 바라는 것>","example":"We prepared for the worst but hoped for the best.","deck":"vocab"},{"id":771,"word":"minion","ipa":"/ˈmɪnjən/","meaning":"하인, 심복, 하수인, 아랫것","example":"The villain ordered his minions to attack the city.","deck":"vocab"},{"id":772,"word":"reckless","ipa":"/ˈrɛkləs/","meaning":"무모한, 신중하지 못한","example":"His reckless driving nearly caused a serious accident.","deck":"vocab"},{"id":773,"word":"reindeer","ipa":"/ˈreɪndɪr/","meaning":"순록","example":"Santa's sleigh is pulled by nine flying reindeer.","deck":"vocab"},{"id":774,"word":"retreat","ipa":"/rɪˈtrit/","meaning":"(회사나 조직에서 하는) 야유회, 단합 대회","example":"The company organized a weekend retreat for the staff.","deck":"vocab"},{"id":775,"word":"prominent","ipa":"/ˈprɑmɪnənt/","meaning":"중요한, 저명한, 유명한","example":"She is a prominent figure in the scientific community.","deck":"vocab"},{"id":776,"word":"impassable","ipa":"/ɪmˈpæsəbəl/","meaning":"(도로, 지역 등이) 통행할 수 없는, 폐쇄된","example":"Heavy snow made the mountain roads impassable.","deck":"vocab"},{"id":777,"word":"stump","ipa":"/stʌmp/","meaning":"당황하게 하다, 쩔쩔매게 하다 <주로 수동태로 씀>","example":"The difficult riddle completely stumped everyone in class.","deck":"vocab"},{"id":778,"word":"anguish","ipa":"/ˈæŋɡwɪʃ/","meaning":"(극심한) 괴로움, 비통 <격식>","example":"Her face was filled with anguish at the sad news.","deck":"vocab"},{"id":779,"word":"largely","ipa":"/ˈlɑrdʒli/","meaning":"대체로, 주로","example":"The project's success was largely due to great teamwork.","deck":"vocab"},{"id":780,"word":"in turn","ipa":"","meaning":"결국, 결과적으로","example":"Higher costs led to higher prices, which in turn reduced sales.","deck":"vocab"},{"id":781,"word":"as to ~","ipa":"","meaning":"~에 관해서는, ~에 관해서, ~은","example":"There was some confusion as to who was responsible.","deck":"vocab"},{"id":782,"word":"cruel","ipa":"/ˈkruəl/","meaning":"(사람, 사람의 행동이) 잔혹한, 잔인한","example":"It was cruel of him to mock her in front of everyone.","deck":"vocab"},{"id":783,"word":"cruel","ipa":"/ˈkruəl/","meaning":"(상황이) 고통스러운, 괴로운, 잔인한","example":"By a cruel twist of fate, they missed the last train.","deck":"vocab"},{"id":784,"word":"mesmerizing","ipa":"/ˈmɛzməraɪzɪŋ/","meaning":"완전 넋을 빼놓는, 입이 떡 벌어지는","example":"The dancer's graceful movements were absolutely mesmerizing.","deck":"vocab"},{"id":785,"word":"invincible","ipa":"/ɪnˈvɪnsəbəl/","meaning":"무적의, 불패의, 아무도 꺾을 수 없는","example":"The champion felt invincible after his tenth straight victory.","deck":"vocab"},{"id":786,"word":"abbreviation","ipa":"/əˌbriviˈeɪʃən/","meaning":"(단어, 어구 등의) 축약형, 줄임말","example":"'Dr.' is a common abbreviation for the word 'doctor'.","deck":"vocab"},{"id":787,"word":"abbreviation","ipa":"/əˌbriviˈeɪʃən/","meaning":"축약 <셀 수 없는 명사>","example":"The heavy use of abbreviation makes the text hard to read.","deck":"vocab"},{"id":788,"word":"point taken","ipa":"","meaning":"알겠다, 당신 말이 옳다 <상대의 말이나 의견을 이해하고 받아들일 때 쓰는 표현>","example":"Point taken; I'll be more careful next time.","deck":"vocab"},{"id":789,"word":"plantation","ipa":"/plænˈteɪʃən/","meaning":"농장","example":"They grew coffee on a large plantation in the hills.","deck":"vocab"},{"id":790,"word":"hinge on ~","ipa":"","meaning":"전적으로 ~에 달려 있다","example":"The whole plan hinges on getting enough funding.","deck":"vocab"},{"id":791,"word":"goosebumps","ipa":"/ˈɡusbʌmps/","meaning":"(춥거나 무섭거나 할 때 돋는) 소름","example":"The scary movie gave me goosebumps all over.","deck":"vocab"},{"id":792,"word":"under the weather","ipa":"","meaning":"몸이 좀 안 좋은","example":"I'm feeling a bit under the weather today.","deck":"vocab"},{"id":793,"word":"clam up","ipa":"","meaning":"입을 꼭 다물다, 말을 안 하다","example":"He tends to clam up whenever he's asked personal questions.","deck":"vocab"},{"id":794,"word":"contradict","ipa":"/ˌkɑntrəˈdɪkt/","meaning":"부정하다, 부인하다, 반박하다","example":"The witness's story seemed to contradict the earlier evidence.","deck":"vocab"},{"id":795,"word":"repression","ipa":"/rɪˈprɛʃən/","meaning":"(감정, 욕구를) 억누름, 억압","example":"Years of emotional repression finally took a toll on him.","deck":"vocab"},{"id":796,"word":"bullfight","ipa":"/ˈbʊlfaɪt/","meaning":"투우","example":"They watched a traditional bullfight while visiting Spain.","deck":"vocab"},{"id":797,"word":"nail","ipa":"/neɪl/","meaning":"~을 이뤄 내다, ~을 완벽하게 해내다","example":"She really nailed the presentation this morning.","deck":"vocab"},{"id":798,"word":"selective","ipa":"/sɪˈlɛktɪv/","meaning":"신중하게 고르는, 까다로운","example":"He is very selective about the friends he keeps.","deck":"vocab"},{"id":799,"word":"infer","ipa":"/ɪnˈfɜr/","meaning":"암시하다, 간접적으로 말하다 <비표준적 표현>","example":"Are you inferring that I am lying to you?","deck":"vocab"},{"id":800,"word":"infer","ipa":"/ɪnˈfɜr/","meaning":"추론하다","example":"From her tone, I inferred that she was upset.","deck":"vocab"},{"id":801,"word":"weirdo","ipa":"/ˈwɪrdoʊ/","meaning":"괴짜, 별난 사람","example":"Everyone at school thought he was a weirdo because of his strange habits.","deck":"vocab"},{"id":802,"word":"give ~ away","ipa":"","meaning":"(비밀을) 누설하다, 드러내다","example":"Her nervous laugh gave away the secret she was trying to hide.","deck":"vocab"},{"id":803,"word":"couldn't agree more","ipa":"","meaning":"전적으로 동의하다","example":"I couldn't agree more with your plan to leave early tomorrow.","deck":"vocab"},{"id":804,"word":"arousal","ipa":"/əˈraʊzəl/","meaning":"자극, 흥분","example":"The film explored themes of fear and physical arousal in great detail.","deck":"vocab"},{"id":805,"word":"shin","ipa":"/ʃɪn/","meaning":"정강이","example":"I bumped my shin against the coffee table in the dark.","deck":"vocab"},{"id":806,"word":"on fire","ipa":"","meaning":"장난 아니게 잘하는","example":"The basketball player was on fire, scoring thirty points last night.","deck":"vocab"},{"id":807,"word":"swift","ipa":"/swɪft/","meaning":"(일, 진행 등이) 신속한, 재빠른","example":"The company gave a swift response to the customer's complaint.","deck":"vocab"},{"id":808,"word":"swift","ipa":"/swɪft/","meaning":"(움직임이) 빠른, 날쌘","example":"With one swift movement, the cat caught the falling toy.","deck":"vocab"},{"id":809,"word":"sit back","ipa":"","meaning":"(의자, 소파 등에) 편안히 앉다","example":"Just sit back and relax while I prepare dinner for everyone.","deck":"vocab"},{"id":810,"word":"on the ground","ipa":"","meaning":"현장에서, 현지에서","example":"Our reporters on the ground described the chaotic scene vividly.","deck":"vocab"},{"id":811,"word":"glamorous","ipa":"/ˈɡlæmərəs/","meaning":"화려한, 매력이 넘치는","example":"She looked absolutely glamorous in her sparkling evening gown.","deck":"vocab"},{"id":812,"word":"second-hand","ipa":"/ˌsɛkəndˈhænd/","meaning":"(뉴스, 정보 등이) 간접적으로, 전해 들어서","example":"I only heard the news second-hand, so it might not be accurate.","deck":"vocab"},{"id":813,"word":"receptive","ipa":"/rɪˈsɛptɪv/","meaning":"수용적인, 선뜻 받아들이는","example":"The manager was receptive to new ideas from her team.","deck":"vocab"},{"id":814,"word":"run ~ over","ipa":"","meaning":"(사람, 동물을 차량이) 깔아뭉개다, 치다","example":"The careless driver almost ran over a dog crossing the street.","deck":"vocab"},{"id":815,"word":"peculiar","ipa":"/pɪˈkjuljər/","meaning":"특이한, 독특한 <이상하거나 일반적이지 않다는 뜻>","example":"There was a peculiar smell coming from the abandoned kitchen.","deck":"vocab"},{"id":816,"word":"bust","ipa":"/bʌst/","meaning":"(경찰 등이) ~를 체포하다, 잡다","example":"The police busted the gang for smuggling illegal goods.","deck":"vocab"},{"id":817,"word":"bust","ipa":"/bʌst/","meaning":"실패작","example":"The expensive movie was a complete bust at the box office.","deck":"vocab"},{"id":818,"word":"nuisance","ipa":"/ˈnuːsəns/","meaning":"성가신 사람, 귀찮은 일, 골칫거리","example":"The constant noise from construction is a real nuisance.","deck":"vocab"},{"id":819,"word":"butterflies in one's stomach","ipa":"","meaning":"마음이 조마조마함, 불안감, 흥분됨, 설렘 <미국 속어. 부정적, 긍정적 감정 모두에 쓸 수 있음>","example":"I had butterflies in my stomach before my big presentation.","deck":"vocab"},{"id":820,"word":"get through","ipa":"","meaning":"(전화로) (~와) 연락이 되다","example":"I tried calling all morning but couldn't get through to her.","deck":"vocab"},{"id":821,"word":"compound","ipa":"/ˈkɑːmpaʊnd/","meaning":"(문법에서) 합성어","example":"The word 'toothbrush' is a compound made from two nouns.","deck":"vocab"},{"id":822,"word":"year-over-year","ipa":"/ˌjɪr oʊvər ˈjɪr/","meaning":"전년대비, 전년동기대비","example":"Sales increased fifteen percent year-over-year, impressing the investors.","deck":"vocab"},{"id":823,"word":"pointless","ipa":"/ˈpɔɪntləs/","meaning":"할 이유가 없는, 할 가치가 없는","example":"It's pointless to argue with him once he's made up his mind.","deck":"vocab"},{"id":824,"word":"execute","ipa":"/ˈɛksɪkjuːt/","meaning":"(기교가 많이 필요한 기술적인 동작을) 해내다","example":"The gymnast executed a perfect landing after her difficult routine.","deck":"vocab"},{"id":825,"word":"potassium","ipa":"/pəˈtæsiəm/","meaning":"칼륨, 포타슘 <원소기호: K>","example":"Bananas are an excellent source of potassium and other nutrients.","deck":"vocab"},{"id":826,"word":"tremendous","ipa":"/trɪˈmɛndəs/","meaning":"굉장한, 기막힌, 엄청나게 훌륭한 <매우 좋거나 매우 인상적이라는 뜻>","example":"She showed tremendous courage during the difficult rescue mission.","deck":"vocab"},{"id":827,"word":"tingle","ipa":"/ˈtɪŋɡəl/","meaning":"(신체 부위가) 따끔거리다, 따끔따끔하다","example":"My fingers began to tingle after the cold winter walk.","deck":"vocab"},{"id":828,"word":"tingle","ipa":"/ˈtɪŋɡəl/","meaning":"따끔거림, 얼얼함","example":"I felt a strange tingle run down my spine.","deck":"vocab"},{"id":829,"word":"preference","ipa":"/ˈprɛfərəns/","meaning":"(~에 대한) 선호, 취향, 선호도 <셀 수 없는 명사 또는 단수형으로 씀>","example":"She has a strong preference for tea over coffee.","deck":"vocab"},{"id":830,"word":"nutrient","ipa":"/ˈnuːtriənt/","meaning":"영양소, 영양분","example":"Fresh vegetables provide many nutrients essential for good health.","deck":"vocab"},{"id":831,"word":"diverse","ipa":"/dɪˈvɜːrs/","meaning":"다양한, 다채로운, 서로 다른","example":"The city is home to a diverse mix of cultures.","deck":"vocab"},{"id":832,"word":"to save one's life","ipa":"","meaning":"죽어도, 죽었다 깨어나도, 아무리 해도, 절대로 <무언가에 매우 서툴다는 것을 강조할 때 씀>","example":"He couldn't sing in tune to save his life.","deck":"vocab"},{"id":833,"word":"that's how things are","ipa":"","meaning":"원래 그런 거다","example":"You can't always get what you want; that's how things are.","deck":"vocab"},{"id":834,"word":"antagonize","ipa":"/ænˈtæɡənaɪz/","meaning":"~의 반감을 사다, ~을 적으로 만들다, 적개심을 품게 하다","example":"Try not to antagonize your coworkers with harsh criticism.","deck":"vocab"},{"id":835,"word":"bump","ipa":"/bʌmp/","meaning":"(부딪치거나 맞아서 생긴) 혹, 타박상","example":"She had a painful bump on her forehead after the fall.","deck":"vocab"},{"id":836,"word":"bump","ipa":"/bʌmp/","meaning":"(~에) 부딪치다","example":"I accidentally bumped into the shelf and knocked over a vase.","deck":"vocab"},{"id":837,"word":"ring in ~","ipa":"","meaning":"(새해 등을) 맞이하다 <뭔가의 시작을 기념 또는 축하한다는 뜻>","example":"We rang in the new year with fireworks and champagne.","deck":"vocab"},{"id":838,"word":"back and forth","ipa":"","meaning":"왔다 갔다","example":"The debaters argued back and forth for nearly an hour.","deck":"vocab"},{"id":839,"word":"barf","ipa":"/bɑːrf/","meaning":"토하다","example":"He felt so sick on the boat that he almost barfed.","deck":"vocab"},{"id":840,"word":"sicken","ipa":"/ˈsɪkən/","meaning":"역겹게 만들다","example":"The cruel treatment of the animals sickened everyone who watched.","deck":"vocab"},{"id":841,"word":"get off easy","ipa":"","meaning":"가벼운 처벌로 끝나다, 큰 벌을 면하다","example":"He got off easy with just a warning from the judge.","deck":"vocab"},{"id":842,"word":"for a rainy day","ipa":"","meaning":"비오는 날을 위하여, 만일의 경우에 대비하여","example":"She saves a little money each month for a rainy day.","deck":"vocab"},{"id":843,"word":"pursue","ipa":"/pərˈsuː/","meaning":"(목표, 특정한 결과 등을) 추구하다","example":"She decided to pursue a career in medicine after college.","deck":"vocab"},{"id":844,"word":"pursue","ipa":"/pərˈsuː/","meaning":"해나가다, 종사하다","example":"He continued to pursue his studies while working full-time.","deck":"vocab"},{"id":845,"word":"torso","ipa":"/ˈtɔːrsoʊ/","meaning":"몸통, 동체","example":"The artist sketched the model's torso with careful detail.","deck":"vocab"},{"id":846,"word":"haze","ipa":"/heɪz/","meaning":"연무, 실안개","example":"A thin haze hung over the valley early that morning.","deck":"vocab"},{"id":847,"word":"spice","ipa":"/spaɪs/","meaning":"~에 양념을 치다, 향신료를 치다, ~을 양념하다","example":"She likes to spice her soup with plenty of black pepper.","deck":"vocab"},{"id":848,"word":"over the hill","ipa":"","meaning":"(사람이) 한물간, 퇴물이 된","example":"At forty, he jokingly claims he's already over the hill.","deck":"vocab"},{"id":849,"word":"club","ipa":"/klʌb/","meaning":"몽둥이, 곤봉","example":"The guard carried a heavy wooden club to defend the gate.","deck":"vocab"},{"id":850,"word":"expertise","ipa":"/ˌɛkspərˈtiːz/","meaning":"전문 지식, 전문 기술","example":"Her expertise in software design made her invaluable to the company.","deck":"vocab"},{"id":851,"word":"cardiac","ipa":"/ˈkɑːrdiæk/","meaning":"심장의, 심장병의","example":"The patient was rushed to the hospital with cardiac problems.","deck":"vocab"},{"id":852,"word":"obsess","ipa":"/əbˈsɛs/","meaning":"(~에 대해) 집착하다, 강박감을 느끼다","example":"She tends to obsess over tiny mistakes in her work.","deck":"vocab"},{"id":853,"word":"nearsighted","ipa":"/ˈnɪrsaɪtɪd/","meaning":"근시의 <주로 미국에서 쓰는 표현>","example":"Being nearsighted, he can't read street signs from far away.","deck":"vocab"},{"id":854,"word":"pretrial","ipa":"/ˌpriːˈtraɪəl/","meaning":"재판 전의, 공판 전의","example":"The lawyers met for a pretrial hearing before the case began.","deck":"vocab"},{"id":855,"word":"sour","ipa":"/ˈsaʊər/","meaning":"(특히 우유가) 상한, 시큼한","example":"The milk turned sour after being left out overnight.","deck":"vocab"},{"id":856,"word":"catch","ipa":"/kætʃ/","meaning":"(숨은) 문제점, 애로점 <주로 단수형으로 씀>","example":"The offer sounds great, but there must be a catch somewhere.","deck":"vocab"},{"id":857,"word":"catch","ipa":"/kætʃ/","meaning":"(~에) ~을 끼이게 하다, ~을 걸리게 하다, ~이 들러붙게 하다","example":"She caught her sleeve on the door handle and tore it.","deck":"vocab"},{"id":858,"word":"downplay","ipa":"/ˌdaʊnˈpleɪ/","meaning":"~이 별것 아닌 것처럼 보이게 하려 하다, 폄하하다","example":"The manager tried to downplay the seriousness of the problem.","deck":"vocab"},{"id":859,"word":"sarcasm","ipa":"/ˈsɑːrkæzəm/","meaning":"빈정댐, 비꼼","example":"His comment was dripping with sarcasm about the failed project.","deck":"vocab"},{"id":860,"word":"derail","ipa":"/dɪˈreɪl/","meaning":"(기차를) 탈선시키다","example":"The heavy storm caused the train to derail near the bridge.","deck":"vocab"},{"id":861,"word":"prevail on ~","ipa":"","meaning":"~를 설득하다","example":"I finally prevailed on my father to lend me the car.","deck":"vocab"},{"id":862,"word":"Prague","ipa":"/prɑːɡ/","meaning":"프라하 <체코의 수도>","example":"We spent a wonderful week exploring the old streets of Prague.","deck":"vocab"},{"id":863,"word":"deposit slip","ipa":"/dɪˈpɑːzɪt slɪp/","meaning":"(은행의) 예금 전표, 예입 전표","example":"Fill out the deposit slip before handing your money to the teller.","deck":"vocab"},{"id":864,"word":"chill","ipa":"/tʃɪl/","meaning":"느긋한 시간을 보내다","example":"We just want to chill at home and watch movies tonight.","deck":"vocab"},{"id":865,"word":"chill","ipa":"/tʃɪl/","meaning":"느긋한, 여유 있는","example":"He has a chill attitude that puts everyone at ease.","deck":"vocab"},{"id":866,"word":"black sheep","ipa":"/ˌblæk ˈʃiːp/","meaning":"(집안이나 조직의) 골칫덩어리, 말썽꾼","example":"He was always the black sheep of his conservative family.","deck":"vocab"},{"id":867,"word":"gravely","ipa":"/ˈɡreɪvli/","meaning":"심각하게, 중대하게","example":"The soldier was gravely wounded during the fierce battle.","deck":"vocab"},{"id":868,"word":"entertain","ipa":"/ˌɛntərˈteɪn/","meaning":"(특히 집에서 손님을) 대접하다, 접대하다","example":"They love to entertain guests with elaborate dinners on weekends.","deck":"vocab"},{"id":869,"word":"gut","ipa":"/ɡʌt/","meaning":"(특히 화재로 건물, 방의) 내부를 파괴하다","example":"The fire completely gutted the historic old building downtown.","deck":"vocab"},{"id":870,"word":"gut","ipa":"/ɡʌt/","meaning":"(특히 동물의) 내장 <복수형으로 씀>","example":"The fisherman removed the guts before cooking the fresh fish.","deck":"vocab"},{"id":871,"word":"gut","ipa":"/ɡʌt/","meaning":"직감, 본능, 감정","example":"My gut told me something was wrong about the deal.","deck":"vocab"},{"id":872,"word":"sweat it","ipa":"","meaning":"걱정하다, 고민하다","example":"Don't sweat it; we'll finish the project on time.","deck":"vocab"},{"id":873,"word":"sound asleep","ipa":"","meaning":"깊이 잠든","example":"The baby was sound asleep before the movie even ended.","deck":"vocab"},{"id":874,"word":"implement","ipa":"/ˈɪmpləmɛnt/","meaning":"시행하다","example":"The school will implement new safety rules starting next month.","deck":"vocab"},{"id":875,"word":"subtle","ipa":"/ˈsʌtəl/","meaning":"미묘한","example":"There was a subtle difference between the two paintings.","deck":"vocab"},{"id":876,"word":"wussy","ipa":"/ˈwʊsi/","meaning":"겁쟁이, 연약한 사내","example":"Don't be such a wussy; the roller coaster is perfectly safe.","deck":"vocab"},{"id":877,"word":"on a budget","ipa":"","meaning":"한정된 예산으로, 예산이 많지 않은, 형편이 빠듯한","example":"We traveled through Europe on a budget, staying in cheap hostels.","deck":"vocab"},{"id":878,"word":"bonfire","ipa":"/ˈbɑːnfaɪər/","meaning":"모닥불","example":"We gathered around the bonfire and told stories all night.","deck":"vocab"},{"id":879,"word":"overthrow","ipa":"/ˌoʊvərˈθroʊ/","meaning":"(지도자, 정부를) 타도하다, 전복시키다","example":"The rebels planned to overthrow the corrupt government by force.","deck":"vocab"},{"id":880,"word":"pragmatically","ipa":"/præɡˈmætɪkli/","meaning":"실용적으로, 실용주의적으로","example":"She approached the crisis pragmatically, focusing on realistic solutions.","deck":"vocab"},{"id":881,"word":"grunt","ipa":"/ɡrʌnt/","meaning":"끙 하고 앓는 소리를 내다","example":"He grunted with effort as he lifted the heavy box.","deck":"vocab"},{"id":882,"word":"contraception","ipa":"/ˌkɑːntrəˈsɛpʃən/","meaning":"피임","example":"The clinic offers free advice about various forms of contraception.","deck":"vocab"},{"id":883,"word":"hunch","ipa":"/hʌntʃ/","meaning":"~을 구부리다","example":"He tends to hunch his shoulders when he feels nervous.","deck":"vocab"},{"id":884,"word":"sophomore","ipa":"/ˈsɑːfəmɔːr/","meaning":"(고등학교나 4년제 대학의) 2학년생","example":"As a sophomore, she already leads the university debate team.","deck":"vocab"},{"id":885,"word":"edification","ipa":"/ˌɛdɪfɪˈkeɪʃən/","meaning":"교화, 의식 고양 <격식 또는 유머>","example":"The lecture was presented for the edification of young students.","deck":"vocab"},{"id":886,"word":"imprudent","ipa":"/ɪmˈpruːdənt/","meaning":"현명하지 못한, 경솔한 <격식>","example":"It would be imprudent to invest all your savings in one stock.","deck":"vocab"},{"id":887,"word":"rigor","ipa":"/ˈrɪɡər/","meaning":"혹독함 <복수형으로 씀>","example":"The soldiers endured the rigors of training in harsh weather.","deck":"vocab"},{"id":888,"word":"invoke","ipa":"/ɪnˈvoʊk/","meaning":"(법, 규칙 등을) 행사하다, 적용하다, 발동하다","example":"The president may invoke emergency powers during a national crisis.","deck":"vocab"},{"id":889,"word":"dusk","ipa":"/dʌsk/","meaning":"황혼, 땅거미 <해가 진 뒤의 어스름>","example":"The streetlights flickered on as dusk settled over the town.","deck":"vocab"},{"id":890,"word":"round ~ up","ipa":"","meaning":"(경찰, 군인이) ~을 찾아 체포하다","example":"Police rounded up several suspects after the robbery downtown.","deck":"vocab"},{"id":891,"word":"think on one's feet","ipa":"","meaning":"순간적으로 판단하다","example":"A good salesperson must think on their feet during tough negotiations.","deck":"vocab"},{"id":892,"word":"pariah","ipa":"/pəˈraɪə/","meaning":"(사회에서) 버림받은 사람, 사회적 왕따","example":"After the scandal, he became a social pariah in his hometown.","deck":"vocab"},{"id":893,"word":"alongside","ipa":"/əˌlɔːŋˈsaɪd/","meaning":"~와 함께, ~와 동시에","example":"She worked alongside her mentor on the groundbreaking research project.","deck":"vocab"},{"id":894,"word":"trash can","ipa":"/ˈtræʃ kæn/","meaning":"쓰레기통","example":"Please throw the empty bottles into the trash can outside.","deck":"vocab"},{"id":895,"word":"dump","ipa":"/dʌmp/","meaning":"(필요 없어진 것 등을) 버리다","example":"They illegally dumped old furniture beside the quiet country road.","deck":"vocab"},{"id":896,"word":"dump","ipa":"/dʌmp/","meaning":"(애인을) 차다","example":"She dumped her boyfriend after discovering he had lied.","deck":"vocab"},{"id":897,"word":"intrusive","ipa":"/ɪnˈtruːsɪv/","meaning":"거슬리는","example":"The reporter's intrusive questions made the actress very uncomfortable.","deck":"vocab"},{"id":898,"word":"redemptive","ipa":"/rɪˈdɛmptɪv/","meaning":"구원하는","example":"The novel tells a redemptive story of forgiveness and second chances.","deck":"vocab"},{"id":899,"word":"get off the ground","ipa":"","meaning":"잘 되기 시작하다, 성공하기 시작하다","example":"The new business finally got off the ground after months of planning.","deck":"vocab"},{"id":900,"word":"airsickness","ipa":"/ˈɛrsɪknəs/","meaning":"비행기 멀미","example":"She suffered from airsickness during the bumpy flight home.","deck":"vocab"},{"id":901,"word":"flattery","ipa":"/ˈflætəri/","meaning":"아첨","example":"His obvious flattery didn't fool the experienced manager at all.","deck":"vocab"},{"id":902,"word":"pledge","ipa":"/plɛdʒ/","meaning":"(정식으로) 약속하다, 맹세하다","example":"The candidates pledged to reduce taxes if they were elected.","deck":"vocab"},{"id":903,"word":"pledge","ipa":"/plɛdʒ/","meaning":"(굳은) 약속, 맹세, 서약","example":"She made a solemn pledge to protect the environment.","deck":"vocab"},{"id":904,"word":"snotnosed","ipa":"/ˈsnɑːtnoʊzd/","meaning":"코흘리개인","example":"The snotnosed kid kept interrupting the adults during dinner.","deck":"vocab"},{"id":905,"word":"get into ~","ipa":"","meaning":"(전문직종, 학교 등에) ~에 들어가다","example":"She worked hard to get into a prestigious law school.","deck":"vocab"},{"id":906,"word":"get into ~","ipa":"","meaning":"(특정한 상태에) 처하다","example":"How did we get into such a complicated situation in the first place?","deck":"vocab"},{"id":907,"word":"antibiotic","ipa":"/ˌæntibaɪˈɑːtɪk/","meaning":"항생제, 항생물질 <주로 복수형으로 씀>","example":"The doctor prescribed antibiotics to treat his throat infection.","deck":"vocab"},{"id":908,"word":"listless","ipa":"/ˈlɪstləs/","meaning":"힘이 없는, 무기력한","example":"The hot afternoon left the children feeling listless and bored.","deck":"vocab"},{"id":909,"word":"unequivocally","ipa":"/ˌʌnɪˈkwɪvəkli/","meaning":"분명히, 명백히, 모호하지 않게","example":"She unequivocally denied any involvement in the scandal.","deck":"vocab"},{"id":910,"word":"venture","ipa":"/ˈvɛntʃər/","meaning":"조심스럽게 말하다 <문어체>","example":"May I venture a suggestion about how to improve the plan?","deck":"vocab"},{"id":911,"word":"stalk","ipa":"/stɔːk/","meaning":"쫓아다니며 괴롭히다, 스토킹하다","example":"The obsessed fan began to stalk the famous singer online.","deck":"vocab"},{"id":912,"word":"nectarine","ipa":"/ˈnɛktəriːn/","meaning":"천도복숭아","example":"She bit into a juicy nectarine on the warm afternoon.","deck":"vocab"},{"id":913,"word":"nifty","ipa":"/ˈnɪfti/","meaning":"솜씨 좋은, 훌륭한","example":"He showed me a nifty trick for folding shirts quickly.","deck":"vocab"},{"id":914,"word":"nifty","ipa":"/ˈnɪfti/","meaning":"실용적인, 쓰기 좋은 <물건 등이 흥미롭거나 사용하기 편리하다는 뜻>","example":"This nifty little gadget makes opening jars so much easier.","deck":"vocab"},{"id":915,"word":"blister","ipa":"/ˈblɪstər/","meaning":"물집, 수포","example":"The new shoes gave her a painful blister on her heel.","deck":"vocab"},{"id":916,"word":"full of oneself","ipa":"","meaning":"자만심에 차 있는, 거만한","example":"Ever since his promotion, he's been so full of himself.","deck":"vocab"},{"id":917,"word":"extrovert","ipa":"/ˈɛkstrəvɜːrt/","meaning":"외향적인","example":"As an extrovert, she thrives at large, lively parties.","deck":"vocab"},{"id":918,"word":"mite","ipa":"/maɪt/","meaning":"진드기","example":"Dust mites can trigger allergies in especially sensitive people.","deck":"vocab"},{"id":919,"word":"flatter","ipa":"/ˈflætər/","meaning":"아부하다, 아첨하다","example":"He tried to flatter the boss to get a promotion.","deck":"vocab"},{"id":920,"word":"pick-me-up","ipa":"/ˈpɪk mi ʌp/","meaning":"기운을 차리게 해 주는 것, 기분이 좋아지게 해 주는 것 <비격식적인 표현>","example":"A strong cup of coffee is a great pick-me-up in the morning.","deck":"vocab"},{"id":921,"word":"bowling alley","ipa":"/ˈboʊlɪŋ ˌæli/","meaning":"볼링장","example":"We spent Friday night having fun at the local bowling alley.","deck":"vocab"},{"id":922,"word":"thorax","ipa":"/ˈθɔːræks/","meaning":"(곤충의) 흉부, 가슴","example":"An insect's legs are all attached to its thorax.","deck":"vocab"},{"id":923,"word":"negatory","ipa":"/ˈnɛɡətɔːri/","meaning":"부정적인, 반대적인","example":"The pilot gave a negatory response to the control tower.","deck":"vocab"},{"id":924,"word":"pretense","ipa":"/ˈpriːtɛns/","meaning":"~인 척함, 가식","example":"Under the pretense of friendship, he gathered private information.","deck":"vocab"},{"id":925,"word":"staple","ipa":"/ˈsteɪpəl/","meaning":"주요 식품, 주식(主食)","example":"Rice is a staple in many Asian households.","deck":"vocab"},{"id":926,"word":"subliminal","ipa":"/səbˈlɪmɪnəl/","meaning":"부지불식간에 영향을 미치는, 잠재의식의","example":"The ad used subliminal messages to influence shoppers' choices.","deck":"vocab"},{"id":927,"word":"prelude","ipa":"/ˈprɛljuːd/","meaning":"(더 중요한 일의) (~의) 서막, 전조","example":"The minor conflict was merely a prelude to a larger war.","deck":"vocab"},{"id":928,"word":"reproach","ipa":"/rɪˈproʊtʃ/","meaning":"(실망하여) 비난하다, 책망하다","example":"She reproached him for forgetting their anniversary again.","deck":"vocab"},{"id":929,"word":"reproach","ipa":"/rɪˈproʊtʃ/","meaning":"비난, 책망, 나무람","example":"His voice was full of reproach when he spoke to me.","deck":"vocab"},{"id":930,"word":"white water","ipa":"/ˌwaɪt ˈwɔːtər/","meaning":"(하얗게 부서지는) 급류","example":"The rafters paddled bravely through the roaring white water.","deck":"vocab"},{"id":931,"word":"wispy","ipa":"/ˈwɪspi/","meaning":"(구름이) 성긴, 희미한","example":"Thin, wispy clouds drifted across the pale evening sky.","deck":"vocab"},{"id":932,"word":"off year","ipa":"/ˌɔːf ˈjɪr/","meaning":"중요 선거가 없는 해, 대통령 선거가 없는 해","example":"Voter turnout is usually lower during an off year election.","deck":"vocab"},{"id":933,"word":"bowel","ipa":"/ˈbaʊəl/","meaning":"창자, 장","example":"The doctor examined his bowel for signs of disease.","deck":"vocab"},{"id":934,"word":"fit","ipa":"/fɪt/","meaning":"(병으로 인한) 발작","example":"The patient suffered a sudden fit and collapsed on the floor.","deck":"vocab"},{"id":935,"word":"unparalleled","ipa":"/ʌnˈpærəlɛld/","meaning":"비교가 불가능한, 비할 데 없는","example":"The pianist performed with unparalleled skill and passion.","deck":"vocab"},{"id":936,"word":"seraphic","ipa":"/səˈræfɪk/","meaning":"천사 같은, 천사처럼 아름답고 순수한 <문학적 표현>","example":"The child had a seraphic smile that melted everyone's heart.","deck":"vocab"},{"id":937,"word":"et cetera","ipa":"","meaning":"기타 등등, ~ 따위 <글로 적을 때는 주로 etc.로 줄여서 씀>","example":"Bring pens, paper, notebooks, et cetera, to the workshop.","deck":"vocab"},{"id":938,"word":"opponent","ipa":"/əˈpoʊnənt/","meaning":"(게임, 대회, 논쟁 등의) 상대","example":"She studied her opponent's moves carefully before the match.","deck":"vocab"},{"id":939,"word":"in a jiff","ipa":"","meaning":"곧바로, 후딱, 즉시, 당장 <비격식적인 표현>","example":"Wait here; I'll be back in a jiff with your coffee.","deck":"vocab"},{"id":940,"word":"blabbermouth","ipa":"/ˈblæbərmaʊθ/","meaning":"입이 싼 사람, 말이 많은 사람","example":"Don't tell him the secret; he's a total blabbermouth.","deck":"vocab"},{"id":941,"word":"amble","ipa":"/ˈæmbəl/","meaning":"천천히 걸어가다, 여유롭게 걷다","example":"They ambled along the beach as the sun slowly set.","deck":"vocab"},{"id":942,"word":"devout","ipa":"/dɪˈvaʊt/","meaning":"(사람이) 독실한","example":"Her devout grandmother attends church every single morning.","deck":"vocab"},{"id":943,"word":"root beer","ipa":"/ˈruːt bɪr/","meaning":"루트 비어 <식물 뿌리로 만든 알코올 성분이 거의 없는 탄산음료>","example":"The kids ordered root beer floats at the old diner.","deck":"vocab"},{"id":944,"word":"compulsory","ipa":"/kəmˈpʌlsəri/","meaning":"(법이나 규정에 의해) 강제된, 의무적인, 필수의","example":"Wearing a seatbelt is compulsory for all passengers in the car.","deck":"vocab"},{"id":945,"word":"no go","ipa":"","meaning":"안 되는 것, 불가능한 일","example":"The plan to expand overseas turned out to be a no go.","deck":"vocab"},{"id":946,"word":"come at a cost","ipa":"","meaning":"대가가 따르다","example":"Success often comes at a cost to your personal life.","deck":"vocab"},{"id":947,"word":"smother","ipa":"/ˈsmʌðər/","meaning":"(지나친 집착이나 과보호 등으로) 숨 막히게 하다","example":"Her constant worrying began to smother her teenage son.","deck":"vocab"},{"id":948,"word":"tend","ipa":"/tɛnd/","meaning":"돌보다, 보살피다","example":"The shepherd tended his flock on the green hillside.","deck":"vocab"},{"id":949,"word":"remorse","ipa":"/rɪˈmɔːrs/","meaning":"회한, 후회","example":"He felt deep remorse for the pain he had caused.","deck":"vocab"},{"id":950,"word":"entitle","ipa":"/ɪnˈtaɪtəl/","meaning":"(~에 대한) 자격을 주다, 권리를 주다","example":"This ticket entitles you to a free drink at the bar.","deck":"vocab"},{"id":951,"word":"serial killer","ipa":"/ˈsɪriəl ˈkɪlər/","meaning":"연쇄 살인범","example":"The detective spent years hunting the notorious serial killer.","deck":"vocab"},{"id":952,"word":"resemblance","ipa":"/rɪˈzɛmbləns/","meaning":"닮음, 비슷함, 유사함","example":"The boy bears a striking resemblance to his late grandfather.","deck":"vocab"},{"id":953,"word":"elegant","ipa":"/ˈɛlɪɡənt/","meaning":"(사람의 외모, 분위기, 스타일 등이) 우아한","example":"She wore an elegant black dress to the charity gala.","deck":"vocab"},{"id":954,"word":"suspend","ipa":"/səˈspɛnd/","meaning":"(공식적으로) 유예하다, 중단하다","example":"The referee decided to suspend the match due to heavy rain.","deck":"vocab"},{"id":955,"word":"suspend","ipa":"/səˈspɛnd/","meaning":"(허가, 면허 등을) 정지시키다","example":"Authorities will suspend his driver's license after the accident.","deck":"vocab"},{"id":956,"word":"suspend","ipa":"/səˈspɛnd/","meaning":"정직시키다, 정학시키다","example":"The school decided to suspend the student for cheating.","deck":"vocab"},{"id":957,"word":"non-disclosure agreement","ipa":"/ˌnɑːn dɪsˈkloʊʒər əˈɡriːmənt/","meaning":"비밀 유지 계약, 비밀 유지 계약서","example":"Every new employee must sign a non-disclosure agreement before starting.","deck":"vocab"},{"id":958,"word":"offbeat","ipa":"/ˈɔːfbiːt/","meaning":"색다른, 엉뚱한, 별난","example":"The film's offbeat humor appealed to a small but loyal audience.","deck":"vocab"},{"id":959,"word":"tranquilizer","ipa":"/ˈtræŋkwɪlaɪzər/","meaning":"진정제, 신경 안정제","example":"The vet gave the frightened dog a mild tranquilizer.","deck":"vocab"},{"id":960,"word":"remnant","ipa":"/ˈrɛmnənt/","meaning":"남은, 나머지의","example":"A few remnants of the old castle still stand today.","deck":"vocab"},{"id":961,"word":"indulge","ipa":"/ɪnˈdʌldʒ/","meaning":"~가 제멋대로 하게 하다, ~가 갖고 싶은 대로 갖게 하다","example":"Her grandparents love to indulge the children with sweets.","deck":"vocab"},{"id":962,"word":"suspender","ipa":"/səˈspɛndər/","meaning":"멜빵 <미국 영어. 복수형으로 씀>","example":"He wore bright red suspenders to hold up his trousers.","deck":"vocab"},{"id":963,"word":"irritatingly","ipa":"/ˈɪrɪteɪtɪŋli/","meaning":"짜증나게 하여, 귀찮아서, 짜증스러울 정도로","example":"The song was irritatingly catchy and stuck in my head all day.","deck":"vocab"},{"id":964,"word":"distraction","ipa":"/dɪˈstrækʃən/","meaning":"머리를 식히게 해 주는 것, 기분 전환, 오락","example":"Playing video games was a welcome distraction from his worries.","deck":"vocab"},{"id":965,"word":"distraction","ipa":"/dɪˈstrækʃən/","meaning":"집중을 방해하는 것","example":"The loud music was a constant distraction while I studied.","deck":"vocab"},{"id":966,"word":"head-on","ipa":"/ˌhɛdˈɑːn/","meaning":"정면으로","example":"The two cars collided head-on at the busy intersection.","deck":"vocab"},{"id":967,"word":"twig","ipa":"/twɪɡ/","meaning":"(나무의) 잔가지","example":"The bird carefully built its nest from small twigs.","deck":"vocab"},{"id":968,"word":"perfect pitch","ipa":"/ˌpɜːrfɪkt ˈpɪtʃ/","meaning":"절대 음감 <음악 용어>","example":"Musicians with perfect pitch can name any note instantly.","deck":"vocab"},{"id":969,"word":"arson","ipa":"/ˈɑːrsən/","meaning":"방화","example":"The fire investigator suspected arson after finding gasoline traces.","deck":"vocab"},{"id":970,"word":"alluring","ipa":"/əˈlʊrɪŋ/","meaning":"(신비롭고) 매혹적인","example":"The resort's brochure painted an alluring picture of tropical beaches.","deck":"vocab"},{"id":971,"word":"congruent","ipa":"/ˈkɑːŋɡruənt/","meaning":"합동의 <기하학에서 크기와 형태가 동일함을 뜻함>","example":"The two triangles are congruent in both size and shape.","deck":"vocab"},{"id":972,"word":"defunct","ipa":"/dɪˈfʌŋkt/","meaning":"현존하지 않는, 기능이 정지된, 쓰이지 않게 된","example":"They discovered old records from a defunct railway company.","deck":"vocab"},{"id":973,"word":"sadden","ipa":"/ˈsædən/","meaning":"슬프게 하다","example":"The news of his death saddened the entire community.","deck":"vocab"},{"id":974,"word":"cowardice","ipa":"/ˈkaʊərdɪs/","meaning":"겁, 비겁","example":"He was deeply ashamed of his cowardice during the emergency.","deck":"vocab"},{"id":975,"word":"tip","ipa":"/tɪp/","meaning":"~에게 기밀 정보를 제공하다, 몰래 귀띔해주다","example":"An anonymous caller tipped the police about the robbery.","deck":"vocab"},{"id":976,"word":"bogus","ipa":"/ˈboʊɡəs/","meaning":"가짜의, 위조의, 허위의","example":"The salesman gave us a bogus phone number and disappeared.","deck":"vocab"},{"id":977,"word":"refute","ipa":"/rɪˈfjuːt/","meaning":"부인하다","example":"She quickly refuted the accusations made against her.","deck":"vocab"},{"id":978,"word":"counteract","ipa":"/ˌkaʊntərˈækt/","meaning":"대응하다, 중화하다 <반대되는 효과를 일으켜서 대상의 영향을 줄이거나 없애다>","example":"The medicine helps counteract the effects of the poison.","deck":"vocab"},{"id":979,"word":"fold","ipa":"/foʊld/","meaning":"접다, 중단하다, 포기하다","example":"The small company was forced to fold after losing its biggest client.","deck":"vocab"},{"id":980,"word":"interrogation","ipa":"/ɪnˌtɛrəˈɡeɪʃən/","meaning":"질문, 심문, 의문","example":"The suspect remained silent throughout the long interrogation.","deck":"vocab"},{"id":981,"word":"helpless","ipa":"/ˈhɛlpləs/","meaning":"(감정을) 참지 못하는, 감당하지 못하는","example":"She was helpless with laughter at his ridiculous joke.","deck":"vocab"},{"id":982,"word":"disrespect","ipa":"/ˌdɪsrɪˈspɛkt/","meaning":"~에게 무례한 짓을 하다, ~을 경멸하다","example":"Never disrespect your elders in front of the whole family.","deck":"vocab"},{"id":983,"word":"ghetto fabulous","ipa":"","meaning":"명품족의 <별로 부자도 아니면서 유명브랜드 가방이나 옷을 걸치고 다니는>","example":"He showed up in a ghetto fabulous outfit dripping with fake gold.","deck":"vocab"},{"id":984,"word":"exaggerated","ipa":"/ɪɡˈzædʒəreɪtɪd/","meaning":"과장된, 부풀린, 지나친","example":"The report gave an exaggerated account of the minor incident.","deck":"vocab"},{"id":985,"word":"schematic","ipa":"/skɪˈmætɪk/","meaning":"개략도, 개념도, 전기 배선도","example":"The engineer studied the schematic before repairing the circuit.","deck":"vocab"},{"id":986,"word":"inebriated","ipa":"/ɪˈniːbrieɪtɪd/","meaning":"술에 취한 <격식 있는 표현>","example":"The inebriated guest stumbled clumsily toward the exit.","deck":"vocab"},{"id":987,"word":"surveillance","ipa":"/sərˈveɪləns/","meaning":"감시","example":"The building is under constant surveillance by security cameras.","deck":"vocab"},{"id":988,"word":"urge","ipa":"/ɜːrdʒ/","meaning":"(강한) 욕구, 충동","example":"She felt a sudden urge to call her old friend.","deck":"vocab"},{"id":989,"word":"urge","ipa":"/ɜːrdʒ/","meaning":"(~하라고) ~에게 강력히 권하다, 열심히 설득하다 <목적어 뒤에 to부정사를 씀>","example":"Doctors urge patients to exercise regularly for better health.","deck":"vocab"},{"id":990,"word":"manifest","ipa":"/ˈmænɪfɛst/","meaning":"탑승객 명부, 탑승자 명단, 적하 목록, 화물 목록 <전문 용어>","example":"The ship's manifest listed every crate of cargo aboard.","deck":"vocab"},{"id":991,"word":"inexplicable","ipa":"/ˌɪnɪkˈsplɪkəbəl/","meaning":"불가해한, 설명할 수 없는","example":"For some inexplicable reason, the machine suddenly stopped working.","deck":"vocab"},{"id":992,"word":"tortilla","ipa":"/tɔːrˈtiːjə/","meaning":"토르티야 <둥글고 얇게 구운 멕시코식 빵. 주로 옥수수나 밀가루로 만든다>","example":"She wrapped the grilled chicken in a warm tortilla.","deck":"vocab"},{"id":993,"word":"civil servant","ipa":"/ˌsɪvəl ˈsɜːrvənt/","meaning":"공무원","example":"As a civil servant, he processed passport applications every day.","deck":"vocab"},{"id":994,"word":"parasite","ipa":"/ˈpærəsaɪt/","meaning":"기생충 <남에게 빌붙어 사는 사람을 비유적으로 표현할 때도 씀>","example":"The doctor found a parasite living in the patient's intestine.","deck":"vocab"},{"id":995,"word":"dictate","ipa":"/ˈdɪkteɪt/","meaning":"명령, 규칙, 요구 <격식 있는 표현. 주로 복수형으로 씀>","example":"We must follow the dictates of our conscience in this matter.","deck":"vocab"},{"id":996,"word":"extortion","ipa":"/ɪkˈstɔːrʃən/","meaning":"(금전 따위의) 갈취","example":"The gang was arrested for extortion and money laundering.","deck":"vocab"},{"id":997,"word":"recap","ipa":"/ˈriːkæp/","meaning":"(이미 한 말, 결정 사항 등을) 요약하다","example":"Let me recap the main points before we finish the meeting.","deck":"vocab"},{"id":998,"word":"outpatient","ipa":"/ˈaʊtpeɪʃənt/","meaning":"(병원의) 외래 환자","example":"He was treated as an outpatient and went home the same day.","deck":"vocab"},{"id":999,"word":"swamped","ipa":"/swɑːmpt/","meaning":"눈코 뜰 새 없이 바쁜","example":"I'm completely swamped with work this week and can't join you.","deck":"vocab"},{"id":1000,"word":"pastime","ipa":"/ˈpæstaɪm/","meaning":"취미, 여가 활동","example":"Fishing is his favorite pastime on lazy summer weekends.","deck":"vocab"},{"id":1001,"word":"vulnerable","ipa":"/ˈvʌlnərəbəl/","meaning":"(~에) 취약한, 연약한 <신체적, 정서적으로 상처받기 쉬움>","example":"Newborn babies are especially vulnerable to infections and cold weather.","deck":"vocab"},{"id":1002,"word":"amen","ipa":"/ˌeɪˈmɛn/","meaning":"전적으로 동감해, 그 말이 맞다","example":"Amen to that, my friend, you couldn't have said it better.","deck":"vocab"},{"id":1003,"word":"solemn","ipa":"/ˈsɑːləm/","meaning":"엄숙한, 근엄한","example":"The judge spoke in a solemn voice as she read the verdict.","deck":"vocab"},{"id":1004,"word":"adolescence","ipa":"/ˌædəˈlɛsəns/","meaning":"청소년기","example":"Many people struggle with self-esteem during their adolescence.","deck":"vocab"},{"id":1005,"word":"scar","ipa":"/skɑːr/","meaning":"(피부에 생긴) 흉터, 반흔, 상흔","example":"He still has a small scar on his forehead from the accident.","deck":"vocab"},{"id":1006,"word":"scar","ipa":"/skɑːr/","meaning":"(상처 등이) 흉터를 남기다","example":"The burn was so deep that it would scar his arm forever.","deck":"vocab"},{"id":1007,"word":"inscription","ipa":"/ɪnˈskrɪpʃən/","meaning":"(책, 금속, 돌 등에) 새겨진 글, 명문(銘文) <셀 수 있는 명사>","example":"The old ring had a tiny inscription engraved on the inside.","deck":"vocab"},{"id":1008,"word":"runner-up","ipa":"/ˌrʌnərˈʌp/","meaning":"(경주, 대회에서) 1위 외의 입상자","example":"She finished as the runner-up in the national piano competition.","deck":"vocab"},{"id":1009,"word":"law enforcement","ipa":"/ˌlɔː ɪnˈfɔːrsmənt/","meaning":"사법 당국 <경찰을 비롯한 치안 조직을 일컫는 말>","example":"Local law enforcement worked together to catch the suspect quickly.","deck":"vocab"},{"id":1010,"word":"resolution","ipa":"/ˌrɛzəˈluːʃən/","meaning":"결의안","example":"The council passed a resolution to ban plastic bags citywide.","deck":"vocab"},{"id":1011,"word":"resolution","ipa":"/ˌrɛzəˈluːʃən/","meaning":"결심, 다짐 <하겠다고, 또는 하지 않겠다고 마음먹은 것들을 뜻함>","example":"My New Year's resolution is to exercise at least three times weekly.","deck":"vocab"},{"id":1012,"word":"geek","ipa":"/ɡiːk/","meaning":"덕후, 오덕후, 괴짜 <한 분야에 집착하는 기질이 있는 사람>","example":"He's a total computer geek who builds his own machines.","deck":"vocab"},{"id":1013,"word":"ostracize","ipa":"/ˈɑːstrəsaɪz/","meaning":"(사람을) ~을 외면하다, 배척하다, 따돌리다","example":"Her classmates began to ostracize her after the rumor spread.","deck":"vocab"},{"id":1014,"word":"usher","ipa":"/ˈʌʃər/","meaning":"안내하다","example":"A young man will usher the guests to their assigned seats.","deck":"vocab"},{"id":1015,"word":"lovelorn","ipa":"/ˈlʌvlɔːrn/","meaning":"상사병에 걸린, 사랑에 애태우는","example":"The lovelorn poet wrote endless verses about his lost sweetheart.","deck":"vocab"},{"id":1016,"word":"pandemonium","ipa":"/ˌpændəˈmoʊniəm/","meaning":"대혼란","example":"Pandemonium broke out when the fire alarm suddenly went off.","deck":"vocab"},{"id":1017,"word":"sketchy","ipa":"/ˈskɛtʃi/","meaning":"나쁜 짓을 한 것 같은, 수상쩍은 <비격식적인 표현>","example":"That guy looked pretty sketchy, so I kept my distance.","deck":"vocab"},{"id":1018,"word":"seminal","ipa":"/ˈsɛmɪnəl/","meaning":"중대한, 중요한, 영향력이 큰","example":"Her seminal paper changed how scientists study human memory.","deck":"vocab"},{"id":1019,"word":"monetize","ipa":"/ˈmɑːnɪtaɪz/","meaning":"(인터넷 서비스 등을) 유료화하다","example":"The startup struggled to monetize its popular free messaging app.","deck":"vocab"},{"id":1020,"word":"stain","ipa":"/steɪn/","meaning":"얼룩 <주로 액체가 스며들어 지우기 어려운 자국을 뜻함>","example":"There's a stubborn coffee stain right on my white shirt.","deck":"vocab"},{"id":1021,"word":"decent","ipa":"/ˈdiːsənt/","meaning":"(남이 봐도 될 만큼) 옷을 제대로 입은","example":"Give me a minute to get decent before you come in.","deck":"vocab"},{"id":1022,"word":"decent","ipa":"/ˈdiːsənt/","meaning":"괜찮은, 제대로 된, 그럴듯한","example":"We finally found a decent restaurant near the train station.","deck":"vocab"},{"id":1023,"word":"outlast","ipa":"/ˌaʊtˈlæst/","meaning":"~보다 더 오래 가다, ~보다 오래 계속되다","example":"These sturdy boots will easily outlast any cheaper pair you buy.","deck":"vocab"},{"id":1024,"word":"composition","ipa":"/ˌkɑːmpəˈzɪʃən/","meaning":"(그림이나 사진의) 구도","example":"The photographer adjusted the composition to balance light and shadow.","deck":"vocab"},{"id":1025,"word":"introvert","ipa":"/ˈɪntrəvɜːrt/","meaning":"내성적인 사람, 내향적인 사람","example":"As an introvert, she prefers quiet evenings over crowded parties.","deck":"vocab"},{"id":1026,"word":"delicacy","ipa":"/ˈdɛlɪkəsi/","meaning":"(특정 지역의) 진미, 별미","example":"Grilled octopus is a local delicacy along this coastal town.","deck":"vocab"},{"id":1027,"word":"delicacy","ipa":"/ˈdɛlɪkəsi/","meaning":"섬세함","example":"She handled the antique vase with great care and delicacy.","deck":"vocab"},{"id":1028,"word":"clumsy","ipa":"/ˈklʌmzi/","meaning":"(사람이) 어설픈, 칠칠치 못한","example":"He felt clumsy and dropped his glass twice during dinner.","deck":"vocab"},{"id":1029,"word":"plausible","ipa":"/ˈplɔːzəbəl/","meaning":"타당한 것 같은, 이치에 맞는, 그럴듯한","example":"Her excuse sounded plausible, so we decided to believe her.","deck":"vocab"},{"id":1030,"word":"bend over backwards","ipa":"","meaning":"무진 애를 쓰다, 안간힘을 쓰다","example":"The staff bent over backwards to make our stay comfortable.","deck":"vocab"},{"id":1031,"word":"pop into one's mind","ipa":"","meaning":"문득 머릿속에 떠오르다","example":"A brilliant idea suddenly popped into my mind during the shower.","deck":"vocab"},{"id":1032,"word":"chestnut","ipa":"/ˈtʃɛsnʌt/","meaning":"밤","example":"We roasted a bag of chestnut over the open fire.","deck":"vocab"},{"id":1033,"word":"demean","ipa":"/dɪˈmiːn/","meaning":"위신을 떨어뜨리다, 품위를 손상시키다, 비하하다","example":"Don't demean yourself by arguing with such a rude person.","deck":"vocab"},{"id":1034,"word":"nerve-racking","ipa":"/ˈnɜːrv ˌrækɪŋ/","meaning":"신경 쓰이는, 안절부절못하게 하는","example":"Waiting for the exam results was an absolutely nerve-racking experience.","deck":"vocab"},{"id":1035,"word":"unorthodox","ipa":"/ʌnˈɔːrθədɑːks/","meaning":"정통적이 아닌, 특이한","example":"The coach used an unorthodox training method that surprised everyone.","deck":"vocab"},{"id":1036,"word":"pitfall","ipa":"/ˈpɪtfɔːl/","meaning":"위험, 곤란, 문제가 될 수 있는 부분","example":"One common pitfall for new investors is chasing quick profits.","deck":"vocab"},{"id":1037,"word":"pecuniary","ipa":"/pɪˈkjuːnieri/","meaning":"금전상의 <격식 있는 표현>","example":"He received no pecuniary reward for his years of volunteering.","deck":"vocab"},{"id":1038,"word":"tactic","ipa":"/ˈtæktɪk/","meaning":"전술, 전략, 작전 <단기적 목표를 달성하기 위한 수단이나 방법>","example":"Delaying the meeting was just a tactic to buy more time.","deck":"vocab"},{"id":1039,"word":"manta ray","ipa":"/ˈmæntə reɪ/","meaning":"쥐가오리, 만타가오리","example":"A giant manta ray glided gracefully beneath our small boat.","deck":"vocab"},{"id":1040,"word":"urine","ipa":"/ˈjʊrɪn/","meaning":"소변, 오줌","example":"The doctor asked for a urine sample before the checkup.","deck":"vocab"},{"id":1041,"word":"accredited","ipa":"/əˈkrɛdɪtɪd/","meaning":"공인된, 인가받은, 승인받은","example":"She earned her degree from a fully accredited online university.","deck":"vocab"},{"id":1042,"word":"orthodox","ipa":"/ˈɔːrθədɑːks/","meaning":"정통의, 정통적인, 옳다고 인정된","example":"He preferred orthodox treatments over any experimental new therapy.","deck":"vocab"},{"id":1043,"word":"obedient","ipa":"/oʊˈbiːdiənt/","meaning":"말을 잘 듣는, 순종적인, 복종하는","example":"Their obedient dog sat quietly until they gave the command.","deck":"vocab"},{"id":1044,"word":"altercation","ipa":"/ˌɔːltərˈkeɪʃən/","meaning":"(화가 나서 시끄럽게 하는) 말다툼, 언쟁","example":"A loud altercation between two drivers blocked the whole intersection.","deck":"vocab"},{"id":1045,"word":"dissect","ipa":"/dɪˈsɛkt/","meaning":"(동식물을) 해부하다, 절개하다","example":"Students had to dissect a frog in the biology lab today.","deck":"vocab"},{"id":1046,"word":"attagirl","ipa":"/ˈætəɡɜːrl/","meaning":"잘한다, 장하다 <여자아이나 어른에게 하는 격려의 말이었다>","example":"Attagirl! You finished the whole race without stopping once.","deck":"vocab"},{"id":1047,"word":"sultry","ipa":"/ˈsʌltri/","meaning":"(날씨, 공기가) 후텁지근한, 덥고 습한","example":"The sultry afternoon left everyone sweating and searching for shade.","deck":"vocab"},{"id":1048,"word":"cannibal","ipa":"/ˈkænɪbəl/","meaning":"식인종","example":"The old legend warned travelers about a cannibal living in the forest.","deck":"vocab"},{"id":1049,"word":"emissary","ipa":"/ˈɛmɪsɛri/","meaning":"사절, 특사 <격식>","example":"The king sent a trusted emissary to negotiate the peace treaty.","deck":"vocab"},{"id":1050,"word":"appetite","ipa":"/ˈæpɪtaɪt/","meaning":"식욕","example":"The long hike gave the children a huge appetite for dinner.","deck":"vocab"},{"id":1051,"word":"ravenous","ipa":"/ˈrævənəs/","meaning":"(식욕, 배고픔 등이) 엄청난","example":"After skipping lunch, I had a ravenous hunger by evening.","deck":"vocab"},{"id":1052,"word":"microbe","ipa":"/ˈmaɪkroʊb/","meaning":"미생물","example":"A single microbe can multiply into millions within a few hours.","deck":"vocab"},{"id":1053,"word":"stick out","ipa":"","meaning":"~을 내밀다, ~을 튀어나오게 하다","example":"Don't stick out your tongue at your little brother again.","deck":"vocab"},{"id":1054,"word":"pot calling the kettle black","ipa":"","meaning":"똥 묻은 개가 겨 묻은 개 나무란다 <직역하면, \"냄비가 주전자보고 검다고 한다\"라는 뜻>","example":"You call me lazy? That's the pot calling the kettle black.","deck":"vocab"},{"id":1055,"word":"veto","ipa":"/ˈviːtoʊ/","meaning":"~을 거부하다, ~에 대해 거부권을 행사하다","example":"The president decided to veto the controversial spending bill.","deck":"vocab"},{"id":1056,"word":"invest","ipa":"/ɪnˈvɛst/","meaning":"(~을) ~에게 부여하다","example":"The constitution invests great authority in the elected president.","deck":"vocab"},{"id":1057,"word":"constitution","ipa":"/ˌkɑːnstɪˈtuːʃən/","meaning":"헌법","example":"Freedom of speech is protected under the country's constitution.","deck":"vocab"},{"id":1058,"word":"hindrance","ipa":"/ˈhɪndrəns/","meaning":"방해, 훼방 <셀 수 없는 명사>","example":"The heavy rain was a serious hindrance to our travel plans.","deck":"vocab"},{"id":1059,"word":"prodigious","ipa":"/prəˈdɪdʒəs/","meaning":"(놀라움, 감탄을 자아낼 정도로) 엄청난, 굉장한","example":"The young pianist showed prodigious talent from a very early age.","deck":"vocab"},{"id":1060,"word":"frivolous","ipa":"/ˈfrɪvələs/","meaning":"시시한, 하찮은, 쓸데없는, 무의미한","example":"She wasted her savings on frivolous purchases she never used.","deck":"vocab"},{"id":1061,"word":"frivolous","ipa":"/ˈfrɪvələs/","meaning":"(사람이) 경솔한, 천박한, 경박한","example":"His frivolous attitude annoyed the serious members of the team.","deck":"vocab"},{"id":1062,"word":"move heaven and earth","ipa":"","meaning":"(뭔가를 달성하기 위해) 갖은 노력을 다하다","example":"She moved heaven and earth to get her son the surgery.","deck":"vocab"},{"id":1063,"word":"falter","ipa":"/ˈfɔːltər/","meaning":"(목소리가) 떨리다, 더듬거리다","example":"His voice began to falter as he read the farewell letter.","deck":"vocab"},{"id":1064,"word":"decree","ipa":"/dɪˈkriː/","meaning":"포고하다, 선포하다, 명하다, 법령으로 정하다","example":"The king decreed that all citizens must pay the new tax.","deck":"vocab"},{"id":1065,"word":"throng","ipa":"/θrɔːŋ/","meaning":"(많은 사람 또는 동물의) 빽빽한 무리, 떼 <문어체>","example":"A throng of fans gathered outside the theater for autographs.","deck":"vocab"},{"id":1066,"word":"aesthetic","ipa":"/ɛsˈθɛtɪk/","meaning":"심미적, 미학적, 미적인","example":"The building's aesthetic design won several international awards.","deck":"vocab"},{"id":1067,"word":"aesthetic","ipa":"/ɛsˈθɛtɪk/","meaning":"미적 특성, 미의식","example":"Her paintings share a minimalist aesthetic rooted in nature.","deck":"vocab"},{"id":1068,"word":"rip ~ off","ipa":"","meaning":"~에게 바가지를 씌우다 <주로 수동태로 씀>","example":"I got ripped off buying this fake watch from a street vendor.","deck":"vocab"},{"id":1069,"word":"captive","ipa":"/ˈkæptɪv/","meaning":"포로 <전쟁에서 사로잡힌 적, 감금된 짐승 등을 뜻함>","example":"The soldiers finally freed the captive after months of imprisonment.","deck":"vocab"},{"id":1070,"word":"delusion","ipa":"/dɪˈluːʒən/","meaning":"망상, 허황된 생각","example":"He lives under the delusion that he'll become famous overnight.","deck":"vocab"},{"id":1071,"word":"maternity leave","ipa":"/məˈtɜːrnəti liːv/","meaning":"출산 휴가","example":"She plans to take six months of maternity leave next spring.","deck":"vocab"},{"id":1072,"word":"itch","ipa":"/ɪtʃ/","meaning":"(몹시 ~하고 싶어 몸이) 근질거리다, 근지럽다","example":"My fingers itch to start painting whenever I see a blank canvas.","deck":"vocab"},{"id":1073,"word":"limp","ipa":"/lɪmp/","meaning":"(사물이) 흐물흐물한, 흐느적거리는","example":"The flowers had gone limp after a week without any water.","deck":"vocab"},{"id":1074,"word":"limp","ipa":"/lɪmp/","meaning":"다리를 절다, 절뚝거리다","example":"He began to limp badly after twisting his ankle on the trail.","deck":"vocab"},{"id":1075,"word":"slaughter","ipa":"/ˈslɔːtər/","meaning":"(가축을) 도살하다, 도축하다","example":"The farm workers slaughter the pigs early each morning.","deck":"vocab"},{"id":1076,"word":"appropriate","ipa":"/əˈproʊprieɪt/","meaning":"도용하다, 전용하다, 유용하다 <자신의 것이 아닌 것을 권한 없이 가져다 쓰다>","example":"The company was accused of appropriating the artist's original design.","deck":"vocab"},{"id":1077,"word":"barley","ipa":"/ˈbɑːrli/","meaning":"보리","example":"The soup was thickened with tender barley and fresh vegetables.","deck":"vocab"},{"id":1078,"word":"parental","ipa":"/pəˈrɛntəl/","meaning":"부모의, 부모로서의","example":"Minors need parental consent to join the overnight school trip.","deck":"vocab"},{"id":1079,"word":"dilute","ipa":"/daɪˈluːt/","meaning":"(액체를) 희석하다, 묽게 하다","example":"You should dilute the concentrated juice with plenty of cold water.","deck":"vocab"},{"id":1080,"word":"extravagant","ipa":"/ɪkˈstrævəɡənt/","meaning":"사치스러운","example":"They threw an extravagant wedding with hundreds of expensive guests.","deck":"vocab"},{"id":1081,"word":"gig","ipa":"/ɡɪɡ/","meaning":"(대중음악가, 코미디언의) 공연, 출연","example":"The band played a small gig at a downtown jazz club.","deck":"vocab"},{"id":1082,"word":"inexorable","ipa":"/ɪnˈɛksərəbəl/","meaning":"멈출 수 없는, 거침없는","example":"The inexorable rise of technology keeps changing how we work.","deck":"vocab"},{"id":1083,"word":"processed food","ipa":"/ˈprɑːsɛst fuːd/","meaning":"가공식품","example":"Doctors warn that too much processed food harms your health.","deck":"vocab"},{"id":1084,"word":"pathetic","ipa":"/pəˈθɛtɪk/","meaning":"한심한 <비격식적인 표현>","example":"His pathetic excuse for being late fooled absolutely no one.","deck":"vocab"},{"id":1085,"word":"Band-Aid","ipa":"/ˈbænd eɪd/","meaning":"일회용 반창고","example":"She put a Band-Aid over the small cut on her finger.","deck":"vocab"},{"id":1086,"word":"spread","ipa":"/sprɛd/","meaning":"나누다, 분산하다, 분산시키다","example":"We decided to spread the payments across three separate months.","deck":"vocab"},{"id":1087,"word":"novelty","ipa":"/ˈnɑːvəlti/","meaning":"새로움, 참신함, 신기함","example":"The novelty of the new phone wore off within a week.","deck":"vocab"},{"id":1088,"word":"novelty","ipa":"/ˈnɑːvəlti/","meaning":"색다른, 진기한","example":"They sold cheap novelty souvenirs outside the crowded museum.","deck":"vocab"},{"id":1089,"word":"asymmetric","ipa":"/ˌeɪsɪˈmɛtrɪk/","meaning":"(도형의 형태가) 비대칭의","example":"The dress featured an asymmetric hemline that everyone admired.","deck":"vocab"},{"id":1090,"word":"long","ipa":"/lɔːŋ/","meaning":"갈망하다, 간절히 바라다","example":"After years abroad, she began to long for her hometown.","deck":"vocab"},{"id":1091,"word":"trade deficit","ipa":"/ˈtreɪd ˌdɛfɪsɪt/","meaning":"무역 적자, 무역 수지 적자 <경제 용어>","example":"The country reported its largest trade deficit in over a decade.","deck":"vocab"},{"id":1092,"word":"pilgrimage","ipa":"/ˈpɪlɡrɪmɪdʒ/","meaning":"순례 <비유적으로, 의미 있는 곳을 찾아다니며 방문하는 것을 뜻하기도 함>","example":"Thousands make the pilgrimage to the sacred temple every year.","deck":"vocab"},{"id":1093,"word":"squash","ipa":"/skwɑːʃ/","meaning":"짓누르다, 으깨다, 찌부러뜨리다","example":"Be careful not to squash the ripe tomatoes in your bag.","deck":"vocab"},{"id":1094,"word":"squash","ipa":"/skwɑːʃ/","meaning":"호박","example":"She roasted a butternut squash with olive oil and herbs.","deck":"vocab"},{"id":1095,"word":"articulate","ipa":"/ɑːrˈtɪkjəleɪt/","meaning":"발음을 또렷이 하다, 또렷이 말하다 <자동사>","example":"Try to articulate clearly so the audience understands every word.","deck":"vocab"},{"id":1096,"word":"articulate","ipa":"/ɑːrˈtɪkjəleɪt/","meaning":"명확히 표현하다, 분명히 설명하다 (타동사)","example":"She could articulate her ideas with remarkable clarity and confidence.","deck":"vocab"},{"id":1097,"word":"sissy","ipa":"/ˈsɪsi/","meaning":"여자 같은 남자 아이","example":"The older boys unfairly called him a sissy for crying.","deck":"vocab"},{"id":1098,"word":"inversion","ipa":"/ɪnˈvɜːrʒən/","meaning":"반전, 전도(轉倒), 도치","example":"The story's clever inversion of roles surprised every reader.","deck":"vocab"},{"id":1099,"word":"inclination","ipa":"/ˌɪnklɪˈneɪʃən/","meaning":"(~하는) 경향","example":"He has a natural inclination to help strangers in trouble.","deck":"vocab"},{"id":1100,"word":"crumb","ipa":"/krʌm/","meaning":"소량, 작은 부분, 약간","example":"She didn't offer even a crumb of sympathy for my situation.","deck":"vocab"},{"id":1101,"word":"rededicate","ipa":"/ˌriːˈdɛdɪkeɪt/","meaning":"~을 다시 바치다, 다시 헌정하다","example":"The mayor will rededicate the restored monument to the fallen soldiers.","deck":"vocab"},{"id":1102,"word":"fructose","ipa":"/ˈfrʌktoʊs/","meaning":"과당(果糖) <화학 용어>","example":"Ripe fruit contains natural fructose that gives it a sweet taste.","deck":"vocab"},{"id":1103,"word":"think of ~ as ~","ipa":"","meaning":"~을 ~으로 생각하다, ~을 ~으로 여기다","example":"I think of my mentor as a second father to me.","deck":"vocab"},{"id":1104,"word":"shrug off","ipa":"","meaning":"~을 떨쳐 버리다, ~에서 벗어나다, ~에서 자유롭게 되다","example":"She tried to shrug off the criticism and focus on her work.","deck":"vocab"},{"id":1105,"word":"spiteful","ipa":"/ˈspaɪtfəl/","meaning":"앙심을 품은, 독기를 품은, 악의적인","example":"He sent a spiteful message just to hurt her feelings.","deck":"vocab"},{"id":1106,"word":"snap","ipa":"/snæp/","meaning":"한 순간에 무너지다, 갑자기 폭발하다 <갑작스럽게 자제력을 잃는 것을 뜻함>","example":"After weeks of stress, he finally snapped and yelled at everyone.","deck":"vocab"},{"id":1107,"word":"concussion","ipa":"/kənˈkʌʃən/","meaning":"뇌진탕","example":"The player suffered a concussion after colliding with the goalpost.","deck":"vocab"},{"id":1108,"word":"covered in bruises","ipa":"","meaning":"군데군데 멍이 든, 멍투성이인","example":"After the fall, her legs were covered in bruises for weeks.","deck":"vocab"},{"id":1109,"word":"company","ipa":"/ˈkʌmpəni/","meaning":"(방문하러 온) 손님","example":"We're having company over for dinner, so please tidy up.","deck":"vocab"},{"id":1110,"word":"pill","ipa":"/pɪl/","meaning":"귀찮은 인간, 귀찮은 녀석","example":"Her younger cousin is such a pill during long car rides.","deck":"vocab"},{"id":1111,"word":"inside out","ipa":"","meaning":"속속들이, 철저하게","example":"After years of repairs, he knows this old car inside out.","deck":"vocab"},{"id":1112,"word":"pebble","ipa":"/ˈpɛbəl/","meaning":"조약돌, 자갈","example":"A small pebble slipped into my shoe during the hike.","deck":"vocab"},{"id":1113,"word":"illustrate","ipa":"/ˈɪləstreɪt/","meaning":"분명히 보여주다, 분명히 하다","example":"This chart clearly illustrates how sales grew over the year.","deck":"vocab"},{"id":1114,"word":"get over ~","ipa":"","meaning":"~을 극복하다, ~에서 회복하다","example":"It took her months to get over the painful breakup.","deck":"vocab"},{"id":1115,"word":"bring ~ down","ipa":"","meaning":"~를 침울하게 만들다, 실망시키다, 의기소침하게 하다","example":"Constant bad news can really bring you down over time.","deck":"vocab"},{"id":1116,"word":"funeral","ipa":"/ˈfjuːnərəl/","meaning":"장례식","example":"Hundreds of people attended the funeral to honor the beloved teacher.","deck":"vocab"},{"id":1117,"word":"common decency","ipa":"/ˌkɑːmən ˈdiːsənsi/","meaning":"상식적인 예절, 일상적인 예절","example":"Common decency requires that you apologize when you're clearly wrong.","deck":"vocab"},{"id":1118,"word":"shed","ipa":"/ʃɛd/","meaning":"보관하는 곳, 헛간","example":"He keeps his garden tools locked inside the wooden shed.","deck":"vocab"},{"id":1119,"word":"shed","ipa":"/ʃɛd/","meaning":"~을 벗다","example":"Snakes shed their skin several times as they grow.","deck":"vocab"},{"id":1120,"word":"filthy","ipa":"/ˈfɪlθi/","meaning":"아주 더러운","example":"The abandoned kitchen was filthy and covered in thick dust.","deck":"vocab"},{"id":1121,"word":"variant","ipa":"/ˈvɛriənt/","meaning":"변종, 변이, 이형(異形)","example":"Scientists discovered a new variant of the common flu virus.","deck":"vocab"},{"id":1122,"word":"ponderous","ipa":"/ˈpɑːndərəs/","meaning":"대단히 무거운, 육중한, 느릿느릿한","example":"The ponderous elephant moved slowly across the dry savanna.","deck":"vocab"},{"id":1123,"word":"ponderous","ipa":"/ˈpɑːndərəs/","meaning":"(너무) 지루한, 장황한, 답답한 <격식 있는 표현. 책, 연설 등에 씀>","example":"The professor's ponderous lecture put half the students to sleep.","deck":"vocab"},{"id":1124,"word":"inside baseball","ipa":"","meaning":"(어떤 주제에 대한) 상세한 지식","example":"His speech was too much inside baseball for ordinary voters.","deck":"vocab"},{"id":1125,"word":"impostor","ipa":"/ɪmˈpɑːstər/","meaning":"사칭하는 사람, 사기꾼","example":"The impostor pretended to be a doctor to gain their trust.","deck":"vocab"},{"id":1126,"word":"grab one's attention","ipa":"","meaning":"~의 관심을 끌다","example":"The bright headline was designed to grab your attention instantly.","deck":"vocab"},{"id":1127,"word":"pilum","ipa":"/ˈpaɪləm/","meaning":"(고대 로마 병사의) 투창","example":"Each Roman legionary carried a heavy pilum into the fierce battle.","deck":"vocab"},{"id":1128,"word":"bark","ipa":"/bɑːrk/","meaning":"나무껍질","example":"The rough bark of the old oak felt cool under my hand.","deck":"vocab"},{"id":1129,"word":"barnacle","ipa":"/ˈbɑːrnəkəl/","meaning":"따개비 <바위나 배 밑에 들러붙는, 작은 조개같이 생긴 것>","example":"The ship's hull was crusted with barnacle and green algae.","deck":"vocab"},{"id":1130,"word":"glucose","ipa":"/ˈɡluːkoʊs/","meaning":"포도당","example":"The nurse measured his blood glucose level before breakfast.","deck":"vocab"},{"id":1131,"word":"pulse","ipa":"/pʌls/","meaning":"활기가 넘치다, 흥분이 넘치다","example":"The whole city seemed to pulse with energy during the festival.","deck":"vocab"},{"id":1132,"word":"prune","ipa":"/pruːn/","meaning":"(나무를) 가지치기하다","example":"You should prune the rose bushes before the first frost.","deck":"vocab"},{"id":1133,"word":"savor","ipa":"/ˈseɪvər/","meaning":"(맛, 풍미를) 음미하다, 즐기다","example":"She closed her eyes to savor the rich chocolate dessert.","deck":"vocab"},{"id":1134,"word":"savor","ipa":"/ˈseɪvər/","meaning":"만끽하다","example":"Let's savor every moment of this peaceful weekend by the lake.","deck":"vocab"},{"id":1135,"word":"humiliating","ipa":"/hjuːˈmɪlieɪtɪŋ/","meaning":"굴욕적인, 면목 없는","example":"Losing so badly in front of everyone was truly humiliating.","deck":"vocab"},{"id":1136,"word":"fallacy","ipa":"/ˈfæləsi/","meaning":"틀린 생각, 잘못된 믿음","example":"It's a common fallacy that lightning never strikes twice.","deck":"vocab"},{"id":1137,"word":"fallacy","ipa":"/ˈfæləsi/","meaning":"(인식상의) 오류","example":"His argument rested on a logical fallacy the judges quickly spotted.","deck":"vocab"},{"id":1138,"word":"enforceable","ipa":"/ɪnˈfɔːrsəbəl/","meaning":"시행할 수 있는, 집행할 수 있는, 강제할 수 있는","example":"Without a signature, the contract is not legally enforceable.","deck":"vocab"},{"id":1139,"word":"prolong","ipa":"/prəˈlɔːŋ/","meaning":"~이 더 길게 지속되게 하다, 더 길게 유지되도록 하다","example":"Regular exercise can help prolong a healthy and active life.","deck":"vocab"},{"id":1140,"word":"foreseeable","ipa":"/fɔːrˈsiːəbəl/","meaning":"예측할 수 있는","example":"Prices are unlikely to drop in the foreseeable future.","deck":"vocab"},{"id":1141,"word":"dejected","ipa":"/dɪˈdʒɛktɪd/","meaning":"실의에 빠진, 낙담한","example":"He looked dejected after failing the driving test again.","deck":"vocab"},{"id":1142,"word":"inflate","ipa":"/ɪnˈfleɪt/","meaning":"(가격을) 인상하다, 올리다","example":"Some vendors inflate their prices sharply during the busy holiday season.","deck":"vocab"},{"id":1143,"word":"integral","ipa":"/ˈɪntɪɡrəl/","meaning":"(전체의 일부로서) 필수적인","example":"Teamwork is an integral part of our company's daily culture.","deck":"vocab"},{"id":1144,"word":"shriek","ipa":"/ʃriːk/","meaning":"꽥 소리를 지르며 ~을 말하다, 악을 쓰며 ~라고 말하다 <타동사>","example":"\"Watch out!\" she shrieked as the ball flew toward him.","deck":"vocab"},{"id":1145,"word":"crack","ipa":"/kræk/","meaning":"시도, 도전, 도전의 기회 <비격식적인 표현>","example":"I've never painted before, but I'll give it a crack.","deck":"vocab"},{"id":1146,"word":"tolerate","ipa":"/ˈtɑːləreɪt/","meaning":"용납하다, 용인하다","example":"The teacher will not tolerate cheating during any of her exams.","deck":"vocab"},{"id":1147,"word":"abusive","ipa":"/əˈbjuːsɪv/","meaning":"(말, 사람이) 모욕적인, 욕하는","example":"She reported the customer for sending abusive messages to staff.","deck":"vocab"},{"id":1148,"word":"blatantly","ipa":"/ˈbleɪtəntli/","meaning":"주제넘게, 뻔뻔스럽게","example":"He blatantly ignored the rules right in front of the referee.","deck":"vocab"},{"id":1149,"word":"unravel","ipa":"/ʌnˈrævəl/","meaning":"(이해하기 어려운 것, 미스터리 등이) 풀리다","example":"The mystery slowly began to unravel as new clues appeared.","deck":"vocab"},{"id":1150,"word":"unravel","ipa":"/ʌnˈrævəl/","meaning":"(이해하기 어려운 것, 미스터리 등을) 풀다","example":"Detectives worked all night to unravel the complicated case.","deck":"vocab"},{"id":1151,"word":"obnoxious","ipa":"/əbˈnɑːkʃəs/","meaning":"아주 불쾌한, 몹시 기분 나쁜","example":"His obnoxious behavior at the party embarrassed all his friends.","deck":"vocab"},{"id":1152,"word":"thaw","ipa":"/θɔː/","meaning":"(눈, 얼음 등의 얼어 있던 물체가) 녹다","example":"The snow began to thaw as the spring sun grew warmer.","deck":"vocab"},{"id":1153,"word":"thaw","ipa":"/θɔː/","meaning":"녹이다, 해동시키다","example":"Remember to thaw the frozen chicken before you start cooking.","deck":"vocab"},{"id":1154,"word":"graham","ipa":"/ˈɡreɪəm/","meaning":"통밀의","example":"We made the pie crust from crushed graham crackers.","deck":"vocab"},{"id":1155,"word":"unfathomable","ipa":"/ʌnˈfæðəməbəl/","meaning":"불가해한","example":"The depth of the ocean remains unfathomable to most people.","deck":"vocab"},{"id":1156,"word":"extremist","ipa":"/ɪkˈstriːmɪst/","meaning":"극단주의자","example":"The group was labeled an extremist organization by the government.","deck":"vocab"},{"id":1157,"word":"on parole","ipa":"","meaning":"가석방되어, 가석방된","example":"He was released on parole after serving five years.","deck":"vocab"},{"id":1158,"word":"sleep-deprived","ipa":"/ˈsliːp dɪˌpraɪvd/","meaning":"잠이 부족한","example":"New parents are often sleep-deprived during the first few months.","deck":"vocab"},{"id":1159,"word":"encounter","ipa":"/ɪnˈkaʊntər/","meaning":"(예상치 못하게) 마주치다, 접하다 <격식 있는 표현>","example":"Hikers may encounter wild deer along this quiet mountain trail.","deck":"vocab"},{"id":1160,"word":"indifferent","ipa":"/ɪnˈdɪfərənt/","meaning":"무관심한 <명사 앞에는 잘 안 씀>","example":"He seemed completely indifferent to the outcome of the game.","deck":"vocab"},{"id":1161,"word":"lift","ipa":"/lɪft/","meaning":"(차 등을) 태워 주기, 얻어 타기","example":"Could you give me a lift to the station tomorrow morning?","deck":"vocab"},{"id":1162,"word":"lift","ipa":"/lɪft/","meaning":"(제재를) 풀다, 해제하다","example":"The government agreed to lift the travel ban next month.","deck":"vocab"},{"id":1163,"word":"burst in","ipa":"","meaning":"불쑥 들어가다, 불쑥 들어오다","example":"She burst in without knocking and interrupted our private meeting.","deck":"vocab"},{"id":1164,"word":"lay ~ off","ipa":"","meaning":"~를 정리해고하다","example":"The factory had to lay off two hundred workers last year.","deck":"vocab"},{"id":1165,"word":"severance pay","ipa":"/ˈsɛvərəns peɪ/","meaning":"퇴직금, 해직 수당","example":"The company offered generous severance pay to the laid-off employees.","deck":"vocab"},{"id":1166,"word":"catch-22","ipa":"/ˌkætʃ twɛnti ˈtuː/","meaning":"모순된 상황, 이러지도 저러지도 못하는 상태, 딜레마, 곤경","example":"Needing experience to get a job is a real catch-22.","deck":"vocab"},{"id":1167,"word":"chop ~ off","ipa":"","meaning":"~을 (~에서) 잘라 내다","example":"The chef chopped off the fish head before cooking it.","deck":"vocab"},{"id":1168,"word":"plaster","ipa":"/ˈplæstər/","meaning":"회반죽, 석고반죽","example":"The workers smoothed fresh plaster over the cracked old wall.","deck":"vocab"},{"id":1169,"word":"desert","ipa":"/dɪˈzɜːrt/","meaning":"(어떤 장소를) 버리다, 떠나다 <흔히 수동태로 씀>","example":"The town was deserted after the factory finally closed down.","deck":"vocab"},{"id":1170,"word":"desert","ipa":"/dɪˈzɜːrt/","meaning":"(도와주거나 부양하지 않고) 버리다, 저버리다","example":"He would never desert his family in their time of need.","deck":"vocab"},{"id":1171,"word":"advocate","ipa":"/ˈædvəkeɪt/","meaning":"공개적으로 지지하다, 옹호하다","example":"Many scientists advocate stronger action against global climate change.","deck":"vocab"},{"id":1172,"word":"turn ~ off","ipa":"","meaning":"~가 (~에 대한) 흥미를 잃게 만들다","example":"His rude comments really turned me off the whole idea.","deck":"vocab"},{"id":1173,"word":"prom","ipa":"/prɑːm/","meaning":"(특히 미국에서 고등학교의) 졸업 파티, 무도회","example":"She wore a beautiful blue gown to her high school prom.","deck":"vocab"},{"id":1174,"word":"hideous","ipa":"/ˈhɪdiəs/","meaning":"(특히 보기에) 흉측한, 흉물스러운, 끔찍한","example":"That hideous wallpaper makes the whole room feel gloomy.","deck":"vocab"},{"id":1175,"word":"apprise","ipa":"/əˈpraɪz/","meaning":"알리다","example":"Please apprise me of any changes to the meeting schedule.","deck":"vocab"},{"id":1176,"word":"in no time","ipa":"","meaning":"즉시, 곧 <예상보다 훨씬 더 빠르게 진행된다는 어감이 있는 표현>","example":"Don't worry, the food will be ready in no time.","deck":"vocab"},{"id":1177,"word":"resonate","ipa":"/ˈrɛzəneɪt/","meaning":"(~에게) 반향을 불러일으키다, 공감을 불러일으키다","example":"Her honest speech seemed to resonate with the entire audience.","deck":"vocab"},{"id":1178,"word":"discriminate","ipa":"/dɪˈskrɪmɪneɪt/","meaning":"차별하다","example":"It is illegal to discriminate against workers based on age.","deck":"vocab"},{"id":1179,"word":"tuition fee","ipa":"/tuˈɪʃən fiː/","meaning":"수업료, 등록금","example":"Rising tuition fees make college harder for many families.","deck":"vocab"},{"id":1180,"word":"cast doubt on","ipa":"","meaning":"~에 대해 의심을 불러일으키다","example":"The new evidence cast doubt on the witness's earlier testimony.","deck":"vocab"},{"id":1181,"word":"up ahead","ipa":"","meaning":"그 앞쪽에, 저 앞쪽에","example":"There's a rest stop up ahead where we can grab coffee.","deck":"vocab"},{"id":1182,"word":"subvert","ipa":"/səbˈvɜːrt/","meaning":"(체제, 권위 등을) 전복시키다, 뒤엎다","example":"The rebels plotted to subvert the corrupt military government.","deck":"vocab"},{"id":1183,"word":"disorder","ipa":"/dɪsˈɔːrdər/","meaning":"(정신이나 신체 기능의) 장애, 이상, 병, 질환","example":"She was diagnosed with a rare blood disorder last spring.","deck":"vocab"},{"id":1184,"word":"affective","ipa":"/əˈfɛktɪv/","meaning":"정서적인","example":"The therapy targets affective symptoms like sadness and anxiety.","deck":"vocab"},{"id":1185,"word":"argumentative","ipa":"/ˌɑːrɡjəˈmɛntətɪv/","meaning":"따지기 좋아하는, 시비 거는 경향이 있는","example":"He becomes argumentative whenever anyone questions his opinions.","deck":"vocab"},{"id":1186,"word":"traumatic","ipa":"/trɔːˈmætɪk/","meaning":"정신적 외상을 초래할 정도의, 대단히 충격적인","example":"The car crash was a deeply traumatic experience for the children.","deck":"vocab"},{"id":1187,"word":"relive","ipa":"/riːˈlɪv/","meaning":"다시 체험하다","example":"Watching the video, she could relive that joyful summer day.","deck":"vocab"},{"id":1188,"word":"abridged","ipa":"/əˈbrɪdʒd/","meaning":"축약된, 요약된","example":"I read an abridged version of the long classic novel.","deck":"vocab"},{"id":1189,"word":"scapegoat","ipa":"/ˈskeɪpɡoʊt/","meaning":"희생양 <남의 죄를 대신 지는 사람>","example":"They made the new intern a scapegoat for the failed project.","deck":"vocab"},{"id":1190,"word":"fixer-upper","ipa":"/ˈfɪksərˌʌpər/","meaning":"손볼 데 많은 사람 <원래는 볼품없으나 애인이 잘 관리해 주면 괜찮아질 사람>","example":"She saw him as a fixer-upper she could gradually improve.","deck":"vocab"},{"id":1191,"word":"admit","ipa":"/ədˈmɪt/","meaning":"입원시키다 <흔히 수동태로 씀>","example":"He was admitted to the hospital with severe chest pain.","deck":"vocab"},{"id":1192,"word":"coarse","ipa":"/kɔːrs/","meaning":"상스러운, 천한, 저속한","example":"His coarse jokes made everyone at the dinner uncomfortable.","deck":"vocab"},{"id":1193,"word":"insubordinate","ipa":"/ˌɪnsəˈbɔːrdɪnət/","meaning":"순종하지 않는, 반항하는","example":"The soldier was punished for being insubordinate to his commander.","deck":"vocab"},{"id":1194,"word":"offend","ipa":"/əˈfɛnd/","meaning":"~를 기분 상하게 하다, ~를 불쾌하게 하다","example":"I didn't mean to offend you with my careless remark.","deck":"vocab"},{"id":1195,"word":"free weight","ipa":"/ˈfriː weɪt/","meaning":"근력운동 기구 <역기나 아령처럼 기계장치에 부착하지 않은 것>","example":"He prefers free weights over machines for building overall strength.","deck":"vocab"},{"id":1196,"word":"shuffle","ipa":"/ˈʃʌfəl/","meaning":"발을 끌며 걷기","example":"The tired old man crossed the room with a slow shuffle.","deck":"vocab"},{"id":1197,"word":"one's ducks in a row","ipa":"","meaning":"만반의 준비를 갖춘 <주로 get, have, put 등의 동사와 함께 씀>","example":"Get your ducks in a row before you launch the business.","deck":"vocab"},{"id":1198,"word":"concoction","ipa":"/kənˈkɑːkʃən/","meaning":"조합, 혼합물","example":"He served us a strange concoction of juice and herbs.","deck":"vocab"},{"id":1199,"word":"reparation","ipa":"/ˌrɛpəˈreɪʃən/","meaning":"(패전국이 승전국에 지불하는) 배상금 <복수형으로 씀>","example":"The defeated nation paid heavy reparations after the long war.","deck":"vocab"},{"id":1200,"word":"retract","ipa":"/rɪˈtrækt/","meaning":"(합의, 약속 등을) 철회하다, 취소하다","example":"The newspaper was forced to retract its false accusation.","deck":"vocab"},{"id":1201,"word":"retract","ipa":"/rɪˈtrækt/","meaning":"(전에 한 말을) 철회하다, 취소하다","example":"He was forced to retract his earlier statement after the backlash.","deck":"vocab"},{"id":1202,"word":"wander","ipa":"/ˈwɑːndər/","meaning":"(이리저리 천천히) 거닐다, 돌아다니다, 헤매다","example":"We like to wander through the old town every evening.","deck":"vocab"},{"id":1203,"word":"wander","ipa":"/ˈwɑːndər/","meaning":"다른 데로 가다, 떨어져 나가다","example":"Don't let the children wander away from the group.","deck":"vocab"},{"id":1204,"word":"live paycheck to paycheck","ipa":"","meaning":"근근이 살아가다","example":"Many families still live paycheck to paycheck despite working two jobs.","deck":"vocab"},{"id":1205,"word":"go for ~","ipa":"","meaning":"~을 택하다","example":"I think I'll go for the chicken instead of the beef.","deck":"vocab"},{"id":1206,"word":"what is it to ~","ipa":"","meaning":"그게 ~랑 무슨 상관이지?","example":"It's my decision, so what is it to you anyway?","deck":"vocab"},{"id":1207,"word":"right to counsel","ipa":"","meaning":"변호사를 선임할 권리, 변호인의 조력을 받을 권리","example":"Every defendant has the right to counsel during questioning.","deck":"vocab"},{"id":1208,"word":"endorse","ipa":"/ɪnˈdɔːrs/","meaning":"(공개적으로) 지지하다","example":"Several celebrities decided to endorse the new candidate publicly.","deck":"vocab"},{"id":1209,"word":"methodical","ipa":"/məˈθɑːdɪkəl/","meaning":"(사람이) 체계적인, 꼼꼼한","example":"She took a methodical approach to solving each problem.","deck":"vocab"},{"id":1210,"word":"performance-enhancing","ipa":"/pərˈfɔːrməns ɪnˌhænsɪŋ/","meaning":"운동 능력을 향상시키는, 경기력을 향상하는","example":"The athlete was banned for using performance-enhancing drugs.","deck":"vocab"},{"id":1211,"word":"introduce","ipa":"/ˌɪntrəˈduːs/","meaning":"(~ 속에) 넣다 <격식>","example":"Scientists introduce the enzyme into the solution slowly.","deck":"vocab"},{"id":1212,"word":"homicide","ipa":"/ˈhɑːmɪsaɪd/","meaning":"(경찰의) 강력계 <살인 사건을 수사하는 경찰 내 부서>","example":"The detective from homicide arrived at the crime scene.","deck":"vocab"},{"id":1213,"word":"dystopian","ipa":"/dɪsˈtoʊpiən/","meaning":"반(反) 이상향의, 디스토피아적인","example":"The novel paints a dystopian future ruled by machines.","deck":"vocab"},{"id":1214,"word":"sit on ~","ipa":"","meaning":"~을 뭉개다 <답장이나 필요한 처리를 하지 않고 있음을 뜻함>","example":"Don't just sit on my request; I need an answer today.","deck":"vocab"},{"id":1215,"word":"propaganda","ipa":"/ˌprɑːpəˈɡændə/","meaning":"(주로 거짓말이 섞여 있는 정치적인) 선전, 선동","example":"The regime spread propaganda through every television channel.","deck":"vocab"},{"id":1216,"word":"endemic","ipa":"/ɛnˈdɛmɪk/","meaning":"(동식물이) ~ 지방 특유의, 토종의, 토착종의","example":"These birds are endemic to the remote island.","deck":"vocab"},{"id":1217,"word":"endemic","ipa":"/ɛnˈdɛmɪk/","meaning":"(특정 지역이나 집단에서) 고질적인, 고유의","example":"Corruption remains endemic in some parts of the government.","deck":"vocab"},{"id":1218,"word":"forfeit","ipa":"/ˈfɔːrfɪt/","meaning":"~을 몰수당하다, 박탈당하다","example":"He had to forfeit his winnings after breaking the rules.","deck":"vocab"},{"id":1219,"word":"forfeit","ipa":"/ˈfɔːrfɪt/","meaning":"~을 포기하다","example":"By not showing up, the team will forfeit the match.","deck":"vocab"},{"id":1220,"word":"deplete","ipa":"/dɪˈpliːt/","meaning":"고갈시키다, 대폭 감소시키다, 격감시키다","example":"Overfishing can quickly deplete the ocean's resources.","deck":"vocab"},{"id":1221,"word":"grenade","ipa":"/ɡrəˈneɪd/","meaning":"수류탄","example":"The soldier carefully pulled the pin from the grenade.","deck":"vocab"},{"id":1222,"word":"herd","ipa":"/hɜːrd/","meaning":"(짐승을) 몰다","example":"The rancher will herd the cattle into the barn before dark.","deck":"vocab"},{"id":1223,"word":"plan","ipa":"/plæn/","meaning":"~할 예정이다, ~할 계획이다","example":"We plan to visit Korea next spring for the festival.","deck":"vocab"},{"id":1224,"word":"awkward","ipa":"/ˈɔːkwərd/","meaning":"(기분이) 어색한","example":"There was an awkward silence after his rude comment.","deck":"vocab"},{"id":1225,"word":"hail","ipa":"/heɪl/","meaning":"우박","example":"Golf-ball-sized hail damaged several cars in the parking lot.","deck":"vocab"},{"id":1226,"word":"mallet","ipa":"/ˈmælɪt/","meaning":"나무망치","example":"He tapped the tent stake with a wooden mallet.","deck":"vocab"},{"id":1227,"word":"amendment","ipa":"/əˈmɛndmənt/","meaning":"(법 등의) 개정, 수정","example":"Congress passed an amendment to the existing law.","deck":"vocab"},{"id":1228,"word":"redundancy","ipa":"/rɪˈdʌndənsi/","meaning":"불필요한 중복, 쓸모없는 반복 <격식 있는 표현>","example":"The editor removed the redundancy from the report.","deck":"vocab"},{"id":1229,"word":"ground","ipa":"/ɡraʊnd/","meaning":"근거, 이유, 사유","example":"They had no legal ground for firing her.","deck":"vocab"},{"id":1230,"word":"after a while","ipa":"","meaning":"잠시 후에, 얼마 후에","example":"After a while, the storm finally began to calm down.","deck":"vocab"},{"id":1231,"word":"dormant","ipa":"/ˈdɔːrmənt/","meaning":"활동하지 않고 있는, 휴면기의, 발육 정지 중인","example":"The volcano has been dormant for hundreds of years.","deck":"vocab"},{"id":1232,"word":"intact","ipa":"/ɪnˈtækt/","meaning":"(손상되지 않고) 멀쩡한, 전혀 다치지 않은","example":"Remarkably, the ancient vase survived the earthquake intact.","deck":"vocab"},{"id":1233,"word":"bail ~ out","ipa":"","meaning":"~에 대한 보석금을 내다","example":"His parents had to bail him out of jail last night.","deck":"vocab"},{"id":1234,"word":"distracted","ipa":"/dɪˈstræktɪd/","meaning":"주의가 산만해진, 마음이 뒤숭숭한, 심란한","example":"She was too distracted to notice the traffic light change.","deck":"vocab"},{"id":1235,"word":"ride on ~","ipa":"","meaning":"~에 달려 있다 <보통 진행형으로 쓰임>","example":"The whole company's future is riding on this deal.","deck":"vocab"},{"id":1236,"word":"break the spell","ipa":"","meaning":"황홀했던 분위기를 깨다","example":"The loud phone ringing suddenly broke the spell.","deck":"vocab"},{"id":1237,"word":"probe","ipa":"/proʊb/","meaning":"(~을) 캐다, 조사하다 <자동사>","example":"Investigators continued to probe into the company's finances.","deck":"vocab"},{"id":1238,"word":"noted","ipa":"/ˈnoʊtɪd/","meaning":"알았어 <상대방이 말한 내용은 충분히 알아들었다는 뜻>","example":"You want it done by Friday? Noted, I'll get started.","deck":"vocab"},{"id":1239,"word":"throw","ipa":"/θroʊ/","meaning":"(파티, 모임 등을) 개최하다, 열다, 벌이다","example":"They decided to throw a huge party for her birthday.","deck":"vocab"},{"id":1240,"word":"throw","ipa":"/θroʊ/","meaning":"(물건을) 던지다","example":"Please don't throw the ball inside the house.","deck":"vocab"},{"id":1241,"word":"hefty","ipa":"/ˈhɛfti/","meaning":"(사람, 사물이) 장대한, 크고 무거운","example":"He carried the hefty suitcase up the stairs alone.","deck":"vocab"},{"id":1242,"word":"infusion","ipa":"/ɪnˈfjuːʒən/","meaning":"(찻잎, 약재 등을) 우려낸 차, 달인 약물","example":"She sipped a warm herbal infusion before bed.","deck":"vocab"},{"id":1243,"word":"infusion","ipa":"/ɪnˈfjuːʒən/","meaning":"투입 <격식>","example":"The startup needed a fresh infusion of cash to survive.","deck":"vocab"},{"id":1244,"word":"stuff","ipa":"/stʌf/","meaning":"너무 많이 먹이다, 잔뜩 먹이다, 과식하게 만들다","example":"Grandma loves to stuff us with food every holiday.","deck":"vocab"},{"id":1245,"word":"stuff","ipa":"/stʌf/","meaning":"것, 것들, 물건, 물질, 문제 <가리키는 대상의 이름을 모르거나 굳이 말할 필요가 없을 때 씀>","example":"Just leave your stuff by the door and come in.","deck":"vocab"},{"id":1246,"word":"field marshal","ipa":"/ˈfiːld ˌmɑːrʃəl/","meaning":"(영국의) 육군 원수","example":"The field marshal reviewed the troops before the ceremony.","deck":"vocab"},{"id":1247,"word":"all about ~","ipa":"","meaning":"~에 푹 빠져 있다, ~을 너무 하고 싶다, ~을 너무 좋아하다","example":"Lately she's all about yoga and healthy eating.","deck":"vocab"},{"id":1248,"word":"all about ~","ipa":"","meaning":"~가 가장 중요하다, ~가 전부다, ~이 최고다","example":"In this business, it's all about building trust.","deck":"vocab"},{"id":1249,"word":"go a long way","ipa":"","meaning":"큰 도움이 되다, 유용하다","example":"A little kindness can go a long way in tough times.","deck":"vocab"},{"id":1250,"word":"servitude","ipa":"/ˈsɜːrvɪtuːd/","meaning":"노예 상태 <격식 있는 표현>","example":"The prisoners were sentenced to years of servitude.","deck":"vocab"},{"id":1251,"word":"fierce","ipa":"/fɪrs/","meaning":"(행동, 감정 등이) 치열한, 격렬한, 맹렬한","example":"There was fierce competition for the top position.","deck":"vocab"},{"id":1252,"word":"off the rack","ipa":"","meaning":"(의복이) 기성품인","example":"He bought a suit off the rack for the interview.","deck":"vocab"},{"id":1253,"word":"have ~ over","ipa":"","meaning":"~을 손님으로 맞이하다, 집에 초대하다","example":"We're going to have some friends over for dinner tonight.","deck":"vocab"},{"id":1254,"word":"name-calling","ipa":"/ˈneɪm ˌkɔːlɪŋ/","meaning":"욕하기","example":"The debate quickly descended into childish name-calling.","deck":"vocab"},{"id":1255,"word":"venue","ipa":"/ˈvɛnjuː/","meaning":"(콘서트, 스포츠 경기, 회담 등의) 장소","example":"The concert venue can hold twenty thousand people.","deck":"vocab"},{"id":1256,"word":"lock down","ipa":"","meaning":"확정하다","example":"We need to lock down the final details before Friday.","deck":"vocab"},{"id":1257,"word":"marlin","ipa":"/ˈmɑːrlɪn/","meaning":"청새치 <바닷물고기의 한 종류>","example":"The fisherman proudly reeled in a massive blue marlin.","deck":"vocab"},{"id":1258,"word":"snort","ipa":"/snɔːrt/","meaning":"(마약을) 코로 흡입하다","example":"He was arrested for trying to snort cocaine at the club.","deck":"vocab"},{"id":1259,"word":"bladder","ipa":"/ˈblædər/","meaning":"방광","example":"Drinking too much water made her bladder feel full.","deck":"vocab"},{"id":1260,"word":"bumpy","ipa":"/ˈbʌmpi/","meaning":"(길이) 울퉁불퉁한","example":"The old country road was incredibly bumpy and rough.","deck":"vocab"},{"id":1261,"word":"manhunt","ipa":"/ˈmænhʌnt/","meaning":"(조직적인) 수색, 범인 수색, 탈옥수 수색","example":"Police launched a massive manhunt for the escaped convict.","deck":"vocab"},{"id":1262,"word":"inquisitive","ipa":"/ɪnˈkwɪzətɪv/","meaning":"호기심이 많은, 탐구적인","example":"The inquisitive child asked endless questions about everything.","deck":"vocab"},{"id":1263,"word":"indigestion","ipa":"/ˌɪndaɪˈdʒɛstʃən/","meaning":"소화불량, 소화량증","example":"Eating too fast often gives me terrible indigestion.","deck":"vocab"},{"id":1264,"word":"carelessness","ipa":"/ˈkɛrləsnəs/","meaning":"부주의, 경솔","example":"The accident was caused by sheer carelessness.","deck":"vocab"},{"id":1265,"word":"continent","ipa":"/ˈkɑːntɪnənt/","meaning":"대륙","example":"Africa is the second largest continent in the world.","deck":"vocab"},{"id":1266,"word":"fraud","ipa":"/frɔːd/","meaning":"사기꾼","example":"The so-called doctor turned out to be a complete fraud.","deck":"vocab"},{"id":1267,"word":"pageant","ipa":"/ˈpædʒənt/","meaning":"미인 대회 <미모뿐 아니라 개인적 자질, 재주 등을 겨루는 대회>","example":"She won first place in the local beauty pageant.","deck":"vocab"},{"id":1268,"word":"placeholder","ipa":"/ˈpleɪshoʊldər/","meaning":"임시 값 <다른 것으로 대체될 것이 예정된 자리에 임시로 넣어 두는 것>","example":"Use a placeholder name until we finalize the details.","deck":"vocab"},{"id":1269,"word":"forsake","ipa":"/fərˈseɪk/","meaning":"(특히 책임져야 할 대상을) 저버리다, 버리다 <문학적인 표현>","example":"He vowed never to forsake his family in hard times.","deck":"vocab"},{"id":1270,"word":"shifty","ipa":"/ˈʃɪfti/","meaning":"수상쩍은, 구린 데가 있는 것 같은","example":"The salesman had a shifty look that made me uneasy.","deck":"vocab"},{"id":1271,"word":"juggle","ipa":"/ˈdʒʌɡəl/","meaning":"잘 조절하다, 잘 처리하다","example":"She has to juggle work, school, and raising two kids.","deck":"vocab"},{"id":1272,"word":"catch ~ up","ipa":"","meaning":"~에게 (~에 관한) 최근 정보를 알려 주다","example":"Let me catch you up on everything you missed.","deck":"vocab"},{"id":1273,"word":"blow off ~","ipa":"","meaning":"(총이나 폭탄으로) ~을 날려버리다, 터뜨려버리다","example":"The explosion nearly blew off the entire rooftop.","deck":"vocab"},{"id":1274,"word":"congestion","ipa":"/kənˈdʒɛstʃən/","meaning":"(차량, 인파 등의) 혼잡, 막힘","example":"Traffic congestion downtown made us late for the meeting.","deck":"vocab"},{"id":1275,"word":"piss ~ off","ipa":"","meaning":"~를 열받게 하다, ~를 지겹게 하다 <비격식적이고 모욕적인 표현>","example":"His constant complaining really pisses me off.","deck":"vocab"},{"id":1276,"word":"treat","ipa":"/triːt/","meaning":"대접하다, 한턱내다","example":"Let me treat you to lunch for helping me move.","deck":"vocab"},{"id":1277,"word":"treat","ipa":"/triːt/","meaning":"큰 기쁨, 매우 즐거운 일, 특별한 즐거움을 주는 것, 훌륭한 대접","example":"This quiet weekend has been a real treat for me.","deck":"vocab"},{"id":1278,"word":"turn to ~","ipa":"","meaning":"(도움, 조언 등을 위해) ~에 의지하다","example":"Whenever I'm confused, I turn to my mentor for advice.","deck":"vocab"},{"id":1279,"word":"nudity","ipa":"/ˈnuːdəti/","meaning":"벌거벗은 상태, 알몸 노출 상태","example":"The film was rated mature due to scenes of nudity.","deck":"vocab"},{"id":1280,"word":"notion","ipa":"/ˈnoʊʃən/","meaning":"개념, 관념, 생각","example":"I have no notion of what he was thinking.","deck":"vocab"},{"id":1281,"word":"reprehensible","ipa":"/ˌrɛprɪˈhɛnsəbəl/","meaning":"(도덕적으로) 부끄러운, 비난받을 만한","example":"His reprehensible behavior shocked the entire community.","deck":"vocab"},{"id":1282,"word":"antivenom","ipa":"/ˌæntiˈvɛnəm/","meaning":"해독제","example":"The hospital quickly administered antivenom after the snakebite.","deck":"vocab"},{"id":1283,"word":"medieval","ipa":"/ˌmiːdiˈiːvəl/","meaning":"중세의 <서기 약 1000년에서 1450년 사이의 기간>","example":"The museum displays weapons from the medieval period.","deck":"vocab"},{"id":1284,"word":"irrespective","ipa":"/ˌɪrɪˈspɛktɪv/","meaning":"~와 상관없이, ~와 관계없이","example":"Everyone is welcome irrespective of their background.","deck":"vocab"},{"id":1285,"word":"mourn","ipa":"/mɔːrn/","meaning":"애도하다, 슬퍼하다, 애석해 하다, 애통해 하다","example":"The whole nation gathered to mourn the fallen leader.","deck":"vocab"},{"id":1286,"word":"discern","ipa":"/dɪˈsɜːrn/","meaning":"알아차리다, 파악하다, 포착하다","example":"It was hard to discern his true intentions.","deck":"vocab"},{"id":1287,"word":"let off steam","ipa":"","meaning":"울분을 발산하다, 열기를 발산하다, 스트레스를 풀다","example":"After a long week, I go running to let off steam.","deck":"vocab"},{"id":1288,"word":"instigate","ipa":"/ˈɪnstɪɡeɪt/","meaning":"부추기다, 선동하다","example":"He was accused of trying to instigate a riot.","deck":"vocab"},{"id":1289,"word":"call it a day","ipa":"","meaning":"하루 일을 마치다, 오늘은 여기까지 하다","example":"We've worked enough, so let's call it a day.","deck":"vocab"},{"id":1290,"word":"uncivilized","ipa":"/ʌnˈsɪvəlaɪzd/","meaning":"예의 없는, 점잖지 못한","example":"Shouting at the waiter was truly uncivilized behavior.","deck":"vocab"},{"id":1291,"word":"contemplate","ipa":"/ˈkɑːntəmpleɪt/","meaning":"심사숙고하다","example":"She sat quietly to contemplate her next big decision.","deck":"vocab"},{"id":1292,"word":"chambermaid","ipa":"/ˈtʃeɪmbərmeɪd/","meaning":"(보통 호텔의) 객실 청소부 <특히 성별이 여성인 객실 청소부>","example":"The chambermaid tidied the room while we were out.","deck":"vocab"},{"id":1293,"word":"caboose","ipa":"/kəˈbuːs/","meaning":"엉덩이, 궁둥이","example":"He slipped on the ice and landed right on his caboose.","deck":"vocab"},{"id":1294,"word":"ambiguous","ipa":"/æmˈbɪɡjuəs/","meaning":"분명히 규정되지 않은, 애매한","example":"The instructions were so ambiguous that nobody understood them.","deck":"vocab"},{"id":1295,"word":"gutter","ipa":"/ˈɡʌtər/","meaning":"(도로의) 배수로","example":"Rainwater rushed down the gutter along the street.","deck":"vocab"},{"id":1296,"word":"flirt","ipa":"/flɜːrt/","meaning":"바람둥이","example":"Everyone knows he's a hopeless flirt at parties.","deck":"vocab"},{"id":1297,"word":"flirt","ipa":"/flɜːrt/","meaning":"추파를 던지다, 찝쩍대다, 들이대다, 플러팅하다 <가볍고 즐거운 태도로>","example":"She likes to flirt with the baristas at the cafe.","deck":"vocab"},{"id":1298,"word":"pull ~ up","ipa":"","meaning":"꺼내 보다, 조회하다","example":"Let me pull up your account information on the screen.","deck":"vocab"},{"id":1299,"word":"speculate","ipa":"/ˈspɛkjəleɪt/","meaning":"추측하다, 짐작하다","example":"Reporters began to speculate about the CEO's sudden resignation.","deck":"vocab"},{"id":1300,"word":"down","ipa":"/daʊn/","meaning":"(~을) 하고 싶어 하는","example":"Are you down to grab some tacos after work?","deck":"vocab"},{"id":1301,"word":"balm","ipa":"/bɑːm/","meaning":"연고, 크림, 향유","example":"She rubbed some soothing balm onto her chapped lips.","deck":"vocab"},{"id":1302,"word":"boredom","ipa":"/ˈbɔːrdəm/","meaning":"지루함, 따분함","example":"Out of sheer boredom, he started doodling on the napkin.","deck":"vocab"},{"id":1303,"word":"stellar","ipa":"/ˈstɛlər/","meaning":"정말 뛰어난 <비격식적인 표현>","example":"The young pianist gave a stellar performance last night.","deck":"vocab"},{"id":1304,"word":"serendipity","ipa":"/ˌsɛrənˈdɪpəti/","meaning":"우연으로 얻은 행운, 뜻밖의 발견","example":"Meeting my business partner was pure serendipity.","deck":"vocab"},{"id":1305,"word":"tear ~ down","ipa":"","meaning":"(건물, 담 등을) 허물다, 헐다","example":"The city plans to tear down the old factory next month.","deck":"vocab"},{"id":1306,"word":"tease","ipa":"/tiːz/","meaning":"약 올리다, 놀리다, 장난하다, 집적거리다","example":"Older brothers love to tease their younger siblings.","deck":"vocab"},{"id":1307,"word":"traitor","ipa":"/ˈtreɪtər/","meaning":"(~의) 배반자, 반역자","example":"He was branded a traitor for leaking the secrets.","deck":"vocab"},{"id":1308,"word":"plead","ipa":"/pliːd/","meaning":"변호하다, 변론하다","example":"A skilled lawyer will plead your case in court.","deck":"vocab"},{"id":1309,"word":"plead","ipa":"/pliːd/","meaning":"애원하다","example":"She began to plead with them to spare his life.","deck":"vocab"},{"id":1310,"word":"take it from","ipa":"","meaning":"~의 말을 믿다","example":"Take it from me, honesty always works out best.","deck":"vocab"},{"id":1311,"word":"hallucinate","ipa":"/həˈluːsɪneɪt/","meaning":"환각을 느끼다","example":"The high fever caused him to hallucinate for hours.","deck":"vocab"},{"id":1312,"word":"gross","ipa":"/ɡroʊs/","meaning":"역겨운, 징그러운, 불쾌한","example":"The moldy leftovers in the fridge looked absolutely gross.","deck":"vocab"},{"id":1313,"word":"intent","ipa":"/ɪnˈtɛnt/","meaning":"의도 <격식 또는 법률 용어>","example":"The prosecutor had to prove criminal intent.","deck":"vocab"},{"id":1314,"word":"trousers","ipa":"/ˈtraʊzərz/","meaning":"바지","example":"He ironed his trousers before the important interview.","deck":"vocab"},{"id":1315,"word":"draft","ipa":"/dræft/","meaning":"찬바람, 외풍","example":"A cold draft slipped through the gap under the door.","deck":"vocab"},{"id":1316,"word":"draw","ipa":"/drɔː/","meaning":"(주로 총, 칼 등의 무기를) ~를 뽑다, 꺼내다","example":"The sheriff was quick to draw his pistol.","deck":"vocab"},{"id":1317,"word":"practice","ipa":"/ˈpræktɪs/","meaning":"관행, 관례, 관습","example":"Bowing is a common practice in many Asian cultures.","deck":"vocab"},{"id":1318,"word":"blinker","ipa":"/ˈblɪŋkər/","meaning":"(자동차의) 깜빡이, 방향 지시등","example":"He forgot to use his blinker before changing lanes.","deck":"vocab"},{"id":1319,"word":"counterfeit","ipa":"/ˈkaʊntərfɪt/","meaning":"위조품, 모조품, 가짜","example":"The vendor was selling counterfeit designer handbags.","deck":"vocab"},{"id":1320,"word":"calling","ipa":"/ˈkɔːlɪŋ/","meaning":"직업, 천직","example":"Teaching children was always her true calling.","deck":"vocab"},{"id":1321,"word":"perennial","ipa":"/pəˈrɛniəl/","meaning":"지속되는, 영원한, 계속 반복되는","example":"Traffic is a perennial problem in this crowded city.","deck":"vocab"},{"id":1322,"word":"by any chance","ipa":"","meaning":"(특히 의문문에서) 혹시, 혹시라도","example":"Are you, by any chance, the new manager here?","deck":"vocab"},{"id":1323,"word":"in the meantime","ipa":"","meaning":"그동안에, 그 사이에","example":"Dinner's almost ready; in the meantime, set the table.","deck":"vocab"},{"id":1324,"word":"mortgage","ipa":"/ˈmɔːrɡɪdʒ/","meaning":"주택 담보 대출, 담보 대출금 <mortgage loan을 줄여서 쓰는 말>","example":"They struggled to keep up with their monthly mortgage payments.","deck":"vocab"},{"id":1325,"word":"go way back","ipa":"","meaning":"오랫동안 알고 지내다","example":"Those two go way back to their college days.","deck":"vocab"},{"id":1326,"word":"instantly","ipa":"/ˈɪnstəntli/","meaning":"즉각, 즉시","example":"The moment she smiled, he instantly recognized her.","deck":"vocab"},{"id":1327,"word":"coyote","ipa":"/kaɪˈoʊti/","meaning":"코요테 <갯과에 속하는 북미산 야생 동물>","example":"A lone coyote howled somewhere out in the desert.","deck":"vocab"},{"id":1328,"word":"greasy","ipa":"/ˈɡriːsi/","meaning":"(요리에) 기름을 많이 쓴 <못마땅함>","example":"The diner served a greasy breakfast that upset my stomach.","deck":"vocab"},{"id":1329,"word":"profoundly","ipa":"/prəˈfaʊndli/","meaning":"(병이나 장애가) 극심하게, 완전히 <의학 용어>","example":"The patient was profoundly deaf from birth.","deck":"vocab"},{"id":1330,"word":"or so","ipa":"","meaning":"~쯤, ~정도","example":"The trip should take an hour or so by car.","deck":"vocab"},{"id":1331,"word":"select","ipa":"/sɪˈlɛkt/","meaning":"고급의","example":"Only a select group of guests received an invitation.","deck":"vocab"},{"id":1332,"word":"paralyze","ipa":"/ˈpærəlaɪz/","meaning":"(인체의 신경, 근육을) 마비시키다","example":"The venom can paralyze its prey within seconds.","deck":"vocab"},{"id":1333,"word":"paralyze","ipa":"/ˈpærəlaɪz/","meaning":"(원래의 기능을) 마비시키다","example":"The strike threatened to paralyze the entire city.","deck":"vocab"},{"id":1334,"word":"Florence","ipa":"/ˈflɔːrəns/","meaning":"피렌체 <이탈리아 중부의 도시>","example":"We spent three days admiring the art in Florence.","deck":"vocab"},{"id":1335,"word":"appendix","ipa":"/əˈpɛndɪks/","meaning":"맹장, 충수","example":"The doctor removed his inflamed appendix in surgery.","deck":"vocab"},{"id":1336,"word":"conscious","ipa":"/ˈkɑːnʃəs/","meaning":"의식이 온전한, 판단 기능이 정상인","example":"The patient remained conscious throughout the procedure.","deck":"vocab"},{"id":1337,"word":"firefly","ipa":"/ˈfaɪərflaɪ/","meaning":"반딧불이, 개똥벌레","example":"A single firefly blinked softly in the summer night.","deck":"vocab"},{"id":1338,"word":"commodity","ipa":"/kəˈmɑːdəti/","meaning":"유용한 것, 가치 있는 것","example":"In the desert, clean water is a precious commodity.","deck":"vocab"},{"id":1339,"word":"intoxicate","ipa":"/ɪnˈtɑːksɪkeɪt/","meaning":"(술, 마약 등에) 취하게 하다","example":"Just one glass of that wine can intoxicate you quickly.","deck":"vocab"},{"id":1340,"word":"consent","ipa":"/kənˈsɛnt/","meaning":"(특히 권위 있는 사람에 의한) 동의, 허락","example":"The surgery cannot proceed without the patient's consent.","deck":"vocab"},{"id":1341,"word":"improvise","ipa":"/ˈɪmprəvaɪz/","meaning":"(연주, 연설 등을) 즉흥적으로 하다","example":"When the music stopped, the actors had to improvise.","deck":"vocab"},{"id":1342,"word":"mortal","ipa":"/ˈmɔːrtəl/","meaning":"영원히 살 수는 없는, 언젠가는 반드시 죽는","example":"The ancient hero was, after all, only mortal.","deck":"vocab"},{"id":1343,"word":"plum","ipa":"/plʌm/","meaning":"자두","example":"She picked a ripe, juicy plum from the tree.","deck":"vocab"},{"id":1344,"word":"ticklish","ipa":"/ˈtɪklɪʃ/","meaning":"(사람이) 간지럼을 잘 타는","example":"My little sister is extremely ticklish on her feet.","deck":"vocab"},{"id":1345,"word":"no sweat","ipa":"","meaning":"별거 아냐, 당연하지 <별로 힘들거나 어려운 일이 아니라는 뜻>","example":"Fixing your computer? No sweat, I'll do it now.","deck":"vocab"},{"id":1346,"word":"humble","ipa":"/ˈhʌmbəl/","meaning":"변변치 않은, 보잘것없는","example":"He grew up in a humble little cottage by the sea.","deck":"vocab"},{"id":1347,"word":"humble","ipa":"/ˈhʌmbəl/","meaning":"겸손하게 처신하다","example":"A good leader knows how to humble himself before others.","deck":"vocab"},{"id":1348,"word":"in the blink of an eye","ipa":"","meaning":"눈 깜박할 사이에","example":"The whole summer passed in the blink of an eye.","deck":"vocab"},{"id":1349,"word":"imprison","ipa":"/ɪmˈprɪzən/","meaning":"투옥하다, 감금하다","example":"The regime would imprison anyone who dared to protest.","deck":"vocab"},{"id":1350,"word":"glaze","ipa":"/ɡleɪz/","meaning":"광택제를 바르다, 윤기가 나게 하다","example":"The baker will glaze the doughnuts with sweet sugar.","deck":"vocab"},{"id":1351,"word":"cool cat","ipa":"","meaning":"멋쟁이 <유행에 민감하거나 스타일이 좋은 사람. 오래된 속어>","example":"With those sunglasses, he really looked like a cool cat.","deck":"vocab"},{"id":1352,"word":"magnificent","ipa":"/mæɡˈnɪfɪsənt/","meaning":"장대한, 장려한, 화려한, 훌륭한, 당당한","example":"The cathedral's magnificent ceiling left us speechless.","deck":"vocab"},{"id":1353,"word":"must","ipa":"/mʌst/","meaning":"필수품, 꼭 해야 하는 것","example":"A good raincoat is a must during the rainy season.","deck":"vocab"},{"id":1354,"word":"butt","ipa":"/bʌt/","meaning":"엉덩이 <주로 미국에서 사용하는 비격식적인 표현>","example":"He slipped and fell right on his butt.","deck":"vocab"},{"id":1355,"word":"grieve","ipa":"/ɡriːv/","meaning":"(특히 누구의 죽음으로 인해) 비통해 하다","example":"She needed time alone to grieve for her mother.","deck":"vocab"},{"id":1356,"word":"temperance","ipa":"/ˈtɛmpərəns/","meaning":"절제, 자제","example":"He practiced temperance and avoided rich foods.","deck":"vocab"},{"id":1357,"word":"jolly","ipa":"/ˈdʒɑːli/","meaning":"아주, 매우, 대단히 <영국식 표현>","example":"That was a jolly good meal, thank you.","deck":"vocab"},{"id":1358,"word":"jolly","ipa":"/ˈdʒɑːli/","meaning":"(행사, 경험 등이) 즐거운","example":"We had a jolly time at the seaside carnival.","deck":"vocab"},{"id":1359,"word":"astronaut","ipa":"/ˈæstrənɔːt/","meaning":"우주 비행사","example":"As a boy, he dreamed of becoming an astronaut.","deck":"vocab"},{"id":1360,"word":"plainly","ipa":"/ˈpleɪnli/","meaning":"분명히","example":"She stated her opinion plainly and left the room.","deck":"vocab"},{"id":1361,"word":"among other things","ipa":"","meaning":"다른 것도 있지만 <현재 이야기하는 예시도 있지만 다른 것들도 있다는 뜻>","example":"He studies biology and chemistry, among other things.","deck":"vocab"},{"id":1362,"word":"hump","ipa":"/hʌmp/","meaning":"(낙타 같은 동물의 등에 난) 혹","example":"The camel stored fat in its large hump.","deck":"vocab"},{"id":1363,"word":"hump","ipa":"/hʌmp/","meaning":"(사람 등에 난) 혹","example":"Years of bad posture gave him a hump on his back.","deck":"vocab"},{"id":1364,"word":"be one's own boss","ipa":"","meaning":"(회사에 소속되지 않고) 독립하다, 자기 사업을 하다 <주로 자영업을 뜻함>","example":"She quit to be her own boss and start a bakery.","deck":"vocab"},{"id":1365,"word":"throw ~ a bone","ipa":"","meaning":"~를 조금만 도와주다, 돕는 시늉만 하다, 달래 주는 척만 하다","example":"Come on, throw me a bone and give me one hint.","deck":"vocab"},{"id":1366,"word":"hit the hay","ipa":"","meaning":"자다, 잠자리에 들다","example":"I'm exhausted, so I'm going to hit the hay early.","deck":"vocab"},{"id":1367,"word":"renovate","ipa":"/ˈrɛnəveɪt/","meaning":"(낡은 건물, 가구 등을) 개보수하다","example":"They spent a year working to renovate the old farmhouse.","deck":"vocab"},{"id":1368,"word":"measure","ipa":"/ˈmɛʒər/","meaning":"(특정 목적을 달성하기 위한) 조치, 대책","example":"The government introduced a new measure to reduce pollution.","deck":"vocab"},{"id":1369,"word":"compel","ipa":"/kəmˈpɛl/","meaning":"자아내다, 불러오다, ~하지 않을 수 없게 만들다","example":"The film's raw honesty compels the audience to keep watching.","deck":"vocab"},{"id":1370,"word":"compel","ipa":"/kəmˈpɛl/","meaning":"~가 ~하게 만들다, 강요하다, 강제하다","example":"You can't compel him to sign the contract.","deck":"vocab"},{"id":1371,"word":"no biggie","ipa":"","meaning":"별거 아니야, 걱정할 것 없어","example":"You forgot the milk? No biggie, I'll grab some.","deck":"vocab"},{"id":1372,"word":"so to speak","ipa":"","meaning":"말하자면","example":"He's the captain of the ship, so to speak.","deck":"vocab"},{"id":1373,"word":"porridge","ipa":"/ˈpɔːrɪdʒ/","meaning":"포리지, 오트밀 죽 <주로 영국에서 쓰는 표현>","example":"On cold mornings I love a warm bowl of porridge.","deck":"vocab"},{"id":1374,"word":"rain out","ipa":"","meaning":"~을 비 때문에 취소하다, 연기하다 <주로 수동태로 씀>","example":"The baseball game was rained out for the second time.","deck":"vocab"},{"id":1375,"word":"nod","ipa":"/nɑːd/","meaning":"고개를 끄덕여 ~를 표시하다, 표현하다","example":"She gave a quick nod to signal her agreement.","deck":"vocab"},{"id":1376,"word":"mean","ipa":"/miːn/","meaning":"(솜씨가) 기막힌, 훌륭한","example":"Wow, you play a mean guitar solo!","deck":"vocab"},{"id":1377,"word":"hate one's guts","ipa":"","meaning":"~를 몹시 싫어하다, ~을 아주 미워하다","example":"Ever since the betrayal, she hates his guts.","deck":"vocab"},{"id":1378,"word":"intimidating","ipa":"/ɪnˈtɪmɪdeɪtɪŋ/","meaning":"(자신감이 없어지도록) 겁을 주는, 겁나는","example":"The interviewer had a rather intimidating presence.","deck":"vocab"},{"id":1379,"word":"squint","ipa":"/skwɪnt/","meaning":"눈을 가늘게 뜨고 보다, 눈을 찡그리고 보다 <밝은 빛을 피하거나 잘 보려고 할 때>","example":"He had to squint against the blinding afternoon sun.","deck":"vocab"},{"id":1380,"word":"driving range","ipa":"/ˈdraɪvɪŋ reɪndʒ/","meaning":"골프 연습장","example":"We spent the afternoon hitting balls at the driving range.","deck":"vocab"},{"id":1381,"word":"mistrust","ipa":"/mɪsˈtrʌst/","meaning":"불신","example":"Years of lies bred deep mistrust between the partners.","deck":"vocab"},{"id":1382,"word":"partial","ipa":"/ˈpɑːrʃəl/","meaning":"~을 매우 좋아하는","example":"I'm rather partial to dark chocolate myself.","deck":"vocab"},{"id":1383,"word":"creep","ipa":"/kriːp/","meaning":"오싹한 느낌, 혐오감 <피부 위로 뭔가가 기어가는 것 같은 느낌>","example":"That abandoned house gives me the creeps.","deck":"vocab"},{"id":1384,"word":"pediatric","ipa":"/ˌpiːdiˈætrɪk/","meaning":"소아과의","example":"She works in the pediatric ward at the children's hospital.","deck":"vocab"},{"id":1385,"word":"break the news","ipa":"","meaning":"(~에게) 나쁜 소식을 전하다","example":"I didn't know how to break the news to my parents.","deck":"vocab"},{"id":1386,"word":"gossip","ipa":"/ˈɡɑːsɪp/","meaning":"험담을 하다, 남 얘기를 하다","example":"They love to gossip about their coworkers at lunch.","deck":"vocab"},{"id":1387,"word":"spill","ipa":"/spɪl/","meaning":"누설하다, 폭로하다, 말해버리다","example":"Don't spill the secret before the surprise party.","deck":"vocab"},{"id":1388,"word":"lotus","ipa":"/ˈloʊtəs/","meaning":"연(蓮), 연꽃","example":"A pink lotus floated gracefully on the still pond.","deck":"vocab"},{"id":1389,"word":"dizzy","ipa":"/ˈdɪzi/","meaning":"어지러운","example":"Standing up too fast made her feel dizzy.","deck":"vocab"},{"id":1390,"word":"fluffy","ipa":"/ˈflʌfi/","meaning":"푹신해 보이는, 솜털 같은","example":"The kitten's fluffy fur was incredibly soft.","deck":"vocab"},{"id":1391,"word":"crook","ipa":"/krʊk/","meaning":"사기꾼 <주로 사기, 횡령, 절도 등을 저지른 범죄자를 뜻함>","example":"That crook cheated dozens of people out of their savings.","deck":"vocab"},{"id":1392,"word":"cherish","ipa":"/ˈtʃɛrɪʃ/","meaning":"(오랫동안) 기억 속에 간직하다","example":"I will always cherish the memories of our childhood.","deck":"vocab"},{"id":1393,"word":"cherish","ipa":"/ˈtʃɛrɪʃ/","meaning":"소중히 여기다, 아끼다","example":"She cherishes the necklace her grandmother gave her.","deck":"vocab"},{"id":1394,"word":"embrace","ipa":"/ɪmˈbreɪs/","meaning":"기꺼이 받아들이다, 수용하다","example":"We should embrace new technology rather than fear it.","deck":"vocab"},{"id":1395,"word":"embrace","ipa":"/ɪmˈbreɪs/","meaning":"포위, 둘러쌈","example":"The valley lay in the embrace of tall mountains.","deck":"vocab"},{"id":1396,"word":"intervention","ipa":"/ˌɪntərˈvɛnʃən/","meaning":"개입 <셀 수 없는 명사 또는 셀 수 있는 명사>","example":"Early intervention greatly improved the patient's recovery.","deck":"vocab"},{"id":1397,"word":"intervention","ipa":"/ˌɪntərˈvɛnʃən/","meaning":"(가족이나 친구 등의) 개입 <치료나 행동 개선을 목적으로 함>","example":"The family staged an intervention to help him quit drinking.","deck":"vocab"},{"id":1398,"word":"immediate","ipa":"/ɪˈmiːdiət/","meaning":"직접적인, 직접적으로 영향을 미치는 <명사 앞에만 씀>","example":"The storm posed an immediate threat to the coast.","deck":"vocab"},{"id":1399,"word":"diversify","ipa":"/daɪˈvɜːrsɪfaɪ/","meaning":"~을 다양화하다, 다각화하다 <타동사>","example":"The company decided to diversify its product line.","deck":"vocab"},{"id":1400,"word":"clarification","ipa":"/ˌklærəfɪˈkeɪʃən/","meaning":"설명, 해명","example":"I asked the professor for clarification on the assignment.","deck":"vocab"},{"id":1401,"word":"ask ~ out","ipa":"","meaning":"~에게 데이트를 신청하다","example":"He finally worked up the courage to ask her out this weekend.","deck":"vocab"},{"id":1402,"word":"displace","ipa":"/dɪsˈpleɪs/","meaning":"(살던 곳에서) 쫓아내다","example":"The war displaced thousands of families from their homes.","deck":"vocab"},{"id":1403,"word":"drill","ipa":"/drɪl/","meaning":"반복 연습","example":"The teacher led a vocabulary drill to reinforce the new words.","deck":"vocab"},{"id":1404,"word":"pragmatism","ipa":"/ˈpræɡməˌtɪzəm/","meaning":"실용주의","example":"Her pragmatism helped the team focus on realistic goals.","deck":"vocab"},{"id":1405,"word":"talk ~ out","ipa":"","meaning":"~을 철저히 논의하다","example":"Let's sit down and talk this problem out before deciding.","deck":"vocab"},{"id":1406,"word":"get off","ipa":"","meaning":"(명령문으로 쓰여) 손 떼, 손 놔","example":"Get off my new car right now, you're scratching it!","deck":"vocab"},{"id":1407,"word":"make up to ~","ipa":"","meaning":"~에게 아첨하다, 알랑거리다 <영국식 표현>","example":"He's always trying to make up to the boss for a promotion.","deck":"vocab"},{"id":1408,"word":"quarantine","ipa":"/ˈkwɔrənˌtin/","meaning":"격리, 격리 기간, 격리 장소","example":"The travelers spent two weeks in quarantine after arriving.","deck":"vocab"},{"id":1409,"word":"quarantine","ipa":"/ˈkwɔrənˌtin/","meaning":"격리하다 <자동사>","example":"Doctors decided to quarantine the patients showing early symptoms.","deck":"vocab"},{"id":1410,"word":"no way","ipa":"","meaning":"절대로 아니다, 결코 안 되다","example":"No way am I lending him money after last time.","deck":"vocab"},{"id":1411,"word":"full of it","ipa":"","meaning":"구라 치고 있는, 거짓말을 하는","example":"Don't believe him, he's completely full of it about that trip.","deck":"vocab"},{"id":1412,"word":"apricot","ipa":"/ˈæprɪˌkɑt/","meaning":"살구","example":"She picked a ripe apricot from the tree in the garden.","deck":"vocab"},{"id":1413,"word":"stench","ipa":"/stɛntʃ/","meaning":"악취","example":"A terrible stench rose from the overflowing garbage bins.","deck":"vocab"},{"id":1414,"word":"redemption","ipa":"/rɪˈdɛmpʃən/","meaning":"구원, 구함 <격식>","example":"The novel explores a criminal's search for redemption.","deck":"vocab"},{"id":1415,"word":"freak","ipa":"/frik/","meaning":"경악하다, 자제력을 잃다, 기겁하다 <흥분, 공포, 분노, 긴장 등으로>","example":"Don't freak when you see the exam results, stay calm.","deck":"vocab"},{"id":1416,"word":"hemisphere","ipa":"/ˈhɛmɪˌsfɪr/","meaning":"반구체","example":"Australia lies in the southern hemisphere of the planet.","deck":"vocab"},{"id":1417,"word":"cramped","ipa":"/kræmpt/","meaning":"(방 등이) 비좁은","example":"Five people shared the tiny, cramped apartment downtown.","deck":"vocab"},{"id":1418,"word":"sleep funny","ipa":"","meaning":"잠을 잘못 자다 <주로 아침에 목이나 어깨 등이 결리는 상황>","example":"My neck aches because I slept funny last night.","deck":"vocab"},{"id":1419,"word":"complement","ipa":"/ˈkɑmpləˌmɛnt/","meaning":"보완하다, 좋은 조합을 이루다, ~의 좋은 점을 더 살려 주다","example":"The rich sauce nicely complements the grilled salmon.","deck":"vocab"},{"id":1420,"word":"blur","ipa":"/blɜr/","meaning":"(기억이) 희미한 것, 흐릿한 것","example":"That whole hectic evening is just a blur to me now.","deck":"vocab"},{"id":1421,"word":"movement","ipa":"/ˈmuvmənt/","meaning":"운동","example":"The environmental movement gained millions of new supporters.","deck":"vocab"},{"id":1422,"word":"regard","ipa":"/rɪˈɡɑrd/","meaning":"안부, 안부의 말 <편지 끝 부분이나 다른 사람에게 안부를 전할 때 씀>","example":"Please give my warmest regards to your parents.","deck":"vocab"},{"id":1423,"word":"on one's feet","ipa":"","meaning":"(병을 앓은 후에) 일어나서, 다 나아서","example":"After weeks in bed, she's finally back on her feet.","deck":"vocab"},{"id":1424,"word":"on one's feet","ipa":"","meaning":"(경제적, 사업적으로) 형편이 괜찮은","example":"The new loan helped the small business get back on its feet.","deck":"vocab"},{"id":1425,"word":"manipulate","ipa":"/məˈnɪpjəˌleɪt/","meaning":"조종하다 <부정적인 어감>","example":"He tried to manipulate his coworkers into doing his tasks.","deck":"vocab"},{"id":1426,"word":"nasty","ipa":"/ˈnæsti/","meaning":"(장소나 환경 등이) 몹시 지저분한, 너무 더러운","example":"The abandoned kitchen was nasty, covered in mold and grease.","deck":"vocab"},{"id":1427,"word":"nasty","ipa":"/ˈnæsti/","meaning":"끔찍한, 형편없는, 역겨운, 지저분한","example":"He gave me a nasty look and slammed the door.","deck":"vocab"},{"id":1428,"word":"nasty","ipa":"/ˈnæsti/","meaning":"못된, 불쾌한, 고약한, 심술궂은","example":"Their neighbor is a nasty man who yells at children.","deck":"vocab"},{"id":1429,"word":"norm","ipa":"/nɔrm/","meaning":"기준","example":"Working from home has become the norm at many companies.","deck":"vocab"},{"id":1430,"word":"funny","ipa":"/ˈfʌni/","meaning":"묘한, 이상한","example":"There's a funny smell coming from the basement.","deck":"vocab"},{"id":1431,"word":"by far","ipa":"","meaning":"훨씬, 단연코 <비교급, 최상급 형용사, 부사와 함께 쓰임>","example":"This is by far the best pizza in the entire city.","deck":"vocab"},{"id":1432,"word":"pensive","ipa":"/ˈpɛnsɪv/","meaning":"수심에 잠긴, 깊은 생각에 잠긴, 수심 어린","example":"She grew pensive as she stared out the rainy window.","deck":"vocab"},{"id":1433,"word":"conceited","ipa":"/kənˈsitɪd/","meaning":"자만심이 강한, 자만하는","example":"He's so conceited that he thinks everyone admires him.","deck":"vocab"},{"id":1434,"word":"feast","ipa":"/fist/","meaning":"연회, 잔치","example":"The village held a grand feast to celebrate the harvest.","deck":"vocab"},{"id":1435,"word":"exotic","ipa":"/ɪɡˈzɑtɪk/","meaning":"이국적인, 색다른, 이국풍의","example":"The market sold exotic fruits I had never seen before.","deck":"vocab"},{"id":1436,"word":"sanctuary","ipa":"/ˈsæŋktʃuˌɛri/","meaning":"피난처, 안식처","example":"The quiet library became her sanctuary during exam week.","deck":"vocab"},{"id":1437,"word":"dispose of ~","ipa":"","meaning":"처리하다, 해결하다","example":"We need to dispose of these old chemicals safely.","deck":"vocab"},{"id":1438,"word":"meet","ipa":"/mit/","meaning":"경기, 대회, 운동회","example":"She won two gold medals at the regional swim meet.","deck":"vocab"},{"id":1439,"word":"martial artist","ipa":"/ˈmɑrʃəl ˈɑrtɪst/","meaning":"무술가, 격투기 선수","example":"The martial artist demonstrated a flawless spinning kick.","deck":"vocab"},{"id":1440,"word":"meditate","ipa":"/ˈmɛdɪˌteɪt/","meaning":"명상하다, 묵상하다","example":"She likes to meditate for twenty minutes each morning.","deck":"vocab"},{"id":1441,"word":"insomnia","ipa":"/ɪnˈsɑmniə/","meaning":"불면증","example":"Stress at work gave him severe insomnia for months.","deck":"vocab"},{"id":1442,"word":"beekeeper","ipa":"/ˈbiˌkipər/","meaning":"양봉가","example":"The beekeeper harvested fresh honey from the hives.","deck":"vocab"},{"id":1443,"word":"pipe dream","ipa":"/ˈpaɪp ˌdrim/","meaning":"몽상 <아편 파이프로 아편을 흡입할 때 생기는 환각에서 유래된 표현>","example":"Owning a private island is just a pipe dream for most.","deck":"vocab"},{"id":1444,"word":"get black eye","ipa":"","meaning":"눈에 멍이 들다","example":"He got a black eye during the boxing match yesterday.","deck":"vocab"},{"id":1445,"word":"every single","ipa":"","meaning":"단 하나의 ~도 빼놓지 않고","example":"She read every single page of the report carefully.","deck":"vocab"},{"id":1446,"word":"carver","ipa":"/ˈkɑrvər/","meaning":"조각가","example":"The wood carver spent weeks shaping the delicate statue.","deck":"vocab"},{"id":1447,"word":"county","ipa":"/ˈkaʊnti/","meaning":"군 <영국, 아일랜드, 미국에서 행정 구역의 한 종류. 미국의 주(州)보다 작은 단위>","example":"The fair attracts visitors from all across the county.","deck":"vocab"},{"id":1448,"word":"lay ~ on ~","ipa":"","meaning":"~에게 ~을 말하다, ~에게 ~을 털어놓다 <비격식적인 표현>","example":"Come on, lay the truth on me, I can handle it.","deck":"vocab"},{"id":1449,"word":"household name","ipa":"/ˈhaʊsˌhoʊld ˈneɪm/","meaning":"누구나 아는 이름, 유명한 사람","example":"That actor became a household name after the hit series.","deck":"vocab"},{"id":1450,"word":"take up ~","ipa":"","meaning":"(시간, 공간을) 차지하다, 쓰다","example":"The huge sofa takes up half of the living room.","deck":"vocab"},{"id":1451,"word":"implore","ipa":"/ɪmˈplɔr/","meaning":"애원하다, 간청하다 <문어체>","example":"She implored the judge to show her son mercy.","deck":"vocab"},{"id":1452,"word":"bracelet","ipa":"/ˈbreɪslɪt/","meaning":"팔찌","example":"He gave her a silver bracelet for her birthday.","deck":"vocab"},{"id":1453,"word":"one-off","ipa":"/ˈwʌnˌɔf/","meaning":"일회성의, 단 한 번의","example":"This concert is a one-off event, so don't miss it.","deck":"vocab"},{"id":1454,"word":"have a ball","ipa":"","meaning":"신나게 즐기다","example":"The kids had a ball at the amusement park all day.","deck":"vocab"},{"id":1455,"word":"anecdote","ipa":"/ˈænɪkˌdoʊt/","meaning":"일화","example":"He shared a funny anecdote about his first job interview.","deck":"vocab"},{"id":1456,"word":"insult","ipa":"/ɪnˈsʌlt/","meaning":"모욕하다","example":"He didn't mean to insult you with that careless remark.","deck":"vocab"},{"id":1457,"word":"synonymous","ipa":"/sɪˈnɑnəməs/","meaning":"동의어의, 유의어의, 같은 뜻의","example":"His name became synonymous with honesty and hard work.","deck":"vocab"},{"id":1458,"word":"lousy","ipa":"/ˈlaʊzi/","meaning":"(몸 상태가) 아주 안 좋은, 안 좋은, 엉망인","example":"I feel lousy today, maybe I'm catching a cold.","deck":"vocab"},{"id":1459,"word":"catchy","ipa":"/ˈkætʃi/","meaning":"기억하기 쉬운, 기억에 잘 남는","example":"The advertisement uses a catchy tune you can't forget.","deck":"vocab"},{"id":1460,"word":"rein ~ in","ipa":"","meaning":"(비유적으로) 통제하다, 제한하다, 고삐를 죄다","example":"The manager tried to rein spending in before the audit.","deck":"vocab"},{"id":1461,"word":"run into ~","ipa":"","meaning":"(~를) 우연히 마주치다","example":"I ran into an old classmate at the grocery store.","deck":"vocab"},{"id":1462,"word":"run","ipa":"/rʌn/","meaning":"(선거에) 출마하다, 입후보하다","example":"She decided to run for mayor in next year's election.","deck":"vocab"},{"id":1463,"word":"slip out","ipa":"","meaning":"(비밀이 입에서) 무심코 튀어나오다","example":"The secret just slipped out before I could stop myself.","deck":"vocab"},{"id":1464,"word":"roll with it","ipa":"","meaning":"흐름에 맡기다, 있는 그대로 받아들이다 <상황 변화에 당황하지 않고 유연하게 대처하다>","example":"Plans changed suddenly, but we decided to roll with it.","deck":"vocab"},{"id":1465,"word":"nominal","ipa":"/ˈnɑmɪnəl/","meaning":"아주 적은, 얼마 안 되는","example":"The museum charges only a nominal fee for students.","deck":"vocab"},{"id":1466,"word":"co-star","ipa":"/ˈkoʊˌstɑr/","meaning":"(주연급으로) 함께 공연한 배우, 공동 주연","example":"She married her co-star from the romantic film.","deck":"vocab"},{"id":1467,"word":"mow","ipa":"/moʊ/","meaning":"(잔디밭 같은 공간에 난 풀을) 깎다, 베다","example":"He has to mow the lawn every Saturday morning.","deck":"vocab"},{"id":1468,"word":"whimper","ipa":"/ˈwɪmpər/","meaning":"훌쩍이다, 훌쩍이며 말하다","example":"The frightened puppy began to whimper in the corner.","deck":"vocab"},{"id":1469,"word":"taxing","ipa":"/ˈtæksɪŋ/","meaning":"아주 힘든, 부담이 큰 <정신적, 육체적 노력이 많이 필요함>","example":"The long hike was more taxing than we expected.","deck":"vocab"},{"id":1470,"word":"exhale","ipa":"/ɛksˈheɪl/","meaning":"숨을 내쉬다","example":"Take a deep breath, then slowly exhale through your mouth.","deck":"vocab"},{"id":1471,"word":"leftover","ipa":"/ˈlɛftˌoʊvər/","meaning":"(식사한 후) 남은 음식","example":"We ate the leftovers from last night's dinner for lunch.","deck":"vocab"},{"id":1472,"word":"leftover","ipa":"/ˈlɛftˌoʊvər/","meaning":"나머지의, 남은","example":"She used the leftover paint to touch up the fence.","deck":"vocab"},{"id":1473,"word":"walk out on ~","ipa":"","meaning":"~를 떠나다, ~를 버리다","example":"He walked out on his family without any explanation.","deck":"vocab"},{"id":1474,"word":"day one","ipa":"","meaning":"첫날, 최초","example":"They've been best friends since day one of college.","deck":"vocab"},{"id":1475,"word":"daydream","ipa":"/ˈdeɪˌdrim/","meaning":"백일몽을 꿈꾸다, 몽상에 잠기다","example":"He tends to daydream during boring afternoon lectures.","deck":"vocab"},{"id":1476,"word":"pinnacle","ipa":"/ˈpɪnəkəl/","meaning":"뾰족한 바위, 뾰족한 산봉우리","example":"Climbers rested at the base of the icy pinnacle.","deck":"vocab"},{"id":1477,"word":"restrict","ipa":"/rɪˈstrɪkt/","meaning":"~을 ~에 국한시키다, ~을 ~으로 제한하다","example":"The new rule restricts parking to residents only.","deck":"vocab"},{"id":1478,"word":"open up","ipa":"","meaning":"마음을 터놓다","example":"It took him years to open up about his childhood.","deck":"vocab"},{"id":1479,"word":"obligate","ipa":"/ˈɑblɪˌɡeɪt/","meaning":"(법률, 도덕상의) 의무를 지우다","example":"The contract obligates the tenant to pay for repairs.","deck":"vocab"},{"id":1480,"word":"behave","ipa":"/bɪˈheɪv/","meaning":"예의 바르게 행동하다","example":"The teacher asked the children to behave during the trip.","deck":"vocab"},{"id":1481,"word":"devastate","ipa":"/ˈdɛvəˌsteɪt/","meaning":"(사람에게) 엄청난 충격을 주다, 비탄에 빠뜨리다","example":"The sudden news of the loss devastated the whole family.","deck":"vocab"},{"id":1482,"word":"take advantage","ipa":"","meaning":"~을 이용해 먹다, ~을 악용하다","example":"He tried to take advantage of her kindness for money.","deck":"vocab"},{"id":1483,"word":"vet","ipa":"/vɛt/","meaning":"수의사","example":"We took the sick cat to the vet this morning.","deck":"vocab"},{"id":1484,"word":"when","ipa":"/wɛn/","meaning":"~인데도 불구하고","example":"Why buy a new one when the old one still works?","deck":"vocab"},{"id":1485,"word":"evolve","ipa":"/ɪˈvɑlv/","meaning":"(점진적으로) 발달하다, 진전하다","example":"Their small blog slowly evolved into a major magazine.","deck":"vocab"},{"id":1486,"word":"around","ipa":"/əˈraʊnd/","meaning":"(사람이) 가까이 있는, 어울려 지내는","example":"It's comforting to have good friends around during hard times.","deck":"vocab"},{"id":1487,"word":"rubbish","ipa":"/ˈrʌbɪʃ/","meaning":"(질이) 형편없는 것, 쓰레기 같은 것, 쓰레기 <형용사로도 쓰임>","example":"That movie was absolute rubbish and a waste of money.","deck":"vocab"},{"id":1488,"word":"haunted","ipa":"/ˈhɔntɪd/","meaning":"(건물이) 귀신이 나오는, 유령이 나오는","example":"Locals claim the old mansion is haunted at night.","deck":"vocab"},{"id":1489,"word":"stocky","ipa":"/ˈstɑki/","meaning":"체격이 다부진","example":"The stocky wrestler easily lifted his lighter opponent.","deck":"vocab"},{"id":1490,"word":"switch over","ipa":"","meaning":"(위치, 입장, 직장 등을) 바꾸다","example":"After ten years in sales, he switched over to marketing.","deck":"vocab"},{"id":1491,"word":"revive","ipa":"/rɪˈvaɪv/","meaning":"소생하다, 의식을 회복하다, 부활하다 <자동사>","example":"The patient began to revive minutes after the treatment.","deck":"vocab"},{"id":1492,"word":"invalid","ipa":"/ˈɪnvəlɪd/","meaning":"(혼자 생활하기 어려운) 병약자","example":"The elderly invalid needs a nurse to help each day.","deck":"vocab"},{"id":1493,"word":"pry","ipa":"/praɪ/","meaning":"(남의 사생활을) 캐묻다, 캐다","example":"I don't mean to pry, but are you feeling alright?","deck":"vocab"},{"id":1494,"word":"hear ~ out","ipa":"","meaning":"~의 말을 끝까지 들어주다","example":"Please just hear me out before you make a decision.","deck":"vocab"},{"id":1495,"word":"toddler","ipa":"/ˈtɑdlər/","meaning":"걸음마를 배우는 아이","example":"The toddler took her first wobbly steps across the room.","deck":"vocab"},{"id":1496,"word":"distract","ipa":"/dɪˈstrækt/","meaning":"(정신이) 집중이 안 되게 하다, 산만하게 하다","example":"Loud noises outside distract me while I'm studying.","deck":"vocab"},{"id":1497,"word":"balmy","ipa":"/ˈbɑmi/","meaning":"(공기, 날씨 등이) 아늑한, 훈훈한","example":"We enjoyed a balmy evening on the beach in June.","deck":"vocab"},{"id":1498,"word":"narrative","ipa":"/ˈnærətɪv/","meaning":"이야기, 서술, 기술, 묘사 <이야기 속 일련의 사건을 나열하여 서술한 것>","example":"The novel's gripping narrative kept me reading until dawn.","deck":"vocab"},{"id":1499,"word":"sort of","ipa":"","meaning":"어느 정도, 다소","example":"I sort of understand the theory, but not completely.","deck":"vocab"},{"id":1500,"word":"sort of","ipa":"","meaning":"일종의","example":"It's sort of a game where you guess the answers.","deck":"vocab"},{"id":1501,"word":"pop","ipa":"/pɑp/","meaning":"빵 하고 터지다","example":"The balloon will pop if you squeeze it too hard.","deck":"vocab"},{"id":1502,"word":"perception","ipa":"/pərˈsɛpʃən/","meaning":"(~에 대한) 인식, 이해","example":"The scandal changed the public's perception of the company.","deck":"vocab"},{"id":1503,"word":"tie","ipa":"/taɪ/","meaning":"비겨서 ~이 되다","example":"The two teams tied at three goals each.","deck":"vocab"},{"id":1504,"word":"rampage","ipa":"/ˈræmpeɪdʒ/","meaning":"광란 <많은 사람이 폭력적이고 무질서하게 행동하는 것>","example":"The angry crowd went on a rampage through downtown.","deck":"vocab"},{"id":1505,"word":"thigh","ipa":"/θaɪ/","meaning":"허벅지, 넓적다리","example":"He pulled a muscle in his left thigh while sprinting.","deck":"vocab"},{"id":1506,"word":"raise","ipa":"/reɪz/","meaning":"모으다, 얻어 내다, 형성하다","example":"They managed to raise ten thousand dollars for charity.","deck":"vocab"},{"id":1507,"word":"parched","ipa":"/pɑrtʃt/","meaning":"몹시 목마른 <비격식적인 표현>","example":"After the long hike, we were absolutely parched.","deck":"vocab"},{"id":1508,"word":"fire away","ipa":"","meaning":"(명령문 형태로 쓰여) 말하세요, 질문하세요","example":"If you have any questions, fire away, I'm listening.","deck":"vocab"},{"id":1509,"word":"vein","ipa":"/veɪn/","meaning":"방식, 태도","example":"She continued the speech in a more serious vein.","deck":"vocab"},{"id":1510,"word":"vein","ipa":"/veɪn/","meaning":"정맥","example":"The nurse carefully inserted the needle into his vein.","deck":"vocab"},{"id":1511,"word":"over time","ipa":"","meaning":"시간이 지남에 따라","example":"Over time, the small cracks in the wall widened.","deck":"vocab"},{"id":1512,"word":"trailer","ipa":"/ˈtreɪlər/","meaning":"(영화, 텔레비전 프로의) 예고편","example":"The movie's trailer made everyone excited for the release.","deck":"vocab"},{"id":1513,"word":"subdue","ipa":"/səbˈdu/","meaning":"진압하다, 제압하다","example":"Police quickly moved in to subdue the violent protesters.","deck":"vocab"},{"id":1514,"word":"go into ~","ipa":"","meaning":"(어떤 일, 행동을) 하기 시작하다","example":"After his mother died, he went into a deep depression.","deck":"vocab"},{"id":1515,"word":"go into ~","ipa":"","meaning":"~을 검토하다, ~에 대해 논의하다, ~에 대해 자세히 말하다","example":"I don't want to go into the details right now.","deck":"vocab"},{"id":1516,"word":"fabulous","ipa":"/ˈfæbjələs/","meaning":"기막히게 좋은, 기막히게 멋진","example":"You look absolutely fabulous in that new red dress.","deck":"vocab"},{"id":1517,"word":"close call","ipa":"/ˈkloʊs ˈkɔl/","meaning":"아슬아슬한 상황","example":"That was a close call; the car nearly hit us.","deck":"vocab"},{"id":1518,"word":"disease","ipa":"/dɪˈziz/","meaning":"질병, 병, 질환","example":"Early detection greatly improves the chances of curing the disease.","deck":"vocab"},{"id":1519,"word":"know the drill","ipa":"","meaning":"어떻게 하는지 알다, 방법을 알다, 상황을 알다","example":"You've done this before, so you know the drill.","deck":"vocab"},{"id":1520,"word":"inflamed","ipa":"/ɪnˈfleɪmd/","meaning":"(신체 부위에) 염증이 생긴","example":"Her throat was red and inflamed from the infection.","deck":"vocab"},{"id":1521,"word":"conductor","ipa":"/kənˈdʌktər/","meaning":"승무원 <기차, 버스 등에서 승차권을 확인하거나 차의 원활한 운행을 돕는 사람>","example":"The conductor checked every passenger's ticket on the train.","deck":"vocab"},{"id":1522,"word":"butcher","ipa":"/ˈbʊtʃər/","meaning":"(고기를 얻기 위해 동물을) 도축하다","example":"The farmer will butcher the pigs before winter arrives.","deck":"vocab"},{"id":1523,"word":"happen","ipa":"/ˈhæpən/","meaning":"마침 ~하다, 마침 ~이다, 공교롭게도 ~하다","example":"I happen to know the answer to that question.","deck":"vocab"},{"id":1524,"word":"silence","ipa":"/ˈsaɪləns/","meaning":"(아무도 말을 하지 않는) 침묵, 묵념","example":"The crowd observed a moment of silence for the victims.","deck":"vocab"},{"id":1525,"word":"blow ~ off","ipa":"","meaning":"~를 바람맞히다","example":"She blew me off and never showed up for dinner.","deck":"vocab"},{"id":1526,"word":"fringe","ipa":"/frɪndʒ/","meaning":"(눈썹 위까지 내려오게 자른) 앞머리 <영국식 표현. 주로 여성의 앞머리를 가리킴>","example":"She got a new fringe cut just above her eyebrows.","deck":"vocab"},{"id":1527,"word":"get to ~","ipa":"","meaning":"~하게 되다, ~할 기회를 갖다","example":"I finally got to meet my favorite author yesterday.","deck":"vocab"},{"id":1528,"word":"identify","ipa":"/aɪˈdɛntɪˌfaɪ/","meaning":"~을 찾다, 발견하다","example":"Scientists worked hard to identify the cause of the outbreak.","deck":"vocab"},{"id":1529,"word":"fridge","ipa":"/frɪdʒ/","meaning":"냉장고","example":"There's some leftover cake in the fridge if you're hungry.","deck":"vocab"},{"id":1530,"word":"genetic","ipa":"/dʒəˈnɛtɪk/","meaning":"유전의, 유전학의","example":"The disease is caused by a rare genetic mutation.","deck":"vocab"},{"id":1531,"word":"crouch","ipa":"/kraʊtʃ/","meaning":"몸을 쭈그리다, 쪼그려 앉다","example":"He had to crouch down to enter the low doorway.","deck":"vocab"},{"id":1532,"word":"endangered","ipa":"/ɪnˈdeɪndʒərd/","meaning":"멸종 위기에 처한","example":"The panda is an endangered species protected by law.","deck":"vocab"},{"id":1533,"word":"relevant","ipa":"/ˈrɛləvənt/","meaning":"(~와) 직접적인 관련이 있는, 밀접하게 관련된","example":"Please include only information that is relevant to the case.","deck":"vocab"},{"id":1534,"word":"relevant","ipa":"/ˈrɛləvənt/","meaning":"(현재의 상황에도) 유의미한, 의의가 있는","example":"The old philosopher's ideas are still relevant today.","deck":"vocab"},{"id":1535,"word":"blast","ipa":"/blæst/","meaning":"신나는 시간","example":"We had a blast at the beach party last weekend.","deck":"vocab"},{"id":1536,"word":"chant","ipa":"/tʃænt/","meaning":"(연이어 외치는) 구호","example":"The fans broke into a loud chant for their team.","deck":"vocab"},{"id":1537,"word":"feel compelled to ~","ipa":"","meaning":"~해야 한다는 생각이 강하게 들다","example":"She felt compelled to apologize after realizing her mistake.","deck":"vocab"},{"id":1538,"word":"location","ipa":"/loʊˈkeɪʃən/","meaning":"장소, 곳, 위치","example":"They chose a scenic location for the wedding ceremony.","deck":"vocab"},{"id":1539,"word":"let ~ off the hook","ipa":"","meaning":"봐주다, 곤란한 상황을 면하게 해 주다, 처벌을 피하게 해 주다","example":"The teacher let him off the hook for the late assignment.","deck":"vocab"},{"id":1540,"word":"therapist","ipa":"/ˈθɛrəpɪst/","meaning":"심리 치료사","example":"She sees a therapist every week to manage her anxiety.","deck":"vocab"},{"id":1541,"word":"ornate","ipa":"/ɔrˈneɪt/","meaning":"(복잡한 패턴이나 형태로) 화려하게 장식된","example":"The palace ceiling was covered in ornate gold carvings.","deck":"vocab"},{"id":1542,"word":"choir","ipa":"/ˈkwaɪər/","meaning":"합창단, 성가대","example":"She sings in the church choir every Sunday morning.","deck":"vocab"},{"id":1543,"word":"corn dog","ipa":"/ˈkɔrn ˌdɔɡ/","meaning":"콘도그, 핫도그 <막대기에 소시지를 꽂고 밀가루와 옥수수 반죽을 입혀 튀긴 음식>","example":"He bought a corn dog and lemonade at the fair.","deck":"vocab"},{"id":1544,"word":"address","ipa":"/əˈdrɛs/","meaning":"~을 다루다, ~의 대응에 나서다, ~에 대처하다","example":"The mayor promised to address the housing crisis soon.","deck":"vocab"},{"id":1545,"word":"dialectic","ipa":"/ˌdaɪəˈlɛktɪk/","meaning":"변증법적 방식","example":"The professor explained Hegel's dialectic in simple terms.","deck":"vocab"},{"id":1546,"word":"oversleep","ipa":"/ˌoʊvərˈslip/","meaning":"늦잠 자다","example":"I missed the bus because I overslept this morning.","deck":"vocab"},{"id":1547,"word":"ask a favor of","ipa":"","meaning":"~에게 부탁을 하다","example":"May I ask a favor of you before you leave?","deck":"vocab"},{"id":1548,"word":"hypocrite","ipa":"/ˈhɪpəˌkrɪt/","meaning":"위선자","example":"He's a hypocrite who preaches honesty but always lies.","deck":"vocab"},{"id":1549,"word":"cramp","ipa":"/kræmp/","meaning":"(근육에 생기는) 경련, 쥐","example":"She got a painful cramp in her leg while swimming.","deck":"vocab"},{"id":1550,"word":"hog","ipa":"/hɔɡ/","meaning":"할리데이비슨 오토바이","example":"He rode his shiny black hog down the open highway.","deck":"vocab"},{"id":1551,"word":"swing by","ipa":"","meaning":"~에 잠깐 들르다","example":"I'll swing by your office after lunch to grab it.","deck":"vocab"},{"id":1552,"word":"grumpy","ipa":"/ˈɡrʌmpi/","meaning":"투덜대는, 짜증을 잘 내는","example":"He's always grumpy before he's had his morning coffee.","deck":"vocab"},{"id":1553,"word":"mobilization","ipa":"/ˌmoʊbələˈzeɪʃən/","meaning":"(물자, 수단 등의) 동원","example":"The crisis required rapid mobilization of medical resources.","deck":"vocab"},{"id":1554,"word":"whistle-blower","ipa":"/ˈwɪsəlˌbloʊər/","meaning":"(기업 비리 등의) 내부 고발자","example":"The whistle-blower exposed the company's illegal accounting.","deck":"vocab"},{"id":1555,"word":"authenticity","ipa":"/ˌɔθɛnˈtɪsɪti/","meaning":"확실성, 신빙성, 진짜임","example":"Experts questioned the authenticity of the ancient painting.","deck":"vocab"},{"id":1556,"word":"engagement","ipa":"/ɪnˈɡeɪdʒmənt/","meaning":"관여, 참여, 관계함","example":"The campaign boosted customer engagement on social media.","deck":"vocab"},{"id":1557,"word":"viral","ipa":"/ˈvaɪrəl/","meaning":"바이럴의, 바이럴한 <SNS나 입소문을 통해 사람들에게 빠르게 퍼지는>","example":"Her funny video went viral within just a few hours.","deck":"vocab"},{"id":1558,"word":"intangible","ipa":"/ɪnˈtændʒəbəl/","meaning":"무형의, 만질 수 없는, 형체가 없는","example":"Trust is an intangible asset that takes years to build.","deck":"vocab"},{"id":1559,"word":"scarcity","ipa":"/ˈskɛrsɪti/","meaning":"부족, 결핍","example":"The drought caused a serious scarcity of clean water.","deck":"vocab"},{"id":1560,"word":"disruptive","ipa":"/dɪsˈrʌptɪv/","meaning":"와해성의, 파괴적인 <업계를 완전히 재편성할 정도로 혁신적인>","example":"The startup introduced a disruptive technology to the market.","deck":"vocab"},{"id":1561,"word":"monetization","ipa":"/ˌmɑnətəˈzeɪʃən/","meaning":"수익화, 수익 창출","example":"The platform explored new monetization strategies for creators.","deck":"vocab"},{"id":1562,"word":"scalability","ipa":"/ˌskeɪləˈbɪlɪti/","meaning":"확장성 <컴퓨터 용어>","example":"Cloud servers offer great scalability as demand grows.","deck":"vocab"},{"id":1563,"word":"interoperability","ipa":"/ˌɪntərˌɑpərəˈbɪlɪti/","meaning":"(국가 간 군사 무기 체계의) 상호운용성","example":"Allied forces trained together to improve their interoperability.","deck":"vocab"},{"id":1564,"word":"encryption","ipa":"/ɪnˈkrɪpʃən/","meaning":"암호화 <평문을 암호로 만드는 과정>","example":"Strong encryption keeps your online messages private.","deck":"vocab"},{"id":1565,"word":"grass roots","ipa":"/ˈɡræs ˌruts/","meaning":"민초, 보통 사람들, 보통 구성원들","example":"The movement grew from the grass roots of the community.","deck":"vocab"},{"id":1566,"word":"interdependence","ipa":"/ˌɪntərdɪˈpɛndəns/","meaning":"상호 의존","example":"Global trade creates deep interdependence among nations.","deck":"vocab"},{"id":1567,"word":"decentralize","ipa":"/diˈsɛntrəˌlaɪz/","meaning":"(권력, 조직 등을) 분권화하다, 분산시키다","example":"The company plans to decentralize decision-making across regions.","deck":"vocab"},{"id":1568,"word":"participatory","ipa":"/pɑrˈtɪsɪpəˌtɔri/","meaning":"참여의, 참가의","example":"The town uses a participatory process for its budget.","deck":"vocab"},{"id":1569,"word":"reciprocity","ipa":"/ˌrɛsəˈprɑsɪti/","meaning":"호혜(互惠)","example":"Their friendship is built on trust and reciprocity.","deck":"vocab"},{"id":1570,"word":"hierarchy","ipa":"/ˈhaɪəˌrɑrki/","meaning":"계층 구조, 계층제, 계급 제도","example":"The company has a strict hierarchy of management levels.","deck":"vocab"},{"id":1571,"word":"solidarity","ipa":"/ˌsɑləˈdɛrɪti/","meaning":"연대, 결속","example":"Workers marched in solidarity with the striking miners.","deck":"vocab"},{"id":1572,"word":"grill","ipa":"/ɡrɪl/","meaning":"그릴에 굽다, 석쇠에 굽다","example":"We're going to grill some burgers in the backyard tonight.","deck":"vocab"},{"id":1573,"word":"praise","ipa":"/preɪz/","meaning":"칭찬하다","example":"The coach praised the team for their hard work.","deck":"vocab"},{"id":1574,"word":"set ~ up","ipa":"","meaning":"소개팅을 주선하다, 맞선을 주선하다","example":"My friend set me up with her handsome coworker.","deck":"vocab"},{"id":1575,"word":"sit tight","ipa":"","meaning":"(자리를 옮기지 않고) 있는 자리에 그대로 있다","example":"Just sit tight; the doctor will see you shortly.","deck":"vocab"},{"id":1576,"word":"fairly","ipa":"/ˈfɛrli/","meaning":"상당히, 꽤","example":"The exam was fairly difficult, but I passed it.","deck":"vocab"},{"id":1577,"word":"appreciate","ipa":"/əˈpriʃiˌeɪt/","meaning":"(상황이나 사물을 제대로) 인식하다, 파악하다","example":"You need to appreciate the full scale of this problem.","deck":"vocab"},{"id":1578,"word":"appreciate","ipa":"/əˈpriʃiˌeɪt/","meaning":"진가를 알아보다, 인정하다","example":"Few people truly appreciate the effort behind her success.","deck":"vocab"},{"id":1579,"word":"case","ipa":"/keɪs/","meaning":"실정, 사실 <말하고 있는 내용이 실제 상황에 부합한다는 뜻>","example":"If that is the case, we should change our plan.","deck":"vocab"},{"id":1580,"word":"by now","ipa":"","meaning":"지금쯤은 이미, 이제","example":"They should have arrived home by now.","deck":"vocab"},{"id":1581,"word":"elicit","ipa":"/ɪˈlɪsɪt/","meaning":"(정보, 반응을 어렵게) 끌어내다 <격식>","example":"The detective tried to elicit a confession from the suspect.","deck":"vocab"},{"id":1582,"word":"altruistic","ipa":"/ˌæltruˈɪstɪk/","meaning":"이타적인","example":"Her altruistic nature led her to volunteer every weekend.","deck":"vocab"},{"id":1583,"word":"tacky","ipa":"/ˈtæki/","meaning":"싸구려 같은, 조잡한, 엉성한","example":"The souvenir shop sold cheap, tacky plastic ornaments.","deck":"vocab"},{"id":1584,"word":"pass ~ out","ipa":"","meaning":"(각자에게) ~을 나눠 주다","example":"The teacher passed the worksheets out to every student.","deck":"vocab"},{"id":1585,"word":"flyer","ipa":"/ˈflaɪər/","meaning":"(광고, 안내용) 전단, 전단지","example":"They handed out a flyer advertising the weekend sale.","deck":"vocab"},{"id":1586,"word":"grateful","ipa":"/ˈɡreɪtfəl/","meaning":"고마워하는, 감사하는","example":"I'm so grateful for all the help you've given me.","deck":"vocab"},{"id":1587,"word":"that is ~ you've got there","ipa":"","meaning":"그거참 ~이네, 그거 정말 ~이네 <다양한 감정을 나타낼 때 씀>","example":"That is a lovely dress you've got there.","deck":"vocab"},{"id":1588,"word":"daily life","ipa":"/ˈdeɪli ˈlaɪf/","meaning":"일상생활","example":"Smartphones have become an essential part of daily life.","deck":"vocab"},{"id":1589,"word":"diversion","ipa":"/dɪˈvɜrʒən/","meaning":"머리를 식히기 위해 하는 활동, 오락 <격식>","example":"Gardening is a pleasant diversion after a stressful week.","deck":"vocab"},{"id":1590,"word":"badly","ipa":"/ˈbædli/","meaning":"간절히, 너무, 몹시 <희망, 필요 등을 강조함>","example":"She badly wanted to win the scholarship this year.","deck":"vocab"},{"id":1591,"word":"for a change","ipa":"","meaning":"여느 때와 달리, 색다르게","example":"Let's eat out tonight for a change.","deck":"vocab"},{"id":1592,"word":"in person","ipa":"","meaning":"직접, 몸소, 직접 만나서","example":"I'd rather discuss this matter with you in person.","deck":"vocab"},{"id":1593,"word":"seemingly","ipa":"/ˈsimɪŋli/","meaning":"외견상으로, 겉보기에는","example":"The seemingly simple task took hours to finish.","deck":"vocab"},{"id":1594,"word":"kind of like","ipa":"","meaning":"마치","example":"The room felt cozy, kind of like a warm cabin.","deck":"vocab"},{"id":1595,"word":"fill one's shoes","ipa":"","meaning":"~의 후임이 되다, ~를 대신하다","example":"It won't be easy to fill her shoes as director.","deck":"vocab"},{"id":1596,"word":"bother","ipa":"/ˈbɑðər/","meaning":"굳이 ~하려고 애쓰다","example":"Don't bother cooking; we can just order takeout tonight.","deck":"vocab"},{"id":1597,"word":"ambience","ipa":"/ˈæmbiəns/","meaning":"(어떤 장소의) 분위기","example":"The candlelit restaurant had a warm, romantic ambience.","deck":"vocab"},{"id":1598,"word":"diaper","ipa":"/ˈdaɪpər/","meaning":"기저귀","example":"She quickly changed the baby's wet diaper before bed.","deck":"vocab"},{"id":1599,"word":"armpit","ipa":"/ˈɑrmˌpɪt/","meaning":"겨드랑이","example":"He felt a sharp pain under his left armpit.","deck":"vocab"},{"id":1600,"word":"get used to","ipa":"","meaning":"~에 익숙해지다","example":"It took me weeks to get used to the new schedule.","deck":"vocab"},{"id":1601,"word":"temptation","ipa":"/tɛmpˈteɪʃən/","meaning":"유혹","example":"She couldn't resist the temptation to eat another slice of cake.","deck":"vocab"},{"id":1602,"word":"sprain","ipa":"/spreɪn/","meaning":"(특히 팔목, 발목을) 삐다, 접지르다","example":"I fell and sprained my ankle while playing soccer.","deck":"vocab"},{"id":1603,"word":"trout","ipa":"/traʊt/","meaning":"송어","example":"We caught a large trout in the mountain stream.","deck":"vocab"},{"id":1604,"word":"pea","ipa":"/piː/","meaning":"완두콩","example":"She left a single pea on the edge of her plate.","deck":"vocab"},{"id":1605,"word":"hilarious","ipa":"/hɪˈlɛriəs/","meaning":"아주 우스운, 아주 재미있는","example":"The comedian's new show was absolutely hilarious.","deck":"vocab"},{"id":1606,"word":"pet","ipa":"/pɛt/","meaning":"(동물, 아이를 다정하게) 어루만지다, 쓰다듬다","example":"She gently petted the dog on its head.","deck":"vocab"},{"id":1607,"word":"regress","ipa":"/rɪˈɡrɛs/","meaning":"퇴행하다, 퇴보하다","example":"Without practice, his skills began to regress quickly.","deck":"vocab"},{"id":1608,"word":"get set","ipa":"","meaning":"준비를 갖추다","example":"On your marks, get set, go!","deck":"vocab"},{"id":1609,"word":"redeem","ipa":"/rɪˈdiːm/","meaning":"(전당포에 맡긴 귀중품 등을 돈을 주고) 되찾다","example":"He went to the pawnshop to redeem his grandfather's watch.","deck":"vocab"},{"id":1610,"word":"yet another","ipa":"","meaning":"또 하나의","example":"This is yet another example of his carelessness.","deck":"vocab"},{"id":1611,"word":"marvel","ipa":"/ˈmɑrvəl/","meaning":"경이, 경이로운 사람, 경이로운 것","example":"The ancient bridge is a marvel of engineering.","deck":"vocab"},{"id":1612,"word":"do you mind?","ipa":"","meaning":"저기요!, 그만 좀 하세요! <짜증이 난 상태에서 상대방에게 하는 말>","example":"Do you mind? I'm trying to concentrate here.","deck":"vocab"},{"id":1613,"word":"chitchat","ipa":"/ˈtʃɪtˌtʃæt/","meaning":"수다, 잡담","example":"We spent the afternoon in casual chitchat over coffee.","deck":"vocab"},{"id":1614,"word":"as well","ipa":"","meaning":"~도 또한 <too와 같은 의미>","example":"I'd like a coffee, and a slice of cake as well.","deck":"vocab"},{"id":1615,"word":"when to","ipa":"","meaning":"언제 ~할지","example":"He hasn't decided when to start his new business.","deck":"vocab"},{"id":1616,"word":"remarkable","ipa":"/rɪˈmɑrkəbəl/","meaning":"놀랄 만한, 놀라운, 주목할 만한","example":"She made a remarkable recovery after the surgery.","deck":"vocab"},{"id":1617,"word":"muse","ipa":"/mjuːz/","meaning":"골똘히 생각하다, 곰곰이 생각하다, 사색하다","example":"He sat by the window, musing about his future.","deck":"vocab"},{"id":1618,"word":"muse","ipa":"/mjuːz/","meaning":"(작가, 화가 등에게 영감을 주는) 뮤즈","example":"The painter said his wife was his greatest muse.","deck":"vocab"},{"id":1619,"word":"social butterfly","ipa":"/ˈsoʊʃəl ˈbʌtərflaɪ/","meaning":"사교성이 뛰어난 사람, 어울리기 좋아하는 사람","example":"My sister is a real social butterfly at every party.","deck":"vocab"},{"id":1620,"word":"take ~ too far","ipa":"","meaning":"~의 도를 지나치다, ~을 도를 지나치게 하다","example":"I think you're taking this too far.","deck":"vocab"},{"id":1621,"word":"keep one's chin up","ipa":"","meaning":"(어려운 상황일지라도) 힘을 내다, 기운 내다","example":"Keep your chin up; things will get better soon.","deck":"vocab"},{"id":1622,"word":"cursive","ipa":"/ˈkɜrsɪv/","meaning":"필기체, 흘림글씨","example":"She writes her name in beautiful cursive.","deck":"vocab"},{"id":1623,"word":"interject","ipa":"/ˌɪntərˈdʒɛkt/","meaning":"말참견을 하다","example":"He interjected a comment during the meeting.","deck":"vocab"},{"id":1624,"word":"pull over","ipa":"","meaning":"차를 대다, 차를 길가에 세우다, 길가에 정차하다 <정차하는 것을 뜻함>","example":"The police officer asked the driver to pull over.","deck":"vocab"},{"id":1625,"word":"refer to ~","ipa":"","meaning":"~을 나타내다","example":"The pronoun 'it' refers to the cat in this sentence.","deck":"vocab"},{"id":1626,"word":"bittersweet","ipa":"/ˈbɪtərˌswiːt/","meaning":"(경험, 상황, 기억 등이) 괴로우면서도 즐거운","example":"Graduation was a bittersweet moment for all of us.","deck":"vocab"},{"id":1627,"word":"study","ipa":"/ˈstʌdi/","meaning":"자세히 살펴보다, 유심히 보다","example":"She studied the map carefully before the trip.","deck":"vocab"},{"id":1628,"word":"you got me","ipa":"","meaning":"모르겠는데, 모르지 <질문에 대한 답을 모를 때 씀>","example":"You got me. I have no idea what the answer is.","deck":"vocab"},{"id":1629,"word":"you got me","ipa":"","meaning":"들통났네, 들켰네","example":"You got me! I ate the last cookie.","deck":"vocab"},{"id":1630,"word":"screw ~ up","ipa":"","meaning":"~을 엉망으로 하다, ~을 망치다 <속어>","example":"I really screwed up my presentation today.","deck":"vocab"},{"id":1631,"word":"out of breath","ipa":"","meaning":"숨이 가쁜","example":"After running upstairs, she was completely out of breath.","deck":"vocab"},{"id":1632,"word":"naturalize","ipa":"/ˈnætʃərəlaɪz/","meaning":"~를 귀화시키다, ~에게 시민권을 주다","example":"He was naturalized as a citizen last year.","deck":"vocab"},{"id":1633,"word":"count","ipa":"/kaʊnt/","meaning":"(정식으로) 인정되다 <자동사>","example":"Does this goal count if the whistle already blew?","deck":"vocab"},{"id":1634,"word":"count","ipa":"/kaʊnt/","meaning":"~으로 간주되다, 여겨지다","example":"In many countries, a bicycle counts as a vehicle.","deck":"vocab"},{"id":1635,"word":"count","ipa":"/kaʊnt/","meaning":"백작","example":"The count lived in a grand castle overlooking the valley.","deck":"vocab"},{"id":1636,"word":"count","ipa":"/kaʊnt/","meaning":"중요하다 <'세는 데 포함된다'라는 뜻에서 파생됐기 때문에 중요하다는 의미가 됨>","example":"Every vote counts in a close election.","deck":"vocab"},{"id":1637,"word":"turn ~ down","ipa":"","meaning":"~을 거절하다","example":"She decided to turn down the job offer.","deck":"vocab"},{"id":1638,"word":"night person","ipa":"/naɪt ˈpɜrsən/","meaning":"저녁형 인간","example":"I'm a night person, so I do my best work late.","deck":"vocab"},{"id":1639,"word":"more of ~","ipa":"","meaning":"오히려, 오히려 ~같은, 오히려 ~에 가까운, 다소","example":"He's more of a listener than a talker.","deck":"vocab"},{"id":1640,"word":"behind the wheel","ipa":"","meaning":"운전대를 잡고 있는, 운전 중에","example":"He fell asleep behind the wheel and had an accident.","deck":"vocab"},{"id":1641,"word":"spot","ipa":"/spɑt/","meaning":"알아채다, 발견하다, 찾다","example":"I spotted my friend in the crowded room.","deck":"vocab"},{"id":1642,"word":"take action","ipa":"","meaning":"조치를 취하다","example":"We must take action to protect the environment.","deck":"vocab"},{"id":1643,"word":"classy","ipa":"/ˈklæsi/","meaning":"세련된, 고급스러운, 기품 있는, 품격 있는","example":"She wore a classy black dress to the gala.","deck":"vocab"},{"id":1644,"word":"cost a fortune","ipa":"","meaning":"엄청나게 비싸다, 돈이 엄청나게 많이 들다","example":"That designer handbag must have cost a fortune.","deck":"vocab"},{"id":1645,"word":"presume","ipa":"/prɪˈzuːm/","meaning":"추정하다, 여기다, 생각하다","example":"I presume you've already finished your homework.","deck":"vocab"},{"id":1646,"word":"presume","ipa":"/prɪˈzuːm/","meaning":"~을 사실로 상정하다, ~이 존재한다는 것을 전제로 하다 <격식>","example":"The law presumes that everyone is innocent until proven guilty.","deck":"vocab"},{"id":1647,"word":"assessment","ipa":"/əˈsɛsmənt/","meaning":"평가","example":"The teacher gave a fair assessment of my work.","deck":"vocab"},{"id":1648,"word":"for now","ipa":"","meaning":"현재로서는, 당장은, 우선은 <곧 상황이 달라질 것임을 강조함>","example":"Let's stop here for now and continue tomorrow.","deck":"vocab"},{"id":1649,"word":"out loud","ipa":"","meaning":"소리 내어, 소리 내서","example":"She read the poem out loud to the class.","deck":"vocab"},{"id":1650,"word":"pitch-black","ipa":"/ˌpɪtʃ ˈblæk/","meaning":"칠흑같이 어두운","example":"The room was pitch-black when the power went out.","deck":"vocab"},{"id":1651,"word":"at all","ipa":"","meaning":"(의문문에서) 조금이라도, 도대체","example":"Do you have any money at all?","deck":"vocab"},{"id":1652,"word":"at the mercy of ~","ipa":"","meaning":"~에 휘둘리는, ~ 앞에서 속수무책인","example":"The small boat was at the mercy of the storm.","deck":"vocab"},{"id":1653,"word":"mop","ipa":"/mɑp/","meaning":"대걸레로 닦다","example":"She mopped the kitchen floor after dinner.","deck":"vocab"},{"id":1654,"word":"ancestor","ipa":"/ˈænsɛstər/","meaning":"(사람의) 조상, 선조","example":"My ancestors came from a small village in Ireland.","deck":"vocab"},{"id":1655,"word":"what brings you","ipa":"","meaning":"무슨 일로 ~에 오셨어요?","example":"What brings you to the city today?","deck":"vocab"},{"id":1656,"word":"stuffy","ipa":"/ˈstʌfi/","meaning":"(코가) 막힌","example":"My nose is stuffy because of this cold.","deck":"vocab"},{"id":1657,"word":"sore throat","ipa":"/sɔr θroʊt/","meaning":"인후염","example":"I woke up with a sore throat this morning.","deck":"vocab"},{"id":1658,"word":"there is no such thing","ipa":"","meaning":"(~같은) 그런 것은 세상에 없다","example":"There is no such thing as a free lunch.","deck":"vocab"},{"id":1659,"word":"dignified","ipa":"/ˈdɪɡnɪfaɪd/","meaning":"위엄 있는, 품위 있는","example":"The elderly man had a calm and dignified manner.","deck":"vocab"},{"id":1660,"word":"could have been worse","ipa":"","meaning":"그만하길 다행이다, 이 정도면 괜찮다, 최악은 면했다","example":"We lost the game, but it could have been worse.","deck":"vocab"},{"id":1661,"word":"how come?","ipa":"","meaning":"왜?, 어째서?, 어째서 ~인가?","example":"How come you didn't call me last night?","deck":"vocab"},{"id":1662,"word":"circumstance","ipa":"/ˈsɜrkəmstæns/","meaning":"(일, 사건 등을 둘러싼) 환경, 상황, 정황 <주로 복수형으로 씀>","example":"Under the circumstances, we made the best decision possible.","deck":"vocab"},{"id":1663,"word":"these days","ipa":"","meaning":"(과거와 비교해서) 요즘, 요즘에는","example":"These days, everyone seems to have a smartphone.","deck":"vocab"},{"id":1664,"word":"diversity","ipa":"/dɪˈvɜrsɪti/","meaning":"다양한 사람의 포용, 다문화 배려","example":"Our company values diversity in the workplace.","deck":"vocab"},{"id":1665,"word":"composite","ipa":"/kəmˈpɑzɪt/","meaning":"몽타주 사진 합성 장치, 몽타주","example":"The police created a composite of the suspect's face.","deck":"vocab"},{"id":1666,"word":"custody","ipa":"/ˈkʌstədi/","meaning":"양육권, 보호권, 관리권, 양육, 관리","example":"After the divorce, she got custody of the children.","deck":"vocab"},{"id":1667,"word":"custody","ipa":"/ˈkʌstədi/","meaning":"(특히 재판 전의) 유치, 구류","example":"The suspect was taken into custody by the police.","deck":"vocab"},{"id":1668,"word":"cocky","ipa":"/ˈkɑki/","meaning":"자만심에 찬","example":"He became cocky after winning a few games.","deck":"vocab"},{"id":1669,"word":"take one's pick","ipa":"","meaning":"마음에 드는 것을 골라잡다, 마음대로 선택하다","example":"There are many desserts, so take your pick.","deck":"vocab"},{"id":1670,"word":"bounty","ipa":"/ˈbaʊnti/","meaning":"현상금, 포상금","example":"The sheriff offered a bounty for the outlaw's capture.","deck":"vocab"},{"id":1671,"word":"What about it?","ipa":"","meaning":"그래서 어쨌다는 거야? <\"so what\"과 같은 의미>","example":"So I was late. What about it?","deck":"vocab"},{"id":1672,"word":"dice","ipa":"/daɪs/","meaning":"주사위 <미국에서는 단수형으로 die, 복수형으로 dice를 씀>","example":"He rolled the dice and hoped for a six.","deck":"vocab"},{"id":1673,"word":"would rather ~","ipa":"","meaning":"차라리 ~하겠다, 차라리 ~하고 싶다, ~를 선호하다","example":"I would rather stay home than go out tonight.","deck":"vocab"},{"id":1674,"word":"obsession","ipa":"/əbˈsɛʃən/","meaning":"집착, 강박 관념 <머릿속에서 뭔가에 관한 생각이 떠나지 않는 것>","example":"Her obsession with cleanliness drove everyone crazy.","deck":"vocab"},{"id":1675,"word":"mean it","ipa":"","meaning":"진심이다, 정말이다, 진심으로 하는 말이다","example":"I love you, and I really mean it.","deck":"vocab"},{"id":1676,"word":"hood","ipa":"/hʊd/","meaning":"동네 <특히 미국에서 주로 쓰이는 속어>","example":"He grew up in a tough hood in the city.","deck":"vocab"},{"id":1677,"word":"convict","ipa":"/kənˈvɪkt/","meaning":"유죄를 선고하다, 유죄 판결을 내리다","example":"The jury convicted him of the crime.","deck":"vocab"},{"id":1678,"word":"conceal","ipa":"/kənˈsiːl/","meaning":"감추다, 숨기다 <격식>","example":"She tried to conceal her disappointment with a smile.","deck":"vocab"},{"id":1679,"word":"prime","ipa":"/praɪm/","meaning":"전성기, 한창때","example":"At the prime of his career, he retired suddenly.","deck":"vocab"},{"id":1680,"word":"extinction","ipa":"/ɪkˈstɪŋkʃən/","meaning":"멸종, 절멸, 소멸","example":"Many species are on the brink of extinction.","deck":"vocab"},{"id":1681,"word":"to the point of ~","ipa":"","meaning":"~라고 할 정도로, ~라고 할 수 있을 정도로","example":"He was tired to the point of collapse.","deck":"vocab"},{"id":1682,"word":"incredible","ipa":"/ɪnˈkrɛdəbəl/","meaning":"놀라운, 훌륭한, 대단한, 굉장한","example":"The view from the mountaintop was absolutely incredible.","deck":"vocab"},{"id":1683,"word":"falling-out","ipa":"/ˈfɔlɪŋ ˌaʊt/","meaning":"다툼, 사이가 틀어지는 일 <비격식>","example":"The two friends had a falling-out over money.","deck":"vocab"},{"id":1684,"word":"blossom","ipa":"/ˈblɑsəm/","meaning":"(나무, 관목이) 꽃 피다, 꽃을 피우다","example":"The cherry trees blossom every spring.","deck":"vocab"},{"id":1685,"word":"talk in one's sleep","ipa":"","meaning":"잠꼬대를 하다","example":"My brother often talks in his sleep.","deck":"vocab"},{"id":1686,"word":"carve","ipa":"/kɑrv/","meaning":"조각하다, 깎아서 만들다","example":"He carved a small boat out of wood.","deck":"vocab"},{"id":1687,"word":"for your information","ipa":"","meaning":"뭔가 잘못 알고 계신 것 같은데 <FYI로 줄여서 말하기도 함>","example":"For your information, I already finished that task.","deck":"vocab"},{"id":1688,"word":"medication","ipa":"/ˌmɛdɪˈkeɪʃən/","meaning":"약, 약물","example":"The doctor prescribed medication for my allergies.","deck":"vocab"},{"id":1689,"word":"jump into ~","ipa":"","meaning":"갑자기 ~을 시작하다, ~에 뛰어들다","example":"Don't jump into a decision without thinking it through.","deck":"vocab"},{"id":1690,"word":"drop the ball","ipa":"","meaning":"(책임지고 있는 일을) 실수로 망치다","example":"He dropped the ball on the project and missed the deadline.","deck":"vocab"},{"id":1691,"word":"cut ~ some slack","ipa":"","meaning":"~을 덜 몰아붙이다","example":"Cut him some slack; he's new here.","deck":"vocab"},{"id":1692,"word":"moral","ipa":"/ˈmɔrəl/","meaning":"(이야기, 경험 등의) 교훈","example":"The moral of the story is to always be honest.","deck":"vocab"},{"id":1693,"word":"spend","ipa":"/spɛnd/","meaning":"(돈을) 쓰다","example":"She spends too much money on clothes.","deck":"vocab"},{"id":1694,"word":"damage","ipa":"/ˈdæmɪdʒ/","meaning":"(~에 대한) 손상, 피해 <물리적인 피해를 뜻함>","example":"The storm caused serious damage to the roof.","deck":"vocab"},{"id":1695,"word":"present","ipa":"/prɪˈzɛnt/","meaning":"(사람들이 보거나 검토하도록) 제시하다, 제출하다","example":"She presented her research to the committee.","deck":"vocab"},{"id":1696,"word":"diagnosis","ipa":"/ˌdaɪəɡˈnoʊsɪs/","meaning":"진단","example":"The doctor's diagnosis was a mild case of the flu.","deck":"vocab"},{"id":1697,"word":"transfusion","ipa":"/trænsˈfjuːʒən/","meaning":"수혈 <의학 용어>","example":"The patient needed a blood transfusion after the accident.","deck":"vocab"},{"id":1698,"word":"sweep ~ back","ipa":"","meaning":"(머리를) 뒤로 쓸어올리다","example":"She swept her hair back into a ponytail.","deck":"vocab"},{"id":1699,"word":"for good","ipa":"","meaning":"영원히","example":"He left the town for good and never returned.","deck":"vocab"},{"id":1700,"word":"deliver","ipa":"/dɪˈlɪvər/","meaning":"내놓다, 산출하다, 약속 지키다","example":"The new manager promised to deliver better results.","deck":"vocab"},{"id":1701,"word":"frown","ipa":"/fraʊn/","meaning":"눈살을 찌푸리다, 얼굴을 찡그리다","example":"She frowned when she heard the bad news.","deck":"vocab"},{"id":1702,"word":"crabby","ipa":"/ˈkræbi/","meaning":"(사람이) 까칠한, 괴팍한","example":"He gets crabby when he doesn't get enough sleep.","deck":"vocab"},{"id":1703,"word":"foodie","ipa":"/ˈfuːdi/","meaning":"식도락가 <비격식>","example":"As a foodie, she loves trying new restaurants.","deck":"vocab"},{"id":1704,"word":"chubby","ipa":"/ˈtʃʌbi/","meaning":"통통한, 토실토실한","example":"The baby had adorable chubby cheeks.","deck":"vocab"},{"id":1705,"word":"bull's eye","ipa":"/ˈbʊlz aɪ/","meaning":"적중, 명중","example":"The archer hit the bull's eye on his first try.","deck":"vocab"},{"id":1706,"word":"all the way","ipa":"","meaning":"내내, 처음부터 끝까지","example":"We drove all the way to the coast in one day.","deck":"vocab"},{"id":1707,"word":"stay out","ipa":"","meaning":"(~에) 관여하지 않다, (~을) 피하다","example":"You should stay out of their argument.","deck":"vocab"},{"id":1708,"word":"happily ever after","ipa":"","meaning":"오래오래 행복하게","example":"They got married and lived happily ever after.","deck":"vocab"},{"id":1709,"word":"have no choice but to ~","ipa":"","meaning":"~하지 않을 수 없다, ~하는 수밖에 없다","example":"We had no choice but to cancel the trip.","deck":"vocab"},{"id":1710,"word":"run out","ipa":"","meaning":"(~을) 다 써버리다, 바닥내다","example":"We ran out of milk this morning.","deck":"vocab"},{"id":1711,"word":"transplant","ipa":"/ˈtrænsplænt/","meaning":"(생체 조직 등의) 이식","example":"He is waiting for a heart transplant.","deck":"vocab"},{"id":1712,"word":"on one's own","ipa":"","meaning":"혼자, 혼자서, 혼자 힘으로, 자력으로","example":"She finished the project on her own.","deck":"vocab"},{"id":1713,"word":"kind of","ipa":"","meaning":"좀, 약간, 어느 정도 <비격식적인 표현>","example":"I'm kind of tired after the long walk.","deck":"vocab"},{"id":1714,"word":"tell","ipa":"/tɛl/","meaning":"~을 알다, 구별하다, 식별하다 <타동사>","example":"Can you tell the difference between these two colors?","deck":"vocab"},{"id":1715,"word":"more or less","ipa":"","meaning":"거의","example":"The project is more or less finished.","deck":"vocab"},{"id":1716,"word":"drown","ipa":"/draʊn/","meaning":"물에 빠져 죽다, 익사하다","example":"He almost drowned while swimming in the ocean.","deck":"vocab"},{"id":1717,"word":"make ~ up","ipa":"","meaning":"~을 형성하다, ~을 차지하다, ~을 이루다, ~을 구성하다","example":"Women make up half of the workforce here.","deck":"vocab"},{"id":1718,"word":"deaf","ipa":"/dɛf/","meaning":"귀가 들리지 않는, 청각 장애가 있는","example":"She has been deaf since birth.","deck":"vocab"},{"id":1719,"word":"struggle","ipa":"/ˈstrʌɡəl/","meaning":"힘든 것, 힘든 일","example":"Learning a new language was a real struggle for him.","deck":"vocab"},{"id":1720,"word":"struggle","ipa":"/ˈstrʌɡəl/","meaning":"분투하다, 고투하다, 고심하다, 애쓰다, 허덕이다, 버둥거리다","example":"She struggled to open the heavy door.","deck":"vocab"},{"id":1721,"word":"imaginative","ipa":"/ɪˈmædʒɪnətɪv/","meaning":"창의적인, 상상력이 풍부한","example":"She wrote an imaginative story about talking animals.","deck":"vocab"},{"id":1722,"word":"humanity","ipa":"/hjuːˈmænɪti/","meaning":"인류, 인간","example":"The disaster brought out the best in humanity.","deck":"vocab"},{"id":1723,"word":"what is the occasion","ipa":"","meaning":"뭔 일 있어?, 무슨 일이야?","example":"You're all dressed up! What is the occasion?","deck":"vocab"},{"id":1724,"word":"hydrate","ipa":"/ˈhaɪdreɪt/","meaning":"수분을 공급하다","example":"Remember to hydrate during your workout.","deck":"vocab"},{"id":1725,"word":"hydrate","ipa":"/ˈhaɪdreɪt/","meaning":"수화시키다 <화학 용어. 물 분자와 결합하여 수화물이 되게 하다>","example":"Certain salts hydrate when exposed to water.","deck":"vocab"},{"id":1726,"word":"persistence","ipa":"/pərˈsɪstəns/","meaning":"(사람의) 고집, 끈기","example":"Her persistence finally paid off when she got the job.","deck":"vocab"},{"id":1727,"word":"lanky","ipa":"/ˈlæŋki/","meaning":"흐느적거리듯 움직이는","example":"The lanky teenager towered over his classmates.","deck":"vocab"},{"id":1728,"word":"sibling","ipa":"/ˈsɪblɪŋ/","meaning":"(한 명의) 형제, 자매","example":"I have three siblings, two brothers and a sister.","deck":"vocab"},{"id":1729,"word":"sing along","ipa":"","meaning":"(~와 함께) 따라부르다, 함께 노래하다","example":"The crowd began to sing along with the band.","deck":"vocab"},{"id":1730,"word":"do well on","ipa":"","meaning":"(~을) 잘하다","example":"She hopes to do well on her final exam.","deck":"vocab"},{"id":1731,"word":"assignment","ipa":"/əˈsaɪnmənt/","meaning":"과제, 임무","example":"The teacher gave us a difficult assignment.","deck":"vocab"},{"id":1732,"word":"besides","ipa":"/bɪˈsaɪdz/","meaning":"게다가, 뿐만 아니라","example":"I don't want to go; besides, it's raining.","deck":"vocab"},{"id":1733,"word":"porch","ipa":"/pɔrtʃ/","meaning":"현관 <집의 출입구 앞에 지붕으로 덮인, 건물의 외벽에서 튀어나온 공간>","example":"We sat on the porch and watched the sunset.","deck":"vocab"},{"id":1734,"word":"tummy","ipa":"/ˈtʌmi/","meaning":"배 <유아어. stomach의 변형>","example":"The little boy said his tummy hurt.","deck":"vocab"},{"id":1735,"word":"that is the spirit","ipa":"","meaning":"바로 그런 정신이야!, 그렇게 하는 거야! <격려하는 말>","example":"That's the spirit! Keep trying and you'll succeed.","deck":"vocab"},{"id":1736,"word":"kettle","ipa":"/ˈkɛtəl/","meaning":"주전자 <주로 물을 끓일 때 씀. 뚜껑, 손잡이, 주둥이가 달려 있음>","example":"She put the kettle on to make some tea.","deck":"vocab"},{"id":1737,"word":"next to","ipa":"","meaning":"(위치상으로) ~ 옆에","example":"The bank is right next to the post office.","deck":"vocab"},{"id":1738,"word":"in need","ipa":"","meaning":"어려움에 처해, 도움이 필요한, 궁핍한 <삶에 꼭 필요한 것이 없는 상태>","example":"We should always help those in need.","deck":"vocab"},{"id":1739,"word":"doodle","ipa":"/ˈduːdəl/","meaning":"낙서를 끄적거리다","example":"He doodled little stars all over his notebook.","deck":"vocab"},{"id":1740,"word":"rip out","ipa":"","meaning":"(비유적으로, 사람의 마음 등을) 찢다","example":"The tragic news seemed to rip out her heart.","deck":"vocab"},{"id":1741,"word":"while","ipa":"/waɪl/","meaning":"~이긴 하지만, ~에도 불구하고","example":"While I understand your point, I still disagree.","deck":"vocab"},{"id":1742,"word":"charity","ipa":"/ˈtʃærɪti/","meaning":"자선 단체, 구호 단체","example":"She donates to a local charity every month.","deck":"vocab"},{"id":1743,"word":"hit on ~","ipa":"","meaning":"~에게 수작을 걸다, ~를 꼬시다","example":"A stranger tried to hit on her at the bar.","deck":"vocab"},{"id":1744,"word":"intrude","ipa":"/ɪnˈtruːd/","meaning":"침범하다, 함부로 끼어들다, 방해하다","example":"I don't want to intrude on your family time.","deck":"vocab"},{"id":1745,"word":"intrude","ipa":"/ɪnˈtruːd/","meaning":"방해하다","example":"Sorry to intrude, but I need to ask you something.","deck":"vocab"},{"id":1746,"word":"guide","ipa":"/ɡaɪd/","meaning":"(~에 대한) 안내, 안내서, 가이드","example":"She bought a travel guide before her trip.","deck":"vocab"},{"id":1747,"word":"increase","ipa":"/ˈɪnkriːs/","meaning":"(수량의) 증가","example":"There was a sharp increase in prices this year.","deck":"vocab"},{"id":1748,"word":"barely","ipa":"/ˈbɛrli/","meaning":"거의 ~아니게, 거의 ~없이","example":"He barely passed the exam.","deck":"vocab"},{"id":1749,"word":"apparently","ipa":"/əˈpærəntli/","meaning":"(확실하지는 않지만) 듣자 하니, 알려진 바로는","example":"Apparently, they canceled the concert due to rain.","deck":"vocab"},{"id":1750,"word":"recess","ipa":"/ˈriːsɛs/","meaning":"(학교의) 쉬는 시간","example":"The children played outside during recess.","deck":"vocab"},{"id":1751,"word":"amused","ipa":"/əˈmjuːzd/","meaning":"재미있어 하는, 즐거워 하는","example":"She was amused by the kitten's playful antics.","deck":"vocab"},{"id":1752,"word":"fine","ipa":"/faɪn/","meaning":"벌금","example":"He had to pay a fine for parking illegally.","deck":"vocab"},{"id":1753,"word":"affordable","ipa":"/əˈfɔrdəbəl/","meaning":"(가격이) 알맞은, 적당한, 큰 부담 없는 <대다수가 충분히 감당할 수 있는>","example":"We found an affordable apartment near downtown.","deck":"vocab"},{"id":1754,"word":"dinosaur","ipa":"/ˈdaɪnəsɔr/","meaning":"공룡","example":"The museum has a huge dinosaur skeleton on display.","deck":"vocab"},{"id":1755,"word":"attempt","ipa":"/əˈtɛmpt/","meaning":"(특히 힘든 일을) 시도하다, 애써 해보다","example":"She attempted to climb the mountain despite the storm.","deck":"vocab"},{"id":1756,"word":"pass away","ipa":"","meaning":"돌아가시다 <die라는 말을 피하기 위해 씀>","example":"His grandmother passed away last winter.","deck":"vocab"},{"id":1757,"word":"upcoming","ipa":"/ˈʌpˌkʌmɪŋ/","meaning":"다가오는, 곧 있을 <명사 앞에만 씀>","example":"Everyone is excited about the upcoming festival.","deck":"vocab"},{"id":1758,"word":"divide","ipa":"/dɪˈvaɪd/","meaning":"(여러 부분들로) 나뉘다, 갈라지다","example":"The class divided into small groups for the project.","deck":"vocab"},{"id":1759,"word":"exclusive","ipa":"/ɪkˈskluːsɪv/","meaning":"독점적인, 전용의","example":"The club offers exclusive benefits to its members.","deck":"vocab"},{"id":1760,"word":"poetic","ipa":"/poʊˈɛtɪk/","meaning":"시적인 <아름답거나 감성적인 것을 뜻하는 비유적인 표현으로도 씀>","example":"The sunset had a poetic beauty that left us speechless.","deck":"vocab"},{"id":1761,"word":"move on","ipa":"","meaning":"(새로운 일, 주제로) 옮기다, 넘어가다","example":"Let's move on to the next topic.","deck":"vocab"},{"id":1762,"word":"get dressed","ipa":"","meaning":"옷을 입다","example":"Hurry up and get dressed, or we'll be late.","deck":"vocab"},{"id":1763,"word":"look ~ up","ipa":"","meaning":"찾아보다","example":"I'll look up the word in the dictionary.","deck":"vocab"},{"id":1764,"word":"dairy","ipa":"/ˈdɛri/","meaning":"유제품","example":"She avoids dairy because she is lactose intolerant.","deck":"vocab"},{"id":1765,"word":"official","ipa":"/əˈfɪʃəl/","meaning":"(고위) 공무원, 관리, 임원","example":"A government official announced the new policy.","deck":"vocab"},{"id":1766,"word":"jerk","ipa":"/dʒɜrk/","meaning":"나쁜 놈, 무례한 놈","example":"Don't be such a jerk to your little brother.","deck":"vocab"},{"id":1767,"word":"jerk","ipa":"/dʒɜrk/","meaning":"홱 움직이다 <갑자기 날카롭게 움직이거나 무엇을 움직이게 하다>","example":"The car jerked forward when he hit the brakes.","deck":"vocab"},{"id":1768,"word":"shame on you","ipa":"","meaning":"부끄러운 줄 알아라","example":"Shame on you for lying to your parents.","deck":"vocab"},{"id":1769,"word":"stunning","ipa":"/ˈstʌnɪŋ/","meaning":"굉장히 아름다운, 굉장히 멋진, 놀랄만한","example":"She looked absolutely stunning in her wedding dress.","deck":"vocab"},{"id":1770,"word":"sunscreen","ipa":"/ˈsʌnskriːn/","meaning":"자외선 차단제","example":"Don't forget to apply sunscreen before going to the beach.","deck":"vocab"},{"id":1771,"word":"corruption","ipa":"/kəˈrʌpʃən/","meaning":"부패, 타락","example":"The scandal exposed widespread corruption in the government.","deck":"vocab"},{"id":1772,"word":"by the time","ipa":"","meaning":"~쯤에, ~할 쯤에는","example":"By the time we arrived, the show had already started.","deck":"vocab"},{"id":1773,"word":"vital","ipa":"/ˈvaɪtəl/","meaning":"필수적인, 매우 중요한, 없어서는 안 될","example":"Water is vital for all living things.","deck":"vocab"},{"id":1774,"word":"once","ipa":"/wʌns/","meaning":"일단 ~하면, ~하자마자","example":"Once you finish your homework, you can play outside.","deck":"vocab"},{"id":1775,"word":"matter","ipa":"/ˈmætər/","meaning":"중요하다, 문제되다 <진행형으로는 쓰이지 않음>","example":"Your opinion really matters to me.","deck":"vocab"},{"id":1776,"word":"through","ipa":"/θruː/","meaning":"~을 겪어","example":"He went through a lot of hardship as a child.","deck":"vocab"},{"id":1777,"word":"overnight","ipa":"/ˌoʊvərˈnaɪt/","meaning":"하룻밤 사이에, 갑자기, 빨리","example":"The company became famous overnight.","deck":"vocab"},{"id":1778,"word":"superb","ipa":"/suːˈpɜrb/","meaning":"최고의, 최상의, 대단히 훌륭한","example":"The food at the restaurant was superb.","deck":"vocab"},{"id":1779,"word":"help oneself","ipa":"","meaning":"(~을) 마음껏 먹다, 마음껏 마시다","example":"Please help yourself to some snacks.","deck":"vocab"},{"id":1780,"word":"help oneself","ipa":"","meaning":"(~을) 마음껏 가져가다","example":"Help yourself to any books on the shelf.","deck":"vocab"},{"id":1781,"word":"volunteer","ipa":"/ˌvɑlənˈtɪr/","meaning":"자원 봉사 하다","example":"She volunteers at the animal shelter every weekend.","deck":"vocab"},{"id":1782,"word":"clothing","ipa":"/ˈkloʊðɪŋ/","meaning":"(특히 특정한 종류의) 옷, 의복","example":"You should wear warm clothing in winter.","deck":"vocab"},{"id":1783,"word":"literally","ipa":"/ˈlɪtərəli/","meaning":"말 그대로, 정말로, 완전히 <사실인 내용을 강조하기 위해 씀>","example":"I was literally frozen after standing in the snow.","deck":"vocab"},{"id":1784,"word":"courage","ipa":"/ˈkɜrɪdʒ/","meaning":"용기","example":"It took great courage to speak up in front of everyone.","deck":"vocab"},{"id":1785,"word":"hang on","ipa":"","meaning":"잠깐, 기다려, 멈춰 봐 <명령형으로 씀>","example":"Hang on a second, I'll be right back.","deck":"vocab"},{"id":1786,"word":"what ~ look like","ipa":"","meaning":"~는 어떻게 생겼어?, ~는 어떻게 생겼는지 <How does ~ look?과 같은 의미>","example":"What does your new house look like?","deck":"vocab"},{"id":1787,"word":"habitat","ipa":"/ˈhæbɪtæt/","meaning":"(생물을 둘러싼) 환경, 거주 환경, 서식지","example":"Pollution is destroying the natural habitat of many animals.","deck":"vocab"},{"id":1788,"word":"squirrel","ipa":"/ˈskwɜrəl/","meaning":"청설모, 다람쥐 <다람쥣과의 동물을 총칭하는 표현>","example":"A squirrel buried an acorn under the tree.","deck":"vocab"},{"id":1789,"word":"fulfill","ipa":"/fʊlˈfɪl/","meaning":"실현하다, 성취하다, 이루다","example":"She worked hard to fulfill her childhood dream.","deck":"vocab"},{"id":1790,"word":"investigate","ipa":"/ɪnˈvɛstɪɡeɪt/","meaning":"(범죄, 상황, 사건 등을) 수사하다","example":"The detectives investigated the mysterious robbery.","deck":"vocab"},{"id":1791,"word":"along with ~","ipa":"","meaning":"~와 함께","example":"She came to the party along with her sister.","deck":"vocab"},{"id":1792,"word":"field trip","ipa":"/ˈfiːld trɪp/","meaning":"현장 학습","example":"The students went on a field trip to the zoo.","deck":"vocab"},{"id":1793,"word":"rush","ipa":"/rʌʃ/","meaning":"급속히 움직이다, 급히 하다, 급히 서두르다","example":"We had to rush to catch the last train.","deck":"vocab"},{"id":1794,"word":"show up","ipa":"","meaning":"(예정된 곳에) 나타나다","example":"He didn't show up for the meeting.","deck":"vocab"},{"id":1795,"word":"embarrassed","ipa":"/ɪmˈbærəst/","meaning":"(사람이) 창피한, 쑥스러운, 당황스러운","example":"She felt embarrassed when she tripped in public.","deck":"vocab"},{"id":1796,"word":"break ~ up","ipa":"","meaning":"(모임, 집회, 무리 등을) ~을 해산시키다","example":"The police came to break up the crowd.","deck":"vocab"},{"id":1797,"word":"cipher","ipa":"/ˈsaɪfər/","meaning":"(글로 쓰인) 암호","example":"The spy sent a message written in a secret cipher.","deck":"vocab"},{"id":1798,"word":"chore","ipa":"/tʃɔr/","meaning":"(빨래, 청소, 설거지 등의) 집안일","example":"Washing the dishes is my least favorite chore.","deck":"vocab"},{"id":1799,"word":"all along","ipa":"","meaning":"내내, 줄곧, 계속","example":"I knew the truth all along.","deck":"vocab"},{"id":1800,"word":"for oneself","ipa":"","meaning":"(다른 사람 도움 없이) 스스로, 직접, 제힘으로","example":"You need to see it for yourself to believe it.","deck":"vocab"},{"id":1801,"word":"all of a sudden","ipa":"","meaning":"갑자기","example":"All of a sudden, the lights went out and everyone screamed.","deck":"vocab"},{"id":1802,"word":"out there","ipa":"","meaning":"어딘가, 세상 어딘가","example":"There is someone out there who really understands you.","deck":"vocab"},{"id":1803,"word":"afford","ipa":"/əˈfɔːrd/","meaning":"여유가 되다, 형편이 되다, 할 수 있다 <수동태로는 안 씀.>","example":"We can't afford a new car this year.","deck":"vocab"},{"id":1804,"word":"terrific","ipa":"/təˈrɪfɪk/","meaning":"아주 좋은, 멋진, 훌륭한, 굉장한","example":"You did a terrific job on the presentation today.","deck":"vocab"},{"id":1805,"word":"should have","ipa":"","meaning":"~했어야 했다","example":"I should have called you before coming over.","deck":"vocab"},{"id":1806,"word":"at all times","ipa":"","meaning":"항상, 언제나","example":"Keep your seatbelt fastened at all times during the flight.","deck":"vocab"},{"id":1807,"word":"in the end","ipa":"","meaning":"마침내, 마지막에 가서는, 결국","example":"In the end, everything worked out just fine.","deck":"vocab"},{"id":1808,"word":"be sure to ~","ipa":"","meaning":"반드시 ~하다 <주로 명령문으로 씀>","example":"Be sure to lock the door before you leave.","deck":"vocab"},{"id":1809,"word":"into","ipa":"/ˈɪntuː/","meaning":"~에 열중하여, ~에 관심을 가지고, ~에 빠져","example":"My son is really into dinosaurs these days.","deck":"vocab"},{"id":1810,"word":"nothing but","ipa":"","meaning":"오직, 단지~일 뿐인","example":"He has given me nothing but trouble since Monday.","deck":"vocab"},{"id":1811,"word":"see ~ as ~","ipa":"","meaning":"~을 ~로 간주하다, ~을 ~로 보다","example":"Many people see her as a natural leader.","deck":"vocab"},{"id":1812,"word":"a bunch of","ipa":"","meaning":"(수나 양이) 많은","example":"She bought a bunch of flowers for her mother.","deck":"vocab"},{"id":1813,"word":"have an impact","ipa":"","meaning":"(~에) 영향을 끼치다, 영향을 주다","example":"Your kind words really had an impact on me.","deck":"vocab"},{"id":1814,"word":"fall off","ipa":"","meaning":"~에서 떨어지다, 낙하하다","example":"Be careful not to fall off the ladder.","deck":"vocab"},{"id":1815,"word":"feel like","ipa":"","meaning":"~한 느낌이 있다","example":"I feel like taking a long walk tonight.","deck":"vocab"},{"id":1816,"word":"fit in","ipa":"","meaning":"(자연스럽게) (~와) 어울리다, 맞다","example":"The new student quickly fit in with her classmates.","deck":"vocab"},{"id":1817,"word":"for sure","ipa":"","meaning":"(의심할 여지없이) 확실히, 틀림없이","example":"I will finish the report by Friday for sure.","deck":"vocab"},{"id":1818,"word":"get along","ipa":"","meaning":"사이좋게 지내다","example":"The two brothers get along really well now.","deck":"vocab"},{"id":1819,"word":"pain","ipa":"/peɪn/","meaning":"(정신적) 고통","example":"The pain of losing a friend never fully disappears.","deck":"vocab"},{"id":1820,"word":"prank","ipa":"/præŋk/","meaning":"(농담으로 하는) 장난","example":"The kids played a harmless prank on their teacher.","deck":"vocab"},{"id":1821,"word":"in a way","ipa":"","meaning":"어떤 면에서는, 어느 정도는","example":"In a way, failing that test taught me a lot.","deck":"vocab"},{"id":1822,"word":"if it were not for","ipa":"","meaning":"~이 없다면, ~이 아니라면 <현재 상황에 대한 가정>","example":"If it were not for your help, I would have failed.","deck":"vocab"},{"id":1823,"word":"order ~ around","ipa":"","meaning":"~에게 이래라저래라하다","example":"Stop trying to order me around all the time.","deck":"vocab"},{"id":1824,"word":"get to","ipa":"","meaning":"(일, 주제 등을) ~을 다루다, ~에 이르다","example":"We didn't get to the last topic during the meeting.","deck":"vocab"},{"id":1825,"word":"get to","ipa":"","meaning":"~을 괴롭히다, 못살게 굴다","example":"Don't let his rude comments get to you.","deck":"vocab"},{"id":1826,"word":"virtue","ipa":"/ˈvɜːrtʃuː/","meaning":"미덕, 덕목","example":"Patience is a virtue that few people truly master.","deck":"vocab"},{"id":1827,"word":"outbreak","ipa":"/ˈaʊtbreɪk/","meaning":"(전쟁, 전염병 등의) 발생, 발발","example":"The outbreak of the disease spread quickly through the town.","deck":"vocab"},{"id":1828,"word":"pick ~ up","ipa":"","meaning":"~을 알게 되다, ~을 익히게 되다","example":"I picked up some Spanish while living in Mexico.","deck":"vocab"},{"id":1829,"word":"stumble","ipa":"/ˈstʌmbəl/","meaning":"발이 걸리다, 발을 헛디디다","example":"She stumbled over a rock on the dark path.","deck":"vocab"},{"id":1830,"word":"stumble","ipa":"/ˈstʌmbəl/","meaning":"잘못, 실수","example":"One small stumble should not ruin your whole career.","deck":"vocab"},{"id":1831,"word":"other than ~","ipa":"","meaning":"~외에","example":"I have no plans this weekend other than resting.","deck":"vocab"},{"id":1832,"word":"means","ipa":"/miːnz/","meaning":"수단, 방법, 방도","example":"We must find a better means of communication.","deck":"vocab"},{"id":1833,"word":"in life","ipa":"","meaning":"생전에, 목숨이 있는 동안에, 이승에서","example":"He accomplished so much in life before he passed.","deck":"vocab"},{"id":1834,"word":"in terms of ~","ipa":"","meaning":"~ 면에서, ~에 관해서는","example":"In terms of price, this option is the best.","deck":"vocab"},{"id":1835,"word":"honor","ipa":"/ˈɑːnər/","meaning":"~에게 경의를 표하다, 예우하다, 기리다","example":"The city built a statue to honor the fallen soldiers.","deck":"vocab"},{"id":1836,"word":"might","ipa":"/maɪt/","meaning":"~할 수도 있다, ~일지도 모른다, ~이었을지도 모른다","example":"It might rain later, so bring an umbrella.","deck":"vocab"},{"id":1837,"word":"within","ipa":"/wɪˈðɪn/","meaning":"(범위, 한계) 내에, 안에","example":"Please return the form within three business days.","deck":"vocab"},{"id":1838,"word":"sip","ipa":"/sɪp/","meaning":"(아주 적은 양의) 한 모금","example":"She took a small sip of the hot coffee.","deck":"vocab"},{"id":1839,"word":"console","ipa":"/kənˈsoʊl/","meaning":"위로하다, 위안을 주다","example":"He tried to console his friend after the loss.","deck":"vocab"},{"id":1840,"word":"no-brainer","ipa":"/ˌnoʊˈbreɪnər/","meaning":"쉬운 문제, 쉬운 결정","example":"Choosing the cheaper flight was a total no-brainer.","deck":"vocab"},{"id":1841,"word":"torn","ipa":"/tɔːrn/","meaning":"(~ 사이에서) 결정하지 못하고 있는, 고민하고 있는","example":"I was torn between staying home and going out.","deck":"vocab"},{"id":1842,"word":"yet","ipa":"/jet/","meaning":"(의문문에서) 이제, 지금쯤은","example":"Has the mail arrived yet this morning?","deck":"vocab"},{"id":1843,"word":"should","ipa":"/ʃʊd/","meaning":"~해야겠다, ~하면 좋겠다","example":"I should get going before it gets too late.","deck":"vocab"},{"id":1844,"word":"bound","ipa":"/baʊnd/","meaning":"(법, 의무상) 얽매인, ~해야 하는","example":"The company is legally bound to honor the contract.","deck":"vocab"},{"id":1845,"word":"sue","ipa":"/suː/","meaning":"고소하다, 소송을 제기하다","example":"They threatened to sue the company for damages.","deck":"vocab"},{"id":1846,"word":"get in","ipa":"","meaning":"합격하다, 입학하다, 입사하다","example":"He finally got in to Harvard last spring.","deck":"vocab"},{"id":1847,"word":"pull up","ipa":"","meaning":"(차량, 운전자가) 멈추다, 서다","example":"A taxi pulled up right in front of the hotel.","deck":"vocab"},{"id":1848,"word":"temper","ipa":"/ˈtempər/","meaning":"(쉽게 화를 내는) 성질, 성미","example":"He has quite a temper when things go wrong.","deck":"vocab"},{"id":1849,"word":"lack","ipa":"/læk/","meaning":"~이 없다, ~이 부족하다 <타동사>","example":"The plan lacks the details we really need.","deck":"vocab"},{"id":1850,"word":"sufficient","ipa":"/səˈfɪʃənt/","meaning":"충분한","example":"We have sufficient food to last the whole week.","deck":"vocab"},{"id":1851,"word":"suffice","ipa":"/səˈfaɪs/","meaning":"충분하다","example":"A simple apology will suffice this time.","deck":"vocab"},{"id":1852,"word":"hold up","ipa":"","meaning":"~을 올리다, ~을 들어 올리다","example":"She held up the trophy for everyone to see.","deck":"vocab"},{"id":1853,"word":"popularity","ipa":"/ˌpɑːpjəˈlærəti/","meaning":"인기","example":"The show's popularity grew rapidly over the years.","deck":"vocab"},{"id":1854,"word":"the other day","ipa":"","meaning":"일전에, 며칠 전에","example":"I ran into your sister the other day downtown.","deck":"vocab"},{"id":1855,"word":"earn","ipa":"/ɜːrn/","meaning":"얻다, 받다, 획득하다","example":"She worked hard to earn everyone's respect.","deck":"vocab"},{"id":1856,"word":"taste","ipa":"/teɪst/","meaning":"(~에 대한) 취향, 기호","example":"He has excellent taste in music and art.","deck":"vocab"},{"id":1857,"word":"prayer","ipa":"/preər/","meaning":"기도 내용, 기도문, 기도 제목 <셀 수 있는 명사>","example":"She whispered a quiet prayer before the exam.","deck":"vocab"},{"id":1858,"word":"grasshopper","ipa":"/ˈɡræsˌhɑːpər/","meaning":"메뚜기","example":"A green grasshopper jumped across the garden path.","deck":"vocab"},{"id":1859,"word":"might want to","ipa":"","meaning":"~하는 게 더 좋다 <권유를 나타냄>","example":"You might want to check the weather before leaving.","deck":"vocab"},{"id":1860,"word":"make-up","ipa":"/ˈmeɪkʌp/","meaning":"화장품, 화장, 분장","example":"She rarely wears make-up on the weekends.","deck":"vocab"},{"id":1861,"word":"unlike","ipa":"/ʌnˈlaɪk/","meaning":"~와는 달리","example":"Unlike her sister, she loves cold weather.","deck":"vocab"},{"id":1862,"word":"put ~ on","ipa":"","meaning":"(얼굴, 피부 등에) ~을 바르다","example":"Don't forget to put sunscreen on before the beach.","deck":"vocab"},{"id":1863,"word":"why would","ipa":"","meaning":"~가 뭐하러 ~하겠어? <주로 why would I ~ 형태로 쓰임>","example":"Why would I lie to you about something so small?","deck":"vocab"},{"id":1864,"word":"massive","ipa":"/ˈmæsɪv/","meaning":"엄청난, 대량의, 대규모의, 거대한","example":"They built a massive stadium near the river.","deck":"vocab"},{"id":1865,"word":"out front","ipa":"","meaning":"(건물의) 입구 쪽에","example":"The car is parked out front waiting for you.","deck":"vocab"},{"id":1866,"word":"messy","ipa":"/ˈmesi/","meaning":"지저분한, 엉망인","example":"His desk is always messy and covered in papers.","deck":"vocab"},{"id":1867,"word":"come by","ipa":"","meaning":"(누구를 보러) 잠깐 들르다","example":"Feel free to come by my office anytime tomorrow.","deck":"vocab"},{"id":1868,"word":"no matter","ipa":"","meaning":"~와는 상관없이 <no matter + what/how/when/who 등과 함께 씀>","example":"No matter what happens, I will support you.","deck":"vocab"},{"id":1869,"word":"determination","ipa":"/dɪˌtɜːrmɪˈneɪʃən/","meaning":"결의","example":"Her determination to succeed inspired the whole team.","deck":"vocab"},{"id":1870,"word":"festive","ipa":"/ˈfestɪv/","meaning":"축제 분위기가 나는, 명절 기분의, 즐거운, 들뜬","example":"The whole street had a festive atmosphere last night.","deck":"vocab"},{"id":1871,"word":"would say","ipa":"","meaning":"~인 것 같아 <소극적인 의사 표현 또는 권유를 나타냄>","example":"I would say this is the best option we have.","deck":"vocab"},{"id":1872,"word":"adjust","ipa":"/əˈdʒʌst/","meaning":"(약간) 조정하다, 조절하다","example":"Please adjust the volume a little lower.","deck":"vocab"},{"id":1873,"word":"adjust","ipa":"/əˈdʒʌst/","meaning":"(~에) 적응하다","example":"It took her months to adjust to the new city.","deck":"vocab"},{"id":1874,"word":"neighborhood","ipa":"/ˈneɪbərˌhʊd/","meaning":"이웃, 인근, 근처","example":"They just moved into a quiet neighborhood nearby.","deck":"vocab"},{"id":1875,"word":"mean ~ by ~","ipa":"","meaning":"~을 ~라는 의미로 말하다, ~을 ~라는 뜻으로 말하다","example":"What do you mean by that remark?","deck":"vocab"},{"id":1876,"word":"even if","ipa":"","meaning":"설령 ~한다고 해도, 가령 ~이라 할지라도","example":"I will go even if it rains all day.","deck":"vocab"},{"id":1877,"word":"stiff","ipa":"/stɪf/","meaning":"(근육이) 걸리는, 뻐근한","example":"My neck feels stiff after sleeping wrong.","deck":"vocab"},{"id":1878,"word":"what have you been up to","ipa":"","meaning":"어떻게 지냈어?","example":"Hey, what have you been up to lately?","deck":"vocab"},{"id":1879,"word":"get lost","ipa":"","meaning":"길을 잃다","example":"We got lost trying to find the old temple.","deck":"vocab"},{"id":1880,"word":"solely","ipa":"/ˈsoʊlli/","meaning":"오직, 오로지, 단지, 단독으로, ~만","example":"The decision rests solely on your shoulders.","deck":"vocab"},{"id":1881,"word":"appealing","ipa":"/əˈpiːlɪŋ/","meaning":"매력적인, 흥미로운","example":"The idea of a beach vacation sounds very appealing.","deck":"vocab"},{"id":1882,"word":"utterly","ipa":"/ˈʌtərli/","meaning":"완전히, 순전히, 아주, 전혀","example":"I was utterly exhausted after the long hike.","deck":"vocab"},{"id":1883,"word":"proposition","ipa":"/ˌprɑːpəˈzɪʃən/","meaning":"(특히 사업상의) 제의, 제안","example":"He made me an interesting business proposition.","deck":"vocab"},{"id":1884,"word":"proposition","ipa":"/ˌprɑːpəˈzɪʃən/","meaning":"명제, 진술 <격식>","example":"The proposition that all men are equal is powerful.","deck":"vocab"},{"id":1885,"word":"proposition","ipa":"/ˌprɑːpəˈzɪʃən/","meaning":"~에게 제안하다","example":"She propositioned the investors with a bold plan.","deck":"vocab"},{"id":1886,"word":"rest on ~","ipa":"","meaning":"~에 달려 있다, ~에 의지하다","example":"The company's future rests on this single deal.","deck":"vocab"},{"id":1887,"word":"perceive","ipa":"/pərˈsiːv/","meaning":"(~을 ~로) 여기다, 인식하다","example":"Many perceive him as a strict but fair boss.","deck":"vocab"},{"id":1888,"word":"perceive","ipa":"/pərˈsiːv/","meaning":"감지하다, 인지하다","example":"Dogs can perceive sounds humans cannot hear.","deck":"vocab"},{"id":1889,"word":"skeptical","ipa":"/ˈskeptɪkəl/","meaning":"의심 많은, 회의적인, 회의를 나타내는, 회의론자 같은, 신용하지 않는","example":"She remained skeptical about his sudden change of heart.","deck":"vocab"},{"id":1890,"word":"salient","ipa":"/ˈseɪliənt/","meaning":"가장 중요한, 핵심적인, 가장 두드러진, 현저한","example":"Let me highlight the most salient points of the plan.","deck":"vocab"},{"id":1891,"word":"startle","ipa":"/ˈstɑːrtəl/","meaning":"깜짝 놀라게 하다","example":"The loud noise startled the sleeping baby.","deck":"vocab"},{"id":1892,"word":"expound","ipa":"/ɪkˈspaʊnd/","meaning":"자세히 설명하다 <격식>","example":"The professor began to expound his new theory.","deck":"vocab"},{"id":1893,"word":"unfazed","ipa":"/ʌnˈfeɪzd/","meaning":"동요하지 않는, 당황하지 않은","example":"She stayed completely unfazed by the criticism.","deck":"vocab"},{"id":1894,"word":"acquaintance","ipa":"/əˈkweɪntəns/","meaning":"아는 사람, 지인","example":"He is just an acquaintance, not a close friend.","deck":"vocab"},{"id":1895,"word":"Martian","ipa":"/ˈmɑːrʃən/","meaning":"화성인","example":"The movie imagines a lonely Martian exploring the desert.","deck":"vocab"},{"id":1896,"word":"ritual","ipa":"/ˈrɪtʃuəl/","meaning":"의례적인 일, 의식과 같은 일","example":"Morning coffee is a daily ritual for many people.","deck":"vocab"},{"id":1897,"word":"tens of thousands","ipa":"","meaning":"수만(數萬)","example":"Tens of thousands of fans filled the stadium.","deck":"vocab"},{"id":1898,"word":"Europe","ipa":"/ˈjʊrəp/","meaning":"유럽 <영국에서는 영국을 제외한 유럽 대륙을 가리키는 의미로도 씀>","example":"They spent the summer traveling across Europe.","deck":"vocab"},{"id":1899,"word":"lately","ipa":"/ˈleɪtli/","meaning":"최근에, 얼마 전에","example":"I haven't seen much of him lately.","deck":"vocab"},{"id":1900,"word":"grab","ipa":"/ɡræb/","meaning":"~을 간단히 먹다 <빠르고 간단하게 먹는다는 뜻>","example":"Let's grab a quick lunch before the meeting.","deck":"vocab"},{"id":1901,"word":"grab","ipa":"/ɡræb/","meaning":"붙잡다, 움켜쥐다, 움켜잡다","example":"She grabbed the railing to keep from falling.","deck":"vocab"},{"id":1902,"word":"make fun of ~","ipa":"","meaning":"~을 놀리다, 비웃다","example":"Please don't make fun of his accent.","deck":"vocab"},{"id":1903,"word":"most of the time","ipa":"","meaning":"대개는","example":"Most of the time, he studies at the library.","deck":"vocab"},{"id":1904,"word":"tariff","ipa":"/ˈtærɪf/","meaning":"관세","example":"The government raised the tariff on imported steel.","deck":"vocab"},{"id":1905,"word":"now","ipa":"/naʊ/","meaning":"이제 ~이니까","example":"Now that you're here, we can finally start.","deck":"vocab"},{"id":1906,"word":"on the fly","ipa":"","meaning":"(사전 계획이나 깊은 고민 없이) 빨리, 즉석에서","example":"We had to change the plan on the fly.","deck":"vocab"},{"id":1907,"word":"cut to the chase","ipa":"","meaning":"바로 본론으로 들어가다","example":"Let's cut to the chase and discuss the budget.","deck":"vocab"},{"id":1908,"word":"stuck","ipa":"/stʌk/","meaning":"움직일 수 없는, 꼼짝 못하는, 갇힌, 빠져나갈 수가 없는","example":"The car got stuck in the thick mud.","deck":"vocab"},{"id":1909,"word":"debit card","ipa":"/ˈdebɪt ˌkɑːrd/","meaning":"체크카드, 직불 카드 <대금 결제 시, 결제 금액이 카드 소유자의 계좌에서 즉시 인출되는 카드>","example":"She paid for groceries with her debit card.","deck":"vocab"},{"id":1910,"word":"with","ipa":"/wɪð/","meaning":"~ 한 채로, ~ 하면서, ~하게, ~ 있게","example":"He walked in with his coat still on.","deck":"vocab"},{"id":1911,"word":"unstressed","ipa":"/ʌnˈstrest/","meaning":"(음절이) 강세가 없는 <음성학 용어>","example":"The second syllable is unstressed in that word.","deck":"vocab"},{"id":1912,"word":"syllable","ipa":"/ˈsɪləbəl/","meaning":"음절","example":"The word 'banana' has three syllables.","deck":"vocab"},{"id":1913,"word":"only to ~","ipa":"","meaning":"(결국) ~하게 되다, ~하고 말다, ~할 뿐이다 <주로 예상 밖의 결과를 나타냄>","example":"He rushed to the station, only to miss the train.","deck":"vocab"},{"id":1914,"word":"go through ~","ipa":"","meaning":"~을 겪다","example":"She had to go through a lot of pain last year.","deck":"vocab"},{"id":1915,"word":"nuts","ipa":"/nʌts/","meaning":"~에 미친, ~한테 푹 빠진, ~에 열광하여","example":"My little sister is nuts about that pop band.","deck":"vocab"},{"id":1916,"word":"slam","ipa":"/slæm/","meaning":"쾅 닫다","example":"He slammed the door in anger and left.","deck":"vocab"},{"id":1917,"word":"sob","ipa":"/sɑːb/","meaning":"흐느끼다 <자동사>","example":"She began to sob quietly during the sad film.","deck":"vocab"},{"id":1918,"word":"commitment","ipa":"/kəˈmɪtmənt/","meaning":"진지한 연애, 진지한 연애의 의지, 한 사람에게만 헌신함","example":"He isn't ready for a serious commitment yet.","deck":"vocab"},{"id":1919,"word":"work out","ipa":"","meaning":"(일이) 풀리다, 잘 풀리다","example":"Don't worry, everything will work out in the end.","deck":"vocab"},{"id":1920,"word":"work out","ipa":"","meaning":"(몸 관리를 위해) 운동하다","example":"I try to work out at the gym three times a week.","deck":"vocab"},{"id":1921,"word":"inappropriate","ipa":"/ˌɪnəˈproʊpriət/","meaning":"부적절한, 부적합한","example":"His joke was completely inappropriate for the occasion.","deck":"vocab"},{"id":1922,"word":"starve","ipa":"/stɑːrv/","meaning":"굶주리다, 굶어 죽다","example":"Without rain, the crops failed and people began to starve.","deck":"vocab"},{"id":1923,"word":"permit","ipa":"/pərˈmɪt/","meaning":"가능하게 하다, 허락하다","example":"The rules do not permit pets inside the building.","deck":"vocab"},{"id":1924,"word":"wish","ipa":"/wɪʃ/","meaning":"~이면 좋겠는데, ~면 좋을텐데 <현실은 그렇지 못하거나 실현 가능성이 낮을 때 씀>","example":"I wish I could speak French fluently.","deck":"vocab"},{"id":1925,"word":"get rid of ~","ipa":"","meaning":"~을 없애다, ~을 처리하다","example":"It's time to get rid of these old clothes.","deck":"vocab"},{"id":1926,"word":"should not have","ipa":"","meaning":"~하지 말았어야 했다 <결국은 그렇게 해서 후회된다는 뜻>","example":"I should not have eaten so much cake.","deck":"vocab"},{"id":1927,"word":"ever","ipa":"/ˈevər/","meaning":"언젠가, 앞으로, 한 번이라도","example":"Have you ever visited Japan before?","deck":"vocab"},{"id":1928,"word":"have ~ in common","ipa":"","meaning":"(~와) ~한 공통점이 있다, 공통으로 가지다","example":"The two friends have a lot in common.","deck":"vocab"},{"id":1929,"word":"stubborn","ipa":"/ˈstʌbərn/","meaning":"고집이 센, 완고한, 완강한","example":"My grandfather is too stubborn to ask for help.","deck":"vocab"},{"id":1930,"word":"dine out","ipa":"","meaning":"(식당이나 누구의 집에서) 외식을 하다","example":"We usually dine out on Friday evenings.","deck":"vocab"},{"id":1931,"word":"break in","ipa":"","meaning":"(건물에) 침입하다","example":"Thieves tried to break in through the back window.","deck":"vocab"},{"id":1932,"word":"keep ~ from ~","ipa":"","meaning":"~가 ~하지 못하게 하다","example":"The heavy rain kept us from going outside.","deck":"vocab"},{"id":1933,"word":"by all means","ipa":"","meaning":"물론이죠, 당연히 그렇게 하셔도 돼요, 아무렴, 좋고말고","example":"By all means, take a seat and make yourself comfortable.","deck":"vocab"},{"id":1934,"word":"suppose","ipa":"/səˈpoʊz/","meaning":"추정하다, 추측하다, 생각하다","example":"I suppose you're right about the whole situation.","deck":"vocab"},{"id":1935,"word":"imply","ipa":"/ɪmˈplaɪ/","meaning":"암시하다, 넌지시 비치다","example":"Are you trying to imply that I was wrong?","deck":"vocab"},{"id":1936,"word":"argue","ipa":"/ˈɑːrɡjuː/","meaning":"(이유를 들어) 주장하다, 설득하다, 논증하다","example":"She argued that the policy was unfair to workers.","deck":"vocab"},{"id":1937,"word":"ensure","ipa":"/ɪnˈʃʊr/","meaning":"반드시 ~하게 하다, 보장하다","example":"Please ensure the door is locked before leaving.","deck":"vocab"},{"id":1938,"word":"wear off","ipa":"","meaning":"없어지다, 효과가 사라지다, 강도가 약해지다","example":"The effect of the medicine will wear off soon.","deck":"vocab"},{"id":1939,"word":"painkiller","ipa":"/ˈpeɪnˌkɪlər/","meaning":"진통제","example":"She took a painkiller to ease her headache.","deck":"vocab"},{"id":1940,"word":"artifact","ipa":"/ˈɑːrtɪˌfækt/","meaning":"(자연물이 아닌) 인공물, 유물 <특히 과거 인류가 남긴 역사적 유물을 가리킴>","example":"The museum displayed an ancient artifact from Egypt.","deck":"vocab"},{"id":1941,"word":"ever since","ipa":"","meaning":"~이후로 줄곧","example":"We've been friends ever since we were children.","deck":"vocab"},{"id":1942,"word":"note","ipa":"/noʊt/","meaning":"기색, 분위기, 어조","example":"There was a note of sadness in her voice.","deck":"vocab"},{"id":1943,"word":"note","ipa":"/noʊt/","meaning":"음 <음악 용어>","example":"She played a single high note on the piano.","deck":"vocab"},{"id":1944,"word":"though","ipa":"/ðoʊ/","meaning":"그렇지만, 하지만 <주로 문장 끝에 씀>","example":"It's cold outside. I don't mind, though.","deck":"vocab"},{"id":1945,"word":"though","ipa":"/ðoʊ/","meaning":"하지만, 그래도 <though의 앞 또는 뒤에 comma를 써서 씀>","example":"The plan, though, was far from perfect.","deck":"vocab"},{"id":1946,"word":"statue","ipa":"/ˈstætʃuː/","meaning":"조각상","example":"A bronze statue stands in the center of the park.","deck":"vocab"},{"id":1947,"word":"legendary","ipa":"/ˈledʒənˌderi/","meaning":"전설적인, 아주 유명한","example":"He was a legendary guitarist admired by millions.","deck":"vocab"},{"id":1948,"word":"rethink","ipa":"/ˌriːˈθɪŋk/","meaning":"다시 생각하다, 재고하다","example":"The bad results made us rethink our strategy.","deck":"vocab"},{"id":1949,"word":"mess with ~","ipa":"","meaning":"~을 건드리다, ~을 함부로 대하다, ~와 싸우다, ~와 한판 붙다","example":"You really shouldn't mess with him when he's angry.","deck":"vocab"},{"id":1950,"word":"begone","ipa":"/bɪˈɡɔːn/","meaning":"썩 꺼져, 썩 꺼져 라고 말하다 <고어>","example":"'Begone!' the old wizard shouted at the intruder.","deck":"vocab"},{"id":1951,"word":"make it","ipa":"","meaning":"가다, 참석하다","example":"Sorry, I can't make it to the party tonight.","deck":"vocab"},{"id":1952,"word":"contagious","ipa":"/kənˈteɪdʒəs/","meaning":"(질병이 접촉을 통해) 전염되는, 전염성의","example":"The flu is highly contagious during the winter.","deck":"vocab"},{"id":1953,"word":"territory","ipa":"/ˈterəˌtɔːri/","meaning":"(한 국가, 통치자가 다스리는) 지역, 영토","example":"The tribe defended its territory for centuries.","deck":"vocab"},{"id":1954,"word":"limit","ipa":"/ˈlɪmɪt/","meaning":"한계, 한계점, 한도, 한계치","example":"There is a strict limit on how much you can borrow.","deck":"vocab"},{"id":1955,"word":"compare","ipa":"/kəmˈper/","meaning":"(~와) 비교하다","example":"It's unfair to compare the two very different players.","deck":"vocab"},{"id":1956,"word":"bet","ipa":"/bet/","meaning":"~라고 장담하다, 확실히 ~라고 보다, 확신하다 <어떤 일이 일어날 것을 확신할 때 씀>","example":"I bet she will win the race easily.","deck":"vocab"},{"id":1957,"word":"grand","ipa":"/ɡrænd/","meaning":"천 달러, 천 파운드","example":"The used car cost him about five grand.","deck":"vocab"},{"id":1958,"word":"do right by ~","ipa":"","meaning":"~를 공정하게 대하다","example":"A good leader always tries to do right by the team.","deck":"vocab"},{"id":1959,"word":"secure","ipa":"/sɪˈkjʊr/","meaning":"(해, 영향을 입지 않고) 안전한","example":"Keep your passwords secure from strangers.","deck":"vocab"},{"id":1960,"word":"at a time","ipa":"","meaning":"한 번에","example":"Please enter the room one person at a time.","deck":"vocab"},{"id":1961,"word":"back","ipa":"/bæk/","meaning":"과거로, 거슬러, 예전에","example":"This tradition dates back many centuries.","deck":"vocab"},{"id":1962,"word":"protest","ipa":"/prəˈtest/","meaning":"시위하다, 항의하다 <자동사>","example":"Thousands gathered to protest against the new law.","deck":"vocab"},{"id":1963,"word":"sound","ipa":"/saʊnd/","meaning":"~인 것 같다, ~하게 들리다","example":"Your idea sounds great to me.","deck":"vocab"},{"id":1964,"word":"sound","ipa":"/saʊnd/","meaning":"괜찮은, 잘 된, 잘 하는","example":"The house was old but built on a sound foundation.","deck":"vocab"},{"id":1965,"word":"lefty","ipa":"/ˈlefti/","meaning":"(정치적 성향이) 좌파, 좌익인 사람 <비격식적인 표현. 정치적 성향을 나타냄>","example":"He's a proud lefty who supports higher taxes.","deck":"vocab"},{"id":1966,"word":"get off work","ipa":"","meaning":"(직장에서) 퇴근하다","example":"I usually get off work around six in the evening.","deck":"vocab"},{"id":1967,"word":"way","ipa":"/weɪ/","meaning":"아주 멀리, 큰 차이로, 훨씬 <전치사, 부사, 비교급 형용사와 함께 씀>","example":"This movie is way better than the first one.","deck":"vocab"},{"id":1968,"word":"figure ~ out","ipa":"","meaning":"~를 알아내다, ~을 생각해 내다, ~를 풀다","example":"I couldn't figure the problem out on my own.","deck":"vocab"},{"id":1969,"word":"go on a trip","ipa":"","meaning":"여행을 떠나다","example":"Let's go on a trip to the mountains this summer.","deck":"vocab"},{"id":1970,"word":"border","ipa":"/ˈbɔːrdər/","meaning":"국경, 국경 지역","example":"They crossed the border early in the morning.","deck":"vocab"},{"id":1971,"word":"end up","ipa":"","meaning":"결국 ~하게 되다 <동사의 현재 분사형과 함께 쓰임>","example":"We ended up staying at home all weekend.","deck":"vocab"},{"id":1972,"word":"eloquent","ipa":"/ˈeləkwənt/","meaning":"말을 잘 하는, 유창한, 달변의","example":"She gave an eloquent speech that moved the audience.","deck":"vocab"},{"id":1973,"word":"fool","ipa":"/fuːl/","meaning":"속이다, 기만하다","example":"You can't fool me with that old trick.","deck":"vocab"},{"id":1974,"word":"settle in","ipa":"","meaning":"(새 집이나 직장 등에 자리를 잡고) 적응하다","example":"It took a while to settle in at the new job.","deck":"vocab"},{"id":1975,"word":"sick","ipa":"/sɪk/","meaning":"(~가) 지긋지긋한, 넌더리 나는, 신물나는","example":"I'm sick of hearing the same excuses every day.","deck":"vocab"},{"id":1976,"word":"not much of a ~","ipa":"","meaning":"대단한 ~이 아닌, 좋은 ~이 아닌","example":"I'm not much of a cook, honestly.","deck":"vocab"},{"id":1977,"word":"you guys","ipa":"","meaning":"너희들","example":"Are you guys coming to the game tonight?","deck":"vocab"},{"id":1978,"word":"hasty","ipa":"/ˈheɪsti/","meaning":"(사람이) 성급한, 경솔한","example":"Don't make a hasty decision you might regret.","deck":"vocab"},{"id":1979,"word":"come over","ipa":"","meaning":"(~에) 들르다","example":"Why don't you come over for dinner tonight?","deck":"vocab"},{"id":1980,"word":"in a bit","ipa":"","meaning":"잠시 후에, 좀 있다가","example":"I'll call you back in a bit, okay?","deck":"vocab"},{"id":1981,"word":"significance","ipa":"/sɪɡˈnɪfɪkəns/","meaning":"의미, 특별한 의미","example":"The discovery has great scientific significance.","deck":"vocab"},{"id":1982,"word":"insecure","ipa":"/ˌɪnsɪˈkjʊr/","meaning":"자신이 없는","example":"He felt insecure about speaking in public.","deck":"vocab"},{"id":1983,"word":"that figures","ipa":"","meaning":"그럴 줄 알았다","example":"He forgot again? Well, that figures.","deck":"vocab"},{"id":1984,"word":"hung over","ipa":"","meaning":"숙취 상태에 있는","example":"She was hung over after the wedding party.","deck":"vocab"},{"id":1985,"word":"go","ipa":"/ɡoʊ/","meaning":"~하러 가다, ~을 떠나다, ~에 나서다","example":"Let's go grab something to eat.","deck":"vocab"},{"id":1986,"word":"do the dishes","ipa":"","meaning":"설거지를 하다","example":"It's your turn to do the dishes tonight.","deck":"vocab"},{"id":1987,"word":"have to","ipa":"","meaning":"틀림없이 ~할 것이다, 틀림없이 ~일 것이다","example":"You look pale; you have to be exhausted.","deck":"vocab"},{"id":1988,"word":"scam","ipa":"/skæm/","meaning":"신용 사기","example":"That email was an obvious phishing scam.","deck":"vocab"},{"id":1989,"word":"gullible","ipa":"/ˈɡʌləbəl/","meaning":"남을 잘 믿는, 잘 속아 넘어가는","example":"He's so gullible that he believes every rumor.","deck":"vocab"},{"id":1990,"word":"pick up on ~","ipa":"","meaning":"~을 알아차리다","example":"She quickly picked up on the awkward mood.","deck":"vocab"},{"id":1991,"word":"come up with ~","ipa":"","meaning":"찾아내다, 내놓다, 생각해 내다","example":"We need to come up with a better plan.","deck":"vocab"},{"id":1992,"word":"fertility","ipa":"/fərˈtɪləti/","meaning":"비옥함","example":"The river's flooding improved the soil's fertility.","deck":"vocab"},{"id":1993,"word":"acne","ipa":"/ˈækni/","meaning":"여드름 <여드름이 많고 트러블이 있는 피부 상태를 뜻함>","example":"Many teenagers struggle with acne during puberty.","deck":"vocab"},{"id":1994,"word":"foothold","ipa":"/ˈfʊtˌhoʊld/","meaning":"(등산 때) 발 디딜 곳","example":"The climber searched for a foothold on the cliff.","deck":"vocab"},{"id":1995,"word":"sublime","ipa":"/səˈblaɪm/","meaning":"장엄한, 숭고한","example":"The view from the summit was absolutely sublime.","deck":"vocab"},{"id":1996,"word":"bowel movement","ipa":"/ˈbaʊəl ˌmuːvmənt/","meaning":"배변","example":"The doctor asked about his daily bowel movement.","deck":"vocab"},{"id":1997,"word":"dweller","ipa":"/ˈdwelər/","meaning":"(특히 합성어에서) ~거주자, ~에 사는 동물","example":"A city dweller often misses the quiet countryside.","deck":"vocab"},{"id":1998,"word":"casually","ipa":"/ˈkæʒuəli/","meaning":"가볍게, 무심하게, 별생각 없이, 별거 아니라는 듯이 <실제로는 그렇지 않을 때도 씀>","example":"He mentioned the news casually, as if it were nothing.","deck":"vocab"},{"id":1999,"word":"constipation","ipa":"/ˌkɑːnstɪˈpeɪʃən/","meaning":"변비","example":"Drinking more water can help relieve constipation.","deck":"vocab"},{"id":2000,"word":"deference","ipa":"/ˈdefərəns/","meaning":"존중, 경의, 경의를 표하는 행동","example":"He bowed in deference to the elderly master.","deck":"vocab"},{"id":2001,"word":"arsonist","ipa":"/ˈɑːrsənɪst/","meaning":"방화범","example":"The arsonist set fire to three abandoned buildings downtown.","deck":"vocab"},{"id":2002,"word":"for some reason","ipa":"","meaning":"무슨 이유로, 어떤 까닭인지","example":"For some reason, she never answered any of my calls.","deck":"vocab"},{"id":2003,"word":"pre-eminent","ipa":"/priˈɛmɪnənt/","meaning":"출중한, 발군의 <격식 있는 표현>","example":"He is the pre-eminent scholar in the field of genetics.","deck":"vocab"},{"id":2004,"word":"carb","ipa":"/kɑːrb/","meaning":"탄수화물, 탄수화물 식품","example":"She avoids bread and pasta because they are high in carbs.","deck":"vocab"},{"id":2005,"word":"marginal","ipa":"/ˈmɑːrdʒɪnəl/","meaning":"주변부의, 주변적인 <사회의 주류나 중심에 속해있지 않다는 뜻>","example":"The policy only helped a marginal group of low-income families.","deck":"vocab"},{"id":2006,"word":"plagiarism","ipa":"/ˈpleɪdʒərɪzəm/","meaning":"표절","example":"The student was expelled after being caught for plagiarism.","deck":"vocab"},{"id":2007,"word":"tense","ipa":"/tɛns/","meaning":"(사람이) 긴장한, 신경이 날카로운","example":"She felt tense before her important job interview yesterday.","deck":"vocab"},{"id":2008,"word":"baffle","ipa":"/ˈbæfəl/","meaning":"당황스럽게 만들다, 전혀 이해하지 못하게 만들다","example":"The strange results continued to baffle the whole research team.","deck":"vocab"},{"id":2009,"word":"reticent","ipa":"/ˈrɛtɪsənt/","meaning":"말을 잘 안 하는, 말이 없는","example":"He was reticent about discussing his private family matters.","deck":"vocab"},{"id":2010,"word":"reversible","ipa":"/rɪˈvɜːrsəbəl/","meaning":"(변했던 것을 원상태로) 되돌릴 수 있는","example":"The early damage to the ecosystem is still reversible.","deck":"vocab"},{"id":2011,"word":"tempest","ipa":"/ˈtɛmpɪst/","meaning":"폭풍우, 거센 비바람 <문어체>","example":"The small ship was tossed violently by the raging tempest.","deck":"vocab"},{"id":2012,"word":"opiate","ipa":"/ˈoʊpiət/","meaning":"아편제, 아편이 든 약","example":"Doctors prescribed an opiate to ease his severe pain.","deck":"vocab"},{"id":2013,"word":"common denominator","ipa":"/ˌkɑːmən dɪˈnɑːmɪneɪtər/","meaning":"(집단 구성원들의) 공통점, 공통분모","example":"Ambition was the common denominator among all the successful founders.","deck":"vocab"},{"id":2014,"word":"deprive","ipa":"/dɪˈpraɪv/","meaning":"(사람에게서 물건을) 빼앗다","example":"The war deprived thousands of children of their homes.","deck":"vocab"},{"id":2015,"word":"suit yourself","ipa":"","meaning":"좋을 대로 해라, 하고 싶은 대로 해라 <보통 부정적인 어감>","example":"If you don't want to come, then suit yourself.","deck":"vocab"},{"id":2016,"word":"go on to ~","ipa":"","meaning":"곧이어 ~을 하다","example":"After college, she went on to start her own company.","deck":"vocab"},{"id":2017,"word":"absurd","ipa":"/əbˈsɜːrd/","meaning":"터무니없는, 어처구니없는","example":"It is absurd to blame him for the sudden storm.","deck":"vocab"},{"id":2018,"word":"have ~ to oneself","ipa":"","meaning":"~을 독점하다, 마음대로 하다","example":"With everyone gone, I had the whole house to myself.","deck":"vocab"},{"id":2019,"word":"stink","ipa":"/stɪŋk/","meaning":"악취가 풍기다, 냄새가 나다","example":"The garbage left outside began to stink in the summer heat.","deck":"vocab"},{"id":2020,"word":"valor","ipa":"/ˈvælər/","meaning":"(특히 전쟁터에서의) 용기, 용맹함 <문학적 표현>","example":"The soldier received a medal for his valor in battle.","deck":"vocab"},{"id":2021,"word":"censorship","ipa":"/ˈsɛnsərʃɪp/","meaning":"검열","example":"Many journalists protested against the government's strict censorship.","deck":"vocab"},{"id":2022,"word":"coagulate","ipa":"/koʊˈæɡjuleɪt/","meaning":"(액체가) 응고하다","example":"The blood will coagulate quickly to seal the wound.","deck":"vocab"},{"id":2023,"word":"ponder","ipa":"/ˈpɑːndər/","meaning":"숙고하다, 곰곰이 생각하다 <격식>","example":"She sat by the window to ponder her next big decision.","deck":"vocab"},{"id":2024,"word":"haul","ipa":"/hɔːl/","meaning":"획득한 것, 산 것, 벌어들인 것, 받은 것","example":"The thieves escaped with a huge haul of jewelry.","deck":"vocab"},{"id":2025,"word":"pliable","ipa":"/ˈplaɪəbəl/","meaning":"(사람이) 영향받기 쉬운, 순응적인","example":"Young children are pliable and easily shaped by their surroundings.","deck":"vocab"},{"id":2026,"word":"entourage","ipa":"/ˈɑːntʊrɑːʒ/","meaning":"(중요 인물의) 수행단, 수행원들","example":"The pop star arrived with a large entourage of assistants.","deck":"vocab"},{"id":2027,"word":"irritant","ipa":"/ˈɪrɪtənt/","meaning":"(피부를 따갑게 하거나 하는) 자극물 <전문 용어>","example":"This cheap soap acts as an irritant to sensitive skin.","deck":"vocab"},{"id":2028,"word":"mackerel","ipa":"/ˈmækərəl/","meaning":"고등어","example":"We grilled fresh mackerel for dinner by the seaside.","deck":"vocab"},{"id":2029,"word":"punctilious","ipa":"/pʌŋkˈtɪliəs/","meaning":"꼼꼼한, 세심한","example":"He is punctilious about following every rule in the manual.","deck":"vocab"},{"id":2030,"word":"juror","ipa":"/ˈdʒʊrər/","meaning":"(한 사람의) 배심원","example":"Each juror listened carefully to the lawyer's closing argument.","deck":"vocab"},{"id":2031,"word":"sway","ipa":"/sweɪ/","meaning":"(전후좌우로 천천히) 흔들리다","example":"The tall trees began to sway gently in the evening breeze.","deck":"vocab"},{"id":2032,"word":"sway","ipa":"/sweɪ/","meaning":"(마음을) 흔들다, 동요시키다","example":"His passionate speech managed to sway the undecided voters.","deck":"vocab"},{"id":2033,"word":"outrageous","ipa":"/aʊtˈreɪdʒəs/","meaning":"너무나 충격적인, 터무니없는","example":"The store charged an outrageous price for a simple coffee.","deck":"vocab"},{"id":2034,"word":"as a whole","ipa":"","meaning":"전체적으로, 전체로서","example":"The team performed well as a whole this season.","deck":"vocab"},{"id":2035,"word":"benign","ipa":"/bɪˈnaɪn/","meaning":"(종양, 질병 등이) 양성의 <의학 용어>","example":"The doctor confirmed that the tumor was completely benign.","deck":"vocab"},{"id":2036,"word":"on one's toes","ipa":"","meaning":"긴장을 늦추지 않는, 경계하는, 주의하는","example":"The surprise quizzes keep the students on their toes.","deck":"vocab"},{"id":2037,"word":"aggregate","ipa":"/ˈæɡrɪɡət/","meaning":"집합, 집합체","example":"The final score is an aggregate of both matches.","deck":"vocab"},{"id":2038,"word":"exert oneself","ipa":"","meaning":"있는 힘껏 노력하다, 있는 힘을 다하다","example":"You must exert yourself if you want to win this race.","deck":"vocab"},{"id":2039,"word":"cloud","ipa":"/klaʊd/","meaning":"(기억력, 판단력 등을) 흐리다","example":"Anger can cloud your judgment during important negotiations.","deck":"vocab"},{"id":2040,"word":"reunification","ipa":"/ˌriːjuːnɪfɪˈkeɪʃən/","meaning":"재통일, 재통합","example":"Many families still hope for the reunification of the country.","deck":"vocab"},{"id":2041,"word":"squabble","ipa":"/ˈskwɑːbəl/","meaning":"시시한 언쟁, 입씨름","example":"The children had a silly squabble over the last cookie.","deck":"vocab"},{"id":2042,"word":"outcast","ipa":"/ˈaʊtkæst/","meaning":"버림받은 사람, 따돌림받는 사람","example":"After the scandal, he felt like a social outcast.","deck":"vocab"},{"id":2043,"word":"burp","ipa":"/bɜːrp/","meaning":"트림","example":"The baby let out a loud burp after her bottle.","deck":"vocab"},{"id":2044,"word":"vague","ipa":"/veɪɡ/","meaning":"모호한, 애매한, 막연한","example":"His answer was too vague to be truly helpful.","deck":"vocab"},{"id":2045,"word":"vague","ipa":"/veɪɡ/","meaning":"흐릿한, 희미한","example":"I only have a vague memory of that childhood trip.","deck":"vocab"},{"id":2046,"word":"abate","ipa":"/əˈbeɪt/","meaning":"(강도가) 약해지다, 누그러지다, 잦아들다","example":"The storm finally began to abate near midnight.","deck":"vocab"},{"id":2047,"word":"delinquent","ipa":"/dɪˈlɪŋkwənt/","meaning":"(돈이) 연체된, 체납된 <금융 용어>","example":"The bank sent a warning about his delinquent loan payments.","deck":"vocab"},{"id":2048,"word":"lurch","ipa":"/lɜːrtʃ/","meaning":"(갑자기) 휘청하다, 휘청거리다","example":"The bus made the passengers lurch forward when it stopped.","deck":"vocab"},{"id":2049,"word":"yank","ipa":"/jæŋk/","meaning":"확 잡아당기다","example":"She had to yank the door hard to open it.","deck":"vocab"},{"id":2050,"word":"anthropological","ipa":"/ˌænθrəpəˈlɑːdʒɪkəl/","meaning":"인류학의, 인류학상의","example":"The museum displayed rare anthropological artifacts from ancient tribes.","deck":"vocab"},{"id":2051,"word":"felicity","ipa":"/fəˈlɪsɪti/","meaning":"아주 큰 행복, 강렬한 행복","example":"The newlyweds enjoyed a summer of pure felicity together.","deck":"vocab"},{"id":2052,"word":"count on ~","ipa":"","meaning":"~을 기대하다, 예상하다","example":"You can always count on her to keep a secret.","deck":"vocab"},{"id":2053,"word":"reconcile","ipa":"/ˈrɛkənsaɪl/","meaning":"(~을) 받아들이다","example":"He struggled to reconcile himself to the sudden loss.","deck":"vocab"},{"id":2054,"word":"courtesy","ipa":"/ˈkɜːrtəsi/","meaning":"예의바름, 공손함, 정중함","example":"She always treats her elders with great courtesy.","deck":"vocab"},{"id":2055,"word":"hallway","ipa":"/ˈhɔːlweɪ/","meaning":"복도 <주로 미국에서 쓰는 표현>","example":"They hung old family photos along the narrow hallway.","deck":"vocab"},{"id":2056,"word":"third degree","ipa":"/ˌθɜːrd dɪˈɡriː/","meaning":"엄한 심문, 고문 <자백을 받기 위해 신체적, 정신적 고통을 가하는 것>","example":"The detectives gave the suspect the third degree all night.","deck":"vocab"},{"id":2057,"word":"bottle ~ up","ipa":"","meaning":"(감정을 드러내지 않고) 억누르다, 묻어 두다","example":"Don't bottle up your anger; talk about your feelings.","deck":"vocab"},{"id":2058,"word":"long-standing","ipa":"/ˌlɔːŋˈstændɪŋ/","meaning":"오랜, 오래된, 오래 지속된","example":"They finally resolved their long-standing dispute over the land.","deck":"vocab"},{"id":2059,"word":"infertile","ipa":"/ɪnˈfɜːrtəl/","meaning":"(사람, 동물, 식물이) 불임의, 생식력이 없는","example":"The couple learned that one of them was infertile.","deck":"vocab"},{"id":2060,"word":"how much have ~ had to drink","ipa":"","meaning":"얼마나 마신거야?, 얼마나 마셨길래 그래?","example":"You can barely stand, so how much have you had to drink?","deck":"vocab"},{"id":2061,"word":"ride","ipa":"/raɪd/","meaning":"~에게 잔소리하다, ~을 괴롭히다 <미국 속어>","example":"The coach kept riding the rookie about his lazy footwork.","deck":"vocab"},{"id":2062,"word":"chalk ~ up to ~","ipa":"","meaning":"~을 ~ 때문으로 여기다","example":"We chalked the mistake up to his lack of experience.","deck":"vocab"},{"id":2063,"word":"nectar","ipa":"/ˈnɛktər/","meaning":"꽃꿀, 화밀 <꽃의 꿀샘에서 분비하는 꿀>","example":"Bees gather nectar from flowers to make sweet honey.","deck":"vocab"},{"id":2064,"word":"give ~ a hand","ipa":"","meaning":"도와주다","example":"Could you give me a hand with these heavy boxes?","deck":"vocab"},{"id":2065,"word":"mind-boggling","ipa":"/ˈmaɪndˌbɑːɡlɪŋ/","meaning":"대단히 놀라운, 믿기 어려운, 상상을 초월하는","example":"The sheer size of the universe is truly mind-boggling.","deck":"vocab"},{"id":2066,"word":"snob","ipa":"/snɑːb/","meaning":"속물 <사회적 지위가 인간의 가치에 영향을 미친다고 생각하는 사람>","example":"He is such a snob that he ignores ordinary people.","deck":"vocab"},{"id":2067,"word":"offensive","ipa":"/əˈfɛnsɪv/","meaning":"모욕적인, 불쾌한","example":"His rude joke was deeply offensive to the whole audience.","deck":"vocab"},{"id":2068,"word":"downright","ipa":"/ˈdaʊnraɪt/","meaning":"완전히, 순전히, 노골적으로","example":"His comment was downright rude and completely uncalled for.","deck":"vocab"},{"id":2069,"word":"immerse","ipa":"/ɪˈmɜːrs/","meaning":"몰두하게 만들다","example":"She likes to immerse herself in a good mystery novel.","deck":"vocab"},{"id":2070,"word":"wait on ~","ipa":"","meaning":"(특히 식사) 시중을 들다","example":"The young waiter had to wait on twelve tables tonight.","deck":"vocab"},{"id":2071,"word":"sorcery","ipa":"/ˈsɔːrsəri/","meaning":"마법 <특히 흑마술>","example":"The villagers accused the old woman of practicing sorcery.","deck":"vocab"},{"id":2072,"word":"back down","ipa":"","meaning":"주장을 굽히다, 패배를 인정하다","example":"He refused to back down during the heated argument.","deck":"vocab"},{"id":2073,"word":"unruly","ipa":"/ʌnˈruːli/","meaning":"다루기 힘든, 제멋대로 구는, 통제하기 어려운","example":"The teacher struggled to control the unruly class.","deck":"vocab"},{"id":2074,"word":"on a whim","ipa":"","meaning":"충동적으로, 즉흥적으로","example":"On a whim, we booked a last-minute flight to Rome.","deck":"vocab"},{"id":2075,"word":"ingenuous","ipa":"/ɪnˈdʒɛnjuəs/","meaning":"순진한, 사람을 잘 믿는","example":"Her ingenuous smile made everyone trust her instantly.","deck":"vocab"},{"id":2076,"word":"tantrum","ipa":"/ˈtæntrəm/","meaning":"(주로 어린아이의) 짜증, 성질을 부림","example":"The toddler threw a tantrum in the middle of the store.","deck":"vocab"},{"id":2077,"word":"prone","ipa":"/proʊn/","meaning":"~하기 쉬운, ~의 경향이 있는","example":"He is prone to catching colds during the winter.","deck":"vocab"},{"id":2078,"word":"scold","ipa":"/skoʊld/","meaning":"(특히 아이를) 야단치다, 꾸짖다","example":"His mother will scold him for breaking the window.","deck":"vocab"},{"id":2079,"word":"lie around","ipa":"","meaning":"(사람이) 빈둥거리다","example":"He tends to lie around all weekend watching television.","deck":"vocab"},{"id":2080,"word":"manure","ipa":"/məˈnʊr/","meaning":"(동물의 배설물로 만든) 거름, 천연 비료","example":"The farmer spread manure across the field before planting.","deck":"vocab"},{"id":2081,"word":"poultry","ipa":"/ˈpoʊltri/","meaning":"가금류의 고기","example":"The recipe calls for poultry rather than red meat.","deck":"vocab"},{"id":2082,"word":"diploma","ipa":"/dɪˈploʊmə/","meaning":"졸업장","example":"She proudly framed her high school diploma on the wall.","deck":"vocab"},{"id":2083,"word":"start off","ipa":"","meaning":"(~로) 시작하다","example":"Let's start off the meeting with a quick introduction.","deck":"vocab"},{"id":2084,"word":"Confucianism","ipa":"/kənˈfjuːʃənɪzəm/","meaning":"유교","example":"Confucianism deeply influenced traditional values across East Asia.","deck":"vocab"},{"id":2085,"word":"know ~ like the palm of one's hand","ipa":"","meaning":"~을 잘 알다, ~을 속속들이 알다","example":"He knows this city like the palm of his hand.","deck":"vocab"},{"id":2086,"word":"intensify","ipa":"/ɪnˈtɛnsɪfaɪ/","meaning":"(정도, 강도가) 심해지다, 격렬해지다","example":"The fighting began to intensify as night fell.","deck":"vocab"},{"id":2087,"word":"willpower","ipa":"/ˈwɪlpaʊər/","meaning":"의지력","example":"It takes great willpower to quit smoking for good.","deck":"vocab"},{"id":2088,"word":"maternal","ipa":"/məˈtɜːrnəl/","meaning":"모계의, 외가 쪽의","example":"My maternal grandmother taught me how to bake bread.","deck":"vocab"},{"id":2089,"word":"lash out","ipa":"","meaning":"(~을) 비난하다, 마구 몰아세우다","example":"He tends to lash out at others when he feels stressed.","deck":"vocab"},{"id":2090,"word":"dreary","ipa":"/ˈdrɪri/","meaning":"음울한, 따분한","example":"The rain made the whole town look dreary and gray.","deck":"vocab"},{"id":2091,"word":"apocalyptic","ipa":"/əˌpɑːkəˈlɪptɪk/","meaning":"종말론적","example":"The film painted an apocalyptic vision of the distant future.","deck":"vocab"},{"id":2092,"word":"congenital","ipa":"/kənˈdʒɛnɪtəl/","meaning":"(비유적으로) 타고난","example":"He seems to have a congenital talent for telling lies.","deck":"vocab"},{"id":2093,"word":"pittance","ipa":"/ˈpɪtəns/","meaning":"아주 적은 돈, 얼마 안 되는 돈","example":"They paid him a mere pittance for months of hard work.","deck":"vocab"},{"id":2094,"word":"averse","ipa":"/əˈvɜːrs/","meaning":"(~을) 싫어하는, 반대하는 <격식 있는 표현>","example":"She is averse to taking any unnecessary financial risks.","deck":"vocab"},{"id":2095,"word":"slight","ipa":"/slaɪt/","meaning":"(사람을) 무시하다 <주로 수동태로 씀>","example":"He felt slighted when they forgot to invite him.","deck":"vocab"},{"id":2096,"word":"meager","ipa":"/ˈmiːɡər/","meaning":"(양, 질이) 빈약한, 변변찮은","example":"They survived on a meager diet of rice and beans.","deck":"vocab"},{"id":2097,"word":"tribute","ipa":"/ˈtrɪbjuːt/","meaning":"존경의 표시, 헌정, 헌사 <존경이나 찬양의 뜻으로 바치는 것>","example":"The concert was a heartfelt tribute to the late singer.","deck":"vocab"},{"id":2098,"word":"constituency","ipa":"/kənˈstɪtʃuənsi/","meaning":"(특정 지역의) 선거구민, 유권자들","example":"The senator visited her constituency to hear their concerns.","deck":"vocab"},{"id":2099,"word":"inept","ipa":"/ɪˈnɛpt/","meaning":"솜씨 없는, 서투른","example":"The inept manager kept losing important documents.","deck":"vocab"},{"id":2100,"word":"chastise","ipa":"/tʃæˈstaɪz/","meaning":"~에게 체벌을 가하다, 태형을 가하다 <구식 표현>","example":"In old times, teachers would chastise disobedient pupils harshly.","deck":"vocab"},{"id":2101,"word":"misperception","ipa":"/ˌmɪspərˈsɛpʃən/","meaning":"오인, 오해","example":"There is a common misperception that bats are blind.","deck":"vocab"},{"id":2102,"word":"exhilarate","ipa":"/ɪɡˈzɪləreɪt/","meaning":"아주 기쁘게 만들다, 신나게 만들다","example":"The fast roller coaster ride never fails to exhilarate me.","deck":"vocab"},{"id":2103,"word":"rambling","ipa":"/ˈræmblɪŋ/","meaning":"횡설수설, 횡설수설하는 말, 횡설수설하는 글","example":"His long rambling made it hard to follow the point.","deck":"vocab"},{"id":2104,"word":"rite","ipa":"/raɪt/","meaning":"(특히 종교상의) 의식, 의례","example":"The ancient rite was performed at sunrise every spring.","deck":"vocab"},{"id":2105,"word":"baptism","ipa":"/ˈbæptɪzəm/","meaning":"세례, 세례식","example":"The baby's baptism took place at the small village church.","deck":"vocab"},{"id":2106,"word":"metabolism","ipa":"/məˈtæbəlɪzəm/","meaning":"(생물의) 신진대사, 대사","example":"Regular exercise can help boost your metabolism significantly.","deck":"vocab"},{"id":2107,"word":"trajectory","ipa":"/trəˈdʒɛktəri/","meaning":"탄도, 궤적, 궤도","example":"Scientists calculated the exact trajectory of the rocket.","deck":"vocab"},{"id":2108,"word":"measured","ipa":"/ˈmɛʒərd/","meaning":"신중한, 침착한","example":"She gave a calm, measured response to the harsh criticism.","deck":"vocab"},{"id":2109,"word":"groin","ipa":"/ɡrɔɪn/","meaning":"사타구니, 서혜부","example":"The athlete pulled a muscle in his groin during training.","deck":"vocab"},{"id":2110,"word":"assortment","ipa":"/əˈsɔːrtmənt/","meaning":"모음, 모듬, 모둠, 종합 <조금씩 다르지만 비슷한 사물이나 물건의 모음>","example":"The box contained a colorful assortment of chocolates.","deck":"vocab"},{"id":2111,"word":"termite","ipa":"/ˈtɜːrmaɪt/","meaning":"흰개미","example":"A termite colony had quietly destroyed the wooden beams.","deck":"vocab"},{"id":2112,"word":"exterminator","ipa":"/ɪkˈstɜːrmɪneɪtər/","meaning":"박멸업자 <해충이나 유해 동물을 없애 주는 일을 하는 사람>","example":"We called an exterminator to deal with the rat problem.","deck":"vocab"},{"id":2113,"word":"epidemic","ipa":"/ˌɛpɪˈdɛmɪk/","meaning":"(흔히 나쁜 것의) 급속한 확산","example":"The city is facing an epidemic of online fraud.","deck":"vocab"},{"id":2114,"word":"card-carrying","ipa":"/ˈkɑːrdˌkæriɪŋ/","meaning":"(정당이나 조직의) 정식의","example":"He is a card-carrying member of the local union.","deck":"vocab"},{"id":2115,"word":"extraterrestrial","ipa":"/ˌɛkstrətəˈrɛstriəl/","meaning":"외계의, 지구 밖의","example":"The scientists searched for signs of extraterrestrial life.","deck":"vocab"},{"id":2116,"word":"misfit","ipa":"/ˈmɪsfɪt/","meaning":"부적응자","example":"He always felt like a misfit at the fancy parties.","deck":"vocab"},{"id":2117,"word":"outlook","ipa":"/ˈaʊtlʊk/","meaning":"관점, 세계관, 인생관","example":"Travel gave her a much broader outlook on life.","deck":"vocab"},{"id":2118,"word":"detention","ipa":"/dɪˈtɛnʃən/","meaning":"(유치장, 교도소 등에서의) 구류, 구금","example":"The protesters were held in detention for several hours.","deck":"vocab"},{"id":2119,"word":"indefinite","ipa":"/ɪnˈdɛfɪnɪt/","meaning":"무기한의","example":"The project was postponed for an indefinite period.","deck":"vocab"},{"id":2120,"word":"tightrope","ipa":"/ˈtaɪtroʊp/","meaning":"(서커스 같은 데서 곡예사가 타는) 줄","example":"The acrobat walked across the tightrope without any net.","deck":"vocab"},{"id":2121,"word":"outsmart","ipa":"/aʊtˈsmɑːrt/","meaning":"~보다 한 수 앞서다","example":"The clever fox managed to outsmart the hunters again.","deck":"vocab"},{"id":2122,"word":"knob","ipa":"/nɑːb/","meaning":"(텔레비전 등의 기계에 달린 동그란) 손잡이","example":"He turned the knob to lower the volume on the radio.","deck":"vocab"},{"id":2123,"word":"freewheeling","ipa":"/ˈfriːˈwiːlɪŋ/","meaning":"자유분방한","example":"They enjoyed a freewheeling road trip across the country.","deck":"vocab"},{"id":2124,"word":"commentary","ipa":"/ˈkɑːmənteri/","meaning":"예, 사례, 예증하는 것, 설명하는 것","example":"The empty seats were a sad commentary on the team's decline.","deck":"vocab"},{"id":2125,"word":"sanity","ipa":"/ˈsænɪti/","meaning":"온전한 정신 상태, 제정신","example":"A quiet walk each morning helps me keep my sanity.","deck":"vocab"},{"id":2126,"word":"installment plan","ipa":"/ɪnˈstɔːlmənt plæn/","meaning":"할부제, 할부 판매","example":"They bought the new sofa on an installment plan.","deck":"vocab"},{"id":2127,"word":"skeptic","ipa":"/ˈskɛptɪk/","meaning":"회의론자","example":"As a skeptic, he questioned every claim the salesman made.","deck":"vocab"},{"id":2128,"word":"run errand","ipa":"","meaning":"심부름 하다","example":"I have to run an errand for my mother this afternoon.","deck":"vocab"},{"id":2129,"word":"ransack","ipa":"/ˈrænsæk/","meaning":"~을 난장판을 만들어 놓다, 샅샅이 뒤지다 <주로 뭔가를 찾기 위해>","example":"Burglars ransacked the house looking for hidden cash.","deck":"vocab"},{"id":2130,"word":"correspondent","ipa":"/ˌkɔːrɪˈspɑːndənt/","meaning":"(특정 지역에 파견된) 특파원, 통신원","example":"The war correspondent reported live from the besieged city.","deck":"vocab"},{"id":2131,"word":"effervescent","ipa":"/ˌɛfərˈvɛsənt/","meaning":"(액체가) 거품이 나는, 탄산이 든","example":"She poured a glass of effervescent mineral water.","deck":"vocab"},{"id":2132,"word":"prerogative","ipa":"/prɪˈrɑːɡətɪv/","meaning":"특권, 특혜","example":"Making the final decision is the manager's prerogative.","deck":"vocab"},{"id":2133,"word":"erect","ipa":"/ɪˈrɛkt/","meaning":"(건물, 장벽, 동상 등을) 세우다","example":"The city plans to erect a statue in the main square.","deck":"vocab"},{"id":2134,"word":"hemorrhage","ipa":"/ˈhɛmərɪdʒ/","meaning":"(심한) 출혈을 일으키다, 출혈이 되다","example":"The patient began to hemorrhage badly after the accident.","deck":"vocab"},{"id":2135,"word":"at one's fingertips","ipa":"","meaning":"즉시 이용할 수 있는","example":"With the app, all the information is at your fingertips.","deck":"vocab"},{"id":2136,"word":"lag","ipa":"/læɡ/","meaning":"뒤처지다, 뒤떨어지다","example":"Our sales still lag behind those of our competitors.","deck":"vocab"},{"id":2137,"word":"posterity","ipa":"/pɑːˈstɛrɪti/","meaning":"후세, 후대","example":"These documents must be preserved for posterity.","deck":"vocab"},{"id":2138,"word":"brazen","ipa":"/ˈbreɪzən/","meaning":"뻔뻔한 <부정적인 어감>","example":"She told a brazen lie right to the teacher's face.","deck":"vocab"},{"id":2139,"word":"screwed-up","ipa":"/ˈskruːdˈʌp/","meaning":"맛이 간 <불안, 혼란 또는 정신적인 문제가 있음을 뜻함>","example":"He had a screwed-up childhood full of chaos and neglect.","deck":"vocab"},{"id":2140,"word":"stretch","ipa":"/strɛtʃ/","meaning":"구간, 지역","example":"This stretch of the highway is often closed for repairs.","deck":"vocab"},{"id":2141,"word":"outgoing","ipa":"/ˈaʊtɡoʊɪŋ/","meaning":"외향적인, 사교적인","example":"Her outgoing personality makes it easy to find new friends.","deck":"vocab"},{"id":2142,"word":"loquacious","ipa":"/loʊˈkweɪʃəs/","meaning":"수다스러운, 말이 많은","example":"The loquacious guide talked nonstop throughout the entire tour.","deck":"vocab"},{"id":2143,"word":"warp","ipa":"/wɔːrp/","meaning":"휘게 만들다, 뒤틀리게 만들다","example":"Too much moisture can warp the wooden floorboards.","deck":"vocab"},{"id":2144,"word":"beseech","ipa":"/bɪˈsiːtʃ/","meaning":"간청하다, 애원하다 <문어체>","example":"She fell to her knees to beseech him for mercy.","deck":"vocab"},{"id":2145,"word":"cheap shot","ipa":"/ˌtʃiːp ˈʃɑːt/","meaning":"비열한 짓, 치사한 짓","example":"Mocking his accent was a real cheap shot.","deck":"vocab"},{"id":2146,"word":"goober","ipa":"/ˈɡuːbər/","meaning":"기인","example":"Everyone thought the eccentric inventor was a harmless goober.","deck":"vocab"},{"id":2147,"word":"hermit","ipa":"/ˈhɜːrmɪt/","meaning":"(보통 종교적 이유에 의한) 은둔자","example":"The old hermit lived alone deep in the mountains.","deck":"vocab"},{"id":2148,"word":"ludicrous","ipa":"/ˈluːdɪkrəs/","meaning":"터무니없는","example":"His excuse for being late was absolutely ludicrous.","deck":"vocab"},{"id":2149,"word":"tact","ipa":"/tækt/","meaning":"기지","example":"She handled the awkward situation with great tact.","deck":"vocab"},{"id":2150,"word":"withdrawn","ipa":"/wɪðˈdrɔːn/","meaning":"내성적인, 내향적인","example":"He became quiet and withdrawn after losing his job.","deck":"vocab"},{"id":2151,"word":"crucify","ipa":"/ˈkruːsɪfaɪ/","meaning":"심하게 질책하다, 호되게 처벌하다","example":"The press will crucify him for such a careless remark.","deck":"vocab"},{"id":2152,"word":"reinstate","ipa":"/ˌriːɪnˈsteɪt/","meaning":"복귀시키다, 복직시키다","example":"The company agreed to reinstate the wrongly fired worker.","deck":"vocab"},{"id":2153,"word":"anesthesia","ipa":"/ˌænɪsˈθiːʒə/","meaning":"마취, 마취 상태 <의학 용어>","example":"The surgeon waited until the anesthesia had fully taken effect.","deck":"vocab"},{"id":2154,"word":"biopsy","ipa":"/ˈbaɪɑːpsi/","meaning":"생검(生檢), 조직 검사","example":"The doctor ordered a biopsy to check for cancer.","deck":"vocab"},{"id":2155,"word":"dissociate","ipa":"/dɪˈsoʊʃieɪt/","meaning":"~을 (~와) 분리해서 생각하다","example":"It is hard to dissociate the artist from his troubled life.","deck":"vocab"},{"id":2156,"word":"dissociate","ipa":"/dɪˈsoʊʃieɪt/","meaning":"~와 관련 없음을 분명히 하다","example":"The company tried to dissociate itself from the scandal.","deck":"vocab"},{"id":2157,"word":"claw one's way","ipa":"","meaning":"끈질기게 노력해서 해내다","example":"She clawed her way to the top of the company.","deck":"vocab"},{"id":2158,"word":"spook","ipa":"/spuːk/","meaning":"(사람, 동물을) 겁먹게 하다 <주로 수동태로 씀>","example":"The sudden loud noise spooked the nervous horse.","deck":"vocab"},{"id":2159,"word":"insipid","ipa":"/ɪnˈsɪpɪd/","meaning":"재미없는, 따분한, 지루한","example":"The movie was so insipid that I fell asleep.","deck":"vocab"},{"id":2160,"word":"condiment","ipa":"/ˈkɑːndɪmənt/","meaning":"양념, 소스, 컨디먼트 <조리된 음식에 기호에 따라 추가하는 양념>","example":"Ketchup is the most popular condiment at the diner.","deck":"vocab"},{"id":2161,"word":"mucous","ipa":"/ˈmjuːkəs/","meaning":"점액을 분비하는, 점액을 함유한, 점액질의","example":"The mucous lining of the nose traps dust and germs.","deck":"vocab"},{"id":2162,"word":"bash","ipa":"/bæʃ/","meaning":"~을 후려치다, 강타하다, 세게 치다 <타동사>","example":"He accidentally bashed his knee against the table.","deck":"vocab"},{"id":2163,"word":"make amends","ipa":"","meaning":"(~에 대해) 보상하다","example":"He sent flowers to make amends for his rude behavior.","deck":"vocab"},{"id":2164,"word":"invigorate","ipa":"/ɪnˈvɪɡəreɪt/","meaning":"기운 나게 하다, 활기를 북돋우다","example":"A cold morning swim always invigorates my whole body.","deck":"vocab"},{"id":2165,"word":"bear","ipa":"/bɛr/","meaning":"~을 가지고 가다, 가지고 오다 <구식 표현>","example":"The messengers came to bear gifts for the young king.","deck":"vocab"},{"id":2166,"word":"tidings","ipa":"/ˈtaɪdɪŋz/","meaning":"소식, 뉴스 <구식 표현>","example":"The traveler brought glad tidings from the distant land.","deck":"vocab"},{"id":2167,"word":"prize","ipa":"/praɪz/","meaning":"소중하게 여기다, 귀하게 여기다 <주로 수동태로 씀>","example":"This old watch is prized as a family heirloom.","deck":"vocab"},{"id":2168,"word":"at large","ipa":"","meaning":"잡히지 않은, 활개 치고 다니는","example":"The escaped prisoner is still at large tonight.","deck":"vocab"},{"id":2169,"word":"dissent","ipa":"/dɪˈsɛnt/","meaning":"(~에 대해) 반대하다","example":"Two judges chose to dissent from the majority ruling.","deck":"vocab"},{"id":2170,"word":"promenade","ipa":"/ˌprɑːməˈnɑːd/","meaning":"(보통 해변가로 넓게 나 있는) 산책로","example":"They took an evening stroll along the seaside promenade.","deck":"vocab"},{"id":2171,"word":"cartilage","ipa":"/ˈkɑːrtɪlɪdʒ/","meaning":"연골, 물렁뼈","example":"The runner tore the cartilage in his right knee.","deck":"vocab"},{"id":2172,"word":"grim","ipa":"/ɡrɪm/","meaning":"(장소, 건물 등이) 음침한, 암울한, 음산한","example":"The abandoned factory looked grim under the gray sky.","deck":"vocab"},{"id":2173,"word":"loot","ipa":"/luːt/","meaning":"전리품, 노획물","example":"The soldiers divided the loot after the battle.","deck":"vocab"},{"id":2174,"word":"convulsion","ipa":"/kənˈvʌlʃən/","meaning":"경련, 경기","example":"The high fever caused the child to have a convulsion.","deck":"vocab"},{"id":2175,"word":"shrill","ipa":"/ʃrɪl/","meaning":"(목소리 등의 소리가) 새된, 날카로운","example":"A shrill whistle pierced the quiet morning air.","deck":"vocab"},{"id":2176,"word":"plummet","ipa":"/ˈplʌmɪt/","meaning":"폭락하다, 급락하다, 급격히 떨어지다","example":"Stock prices began to plummet after the bad news.","deck":"vocab"},{"id":2177,"word":"plummet","ipa":"/ˈplʌmɪt/","meaning":"급락, 곤두박질침","example":"The sudden plummet in temperatures caught everyone off guard.","deck":"vocab"},{"id":2178,"word":"sparingly","ipa":"/ˈspɛrɪŋli/","meaning":"아껴서, 조금씩","example":"Use this expensive spice sparingly in your cooking.","deck":"vocab"},{"id":2179,"word":"perishable","ipa":"/ˈpɛrɪʃəbəl/","meaning":"(특히 식품이) 잘 상하는, 잘 썩는","example":"Store perishable food in the refrigerator right away.","deck":"vocab"},{"id":2180,"word":"enunciate","ipa":"/ɪˈnʌnsieɪt/","meaning":"또렷이 발음하다, 명확하게 말하다","example":"The teacher told him to enunciate each word clearly.","deck":"vocab"},{"id":2181,"word":"opportune","ipa":"/ˌɑːpərˈtuːn/","meaning":"(일, 동작, 발언 등이) 시의적절한","example":"She arrived at the most opportune moment to help us.","deck":"vocab"},{"id":2182,"word":"insincere","ipa":"/ˌɪnsɪnˈsɪr/","meaning":"진실되지 못한 <못마땅함>","example":"His apology felt hollow and completely insincere.","deck":"vocab"},{"id":2183,"word":"stigmatize","ipa":"/ˈstɪɡmətaɪz/","meaning":"오명을 씌우다, 낙인 찍다","example":"Society should not stigmatize people with mental illness.","deck":"vocab"},{"id":2184,"word":"tax evasion","ipa":"/ˌtæks ɪˈveɪʒən/","meaning":"탈세","example":"The businessman was arrested for large-scale tax evasion.","deck":"vocab"},{"id":2185,"word":"prosecution","ipa":"/ˌprɑːsɪˈkjuːʃən/","meaning":"기소, 공소 제기, 소추","example":"The evidence was strong enough to justify prosecution.","deck":"vocab"},{"id":2186,"word":"sitting","ipa":"/ˈsɪtɪŋ/","meaning":"현직의","example":"The sitting president will run for a second term.","deck":"vocab"},{"id":2187,"word":"divert","ipa":"/daɪˈvɜːrt/","meaning":"(관심, 생각 등을 다른 데로) 돌리다, 전환하다","example":"He told a joke to divert attention from his mistake.","deck":"vocab"},{"id":2188,"word":"utilitarian","ipa":"/juːˌtɪlɪˈtɛriən/","meaning":"실용적인 <격식>","example":"The office had a plain, utilitarian design with no decoration.","deck":"vocab"},{"id":2189,"word":"without a nickel to one's name","ipa":"","meaning":"땡전 한 푼 없는, 땡전 한 푼 없이","example":"He arrived in the big city without a nickel to his name.","deck":"vocab"},{"id":2190,"word":"come down","ipa":"","meaning":"(찬반을) 표명하다","example":"The senator finally came down in favor of the new law.","deck":"vocab"},{"id":2191,"word":"authenticate","ipa":"/ɔːˈθɛntɪkeɪt/","meaning":"~을 증명하다","example":"Experts were called in to authenticate the old painting.","deck":"vocab"},{"id":2192,"word":"outlive","ipa":"/aʊtˈlɪv/","meaning":"(사람이) ~보다 더 오래 살다","example":"She outlived her husband by nearly twenty years.","deck":"vocab"},{"id":2193,"word":"capitalize on ~","ipa":"","meaning":"~을 활용하다, ~을 기회로 삼다","example":"The company capitalized on the growing demand for electric cars.","deck":"vocab"},{"id":2194,"word":"attire","ipa":"/əˈtaɪər/","meaning":"의복, 복장 <격식>","example":"Guests were asked to wear formal attire to the gala.","deck":"vocab"},{"id":2195,"word":"redo","ipa":"/riːˈduː/","meaning":"장식을 다시 하다, 다시 꾸미다","example":"They decided to redo the living room in brighter colors.","deck":"vocab"},{"id":2196,"word":"pavement","ipa":"/ˈpeɪvmənt/","meaning":"인도, 보도 <영국식 표현. 미국영어의 sidewalk과 같은 뜻>","example":"She slipped on the icy pavement outside the shop.","deck":"vocab"},{"id":2197,"word":"meddle","ipa":"/ˈmɛdəl/","meaning":"(~에) 손을 대다, (~을) 건드리다 <특히 남의 것을 허락 없이>","example":"Please don't meddle in other people's private affairs.","deck":"vocab"},{"id":2198,"word":"embroider","ipa":"/ɪmˈbrɔɪdər/","meaning":"수를 놓다","example":"She likes to embroider flowers on old cotton shirts.","deck":"vocab"},{"id":2199,"word":"fetus","ipa":"/ˈfiːtəs/","meaning":"태아 <임신 8주를 지난 태아를 가리킴>","example":"The ultrasound showed the fetus developing normally.","deck":"vocab"},{"id":2200,"word":"womb","ipa":"/wuːm/","meaning":"자궁","example":"The baby grew safely inside its mother's womb.","deck":"vocab"},{"id":2201,"word":"sedentary","ipa":"/ˈsɛdənˌtɛri/","meaning":"(일, 활동 등이) 주로 앉아서 하는","example":"Working a sedentary job can lead to various health problems over time.","deck":"vocab"},{"id":2202,"word":"unanimously","ipa":"/juˈnænəməsli/","meaning":"만장일치로","example":"The committee voted unanimously to approve the new budget proposal.","deck":"vocab"},{"id":2203,"word":"endorsement","ipa":"/ɪnˈdɔrsmənt/","meaning":"홍보, 보증","example":"The athlete earned a lucrative endorsement deal with a sportswear brand.","deck":"vocab"},{"id":2204,"word":"cozy up to ~","ipa":"","meaning":"~에게 친하게 굴다, ~의 환심을 사려고 하다","example":"She tried to cozy up to the manager hoping for a promotion.","deck":"vocab"},{"id":2205,"word":"binoculars","ipa":"/bɪˈnɑkjələrz/","meaning":"쌍안경","example":"He used binoculars to watch the birds nesting across the valley.","deck":"vocab"},{"id":2206,"word":"raft","ipa":"/ræft/","meaning":"뗏목","example":"They built a small raft to cross the river safely.","deck":"vocab"},{"id":2207,"word":"meander","ipa":"/miˈændər/","meaning":"구불구불하게 나 있다, 굽이치다, 굽이쳐 흐르다","example":"The lazy stream tends to meander through the green meadow.","deck":"vocab"},{"id":2208,"word":"falsify","ipa":"/ˈfɔlsəˌfaɪ/","meaning":"~이 잘못임을 입증하다, 반증을 들다","example":"The scientist refused to falsify the data to fit his theory.","deck":"vocab"},{"id":2209,"word":"condescend","ipa":"/ˌkɑndɪˈsɛnd/","meaning":"(~에게) 거들먹거리다, 잘난 체하다","example":"He would never condescend to explain his reasoning to us.","deck":"vocab"},{"id":2210,"word":"outrageously","ipa":"/aʊtˈreɪdʒəsli/","meaning":"난폭하게, 극악하게, 터무니없게","example":"The restaurant charged outrageously high prices for very small portions.","deck":"vocab"},{"id":2211,"word":"stargaze","ipa":"/ˈstɑrˌgeɪz/","meaning":"별을 바라보다, 별을 관찰하다","example":"We drove out to the countryside to stargaze far from city lights.","deck":"vocab"},{"id":2212,"word":"fission","ipa":"/ˈfɪʃən/","meaning":"핵분열 <물리학 용어>","example":"Nuclear fission releases an enormous amount of energy in power plants.","deck":"vocab"},{"id":2213,"word":"bluntly","ipa":"/ˈblʌntli/","meaning":"직설적으로","example":"She told him bluntly that his plan would never work.","deck":"vocab"},{"id":2214,"word":"contrite","ipa":"/kənˈtraɪt/","meaning":"깊이 뉘우치는, 회한에 찬 <격식 있는 표현>","example":"He looked genuinely contrite after realizing he had hurt her feelings.","deck":"vocab"},{"id":2215,"word":"hay","ipa":"/heɪ/","meaning":"건초","example":"The farmer stacked the dried hay in the barn before winter.","deck":"vocab"},{"id":2216,"word":"hatred","ipa":"/ˈheɪtrɪd/","meaning":"증오, 혐오, 혐오감","example":"His speech was filled with hatred toward his political rivals.","deck":"vocab"},{"id":2217,"word":"rave","ipa":"/reɪv/","meaning":"극찬하는 평가","example":"The new film received a rave review from every major critic.","deck":"vocab"},{"id":2218,"word":"peripheral","ipa":"/pəˈrɪfərəl/","meaning":"외곽의, 주변부의","example":"Parking is available in the peripheral areas around the stadium.","deck":"vocab"},{"id":2219,"word":"keen","ipa":"/kin/","meaning":"~을 아주 좋아하는, ~에 대단히 관심이 많은","example":"She is very keen on learning how to play the violin.","deck":"vocab"},{"id":2220,"word":"keen","ipa":"/kin/","meaning":"강한, 깊은 <주로 명사 앞에 씀>","example":"He has a keen interest in ancient Roman history.","deck":"vocab"},{"id":2221,"word":"care for ~","ipa":"","meaning":"(사물이나 상황을) ~을 좋아하다, ~을 즐기다 <주로 부정문에 씀>","example":"I don't really care for spicy food late at night.","deck":"vocab"},{"id":2222,"word":"assimilate","ipa":"/əˈsɪməˌleɪt/","meaning":"동화되다","example":"Immigrants often take years to assimilate into a new culture.","deck":"vocab"},{"id":2223,"word":"render","ipa":"/ˈrɛndər/","meaning":"(다른 언어로) 옮기다, 번역하다","example":"The translator worked hard to render the poem into English.","deck":"vocab"},{"id":2224,"word":"uplifting","ipa":"/ʌpˈlɪftɪŋ/","meaning":"희망을 주는, 행복감을 주는","example":"The choir sang an uplifting song that lifted everyone's spirits.","deck":"vocab"},{"id":2225,"word":"satire","ipa":"/ˈsæˌtaɪər/","meaning":"풍자","example":"The novel is a sharp satire of modern political life.","deck":"vocab"},{"id":2226,"word":"appalling","ipa":"/əˈpɔlɪŋ/","meaning":"형편없는, 품질이 매우 나쁜","example":"The service at the hotel was absolutely appalling last night.","deck":"vocab"},{"id":2227,"word":"incurable","ipa":"/ɪnˈkjʊrəbəl/","meaning":"치유할 수 없는, 불치의","example":"Doctors told him the rare disease was sadly incurable.","deck":"vocab"},{"id":2228,"word":"titular","ipa":"/ˈtɪtʃələr/","meaning":"명목상의, 명의뿐인, 이름뿐인","example":"The queen remained only the titular head of the government.","deck":"vocab"},{"id":2229,"word":"impeachment","ipa":"/ɪmˈpitʃmənt/","meaning":"탄핵","example":"The president faced impeachment for abusing his official powers.","deck":"vocab"},{"id":2230,"word":"reincarnate","ipa":"/ˌriɪnˈkɑrˌneɪt/","meaning":"환생하다","example":"Some believe the soul will reincarnate into a new body.","deck":"vocab"},{"id":2231,"word":"in litigation","ipa":"","meaning":"소송 중인, 소송 중에","example":"The disputed property has been in litigation for several years.","deck":"vocab"},{"id":2232,"word":"with a vengeance","ipa":"","meaning":"맹렬히, 심하게, 지나치게","example":"After the break, she returned to work with a vengeance.","deck":"vocab"},{"id":2233,"word":"agility","ipa":"/əˈdʒɪləti/","meaning":"민첩, 명민함","example":"The gymnast moved with remarkable agility across the balance beam.","deck":"vocab"},{"id":2234,"word":"propensity","ipa":"/prəˈpɛnsəti/","meaning":"(특정한 행동을 하는) 경향, 성향 <격식>","example":"He has a propensity for spending money on unnecessary gadgets.","deck":"vocab"},{"id":2235,"word":"outright","ipa":"/ˈaʊtˌraɪt/","meaning":"즉석에서, 즉각","example":"The board rejected the proposal outright without any discussion.","deck":"vocab"},{"id":2236,"word":"exquisitely","ipa":"/ɪkˈskwɪzɪtli/","meaning":"아주 아름답게, 절묘하게, 정교하게, 우아하게","example":"The wedding cake was exquisitely decorated with delicate sugar flowers.","deck":"vocab"},{"id":2237,"word":"brisk","ipa":"/brɪsk/","meaning":"(사람, 태도 등이) 활발한, 활기찬","example":"She set off at a brisk pace to catch the morning train.","deck":"vocab"},{"id":2238,"word":"affiliate","ipa":"/əˈfɪliət/","meaning":"관계 단체, 지부, 지점, 분회","example":"The local TV station is an affiliate of a national network.","deck":"vocab"},{"id":2239,"word":"allot","ipa":"/əˈlɑt/","meaning":"(시간, 돈, 업무 등을) 할당하다, 배당하다","example":"The teacher will allot ten minutes for each student's presentation.","deck":"vocab"},{"id":2240,"word":"shingle","ipa":"/ˈʃɪŋgəl/","meaning":"조약돌","example":"We walked along the shingle beach collecting smooth stones.","deck":"vocab"},{"id":2241,"word":"fragmentation","ipa":"/ˌfrægmənˈteɪʃən/","meaning":"분열, 파쇄(破碎)","example":"The fragmentation of the party weakened its chances in the election.","deck":"vocab"},{"id":2242,"word":"holdout","ipa":"/ˈhoʊldˌaʊt/","meaning":"타협을 거부하는 사람, 협조를 거부하는 사람","example":"He was the last holdout who refused to sign the agreement.","deck":"vocab"},{"id":2243,"word":"speak of the devil","ipa":"","meaning":"호랑이도 제 말하면 온다","example":"Well, speak of the devil, here he comes right now.","deck":"vocab"},{"id":2244,"word":"salvation","ipa":"/sælˈveɪʃən/","meaning":"구제자, 구제 수단, 구제해 주는 것 <one's salvation의 형태로 씀>","example":"Volunteering became his salvation during a difficult period of life.","deck":"vocab"},{"id":2245,"word":"pervasive","ipa":"/pərˈveɪsɪv/","meaning":"만연하는, 만연한, 구석구석 스며드는","example":"A pervasive sense of fear spread throughout the small town.","deck":"vocab"},{"id":2246,"word":"jest","ipa":"/dʒɛst/","meaning":"농담하다","example":"Surely you jest about quitting such a wonderful job.","deck":"vocab"},{"id":2247,"word":"jammies","ipa":"/ˈdʒæmiz/","meaning":"잠옷, 파자마 <유아어>","example":"The kids put on their cozy jammies before bedtime.","deck":"vocab"},{"id":2248,"word":"regimen","ipa":"/ˈrɛdʒəmən/","meaning":"양생법, 섭생, 요법 <건강 회복이나 증진을 위한 정해진 치료법이나 식이요법>","example":"The doctor recommended a strict diet and exercise regimen.","deck":"vocab"},{"id":2249,"word":"ramification","ipa":"/ˌræməfəˈkeɪʃən/","meaning":"영향, 파급 효과, 파문, 파장 <어떤 행동이나 결정에 따라 생기는 결과>","example":"The new law had serious ramifications for small business owners.","deck":"vocab"},{"id":2250,"word":"unequivocal","ipa":"/ˌʌnɪˈkwɪvəkəl/","meaning":"명백한, 분명한 <격식>","example":"She gave an unequivocal answer, leaving no room for doubt.","deck":"vocab"},{"id":2251,"word":"delve into","ipa":"","meaning":"(더 많은 것을 알아내기 위해) ~을 파헤치다","example":"The researchers decided to delve into the ancient manuscripts.","deck":"vocab"},{"id":2252,"word":"realm","ipa":"/rɛlm/","meaning":"왕국 <격식>","example":"The knights swore to protect the realm from all invaders.","deck":"vocab"},{"id":2253,"word":"susceptible","ipa":"/səˈsɛptəbəl/","meaning":"(질병, 부상 등에) (~에) 걸리기 쉬운","example":"Young children are especially susceptible to colds during winter.","deck":"vocab"},{"id":2254,"word":"unsolicited","ipa":"/ˌʌnsəˈlɪsɪtɪd/","meaning":"청하지 않은","example":"He kept giving unsolicited advice that nobody had asked for.","deck":"vocab"},{"id":2255,"word":"coddle","ipa":"/ˈkɑdəl/","meaning":"애지중지하다, 오냐오냐해 주다","example":"Some parents coddle their children and never let them fail.","deck":"vocab"},{"id":2256,"word":"kink","ipa":"/kɪŋk/","meaning":"(제도, 계획, 기계 등의) 결함, 결점","example":"Engineers found a small kink in the new software system.","deck":"vocab"},{"id":2257,"word":"fledgling","ipa":"/ˈflɛdʒlɪŋ/","meaning":"신생, 신출내기, 초보자 <새로 생겨났거나 경험이 없는 사람이나 조직>","example":"The fledgling company struggled to survive its first difficult year.","deck":"vocab"},{"id":2258,"word":"bellow","ipa":"/ˈbɛloʊ/","meaning":"큰 소리로 말하다, 고함쳐 말하다","example":"The sergeant would bellow orders across the training field.","deck":"vocab"},{"id":2259,"word":"flicker","ipa":"/ˈflɪkər/","meaning":"(전깃불이나 불길이) 깜박거리다","example":"The candle began to flicker in the gentle evening breeze.","deck":"vocab"},{"id":2260,"word":"petty","ipa":"/ˈpɛti/","meaning":"사소한, 하찮은","example":"They argued over petty details instead of the real issue.","deck":"vocab"},{"id":2261,"word":"gracious","ipa":"/ˈgreɪʃəs/","meaning":"정중한, 친절한, 상냥한, 품위 있는","example":"Our host was gracious and made every guest feel welcome.","deck":"vocab"},{"id":2262,"word":"permeate","ipa":"/ˈpɜrmiˌeɪt/","meaning":"(액체, 기체 등이) 스며들다, 배어들다, 번지다","example":"The smell of fresh bread began to permeate the entire house.","deck":"vocab"},{"id":2263,"word":"ostentatious","ipa":"/ˌɑstɛnˈteɪʃəs/","meaning":"호사스러운, 대단히 비싼","example":"He drove an ostentatious sports car to impress his neighbors.","deck":"vocab"},{"id":2264,"word":"affinity","ipa":"/əˈfɪnəti/","meaning":"친밀감","example":"She felt a strong affinity for the quiet mountain village.","deck":"vocab"},{"id":2265,"word":"hinder","ipa":"/ˈhɪndər/","meaning":"저해하다, 방해하다, ~을 못하게 하다","example":"Heavy rain could hinder our progress on the hiking trail.","deck":"vocab"},{"id":2266,"word":"subside","ipa":"/səbˈsaɪd/","meaning":"가라앉다, 진정되다","example":"The storm finally began to subside late in the evening.","deck":"vocab"},{"id":2267,"word":"tasteful","ipa":"/ˈteɪstfəl/","meaning":"세련된","example":"The room was decorated in a simple yet tasteful manner.","deck":"vocab"},{"id":2268,"word":"paragon","ipa":"/ˈpærəˌgɑn/","meaning":"표상, 전형, 모범, 본보기, 귀감","example":"She is regarded as a paragon of honesty and hard work.","deck":"vocab"},{"id":2269,"word":"scenic","ipa":"/ˈsinɪk/","meaning":"경치가 좋은","example":"We took the scenic route along the coast to enjoy the view.","deck":"vocab"},{"id":2270,"word":"submission","ipa":"/səbˈmɪʃən/","meaning":"항복, 굴복","example":"The rebels were finally forced into submission by the army.","deck":"vocab"},{"id":2271,"word":"give ~ the cold shoulder","ipa":"","meaning":"~를 쌀쌀맞게 대하다","example":"Don't give me the cold shoulder just because I disagreed.","deck":"vocab"},{"id":2272,"word":"capricious","ipa":"/kəˈprɪʃəs/","meaning":"(사람이) 변덕스러운","example":"The weather here is capricious, sunny one moment and rainy the next.","deck":"vocab"},{"id":2273,"word":"chip in","ipa":"","meaning":"나눠 내다, 갹출하다, 나눠 부담하다 <비격식적인 표현>","example":"Everyone agreed to chip in for the retirement gift.","deck":"vocab"},{"id":2274,"word":"moot","ipa":"/mut/","meaning":"고려할 가치가 없는","example":"Since the event was canceled, the whole debate became moot.","deck":"vocab"},{"id":2275,"word":"live through ~","ipa":"","meaning":"~을 겪고 살아남다","example":"My grandparents lived through the war and its aftermath.","deck":"vocab"},{"id":2276,"word":"sharp","ipa":"/ʃɑrp/","meaning":"정각","example":"The meeting will begin at nine o'clock sharp tomorrow morning.","deck":"vocab"},{"id":2277,"word":"gleaming","ipa":"/ˈglimɪŋ/","meaning":"빛나는, 환한","example":"The kitchen counters were gleaming after she cleaned them.","deck":"vocab"},{"id":2278,"word":"monastery","ipa":"/ˈmɑnəˌstɛri/","meaning":"수도원","example":"The monks lived quietly in a monastery high in the mountains.","deck":"vocab"},{"id":2279,"word":"take ~ on the chin","ipa":"","meaning":"묵묵히 받아들이다","example":"You have to take it on the chin and move on.","deck":"vocab"},{"id":2280,"word":"adulterate","ipa":"/əˈdʌltəˌreɪt/","meaning":"~에 불순물을 섞다, (~을 섞어서) ~의 품질을 떨어뜨리다","example":"Dishonest sellers sometimes adulterate olive oil with cheaper substances.","deck":"vocab"},{"id":2281,"word":"leash","ipa":"/liʃ/","meaning":"(개의 목에 둘러매는) 목줄","example":"Please keep your dog on a leash while in the park.","deck":"vocab"},{"id":2282,"word":"rarity","ipa":"/ˈrɛrəti/","meaning":"희귀성","example":"A snowfall in this desert region is a real rarity.","deck":"vocab"},{"id":2283,"word":"refined","ipa":"/rɪˈfaɪnd/","meaning":"교양 있는, 품위 있는, 세련된, 고상한","example":"She has refined manners and speaks in a gentle voice.","deck":"vocab"},{"id":2284,"word":"corrupt","ipa":"/kəˈrʌpt/","meaning":"부패한, 타락한, 부도덕한","example":"The corrupt official accepted bribes from local businesses.","deck":"vocab"},{"id":2285,"word":"fashion","ipa":"/ˈfæʃən/","meaning":"방법, 방식","example":"He solved the problem in a very clever fashion.","deck":"vocab"},{"id":2286,"word":"respray","ipa":"/ˌriˈspreɪ/","meaning":"도색을 새로 하다","example":"He decided to respray the old car a bright red.","deck":"vocab"},{"id":2287,"word":"circumvent","ipa":"/ˌsɜrkəmˈvɛnt/","meaning":"(어려움이나 법 등을) 피하다, 면하다","example":"They found a clever way to circumvent the strict regulations.","deck":"vocab"},{"id":2288,"word":"nosedive","ipa":"/ˈnoʊzˌdaɪv/","meaning":"(물가, 비용 등이) 급락하다","example":"Stock prices began to nosedive after the shocking announcement.","deck":"vocab"},{"id":2289,"word":"carry away","ipa":"","meaning":"~의 넋을 잃게 하다, ~을 열중케 하다, ~을 흥분시키다","example":"He got carried away and spent far too much money.","deck":"vocab"},{"id":2290,"word":"relentless","ipa":"/rɪˈlɛntləs/","meaning":"(사람이) 집요한, 끈질긴","example":"Her relentless determination finally earned her the championship.","deck":"vocab"},{"id":2291,"word":"on a regular basis","ipa":"","meaning":"정기적으로","example":"She visits her elderly parents on a regular basis.","deck":"vocab"},{"id":2292,"word":"agony","ipa":"/ˈægəni/","meaning":"(극도의 육체적, 정신적) 고통, 괴로움","example":"He was in agony after breaking his leg on the ice.","deck":"vocab"},{"id":2293,"word":"civil service examination","ipa":"/ˈsɪvəl ˈsɜrvɪs ɪgˌzæməˈneɪʃən/","meaning":"공무원 시험","example":"She spent two years preparing for the civil service examination.","deck":"vocab"},{"id":2294,"word":"judicial","ipa":"/dʒuˈdɪʃəl/","meaning":"사법의, 재판의","example":"The judicial system must remain independent from political pressure.","deck":"vocab"},{"id":2295,"word":"carnal","ipa":"/ˈkɑrnəl/","meaning":"(느낌, 욕구 등이) 육체적인, 성적인 <주로 명사 앞에 씀>","example":"The novel explores carnal desire and its consequences.","deck":"vocab"},{"id":2296,"word":"Easter","ipa":"/ˈistər/","meaning":"부활절","example":"The family gathered for a big dinner on Easter Sunday.","deck":"vocab"},{"id":2297,"word":"on cloud nine","ipa":"","meaning":"정말 기분이 좋은, 너무나 행복한","example":"She was on cloud nine after hearing she got the job.","deck":"vocab"},{"id":2298,"word":"spew","ipa":"/spju/","meaning":"뿜어내다, 토해 내다, 분출하다","example":"The volcano continued to spew ash into the sky.","deck":"vocab"},{"id":2299,"word":"migraine","ipa":"/ˈmaɪˌgreɪn/","meaning":"편두통","example":"She had to lie down because of a terrible migraine.","deck":"vocab"},{"id":2300,"word":"pancreas","ipa":"/ˈpæŋkriəs/","meaning":"췌장","example":"The pancreas produces insulin to regulate blood sugar levels.","deck":"vocab"},{"id":2301,"word":"paramedic","ipa":"/ˌpærəˈmɛdɪk/","meaning":"구급대원 <응급상황에서 환자가 병원에 도착하기 전까지 응급처치를 하는 사람>","example":"A paramedic quickly treated the injured driver at the scene.","deck":"vocab"},{"id":2302,"word":"eel","ipa":"/il/","meaning":"장어","example":"We ordered grilled eel at the small Japanese restaurant.","deck":"vocab"},{"id":2303,"word":"mussel","ipa":"/ˈmʌsəl/","meaning":"홍합","example":"The seafood pasta was topped with fresh mussel and shrimp.","deck":"vocab"},{"id":2304,"word":"relinquish","ipa":"/rɪˈlɪŋkwɪʃ/","meaning":"(소유권, 권한 등을) 포기하다, 내주다","example":"He refused to relinquish control of the family business.","deck":"vocab"},{"id":2305,"word":"inmate","ipa":"/ˈɪnˌmeɪt/","meaning":"수감자, 재소자, 입원 환자, 피수용자","example":"Each inmate was allowed one hour of exercise per day.","deck":"vocab"},{"id":2306,"word":"binge","ipa":"/bɪndʒ/","meaning":"(~을) 폭식하다, 폭음하다, 몰아보다, 과하게 탐닉하다 <한꺼번에 몰아서 하는 것을 뜻함>","example":"They decided to binge the entire series over the weekend.","deck":"vocab"},{"id":2307,"word":"due","ipa":"/du/","meaning":"(~을) 받을 예정인, (~이) 이루어질 예정인","example":"The final report is due at the end of this month.","deck":"vocab"},{"id":2308,"word":"utensil","ipa":"/juˈtɛnsəl/","meaning":"(가정에서 사용하는) 기구, 도구","example":"A whisk is a handy utensil for beating eggs.","deck":"vocab"},{"id":2309,"word":"dilate","ipa":"/ˈdaɪˌleɪt/","meaning":"확장시키다, 팽창시키다, 키우다","example":"The doctor used drops to dilate the patient's pupils.","deck":"vocab"},{"id":2310,"word":"pupil","ipa":"/ˈpjupəl/","meaning":"눈동자, 동공","example":"In dim light, the pupil of the eye grows larger.","deck":"vocab"},{"id":2311,"word":"puny","ipa":"/ˈpjuni/","meaning":"작고 연약한","example":"The puny kitten was the smallest of the entire litter.","deck":"vocab"},{"id":2312,"word":"pelvis","ipa":"/ˈpɛlvɪs/","meaning":"골반","example":"She fractured her pelvis in the skiing accident.","deck":"vocab"},{"id":2313,"word":"relish","ipa":"/ˈrɛlɪʃ/","meaning":"즐기다, 좋아하다","example":"He seemed to relish every moment of his sudden fame.","deck":"vocab"},{"id":2314,"word":"tech-savvy","ipa":"/ˈtɛk ˈsævi/","meaning":"최신기술에 능통한","example":"The new intern is very tech-savvy and fixed the network instantly.","deck":"vocab"},{"id":2315,"word":"last resort","ipa":"/ˈlæst rɪˈzɔrt/","meaning":"마지막 수단","example":"Selling the house was their last resort to pay the debts.","deck":"vocab"},{"id":2316,"word":"overhear","ipa":"/ˌoʊvərˈhɪr/","meaning":"(남의 대화 등을) 우연히 듣다","example":"I happened to overhear their conversation on the bus.","deck":"vocab"},{"id":2317,"word":"whacked","ipa":"/wækt/","meaning":"녹초가 된, 몹시 지친, 기진맥진한 <비격식 영국 표현>","example":"After the long hike, I felt completely whacked.","deck":"vocab"},{"id":2318,"word":"tremulous","ipa":"/ˈtrɛmjələs/","meaning":"약간 떠는, 약간 떨리는 <문어체>","example":"She answered in a tremulous voice, clearly frightened.","deck":"vocab"},{"id":2319,"word":"prolonged","ipa":"/prəˈlɔŋd/","meaning":"오래 계속되는, 장기적인","example":"The region suffered from a prolonged drought last summer.","deck":"vocab"},{"id":2320,"word":"upstart","ipa":"/ˈʌpˌstɑrt/","meaning":"벼락출세자 <갑자기 부/명예/권력 등을 얻어서 건방지게 구는 사람>","example":"The arrogant upstart tried to lecture experienced professionals.","deck":"vocab"},{"id":2321,"word":"sitting duck","ipa":"","meaning":"속수무책으로 당하는 약자, 공격하기 쉬운 대상","example":"Alone on the open field, he was a sitting duck.","deck":"vocab"},{"id":2322,"word":"come clean","ipa":"","meaning":"실토하다, 자백하다, 솔직히 털어놓다","example":"He finally decided to come clean about the missing money.","deck":"vocab"},{"id":2323,"word":"induce","ipa":"/ɪnˈdus/","meaning":"유발하다, 초래하다 <격식>","example":"Certain foods can induce a headache in sensitive people.","deck":"vocab"},{"id":2324,"word":"adulthood","ipa":"/əˈdʌltˌhʊd/","meaning":"성인, 성년, 성인임","example":"He moved abroad shortly after reaching adulthood.","deck":"vocab"},{"id":2325,"word":"aspire","ipa":"/əˈspaɪər/","meaning":"(~하기를) 열망하다, 염원하다 <\"aspire to + 동사원형\" 형태로 씀>","example":"Many young athletes aspire to compete in the Olympics.","deck":"vocab"},{"id":2326,"word":"marvelous","ipa":"/ˈmɑrvələs/","meaning":"기막히게 좋은, 경탄할 만한","example":"We had a marvelous time at the seaside resort.","deck":"vocab"},{"id":2327,"word":"containment","ipa":"/kənˈteɪnmənt/","meaning":"(좋지 않은 일의) 억제","example":"The government focused on the containment of the disease outbreak.","deck":"vocab"},{"id":2328,"word":"testimony","ipa":"/ˈtɛstəˌmoʊni/","meaning":"(공식적인) 발언, 진술","example":"Her testimony in court helped convict the criminal.","deck":"vocab"},{"id":2329,"word":"as long as","ipa":"","meaning":"~하는 한은, ~이기만 하면, ~하기만 하면","example":"You can borrow my car as long as you drive carefully.","deck":"vocab"},{"id":2330,"word":"queasy","ipa":"/ˈkwizi/","meaning":"메스꺼운, 욕지기나는 <비격식적인 표현>","example":"The rocking boat made her feel a little queasy.","deck":"vocab"},{"id":2331,"word":"conclude","ipa":"/kənˈklud/","meaning":"끝내다, 마치다, 마무리하다","example":"The professor will conclude the lecture with a short summary.","deck":"vocab"},{"id":2332,"word":"firework","ipa":"/ˈfaɪərˌwɜrk/","meaning":"폭죽","example":"A single firework lit up the entire night sky.","deck":"vocab"},{"id":2333,"word":"mock","ipa":"/mɑk/","meaning":"(특히 흉내를 내며) 놀리다, 조롱하다","example":"The other kids would mock him for his old shoes.","deck":"vocab"},{"id":2334,"word":"meant to ~","ipa":"","meaning":"~하기로 되어 있는, ~할 예정인, ~하지 않으면 안 되는","example":"You were meant to call me back an hour ago.","deck":"vocab"},{"id":2335,"word":"conviction","ipa":"/kənˈvɪkʃən/","meaning":"(강한) 신념, 의견","example":"She spoke with deep conviction about the need for change.","deck":"vocab"},{"id":2336,"word":"abdomen","ipa":"/ˈæbdəmən/","meaning":"배, 복부","example":"The patient complained of sharp pain in the lower abdomen.","deck":"vocab"},{"id":2337,"word":"start over","ipa":"","meaning":"다시 시작하다","example":"After the mistake, we had to start over from scratch.","deck":"vocab"},{"id":2338,"word":"gal pal","ipa":"/ˈgæl ˈpæl/","meaning":"여자인 친구","example":"She went shopping with her gal pal all afternoon.","deck":"vocab"},{"id":2339,"word":"project","ipa":"/prəˈdʒɛkt/","meaning":"예상하다, 추정하다","example":"Analysts project a steady rise in sales next year.","deck":"vocab"},{"id":2340,"word":"integrity","ipa":"/ɪnˈtɛgrəti/","meaning":"진실성, 고결함, 정직, 청렴","example":"The judge was admired for her honesty and integrity.","deck":"vocab"},{"id":2341,"word":"pristine","ipa":"/ˈprɪsˌtin/","meaning":"완전 새 것 같은, 아주 깨끗한","example":"The mountain lake was pristine and perfectly clear.","deck":"vocab"},{"id":2342,"word":"discrimination","ipa":"/dɪˌskrɪməˈneɪʃən/","meaning":"(차이를 구분해 낼 수 있는) 식별력, 판별력","example":"A wine expert needs great discrimination in judging flavors.","deck":"vocab"},{"id":2343,"word":"light up","ipa":"","meaning":"(빛, 색이) ~을 밝히다, 환하게 만들다","example":"The fireworks lit up the sky in brilliant colors.","deck":"vocab"},{"id":2344,"word":"for sale","ipa":"","meaning":"팔려고 내놓은","example":"They put their old house up for sale last week.","deck":"vocab"},{"id":2345,"word":"digest","ipa":"/daɪˈdʒɛst/","meaning":"(음식을) 소화하다, 소화시키다","example":"It takes time to digest a heavy meal properly.","deck":"vocab"},{"id":2346,"word":"bizarre","ipa":"/bɪˈzɑr/","meaning":"기괴한, 기이한, 특이한","example":"He told us a bizarre story about talking animals.","deck":"vocab"},{"id":2347,"word":"archive","ipa":"/ˈɑrˌkaɪv/","meaning":"기록 보관소, 보존 기록","example":"The old newspapers are stored in the city archive.","deck":"vocab"},{"id":2348,"word":"sounds like a plan","ipa":"","meaning":"좋아요, 그래요, 좋은 생각이야 <상대의 말에 동의를 나타내는 표현>","example":"Meeting at noon sounds like a plan to everyone.","deck":"vocab"},{"id":2349,"word":"flimsy","ipa":"/ˈflɪmzi/","meaning":"조잡한, 엉성하게 만든, 약한","example":"The flimsy umbrella broke in the first strong gust.","deck":"vocab"},{"id":2350,"word":"ballot","ipa":"/ˈbælət/","meaning":"무기명 투표, 비밀 투표","example":"Members cast their votes by secret ballot.","deck":"vocab"},{"id":2351,"word":"shove","ipa":"/ʃʌv/","meaning":"(거칠게) 밀치다, 떠밀다","example":"He gave the heavy door a hard shove to open it.","deck":"vocab"},{"id":2352,"word":"forestry","ipa":"/ˈfɔrəstri/","meaning":"임학, 임업, 삼림 관리","example":"She studied forestry to help manage the national parks.","deck":"vocab"},{"id":2353,"word":"infuriate","ipa":"/ɪnˈfjʊriˌeɪt/","meaning":"극도로 화나게 만들다","example":"His constant lateness never fails to infuriate the boss.","deck":"vocab"},{"id":2354,"word":"wretched","ipa":"/ˈrɛtʃɪd/","meaning":"기분이 매우 안 좋은, 비참한, 몸 상태가 아주 나쁜","example":"He felt wretched and feverish after catching the flu.","deck":"vocab"},{"id":2355,"word":"overseer","ipa":"/ˈoʊvərˌsiər/","meaning":"감독관, 감독 기관 <시스템, 활동 등이 적절히 이뤄지도록 감독하는 사람>","example":"The overseer inspected the workers' progress every morning.","deck":"vocab"},{"id":2356,"word":"out of business","ipa":"","meaning":"폐업한","example":"The old bookstore finally went out of business last year.","deck":"vocab"},{"id":2357,"word":"ease into ~","ipa":"","meaning":"~에 서서히 익숙해지다, ~에 서서히 친숙해지다","example":"She slowly eased into her new role as manager.","deck":"vocab"},{"id":2358,"word":"have got","ipa":"","meaning":"있다, 가지고 있다, 가지다","example":"I have got a meeting scheduled for early tomorrow.","deck":"vocab"},{"id":2359,"word":"predecessor","ipa":"/ˈprɛdəˌsɛsər/","meaning":"전임자","example":"The new director continued the projects started by her predecessor.","deck":"vocab"},{"id":2360,"word":"distribution","ipa":"/ˌdɪstrəˈbjuʃən/","meaning":"유통 <제품/상품을 생산자에서 소비자에게 도달되게 하는 과정>","example":"The company improved the distribution of its products nationwide.","deck":"vocab"},{"id":2361,"word":"belly","ipa":"/ˈbɛli/","meaning":"배","example":"The baby giggled when I tickled his round belly.","deck":"vocab"},{"id":2362,"word":"footage","ipa":"/ˈfʊtɪdʒ/","meaning":"(특정한 사건을 담은) 장면, 화면, 영상","example":"Security footage captured the thief entering the building.","deck":"vocab"},{"id":2363,"word":"malicious","ipa":"/məˈlɪʃəs/","meaning":"악의적인, 적의 있는","example":"She spread malicious rumors about her coworker.","deck":"vocab"},{"id":2364,"word":"landline","ipa":"/ˈlændˌlaɪn/","meaning":"일반 전화","example":"Many households no longer keep a traditional landline.","deck":"vocab"},{"id":2365,"word":"evoke","ipa":"/ɪˈvoʊk/","meaning":"~을 떠올리게 만들다, 불러일으키다, 상기시키다 <격식 있는 표현>","example":"The old song can evoke memories of my childhood.","deck":"vocab"},{"id":2366,"word":"bona fide","ipa":"","meaning":"진정한, 진실된, 진짜의 <라틴어에서 유래한 표현>","example":"He is a bona fide expert in ancient languages.","deck":"vocab"},{"id":2367,"word":"adversity","ipa":"/ædˈvɜrsəti/","meaning":"역경 <격식>","example":"She showed great courage in the face of adversity.","deck":"vocab"},{"id":2368,"word":"give ~ a go","ipa":"","meaning":"~을 한번 해 보다","example":"I've never tried skiing, but I'll give it a go.","deck":"vocab"},{"id":2369,"word":"uncalled for","ipa":"","meaning":"(행동, 발언이) 부적절한, 부당한","example":"His rude comment was completely uncalled for.","deck":"vocab"},{"id":2370,"word":"euphoria","ipa":"/juˈfɔriə/","meaning":"희열, 도취, 행복감","example":"A wave of euphoria swept over the winning team.","deck":"vocab"},{"id":2371,"word":"subsequently","ipa":"/ˈsʌbsɪkwəntli/","meaning":"그 뒤에, 나중에 <격식 있는 표현>","example":"He was arrested and subsequently released on bail.","deck":"vocab"},{"id":2372,"word":"desertification","ipa":"/dɪˌzɜrtəfɪˈkeɪʃən/","meaning":"사막화","example":"Overgrazing is a major cause of desertification in the region.","deck":"vocab"},{"id":2373,"word":"repentant","ipa":"/rɪˈpɛntənt/","meaning":"뉘우치는, 회개하는, 후회하는","example":"The repentant thief returned everything he had stolen.","deck":"vocab"},{"id":2374,"word":"circumscribe","ipa":"/ˈsɜrkəmˌskraɪb/","meaning":"(권리, 자유 등을) 제한하다, 억제하다","example":"New rules circumscribe the powers of local officials.","deck":"vocab"},{"id":2375,"word":"home remedy","ipa":"/ˈhoʊm ˈrɛmədi/","meaning":"민간요법, 가정요법","example":"My grandmother swears by a home remedy for the common cold.","deck":"vocab"},{"id":2376,"word":"square","ipa":"/skwɛr/","meaning":"~와 일치하다, 들어맞다","example":"His story doesn't quite square with the evidence.","deck":"vocab"},{"id":2377,"word":"atheist","ipa":"/ˈeɪθiɪst/","meaning":"무신론자","example":"As an atheist, he does not believe in any god.","deck":"vocab"},{"id":2378,"word":"contemptuous","ipa":"/kənˈtɛmptʃuəs/","meaning":"경멸하는, 업신여기는","example":"She gave him a contemptuous look and walked away.","deck":"vocab"},{"id":2379,"word":"dialect","ipa":"/ˈdaɪəˌlɛkt/","meaning":"방언, 사투리","example":"The villagers speak a dialect quite different from the standard language.","deck":"vocab"},{"id":2380,"word":"ad hoc","ipa":"","meaning":"즉석의, 필요에 의해 즉석에서 마련된 <라틴어에서 유래. 한시적으로 마련된 것을 뜻함>","example":"They formed an ad hoc committee to handle the emergency.","deck":"vocab"},{"id":2381,"word":"muster","ipa":"/ˈmʌstər/","meaning":"(병사, 병력 등을) 소집하다, 동원하다","example":"The general tried to muster more troops for the battle.","deck":"vocab"},{"id":2382,"word":"reincarnation","ipa":"/ˌriɪnkɑrˈneɪʃən/","meaning":"환생","example":"Many Hindus believe in the reincarnation of the soul.","deck":"vocab"},{"id":2383,"word":"fidelity","ipa":"/fɪˈdɛləti/","meaning":"(배우자에 대한) 신의, 정절","example":"He promised lifelong fidelity to his wife.","deck":"vocab"},{"id":2384,"word":"distress","ipa":"/dɪˈstrɛs/","meaning":"괴롭히다, 고통스럽게 하다","example":"The sad news continued to distress her for weeks.","deck":"vocab"},{"id":2385,"word":"save","ipa":"/seɪv/","meaning":"(돈을) ~을 모으다, ~을 저축하다","example":"They tried to save enough money to buy a house.","deck":"vocab"},{"id":2386,"word":"foot traffic","ipa":"/ˈfʊt ˈtræfɪk/","meaning":"유동 인구","example":"The new store location gets a lot of foot traffic.","deck":"vocab"},{"id":2387,"word":"in vain","ipa":"","meaning":"헛수고인, 헛되이, 허사가 되어","example":"They searched all night, but their efforts were in vain.","deck":"vocab"},{"id":2388,"word":"strenuous","ipa":"/ˈstrɛnjuəs/","meaning":"불굴의, 굽히지 않는, 완강한","example":"She made strenuous efforts to finish the marathon.","deck":"vocab"},{"id":2389,"word":"subordinate","ipa":"/səˈbɔrdənət/","meaning":"(~에) 종속된","example":"In this system, personal wishes are subordinate to the group's needs.","deck":"vocab"},{"id":2390,"word":"feverish","ipa":"/ˈfivərɪʃ/","meaning":"열이 나는, 열로 인한","example":"The child felt hot and feverish throughout the night.","deck":"vocab"},{"id":2391,"word":"whim","ipa":"/wɪm/","meaning":"(일시적인) 기분, 변덕","example":"He bought the expensive watch on a sudden whim.","deck":"vocab"},{"id":2392,"word":"antiquity","ipa":"/ænˈtɪkwəti/","meaning":"유물, 고대 유물 <주로 복수형으로 씀>","example":"The museum houses many rare antiquities from ancient Greece.","deck":"vocab"},{"id":2393,"word":"disarray","ipa":"/ˌdɪsəˈreɪ/","meaning":"(상황, 장소의) 혼란스러움, 혼란","example":"The office was in complete disarray after the sudden move.","deck":"vocab"},{"id":2394,"word":"defiant","ipa":"/dɪˈfaɪənt/","meaning":"반항하는, 저항하는","example":"The defiant teenager refused to obey his parents' rules.","deck":"vocab"},{"id":2395,"word":"scoop","ipa":"/skup/","meaning":"뜨다, 파다, 푸다, 퍼 올리다","example":"She used a spoon to scoop the ice cream into bowls.","deck":"vocab"},{"id":2396,"word":"rioter","ipa":"/ˈraɪətər/","meaning":"폭도","example":"One rioter threw a rock through the shop window.","deck":"vocab"},{"id":2397,"word":"publicize","ipa":"/ˈpʌbləˌsaɪz/","meaning":"(일반 사람들에게) 공표하다, 알리다, 홍보하다","example":"The company spent millions to publicize its new product.","deck":"vocab"},{"id":2398,"word":"pack up","ipa":"","meaning":"(기계가) 작동을 멈추다, 서다","example":"My old laptop finally packed up during the meeting.","deck":"vocab"},{"id":2399,"word":"fraction","ipa":"/ˈfrækʃən/","meaning":"아주 적은 일부, 아주 조금","example":"Only a small fraction of the applicants were accepted.","deck":"vocab"},{"id":2400,"word":"deliberate","ipa":"/dɪˈlɪbərət/","meaning":"고의의, 의도적인, 계획적인","example":"The insult was clearly deliberate, not an accident.","deck":"vocab"},{"id":2401,"word":"get back on the horse","ipa":"","meaning":"실패했던 걸 다시 시도하다","example":"After the injury he had to get back on the horse and race again.","deck":"vocab"},{"id":2402,"word":"debut","ipa":"/deɪˈbjuː/","meaning":"데뷔, 첫 출연, 첫 등장","example":"Her film debut earned rave reviews from every major critic.","deck":"vocab"},{"id":2403,"word":"like","ipa":"/laɪk/","meaning":"(인용문 앞에서) ~라고 말하다","example":"She was like, \"I can't believe you actually did that.\"","deck":"vocab"},{"id":2404,"word":"provocation","ipa":"/ˌprɑːvəˈkeɪʃən/","meaning":"도발, 자극, 화낼 이유","example":"He lost his temper at the slightest provocation from his coworkers.","deck":"vocab"},{"id":2405,"word":"complementary","ipa":"/ˌkɑːmpləˈmentri/","meaning":"상호 보완적인","example":"Their skills are complementary, so they make an excellent team.","deck":"vocab"},{"id":2406,"word":"get there","ipa":"","meaning":"(과제, 목표 등을) 해 내다, 달성하다","example":"It's a tough goal, but with practice we'll get there.","deck":"vocab"},{"id":2407,"word":"go haywire","ipa":"","meaning":"고장 나다, 잘못되다, 통제 불능이 되다, 맛 가다","example":"The computer started to go haywire right before the deadline.","deck":"vocab"},{"id":2408,"word":"contender","ipa":"/kənˈtendər/","meaning":"도전자, 경쟁자, 우승 후보 <보통 대회나 경쟁에 참여한 사람>","example":"She quickly became a serious contender for the championship title.","deck":"vocab"},{"id":2409,"word":"skyrocket","ipa":"/ˈskaɪˌrɑːkɪt/","meaning":"(물가 등이) 급등하다","example":"Housing prices skyrocketed in the city over the past year.","deck":"vocab"},{"id":2410,"word":"hold on to ~","ipa":"","meaning":"(자기에게 유리한 것을) 고수하다, 지키다","example":"You should hold on to those old coins; they're valuable now.","deck":"vocab"},{"id":2411,"word":"projectile","ipa":"/prəˈdʒektəl/","meaning":"(총알, 포탄 등의) 발사체, 발사물","example":"The cannon launched a heavy projectile across the open field.","deck":"vocab"},{"id":2412,"word":"gill","ipa":"/ɡɪl/","meaning":"아가미","example":"Fish breathe by passing water over their delicate gills.","deck":"vocab"},{"id":2413,"word":"pathetically","ipa":"/pəˈθetɪkli/","meaning":"애처롭게, 애절하게, 감상적으로","example":"The lost puppy whined pathetically outside the locked front door.","deck":"vocab"},{"id":2414,"word":"grant","ipa":"/ɡrænt/","meaning":"(정부나 단체에서 주는) 보조금","example":"The university received a large grant for cancer research.","deck":"vocab"},{"id":2415,"word":"clingy","ipa":"/ˈklɪŋi/","meaning":"(사람이) 집착하는, 들러붙는 <타인에게 지나치게 의존하려는>","example":"Her new boyfriend became clingy and texted her every few minutes.","deck":"vocab"},{"id":2416,"word":"rehabilitate","ipa":"/ˌriːhəˈbɪlɪteɪt/","meaning":"재활 치료를 하다, 갱생시키다","example":"The program helps rehabilitate injured soldiers back into daily life.","deck":"vocab"},{"id":2417,"word":"enchanted","ipa":"/ɪnˈtʃæntɪd/","meaning":"마법에 걸린","example":"The enchanted forest glowed softly under the pale moonlight.","deck":"vocab"},{"id":2418,"word":"genuinely","ipa":"/ˈdʒenjuɪnli/","meaning":"진짜로, 진정으로, 진심 어리게","example":"I'm genuinely happy that you finally got the promotion.","deck":"vocab"},{"id":2419,"word":"defrost","ipa":"/diːˈfrɔːst/","meaning":"(특히 식품을) 해동하다","example":"Remember to defrost the chicken before you start cooking dinner.","deck":"vocab"},{"id":2420,"word":"not to mention","ipa":"","meaning":"~은 말할 것도 없고, ~은 물론이고","example":"The trip was expensive, not to mention exhausting for everyone.","deck":"vocab"},{"id":2421,"word":"compelling","ipa":"/kəmˈpelɪŋ/","meaning":"설득력 있는, 강력한","example":"The lawyer presented a compelling argument that swayed the jury.","deck":"vocab"},{"id":2422,"word":"benevolent","ipa":"/bəˈnevələnt/","meaning":"(특히 권위 있는 위치의 사람들이) 자애로운 <격식>","example":"The benevolent king lowered taxes to help his struggling people.","deck":"vocab"},{"id":2423,"word":"feed on ~","ipa":"","meaning":"(동물이) ~을 먹다, ~을 먹고 살다","example":"Owls typically feed on small rodents that come out at night.","deck":"vocab"},{"id":2424,"word":"root for ~","ipa":"","meaning":"~를 응원하다","example":"The whole town came out to root for the local team.","deck":"vocab"},{"id":2425,"word":"spatula","ipa":"/ˈspætʃələ/","meaning":"주걱 <요리 중에 음식을 뒤집는 도구>","example":"She flipped the pancakes carefully with a wooden spatula.","deck":"vocab"},{"id":2426,"word":"in good hands","ipa":"","meaning":"(맡겨서) 안심할 수 있는, 잘 관리되는","example":"Don't worry about your dog; he's in good hands with us.","deck":"vocab"},{"id":2427,"word":"smirk","ipa":"/smɜːrk/","meaning":"히죽히죽 웃다","example":"He smirked knowingly when she finally realized her mistake.","deck":"vocab"},{"id":2428,"word":"triumph","ipa":"/ˈtraɪəmf/","meaning":"성취, 업적, 대성공, 개가(凱歌)","example":"Winning the award was a personal triumph after years of effort.","deck":"vocab"},{"id":2429,"word":"ornamental","ipa":"/ˌɔːrnəˈmentl/","meaning":"장식용의","example":"The garden was full of ornamental plants rather than vegetables.","deck":"vocab"},{"id":2430,"word":"incorrigible","ipa":"/ɪnˈkɔːrɪdʒəbl/","meaning":"구제 불능의, 고질적인 <사람이 고치거나 개선할 수 없는>","example":"He's an incorrigible liar who never admits the truth.","deck":"vocab"},{"id":2431,"word":"in jeopardy","ipa":"","meaning":"위기에 처한","example":"The company's future was in jeopardy after the massive lawsuit.","deck":"vocab"},{"id":2432,"word":"ferment","ipa":"/fərˈment/","meaning":"발효되다","example":"The grapes are left to ferment for several weeks in barrels.","deck":"vocab"},{"id":2433,"word":"tenuous","ipa":"/ˈtenjuəs/","meaning":"보잘것없는, 미약한, 시시한","example":"His connection to the crime was tenuous at best.","deck":"vocab"},{"id":2434,"word":"enticing","ipa":"/ɪnˈtaɪsɪŋ/","meaning":"유혹적인","example":"The smell of fresh bread was absolutely enticing this morning.","deck":"vocab"},{"id":2435,"word":"compliment","ipa":"/ˈkɑːmplɪment/","meaning":"칭찬하다","example":"She complimented him on his beautifully written speech.","deck":"vocab"},{"id":2436,"word":"graze","ipa":"/ɡreɪz/","meaning":"(피부가) 까진 상처, 긁힌 상처, 찰과상","example":"He got a nasty graze on his knee after falling.","deck":"vocab"},{"id":2437,"word":"wiretap","ipa":"/ˈwaɪərtæp/","meaning":"도청 장치","example":"Police installed a wiretap to record the suspect's phone calls.","deck":"vocab"},{"id":2438,"word":"nonconformist","ipa":"/ˌnɑːnkənˈfɔːrmɪst/","meaning":"이단아 <일반적인 관행을 따르지 않는 사람>","example":"As a nonconformist, she refused to follow the company dress code.","deck":"vocab"},{"id":2439,"word":"mesmerize","ipa":"/ˈmezməraɪz/","meaning":"최면을 걸듯 마음을 사로잡다, 완전 넋을 빼놓다","example":"The dancer's graceful movements mesmerized the entire audience.","deck":"vocab"},{"id":2440,"word":"preconception","ipa":"/ˌpriːkənˈsepʃən/","meaning":"선입견","example":"Try to set aside your preconceptions before meeting the new team.","deck":"vocab"},{"id":2441,"word":"fathom","ipa":"/ˈfæðəm/","meaning":"(의미 등을) 헤아리다, 가늠하다","example":"I can't fathom why she would quit such a great job.","deck":"vocab"},{"id":2442,"word":"mandate","ipa":"/ˈmændeɪt/","meaning":"(법, 규정 등으로) 강제하다, 요구하다","example":"The new law mandates that all cars have safety airbags.","deck":"vocab"},{"id":2443,"word":"mandate","ipa":"/ˈmændeɪt/","meaning":"(공식적인) 지시, 명령","example":"The governor received a clear mandate to reform the schools.","deck":"vocab"},{"id":2444,"word":"corridor","ipa":"/ˈkɔːrɪdɔːr/","meaning":"복도, 회랑","example":"She hurried down the long corridor toward the meeting room.","deck":"vocab"},{"id":2445,"word":"minuscule","ipa":"/ˈmɪnəskjuːl/","meaning":"아주 적은, 아주 작은","example":"The chances of winning the lottery are absolutely minuscule.","deck":"vocab"},{"id":2446,"word":"roll on","ipa":"","meaning":"(시간이) 흐르다","example":"As the years rolled on, the small village slowly grew.","deck":"vocab"},{"id":2447,"word":"frowny","ipa":"/ˈfraʊni/","meaning":"(얼굴을) 찡그린","example":"The child drew a frowny face when she felt upset.","deck":"vocab"},{"id":2448,"word":"resort to ~","ipa":"","meaning":"~에 기대다, 의지하다","example":"When words failed, they resorted to violence to settle the dispute.","deck":"vocab"},{"id":2449,"word":"embody","ipa":"/ɪmˈbɑːdi/","meaning":"상징하다, 구현하다, 구체화하다","example":"She embodies the spirit of kindness in everything she does.","deck":"vocab"},{"id":2450,"word":"embody","ipa":"/ɪmˈbɑːdi/","meaning":"포함하다, 담다 (격식)","example":"The report embodies the findings of a decade of research.","deck":"vocab"},{"id":2451,"word":"communal","ipa":"/kəˈmjuːnl/","meaning":"(특히 함께 사는 사람들) 공동의, 공용의","example":"The residents share a communal kitchen on the ground floor.","deck":"vocab"},{"id":2452,"word":"alleyway","ipa":"/ˈæliweɪ/","meaning":"골목, 좁은 길","example":"The cat slipped quietly into the dark, narrow alleyway.","deck":"vocab"},{"id":2453,"word":"wee hours","ipa":"/ˌwiː ˈaʊərz/","meaning":"꼭두새벽 <자정에서 해 뜰 때까지를 가리킴>","example":"They talked until the wee hours of the morning.","deck":"vocab"},{"id":2454,"word":"standard","ipa":"/ˈstændərd/","meaning":"(특정 부대를 상징하는) 기(旗), 군기","example":"The soldiers marched proudly behind their regiment's standard.","deck":"vocab"},{"id":2455,"word":"wreak havoc","ipa":"","meaning":"(~에) 큰 피해를 주다","example":"The storm wreaked havoc across the coastal towns overnight.","deck":"vocab"},{"id":2456,"word":"tortured","ipa":"/ˈtɔːrtʃərd/","meaning":"극심한 고통에 시달리는, 지독히 고통스러운 <명사 앞에만 씀>","example":"The poet was a tortured soul haunted by past regrets.","deck":"vocab"},{"id":2457,"word":"reap","ipa":"/riːp/","meaning":"(농작물을) 수확하다, 거둬들이다","example":"The farmers reap the wheat every year in late summer.","deck":"vocab"},{"id":2458,"word":"feud","ipa":"/fjuːd/","meaning":"(오랜 동안의) 불화, 반목","example":"The two families had a bitter feud lasting many generations.","deck":"vocab"},{"id":2459,"word":"smolder","ipa":"/ˈsmoʊldər/","meaning":"(불이) 불꽃 없이 서서히 연소하다","example":"The campfire continued to smolder long after everyone slept.","deck":"vocab"},{"id":2460,"word":"smolder","ipa":"/ˈsmoʊldər/","meaning":"들끓다, 끓어오르다, 가득 차다","example":"Resentment smoldered within him for years after the betrayal.","deck":"vocab"},{"id":2461,"word":"futon","ipa":"/ˈfuːtɑːn/","meaning":"소파 침대 <펼쳐서 침대로 쓸 수도 있고, 접어서 소파로 쓸 수 있는 가구>","example":"Our guests slept on the futon in the living room.","deck":"vocab"},{"id":2462,"word":"straightforward","ipa":"/ˌstreɪtˈfɔːrwərd/","meaning":"간단한, 쉬운, 복잡하지 않은","example":"The instructions were straightforward and easy to follow.","deck":"vocab"},{"id":2463,"word":"telecommute","ipa":"/ˈtelɪkəmjuːt/","meaning":"(컴퓨터 등에 접속해서) 재택 근무하다","example":"Many employees now telecommute several days a week from home.","deck":"vocab"},{"id":2464,"word":"house","ipa":"/haʊz/","meaning":"보관하다, 소장하다, 수용하다","example":"The museum houses thousands of priceless ancient artifacts.","deck":"vocab"},{"id":2465,"word":"regain","ipa":"/rɪˈɡeɪn/","meaning":"(능력, 특성 등을) 되찾다, 회복하다","example":"It took months for him to regain his full strength.","deck":"vocab"},{"id":2466,"word":"relent","ipa":"/rɪˈlent/","meaning":"(기세, 강도 등이) 수그러들다, 누그러지다","example":"The heavy rain finally relented late in the afternoon.","deck":"vocab"},{"id":2467,"word":"sanction","ipa":"/ˈsæŋkʃən/","meaning":"허가, 승인, 인가","example":"The project cannot proceed without official sanction from the board.","deck":"vocab"},{"id":2468,"word":"flesh","ipa":"/fleʃ/","meaning":"(마음, 정신에 대비되는 사람의) 육체, 몸 <주로 the flesh로 씀>","example":"The spirit is willing, but the flesh is weak.","deck":"vocab"},{"id":2469,"word":"conform","ipa":"/kənˈfɔːrm/","meaning":"(~에) 순응하다, 따르다","example":"New students are expected to conform to the school's rules.","deck":"vocab"},{"id":2470,"word":"hayride","ipa":"/ˈheɪraɪd/","meaning":"건초 더미 위에 올라타고 가기","example":"The children enjoyed a bumpy hayride through the autumn fields.","deck":"vocab"},{"id":2471,"word":"acrid","ipa":"/ˈækrɪd/","meaning":"(냄새나 맛이) 매캐한, 콕 쏘는 듯한","example":"The acrid smoke from the fire made everyone cough.","deck":"vocab"},{"id":2472,"word":"defund","ipa":"/diːˈfʌnd/","meaning":"~에 대한 자금 지원을 중단하다","example":"Lawmakers threatened to defund the program after the scandal broke.","deck":"vocab"},{"id":2473,"word":"ratify","ipa":"/ˈrætɪfaɪ/","meaning":"비준하다 (헌법상의 조약 체결권자가 조약에 최종적으로 동의함)","example":"The senate voted to ratify the international climate treaty.","deck":"vocab"},{"id":2474,"word":"ratify","ipa":"/ˈrætɪfaɪ/","meaning":"승인하다 <합의나 협정에 사인하거나 격식을 갖춘 방법으로>","example":"Both parties met to ratify the terms of the new agreement.","deck":"vocab"},{"id":2475,"word":"wig","ipa":"/wɪɡ/","meaning":"가발","example":"The actor wore a curly wig for his stage role.","deck":"vocab"},{"id":2476,"word":"excavate","ipa":"/ˈekskəveɪt/","meaning":"(땅을) 파다","example":"Archaeologists began to excavate the site near the old temple.","deck":"vocab"},{"id":2477,"word":"contention","ipa":"/kənˈtenʃən/","meaning":"(논쟁 등에서 말하는) 주장, 견해","example":"Her contention is that the new policy will hurt small businesses.","deck":"vocab"},{"id":2478,"word":"mercifully","ipa":"/ˈmɜːrsɪfəli/","meaning":"다행히도","example":"Mercifully, no one was seriously hurt in the accident.","deck":"vocab"},{"id":2479,"word":"stab","ipa":"/stæb/","meaning":"(칼같이 뾰족한 것으로) 찌르다","example":"The attacker tried to stab him with a kitchen knife.","deck":"vocab"},{"id":2480,"word":"admire","ipa":"/ədˈmaɪər/","meaning":"(사물을) 감상하다 <즐겁게 바라본다는 뜻>","example":"We stopped to admire the stunning view from the mountaintop.","deck":"vocab"},{"id":2481,"word":"condemn","ipa":"/kənˈdem/","meaning":"~가 유죄임을 보여주다, 유죄임을 시사하다","example":"The fingerprints on the weapon seemed to condemn the suspect.","deck":"vocab"},{"id":2482,"word":"putative","ipa":"/ˈpjuːtətɪv/","meaning":"추정의, 추정 상의, ~로 추정되는, 추정되고 있는 <법률 용어>","example":"The putative father was asked to take a DNA test.","deck":"vocab"},{"id":2483,"word":"riddle","ipa":"/ˈrɪdl/","meaning":"수수께끼","example":"The old man told the children a clever riddle to solve.","deck":"vocab"},{"id":2484,"word":"rigorously","ipa":"/ˈrɪɡərəsli/","meaning":"엄격히, 엄밀히","example":"Each product is rigorously tested before it reaches the market.","deck":"vocab"},{"id":2485,"word":"hypnotize","ipa":"/ˈhɪpnətaɪz/","meaning":"~에게 최면을 걸다","example":"The therapist tried to hypnotize her to ease the anxiety.","deck":"vocab"},{"id":2486,"word":"retrial","ipa":"/ˌriːˈtraɪəl/","meaning":"(재판의) 재심 <확정판결로 사건이 종결되었으나 중대한 결함이 발견되었을 때 다시 하는 재판>","example":"The judge ordered a retrial after new evidence emerged.","deck":"vocab"},{"id":2487,"word":"draw attention","ipa":"","meaning":"관심을 끌다, 주의를 끌다","example":"The bright poster was designed to draw attention to the event.","deck":"vocab"},{"id":2488,"word":"wield","ipa":"/wiːld/","meaning":"(무기, 도구를) 휘두르다, 들다","example":"The knight learned to wield a heavy sword in battle.","deck":"vocab"},{"id":2489,"word":"influx","ipa":"/ˈɪnflʌks/","meaning":"밀어닥침, 밀려듦, 유입","example":"The city saw a sudden influx of tourists this summer.","deck":"vocab"},{"id":2490,"word":"herbivore","ipa":"/ˈɜːrbɪvɔːr/","meaning":"초식 동물","example":"A cow is a herbivore that grazes on grass all day.","deck":"vocab"},{"id":2491,"word":"labyrinth","ipa":"/ˈlæbərɪnθ/","meaning":"미로 <격식>","example":"The old castle was a labyrinth of winding stone passages.","deck":"vocab"},{"id":2492,"word":"nerd","ipa":"/nɜːrd/","meaning":"얼간이, 멍텅구리, 자기 분야만 아는 괴짜","example":"He's a total computer nerd who codes every single weekend.","deck":"vocab"},{"id":2493,"word":"den","ipa":"/den/","meaning":"작은 거실 <손님이 왔을 때도 사용하는 living room보다는 사적인 공간>","example":"Dad likes to read the newspaper in his cozy den.","deck":"vocab"},{"id":2494,"word":"impeccable","ipa":"/ɪmˈpekəbl/","meaning":"죄를 저지르지 않는 <신학 용어>","example":"In theology, an impeccable being is incapable of committing sin.","deck":"vocab"},{"id":2495,"word":"prevalent","ipa":"/ˈprevələnt/","meaning":"(특정 시기, 장소에) 일반적인, 널리 퍼져 있는","example":"Smartphones are prevalent among teenagers across the entire country.","deck":"vocab"},{"id":2496,"word":"vote of confidence","ipa":"","meaning":"신뢰의 말","example":"Her promotion was a real vote of confidence from the boss.","deck":"vocab"},{"id":2497,"word":"salvage","ipa":"/ˈsælvɪdʒ/","meaning":"(특히 재난사고로부터 재화의) 구조, 인양","example":"The salvage of the sunken ship took several difficult months.","deck":"vocab"},{"id":2498,"word":"salvage","ipa":"/ˈsælvɪdʒ/","meaning":"구해내다, 건져내다, 회수하다","example":"They managed to salvage a few photos from the flooded house.","deck":"vocab"},{"id":2499,"word":"malleable","ipa":"/ˈmæliəbl/","meaning":"(사람, 사상 등이) 영향을 잘 받는, 잘 변하는","example":"Young children have malleable minds that absorb new ideas quickly.","deck":"vocab"},{"id":2500,"word":"malleable","ipa":"/ˈmæliəbl/","meaning":"펴 늘일 수 있는, 전성이 있는, 가단성 있는","example":"Gold is a soft, malleable metal that bends easily.","deck":"vocab"},{"id":2501,"word":"emanate","ipa":"/ˈeməneɪt/","meaning":"(느낌, 특징 등이) 뿜어져 나오다","example":"A sense of calm seemed to emanate from the quiet garden.","deck":"vocab"},{"id":2502,"word":"versatile","ipa":"/ˈvɜːrsətl/","meaning":"(사물이) 다용도의, 다목적의","example":"This versatile tool can cut, sand, and polish wood.","deck":"vocab"},{"id":2503,"word":"voracious","ipa":"/vəˈreɪʃəs/","meaning":"(식욕이) 왕성한","example":"The growing boy had a voracious appetite at every meal.","deck":"vocab"},{"id":2504,"word":"enzyme","ipa":"/ˈenzaɪm/","meaning":"효소 <생물학 용어>","example":"This enzyme helps break down the food in your stomach.","deck":"vocab"},{"id":2505,"word":"objectify","ipa":"/əbˈdʒektɪfaɪ/","meaning":"~을 대상화하다, ~을 물건 취급하다","example":"The advertisement was criticized for objectifying women.","deck":"vocab"},{"id":2506,"word":"preservative","ipa":"/prɪˈzɜːrvətɪv/","meaning":"방부제","example":"This bread contains no artificial preservatives or added colors.","deck":"vocab"},{"id":2507,"word":"transitory","ipa":"/ˈtrænsətɔːri/","meaning":"일시적인, 덧없는 <격식>","example":"Fame can be transitory, fading long before real talent does.","deck":"vocab"},{"id":2508,"word":"mount","ipa":"/maʊnt/","meaning":"~을 조직해서 시작하다, 개시하다","example":"The activists mounted a campaign to protect the local forest.","deck":"vocab"},{"id":2509,"word":"stem","ipa":"/stem/","meaning":"(~에서) 생겨나다, 기인하다, 일어나다, 유래하다","example":"Many of her fears stem from a childhood accident.","deck":"vocab"},{"id":2510,"word":"stem","ipa":"/stem/","meaning":"(흐름을) 막다, 저지하다","example":"Doctors worked quickly to stem the bleeding from the wound.","deck":"vocab"},{"id":2511,"word":"glorify","ipa":"/ˈɡlɔːrɪfaɪ/","meaning":"미화하다 <주로 부정적인 어감>","example":"The film was criticized for glorifying war and violence.","deck":"vocab"},{"id":2512,"word":"inconceivable","ipa":"/ˌɪnkənˈsiːvəbl/","meaning":"상상도 할 수 없는, 생각도 할 수 없는","example":"It's inconceivable that she would betray her closest friends.","deck":"vocab"},{"id":2513,"word":"frost","ipa":"/frɔːst/","meaning":"크림을 바르다, 프로스팅을 입히다, 아이싱을 입히다 <주로 미국에서 쓰는 표현>","example":"She carefully frosted the birthday cake with pink icing.","deck":"vocab"},{"id":2514,"word":"infidelity","ipa":"/ˌɪnfɪˈdeləti/","meaning":"불륜, 외도","example":"Their marriage fell apart after his repeated infidelity.","deck":"vocab"},{"id":2515,"word":"elephant in the room","ipa":"","meaning":"껄끄러운 문제, 말하기 꺼리는 문제 <사람들이 알고는 있지만 말하기를 꺼리는 문제>","example":"Nobody mentioned the debt, the obvious elephant in the room.","deck":"vocab"},{"id":2516,"word":"proper","ipa":"/ˈprɑːpər/","meaning":"엄밀한 의미의 <명사 뒤에 씀>","example":"The suburbs are large, but the city proper is quite small.","deck":"vocab"},{"id":2517,"word":"reframe","ipa":"/ˌriːˈfreɪm/","meaning":"~을 재구성하다","example":"Try to reframe the problem as an exciting new opportunity.","deck":"vocab"},{"id":2518,"word":"rather","ipa":"/ˈræðər/","meaning":"꽤, 상당히, 어느 정도","example":"The exam was rather difficult, but I managed to pass.","deck":"vocab"},{"id":2519,"word":"bustling","ipa":"/ˈbʌslɪŋ/","meaning":"부산한, 북적거리는","example":"The market was bustling with shoppers early on Saturday morning.","deck":"vocab"},{"id":2520,"word":"anything but","ipa":"","meaning":"전혀 ~하지 않은, 전혀 ~이 아닌","example":"The task was anything but easy, despite what they promised.","deck":"vocab"},{"id":2521,"word":"walk on eggshells","ipa":"","meaning":"(~의) 눈치를 살살 보다","example":"Everyone walked on eggshells around the angry, unpredictable manager.","deck":"vocab"},{"id":2522,"word":"exclusively","ipa":"/ɪkˈskluːsɪvli/","meaning":"배타적으로, 독점적으로, 오로지, 오직 ~뿐","example":"This lounge is reserved exclusively for first-class passengers.","deck":"vocab"},{"id":2523,"word":"profess","ipa":"/prəˈfes/","meaning":"(감정 등을) 고백하다, 공언하다, 천명하다","example":"He professed his undying love for her in front of everyone.","deck":"vocab"},{"id":2524,"word":"hamper","ipa":"/ˈhæmpər/","meaning":"방해하다","example":"Heavy snow hampered the rescue team's efforts on the mountain.","deck":"vocab"},{"id":2525,"word":"leave","ipa":"/liːv/","meaning":"(책임을 다른 사람에게) 맡기다","example":"I'll leave the final decision entirely to you and your team.","deck":"vocab"},{"id":2526,"word":"audacious","ipa":"/ɔːˈdeɪʃəs/","meaning":"대담한","example":"Her audacious plan to cross the desert alone shocked everyone.","deck":"vocab"},{"id":2527,"word":"undermine","ipa":"/ˌʌndərˈmaɪn/","meaning":"(특히 자신감, 권위 등을) 약화시키다","example":"Constant criticism can undermine a child's confidence over time.","deck":"vocab"},{"id":2528,"word":"reminiscence","ipa":"/ˌremɪˈnɪsns/","meaning":"추억, 회상 <셀 수 없는 명사>","example":"The old letters were full of warm reminiscence about their youth.","deck":"vocab"},{"id":2529,"word":"to some extent","ipa":"","meaning":"어느 정도, 약간은","example":"To some extent, I agree with your assessment of the situation.","deck":"vocab"},{"id":2530,"word":"envision","ipa":"/ɪnˈvɪʒən/","meaning":"(미래의 일을) 마음속에 그리다, 상상하다","example":"I envision a future where clean energy powers every home.","deck":"vocab"},{"id":2531,"word":"coincidental","ipa":"/koʊˌɪnsɪˈdentl/","meaning":"우연의 일치인, 우연의","example":"Their meeting at the airport was purely coincidental.","deck":"vocab"},{"id":2532,"word":"conformity","ipa":"/kənˈfɔːrməti/","meaning":"(규칙, 관습 등에) 따름, 순응 <격식>","example":"The school demands strict conformity to its dress code.","deck":"vocab"},{"id":2533,"word":"bail","ipa":"/beɪl/","meaning":"급히 떠나다, 빨리 가다 <미국 구어>","example":"The party was boring, so we decided to bail early.","deck":"vocab"},{"id":2534,"word":"bail","ipa":"/beɪl/","meaning":"보석, 보석금","example":"The judge set bail at fifty thousand dollars.","deck":"vocab"},{"id":2535,"word":"persist","ipa":"/pərˈsɪst/","meaning":"집요하게 계속하다, 끈질기게 계속하다","example":"She persisted with her questions until she got a clear answer.","deck":"vocab"},{"id":2536,"word":"coin","ipa":"/kɔɪn/","meaning":"(새로운 단어나 표현을) 만들다","example":"Scientists coined a new term to describe the strange phenomenon.","deck":"vocab"},{"id":2537,"word":"status quo","ipa":"/ˌstætəs ˈkwoʊ/","meaning":"현재의 상황, 현상","example":"Many people are reluctant to challenge the comfortable status quo.","deck":"vocab"},{"id":2538,"word":"get ~ over with","ipa":"","meaning":"(불쾌하지만 해야 할 일) ~을 끝내다","example":"Let's just get the dentist appointment over with today.","deck":"vocab"},{"id":2539,"word":"paralyzed","ipa":"/ˈpærəlaɪzd/","meaning":"마비된","example":"The accident left him paralyzed from the waist down.","deck":"vocab"},{"id":2540,"word":"disagreeable","ipa":"/ˌdɪsəˈɡriːəbl/","meaning":"불쾌한, 마음에 들지 않는, 싫은","example":"There was a disagreeable smell coming from the old refrigerator.","deck":"vocab"},{"id":2541,"word":"killer whale","ipa":"/ˈkɪlər weɪl/","meaning":"범고래","example":"A pod of killer whales swam gracefully past the boat.","deck":"vocab"},{"id":2542,"word":"natural enemy","ipa":"/ˈnætʃərəl ˈenəmi/","meaning":"(생물의) 천적(天敵)","example":"The mongoose is a natural enemy of the venomous cobra.","deck":"vocab"},{"id":2543,"word":"rescuer","ipa":"/ˈreskjuːər/","meaning":"구조자, 구제자, 구해준 사람","example":"The grateful hikers thanked their rescuer for the daring effort.","deck":"vocab"},{"id":2544,"word":"dip","ipa":"/dɪp/","meaning":"(아래로) 내려가다, 떨어지다","example":"The temperature will dip below freezing later tonight.","deck":"vocab"},{"id":2545,"word":"windbag","ipa":"/ˈwɪndbæɡ/","meaning":"쓸데없는 말을 너무 많이 하는 사람","example":"That politician is a windbag who never actually says anything useful.","deck":"vocab"},{"id":2546,"word":"interpose","ipa":"/ˌɪntərˈpoʊz/","meaning":"(대화 중에 질문, 발언을) 덧붙이다, 끼어들다","example":"She interposed a quick question before the speaker moved on.","deck":"vocab"},{"id":2547,"word":"radiant","ipa":"/ˈreɪdiənt/","meaning":"빛나는, 환한","example":"The bride looked absolutely radiant on her wedding day.","deck":"vocab"},{"id":2548,"word":"severance","ipa":"/ˈsevərəns/","meaning":"고용 계약 해지, 해고","example":"The laid-off workers each received a generous severance package.","deck":"vocab"},{"id":2549,"word":"relegate","ipa":"/ˈreləɡeɪt/","meaning":"~를 좌천시키다, 내려앉히다","example":"After the mistake, they relegated him to a minor role.","deck":"vocab"},{"id":2550,"word":"draw on ~","ipa":"","meaning":"~을 활용하다, ~에 의지하다","example":"The novelist drew on her own childhood for the story.","deck":"vocab"},{"id":2551,"word":"beside oneself","ipa":"","meaning":"(걱정, 흥분으로) 이성을 잃고, 제정신이 아닌","example":"She was beside herself with worry when the child went missing.","deck":"vocab"},{"id":2552,"word":"beat back","ipa":"","meaning":"~을 격퇴하다, ~을 물리치다","example":"The soldiers managed to beat back the enemy's fierce attack.","deck":"vocab"},{"id":2553,"word":"allowance","ipa":"/əˈlaʊəns/","meaning":"용돈 <주로 미국에서 쓰는 표현>","example":"My parents gave me a weekly allowance when I was young.","deck":"vocab"},{"id":2554,"word":"put together","ipa":"","meaning":"마련하다, 준비하다","example":"She put together a wonderful dinner for the whole family.","deck":"vocab"},{"id":2555,"word":"rerun","ipa":"/ˈriːrʌn/","meaning":"(텔레비전 프로의) 재방송","example":"On rainy days I love watching reruns of old sitcoms.","deck":"vocab"},{"id":2556,"word":"spontaneous","ipa":"/spɑːnˈteɪniəs/","meaning":"(미리 계획되거나 준비된 것이 아니라) 즉흥적인","example":"We took a spontaneous road trip along the coast last weekend.","deck":"vocab"},{"id":2557,"word":"dictatorship","ipa":"/dɪkˈteɪtərʃɪp/","meaning":"독재 국가, 독재 정권 <셀 수 있는 명사>","example":"The country suffered for decades under a brutal dictatorship.","deck":"vocab"},{"id":2558,"word":"punchline","ipa":"/ˈpʌntʃlaɪn/","meaning":"결정적인 한 방, 급소를 찌르는 말, 핵심이 되는 구절 <유머의 핵심 부분>","example":"Everyone laughed loudly when he finally delivered the punchline.","deck":"vocab"},{"id":2559,"word":"what is the big deal","ipa":"","meaning":"그게 뭐가 그렇게 중요해?, 그래서 어쨌단 거야?","example":"So I forgot to call; what is the big deal?","deck":"vocab"},{"id":2560,"word":"diabetes","ipa":"/ˌdaɪəˈbiːtiːz/","meaning":"당뇨병","example":"His doctor warned him that too much sugar could cause diabetes.","deck":"vocab"},{"id":2561,"word":"give way to ~","ipa":"","meaning":"(감정, 눈물 등에) ~에 못 이기다, 무너지다","example":"She finally gave way to tears at the funeral.","deck":"vocab"},{"id":2562,"word":"succulent","ipa":"/ˈsʌkjələnt/","meaning":"(과일, 채소, 고기가) 즙이 많은 <호감>","example":"The peach was ripe, sweet, and wonderfully succulent.","deck":"vocab"},{"id":2563,"word":"scarce","ipa":"/skers/","meaning":"부족한, 드문, 희귀한","example":"Fresh water became scarce during the long summer drought.","deck":"vocab"},{"id":2564,"word":"excruciating","ipa":"/ɪkˈskruːʃieɪtɪŋ/","meaning":"(육체적 또는 정신적으로) 몹시 고통스러운","example":"The pain in his broken leg was absolutely excruciating.","deck":"vocab"},{"id":2565,"word":"excruciating","ipa":"/ɪkˈskruːʃieɪtɪŋ/","meaning":"(수치, 어색함, 지루함 등이) 극심한","example":"The three-hour lecture was excruciating from start to finish.","deck":"vocab"},{"id":2566,"word":"accusation","ipa":"/ˌækjuˈzeɪʃən/","meaning":"비난","example":"He strongly denied the accusation that he had cheated.","deck":"vocab"},{"id":2567,"word":"longevity","ipa":"/lɔːnˈdʒevəti/","meaning":"수명","example":"Regular exercise and good diet can improve your longevity.","deck":"vocab"},{"id":2568,"word":"tacit","ipa":"/ˈtæsɪt/","meaning":"암묵적인, 무언의","example":"There was a tacit agreement between them never to discuss it.","deck":"vocab"},{"id":2569,"word":"benefactor","ipa":"/ˈbenɪfæktər/","meaning":"(학교, 자선단체 등의) 후원자 <격식>","example":"An anonymous benefactor donated millions to the children's hospital.","deck":"vocab"},{"id":2570,"word":"repressive","ipa":"/rɪˈpresɪv/","meaning":"(제도, 체제, 정부 등이) 억압적인, 탄압하는","example":"The repressive regime jailed anyone who dared to protest.","deck":"vocab"},{"id":2571,"word":"patriarchal","ipa":"/ˌpeɪtriˈɑːrkl/","meaning":"가부장적인, 가부장제의","example":"She grew up in a strict, patriarchal household.","deck":"vocab"},{"id":2572,"word":"peril","ipa":"/ˈperəl/","meaning":"(심각한) 위험","example":"The sailors faced great peril during the violent storm.","deck":"vocab"},{"id":2573,"word":"patio","ipa":"/ˈpætioʊ/","meaning":"문밖 테라스, 파티오 <스페인식 주택의 안뜰, 중정(中庭)을 가리킴>","example":"We had breakfast outside on the sunny patio this morning.","deck":"vocab"},{"id":2574,"word":"out","ipa":"/aʊt/","meaning":"(이유를 나타내어) ~에서, ~때문에","example":"She helped the stranger out of pure kindness.","deck":"vocab"},{"id":2575,"word":"stance","ipa":"/stæns/","meaning":"(어떤 일에 대한 공개적인) 입장, 태도","example":"The senator took a firm stance against the new tax.","deck":"vocab"},{"id":2576,"word":"student body president","ipa":"/ˈstuːdnt ˈbɑːdi ˈprezɪdənt/","meaning":"총학생회장","example":"She was elected student body president in her senior year.","deck":"vocab"},{"id":2577,"word":"marble","ipa":"/ˈmɑːrbl/","meaning":"(아이들이 가지고 노는) 구슬","example":"The boys played a game with colorful glass marbles.","deck":"vocab"},{"id":2578,"word":"from the get-go","ipa":"","meaning":"처음부터","example":"I knew from the get-go that the plan would fail.","deck":"vocab"},{"id":2579,"word":"legislative","ipa":"/ˈledʒɪsleɪtɪv/","meaning":"입법의, 입법부의","example":"Congress holds the legislative power to create new federal laws.","deck":"vocab"},{"id":2580,"word":"not the sharpest tool in the shed","ipa":"","meaning":"머리가 둔한, 어리석은","example":"Nice guy, but he's not the sharpest tool in the shed.","deck":"vocab"},{"id":2581,"word":"spearhead","ipa":"/ˈspɪrhed/","meaning":"(공격, 운동 등의) 선봉","example":"She became the spearhead of the environmental movement in town.","deck":"vocab"},{"id":2582,"word":"serene","ipa":"/səˈriːn/","meaning":"고요한, 평화로운, 조용한","example":"The lake was calm and serene in the early morning light.","deck":"vocab"},{"id":2583,"word":"introspective","ipa":"/ˌɪntrəˈspektɪv/","meaning":"자기 성찰적인","example":"He became quiet and introspective after his father passed away.","deck":"vocab"},{"id":2584,"word":"surge","ipa":"/sɜːrdʒ/","meaning":"(강한 감정이) 휩싸다, 휘감다","example":"A surge of joy swept over her when she saw him.","deck":"vocab"},{"id":2585,"word":"creed","ipa":"/kriːd/","meaning":"신념, 신조","example":"Honesty and hard work were the core of his personal creed.","deck":"vocab"},{"id":2586,"word":"animosity","ipa":"/ˌænɪˈmɑːsəti/","meaning":"적대감, 증오, 반감","example":"There was deep animosity between the two rival gangs.","deck":"vocab"},{"id":2587,"word":"illicit","ipa":"/ɪˈlɪsɪt/","meaning":"불법의","example":"The police uncovered an illicit drug operation downtown.","deck":"vocab"},{"id":2588,"word":"mold","ipa":"/moʊld/","meaning":"곰팡이","example":"Green mold had spread across the forgotten loaf of bread.","deck":"vocab"},{"id":2589,"word":"hiatus","ipa":"/haɪˈeɪtəs/","meaning":"(행동의) 중단","example":"The band took a two-year hiatus before releasing new music.","deck":"vocab"},{"id":2590,"word":"sterile","ipa":"/ˈsterəl/","meaning":"(땅이) 불모의, 척박한","example":"Nothing grew in the dry, sterile soil of the desert.","deck":"vocab"},{"id":2591,"word":"bud","ipa":"/bʌd/","meaning":"싹을 티우다","example":"The cherry trees begin to bud in early spring.","deck":"vocab"},{"id":2592,"word":"lifer","ipa":"/ˈlaɪfər/","meaning":"직업 군인","example":"As a lifer, he served in the army for over thirty years.","deck":"vocab"},{"id":2593,"word":"glare","ipa":"/ɡler/","meaning":"노려봄","example":"She shot him an angry glare across the crowded room.","deck":"vocab"},{"id":2594,"word":"surrogate","ipa":"/ˈsɜːrəɡət/","meaning":"대리의, 대용의","example":"The kind teacher became a surrogate parent to the orphaned boy.","deck":"vocab"},{"id":2595,"word":"infuse","ipa":"/ɪnˈfjuːz/","meaning":"(속속들이) 스미다, 영향을 미치다 <격식 있는 표현>","example":"Her passion seemed to infuse every page of the novel.","deck":"vocab"},{"id":2596,"word":"ruling","ipa":"/ˈruːlɪŋ/","meaning":"(판사나 법원이 공식적으로 내리는) 판결, 결정","example":"The court's ruling surprised both the lawyers and the public.","deck":"vocab"},{"id":2597,"word":"solidify","ipa":"/səˈlɪdɪfaɪ/","meaning":"(생각 등을) 굳히다, 확고히 하다 <격식 있는 표현>","example":"The victory helped solidify her reputation as a leader.","deck":"vocab"},{"id":2598,"word":"surreal","ipa":"/səˈriːəl/","meaning":"초현실적인, 비현실적인, 꿈 같은","example":"Meeting my childhood hero felt completely surreal to me.","deck":"vocab"},{"id":2599,"word":"hodgepodge","ipa":"/ˈhɑːdʒpɑːdʒ/","meaning":"뒤범벅, 뒤범벅된 것","example":"His essay was a hodgepodge of unrelated ideas and quotes.","deck":"vocab"},{"id":2600,"word":"hand over fist","ipa":"","meaning":"대량으로, 척척","example":"The new shop was making money hand over fist.","deck":"vocab"},{"id":2601,"word":"deficient","ipa":"/dɪˈfɪʃənt/","meaning":"(필수적인 것이) (~이) 부족한, 결핍된","example":"Her diet was deficient in iron, so the doctor prescribed supplements.","deck":"vocab"},{"id":2602,"word":"caliber","ipa":"/ˈkæləbər/","meaning":"역량, 자질","example":"We need to hire an engineer of the highest caliber for this project.","deck":"vocab"},{"id":2603,"word":"favoritism","ipa":"/ˈfeɪvərɪtɪzəm/","meaning":"편애, 편파","example":"The manager was accused of favoritism toward his younger relatives.","deck":"vocab"},{"id":2604,"word":"lethal","ipa":"/ˈliːθəl/","meaning":"(생명을 위협하여) 치명적인","example":"The snake's venom is lethal if the wound goes untreated.","deck":"vocab"},{"id":2605,"word":"sneak into ~","ipa":"","meaning":"~에 몰래 들어가다","example":"The kids tried to sneak into the theater without paying for tickets.","deck":"vocab"},{"id":2606,"word":"puberty","ipa":"/ˈpjuːbərti/","meaning":"사춘기 <성인이 되는 과정에서 신체적 변화가 생기는 시기>","example":"Most children reach puberty somewhere between the ages of ten and fourteen.","deck":"vocab"},{"id":2607,"word":"disseminate","ipa":"/dɪˈsɛmɪneɪt/","meaning":"(정보, 지식 등을) 퍼뜨리다, 전파하다 <격식 있는 표현>","example":"The agency works hard to disseminate accurate information during a crisis.","deck":"vocab"},{"id":2608,"word":"redundant","ipa":"/rɪˈdʌndənt/","meaning":"불필요한, 쓸모없는, 잉여의","example":"The editor deleted several redundant phrases to tighten the paragraph.","deck":"vocab"},{"id":2609,"word":"burn one's bridges","ipa":"","meaning":"돌이킬 수 없게 만들다, 인연을 끊다, 배수의 진을 치다","example":"Don't burn your bridges with former colleagues when you quit the job.","deck":"vocab"},{"id":2610,"word":"rehabilitation","ipa":"/ˌriːhəˌbɪlɪˈteɪʃən/","meaning":"재활, 갱생 <마약(약물) 중독, 질병, 장애 등으로부터 회복하는 과정>","example":"After the accident, he spent months in rehabilitation to walk again.","deck":"vocab"},{"id":2611,"word":"ornament","ipa":"/ˈɔːrnəmənt/","meaning":"장식","example":"She hung a delicate glass ornament on the Christmas tree.","deck":"vocab"},{"id":2612,"word":"lint","ipa":"/lɪnt/","meaning":"실의 잔부스러기, 보풀","example":"I found a piece of lint stuck to my black sweater.","deck":"vocab"},{"id":2613,"word":"bolt","ipa":"/boʊlt/","meaning":"(동물이 놀라서) 갑자기 달아나다","example":"The horse bolted the moment it heard the loud thunderclap.","deck":"vocab"},{"id":2614,"word":"clueless","ipa":"/ˈkluːləs/","meaning":"(사람이) 무지한, 우둔한","example":"He was completely clueless about how the new software worked.","deck":"vocab"},{"id":2615,"word":"dribble","ipa":"/ˈdrɪbəl/","meaning":"(축구, 농구 등에서 공을) 드리블하다","example":"She managed to dribble the ball past three defenders and score.","deck":"vocab"},{"id":2616,"word":"rock","ipa":"/rɑːk/","meaning":"~를 크게 흥분시키다","example":"The band's surprise encore totally rocked the entire stadium crowd.","deck":"vocab"},{"id":2617,"word":"berate","ipa":"/bɪˈreɪt/","meaning":"질책하다","example":"The coach began to berate his players for their careless mistakes.","deck":"vocab"},{"id":2618,"word":"lyric","ipa":"/ˈlɪrɪk/","meaning":"(노래의) 가사 <복수형으로 씀>","example":"I couldn't understand the lyrics because the singer mumbled them.","deck":"vocab"},{"id":2619,"word":"extraneous","ipa":"/ɪkˈstreɪniəs/","meaning":"(특정 상황이나 주제와) 관련 없는","example":"Please remove any extraneous details that distract from your main argument.","deck":"vocab"},{"id":2620,"word":"live off ~","ipa":"","meaning":"~에 의지해서 살다, ~의 경제적 도움으로 살다","example":"He still lives off his parents even though he's almost thirty.","deck":"vocab"},{"id":2621,"word":"provoke","ipa":"/prəˈvoʊk/","meaning":"(특정한 반응을) 유발하다, 불러일으키다","example":"The controversial ad was designed to provoke a strong reaction.","deck":"vocab"},{"id":2622,"word":"outline","ipa":"/ˈaʊtlaɪn/","meaning":"개요를 서술하다","example":"The professor asked us to outline the main points before writing.","deck":"vocab"},{"id":2623,"word":"baloney","ipa":"/bəˈloʊni/","meaning":"말도 안 되는 소리, 헛소리, 어이없는 소리","example":"That excuse sounds like complete baloney to me.","deck":"vocab"},{"id":2624,"word":"liquidate","ipa":"/ˈlɪkwɪdeɪt/","meaning":"~을 제거하다, 없애 버리다, 죽이다","example":"The dictator ordered his agents to liquidate every political rival.","deck":"vocab"},{"id":2625,"word":"concord","ipa":"/ˈkɑːnkɔːrd/","meaning":"화합 <격식 있는 표현>","example":"The two nations finally reached a lasting concord after years of tension.","deck":"vocab"},{"id":2626,"word":"phonics","ipa":"/ˈfɑːnɪks/","meaning":"발음 중심 어학 교수법","example":"The teacher used phonics to help young children learn to read.","deck":"vocab"},{"id":2627,"word":"conscientious","ipa":"/ˌkɑːnʃiˈɛnʃəs/","meaning":"성실한 <맡은 일이나 책임 등을 제대로 해내려 한다는 뜻>","example":"She is a conscientious worker who never leaves a task unfinished.","deck":"vocab"},{"id":2628,"word":"yearn","ipa":"/jɜːrn/","meaning":"갈망하다, 동경하다 <문어체>","example":"After years abroad, he began to yearn for his hometown.","deck":"vocab"},{"id":2629,"word":"hail from ~","ipa":"","meaning":"~출신이다, ~에서 태어났다","example":"The famous chef hails from a small village in southern Italy.","deck":"vocab"},{"id":2630,"word":"judgmental","ipa":"/dʒʌdʒˈmɛntəl/","meaning":"(남에 대해) 비판을 잘하는, 재단을 잘하는","example":"Try not to be so judgmental about people you barely know.","deck":"vocab"},{"id":2631,"word":"convincing","ipa":"/kənˈvɪnsɪŋ/","meaning":"설득력 있는, 납득이 가는, 그럴듯한","example":"Her argument was so convincing that everyone changed their minds.","deck":"vocab"},{"id":2632,"word":"favorably","ipa":"/ˈfeɪvərəbli/","meaning":"호의적으로, 호의를 가지고","example":"Critics responded favorably to the director's latest film.","deck":"vocab"},{"id":2633,"word":"lick","ipa":"/lɪk/","meaning":"핥다","example":"The puppy tried to lick the ice cream off my hand.","deck":"vocab"},{"id":2634,"word":"let go","ipa":"","meaning":"(~을) 놓다, 쥔 손을 늦추다","example":"She refused to let go of the rope as she climbed higher.","deck":"vocab"},{"id":2635,"word":"for God's sake","ipa":"","meaning":"제발, 좀, 하느님 맙소사","example":"For God's sake, please stop shouting and listen to me.","deck":"vocab"},{"id":2636,"word":"pay","ipa":"/peɪ/","meaning":"(말이나 행동에 대한) 대가를 치르다","example":"You'll pay dearly for the reckless decisions you made today.","deck":"vocab"},{"id":2637,"word":"seduce","ipa":"/sɪˈduːs/","meaning":"(사람이, 주로 성적인 목적으로) 유혹하다, 꾀다","example":"The villain tried to seduce the heroine to gain her secrets.","deck":"vocab"},{"id":2638,"word":"tax deduction","ipa":"/ˈtæks dɪˌdʌkʃən/","meaning":"소득 공제 <과세 대상 소득액을 줄여서 납부해야 할 세액을 줄여 주는 것>","example":"You can claim a tax deduction for your charitable donations this year.","deck":"vocab"},{"id":2639,"word":"inability","ipa":"/ˌɪnəˈbɪləti/","meaning":"무능, 불능","example":"His inability to admit mistakes made teamwork very difficult.","deck":"vocab"},{"id":2640,"word":"factor ~ in","ipa":"","meaning":"~을 고려하다, ~을 감안하다","example":"Remember to factor the shipping costs in when you set the price.","deck":"vocab"},{"id":2641,"word":"talon","ipa":"/ˈtælən/","meaning":"(특히 맹금류의 갈고리 모양의) 발톱","example":"The eagle seized the fish with its powerful talons.","deck":"vocab"},{"id":2642,"word":"solvent","ipa":"/ˈsɑːlvənt/","meaning":"부채 상환 능력이 있는 <부채를 상환할 수 있을 정도의 자산이 있는>","example":"Despite the recession, the company remained solvent throughout the year.","deck":"vocab"},{"id":2643,"word":"crooked","ipa":"/ˈkrʊkɪd/","meaning":"비뚤어진, 구부러진","example":"The old picture frame hung crooked on the wall.","deck":"vocab"},{"id":2644,"word":"deflate","ipa":"/dɪˈfleɪt/","meaning":"(가격, 통화, 경기를) 수축시키다 <경제학 용어>","example":"The central bank's policy helped deflate the overheated economy.","deck":"vocab"},{"id":2645,"word":"mutate","ipa":"/ˈmjuːteɪt/","meaning":"(새로운 형태로) 변형되다, 변화하다","example":"Viruses can mutate quickly, making vaccines harder to design.","deck":"vocab"},{"id":2646,"word":"volatile","ipa":"/ˈvɑːlətəl/","meaning":"(사람 또는 사람의 기분, 성격이) 변덕스러운","example":"His volatile temper made his coworkers nervous around him.","deck":"vocab"},{"id":2647,"word":"eccentric","ipa":"/ɪkˈsɛntrɪk/","meaning":"기이한, 별난","example":"The eccentric professor wore mismatched socks to every lecture.","deck":"vocab"},{"id":2648,"word":"every dog has his day","ipa":"","meaning":"쥐구멍에도 볕 들 날이 있다","example":"Don't lose hope; every dog has his day eventually.","deck":"vocab"},{"id":2649,"word":"infectious","ipa":"/ɪnˈfɛkʃəs/","meaning":"전염성이 있는, 퍼지기 쉬운","example":"Measles is a highly infectious disease that spreads through the air.","deck":"vocab"},{"id":2650,"word":"zillion","ipa":"/ˈzɪljən/","meaning":"무수히 많은, 방대한 수의","example":"There were a zillion stars scattered across the desert sky.","deck":"vocab"},{"id":2651,"word":"tame","ipa":"/teɪm/","meaning":"(짐승이) 길들여진","example":"The once wild fox became surprisingly tame after months of care.","deck":"vocab"},{"id":2652,"word":"browse","ipa":"/braʊz/","meaning":"(가게 안의 물건들을) 둘러보다, 훑어보다","example":"I like to browse through the bookstore on rainy afternoons.","deck":"vocab"},{"id":2653,"word":"no wonder","ipa":"","meaning":"~할 만도 하다","example":"No wonder you're tired; you've been working all night.","deck":"vocab"},{"id":2654,"word":"freakish","ipa":"/ˈfriːkɪʃ/","meaning":"별스러운, 별난, 기이한","example":"A freakish storm dumped snow on the city in mid-summer.","deck":"vocab"},{"id":2655,"word":"justification","ipa":"/ˌdʒʌstɪfɪˈkeɪʃən/","meaning":"타당한 이유, 정당한 이유","example":"There is no justification for treating employees so unfairly.","deck":"vocab"},{"id":2656,"word":"daredevil","ipa":"/ˈdɛrˌdɛvəl/","meaning":"저돌적인 사람, 무모한 사람","example":"The young daredevil jumped off the cliff into the icy river.","deck":"vocab"},{"id":2657,"word":"anesthetic","ipa":"/ˌænəsˈθɛtɪk/","meaning":"마취제","example":"The dentist gave me a local anesthetic before pulling the tooth.","deck":"vocab"},{"id":2658,"word":"speculation","ipa":"/ˌspɛkjəˈleɪʃən/","meaning":"추측, 어림짐작","example":"There is much speculation about who will lead the company next.","deck":"vocab"},{"id":2659,"word":"snatch","ipa":"/snætʃ/","meaning":"(기회 등을) (~을) 낚아채다 <자동사>","example":"She was quick to snatch at the chance to study abroad.","deck":"vocab"},{"id":2660,"word":"eviction","ipa":"/ɪˈvɪkʃən/","meaning":"(살던 집이나 땅에서) 쫓아냄, 퇴거, 축출","example":"The family received an eviction notice after failing to pay rent.","deck":"vocab"},{"id":2661,"word":"prestigious","ipa":"/prɛˈstɪdʒəs/","meaning":"명망 있는, 명망 높은, 일류의","example":"She graduated from a prestigious university with top honors.","deck":"vocab"},{"id":2662,"word":"endearing","ipa":"/ɪnˈdɪrɪŋ/","meaning":"호감 가는, 마음을 끄는, 사랑스러운","example":"His shy smile was one of his most endearing qualities.","deck":"vocab"},{"id":2663,"word":"suffocating","ipa":"/ˈsʌfəkeɪtɪŋ/","meaning":"숨이 막히는, 숨을 쉬기가 힘든","example":"The crowded room felt suffocating in the summer heat.","deck":"vocab"},{"id":2664,"word":"horn in","ipa":"","meaning":"(남의 일에) 끼어들다, 참견하다","example":"Please don't horn in on our private conversation.","deck":"vocab"},{"id":2665,"word":"impromptu","ipa":"/ɪmˈprɑːmptuː/","meaning":"(사전 준비 없이) 즉흥적으로 한, 즉석에서 한","example":"She gave an impromptu speech that impressed the entire audience.","deck":"vocab"},{"id":2666,"word":"altar","ipa":"/ˈɔːltər/","meaning":"제단","example":"The priest lit the candles on the altar before the ceremony.","deck":"vocab"},{"id":2667,"word":"prognosis","ipa":"/prɑːgˈnoʊsɪs/","meaning":"예후(豫後) <의학 용어. 질병 치료 뒤의 경과 예상>","example":"The doctor gave a hopeful prognosis after reviewing the test results.","deck":"vocab"},{"id":2668,"word":"taut","ipa":"/tɔːt/","meaning":"(밧줄 따위가) 팽팽한","example":"The sailors pulled the rope until it was completely taut.","deck":"vocab"},{"id":2669,"word":"myriad","ipa":"/ˈmɪriəd/","meaning":"무수, 무수히 많음, 무수히 많은 수 <\"a myriad of ~\" 또는 \"myriads of ~\"의 형태로 씀>","example":"The night sky revealed a myriad of glittering stars.","deck":"vocab"},{"id":2670,"word":"give off ~","ipa":"","meaning":"(빛, 열, 냄새 등을) 발하다, 내다","example":"The old engine gives off a strange burning smell.","deck":"vocab"},{"id":2671,"word":"compost","ipa":"/ˈkɑːmpoʊst/","meaning":"퇴비를 만들다, 두엄을 만들다","example":"We compost our kitchen scraps to enrich the garden soil.","deck":"vocab"},{"id":2672,"word":"compost","ipa":"/ˈkɑːmpoʊst/","meaning":"퇴비를 주다","example":"She likes to compost the flower beds every spring.","deck":"vocab"},{"id":2673,"word":"backlash","ipa":"/ˈbæklæʃ/","meaning":"(사회적 변화 등에 대한 대중의) 반발","example":"The new policy triggered a fierce backlash from local residents.","deck":"vocab"},{"id":2674,"word":"slur","ipa":"/slɜːr/","meaning":"흐리멍덩하게 말하다, 발음을 불분명하게 하다","example":"He was so tired that he began to slur his words.","deck":"vocab"},{"id":2675,"word":"slash","ipa":"/slæʃ/","meaning":"~ 겸 ~","example":"She works as a writer slash photographer for the magazine.","deck":"vocab"},{"id":2676,"word":"corny","ipa":"/ˈkɔːrni/","meaning":"진부한 <비격식적인 표현>","example":"The movie's ending was so corny that everyone rolled their eyes.","deck":"vocab"},{"id":2677,"word":"all-you-can-eat","ipa":"","meaning":"양껏 먹을 수 있는 <식당에서 먹는 양과 관계없이 고정된 요금을 내는>","example":"We went to an all-you-can-eat buffet and stuffed ourselves silly.","deck":"vocab"},{"id":2678,"word":"cross ~ out","ipa":"","meaning":"(보통 틀린 단어 위에) X자로 줄을 그어 지우다","example":"The teacher told me to cross the wrong answer out neatly.","deck":"vocab"},{"id":2679,"word":"fascinating","ipa":"/ˈfæsɪneɪtɪŋ/","meaning":"대단히 흥미로운, 매력적인","example":"The documentary about deep-sea creatures was absolutely fascinating.","deck":"vocab"},{"id":2680,"word":"day in day out","ipa":"","meaning":"(오랫동안) 날이면 날마다, 매일매일","example":"He practices the piano day in day out without ever complaining.","deck":"vocab"},{"id":2681,"word":"malignant","ipa":"/məˈlɪgnənt/","meaning":"(종양, 질병 등이) 악성의","example":"The biopsy confirmed that the tumor was malignant.","deck":"vocab"},{"id":2682,"word":"segregate","ipa":"/ˈsɛgrɪgeɪt/","meaning":"분리하다, 차별하다","example":"The old laws used to segregate people by the color of their skin.","deck":"vocab"},{"id":2683,"word":"composed","ipa":"/kəmˈpoʊzd/","meaning":"침착한, 차분한","example":"She remained composed even when the reporters shouted questions.","deck":"vocab"},{"id":2684,"word":"blessing in disguise","ipa":"","meaning":"전화위복","example":"Losing that job turned out to be a blessing in disguise.","deck":"vocab"},{"id":2685,"word":"uncoordinated","ipa":"/ˌʌnkoʊˈɔːrdɪneɪtɪd/","meaning":"부드럽게 움직이지 않는, 움직임이 부자연스러운","example":"The toddler's uncoordinated steps made everyone smile.","deck":"vocab"},{"id":2686,"word":"trial","ipa":"/ˈtraɪəl/","meaning":"재판, 공판","example":"The suspect will stand trial early next month.","deck":"vocab"},{"id":2687,"word":"miscarriage","ipa":"/ˈmɪskærɪdʒ/","meaning":"유산 <임신 12-28주 사이의 경우>","example":"She was devastated after suffering a miscarriage last spring.","deck":"vocab"},{"id":2688,"word":"foul","ipa":"/faʊl/","meaning":"(말이) 상스러운, 천박한, 저속한, 거친","example":"The referee ejected the player for using foul language.","deck":"vocab"},{"id":2689,"word":"managerial","ipa":"/ˌmænɪˈdʒɪriəl/","meaning":"경영의, 관리의, 운영의","example":"She was promoted to a managerial position after five years.","deck":"vocab"},{"id":2690,"word":"intolerant","ipa":"/ɪnˈtɑːlərənt/","meaning":"(~을) 배척하는, 용납하지 않는, (~에 대해) 너그럽지 못한","example":"He is intolerant of anyone who disagrees with his opinions.","deck":"vocab"},{"id":2691,"word":"intolerant","ipa":"/ɪnˈtɑːlərənt/","meaning":"불내증이 있는 <특정 식품이나 물질을 제대로 소화하지 못하는>","example":"Many adults are lactose intolerant and cannot digest milk easily.","deck":"vocab"},{"id":2692,"word":"chronological","ipa":"/ˌkrɑːnəˈlɑːdʒɪkəl/","meaning":"발생 순서대로 된, 시간 순서로 된, 연대순의","example":"Please arrange these historical events in chronological order.","deck":"vocab"},{"id":2693,"word":"newspaper route","ipa":"/ˈnuːzpeɪpər ruːt/","meaning":"신문 배달","example":"As a boy, he earned pocket money with a newspaper route.","deck":"vocab"},{"id":2694,"word":"streak","ipa":"/striːk/","meaning":"(사람의 성격에서 특히 좋지 못한) 구석, 데","example":"Beneath his calm surface lay a stubborn streak.","deck":"vocab"},{"id":2695,"word":"ammunition","ipa":"/ˌæmjəˈnɪʃən/","meaning":"탄약 <무기에서 발사되는 총알, 미사일 등>","example":"The soldiers were running low on ammunition during the siege.","deck":"vocab"},{"id":2696,"word":"and the like","ipa":"","meaning":"기타 등등","example":"The store sells pens, notebooks, and the like.","deck":"vocab"},{"id":2697,"word":"legislation","ipa":"/ˌlɛdʒɪsˈleɪʃən/","meaning":"법률 제정, 입법","example":"New legislation was passed to protect endangered wildlife.","deck":"vocab"},{"id":2698,"word":"mere","ipa":"/mɪr/","meaning":"단지 ~만으로도","example":"The mere thought of spiders makes her shiver.","deck":"vocab"},{"id":2699,"word":"choke","ipa":"/tʃoʊk/","meaning":"(사물이 사람을) 질식시키다","example":"The thick smoke began to choke the trapped firefighters.","deck":"vocab"},{"id":2700,"word":"infringe","ipa":"/ɪnˈfrɪndʒ/","meaning":"(법규, 계약 등을) ~를 위반하다, 침해하다 <타동사>","example":"Copying that design would infringe the company's patent.","deck":"vocab"},{"id":2701,"word":"tidy","ipa":"/ˈtaɪdi/","meaning":"정돈하다, 정리하다","example":"Please tidy your room before the guests arrive.","deck":"vocab"},{"id":2702,"word":"fetching","ipa":"/ˈfɛtʃɪŋ/","meaning":"(특히 사람이나 그의 옷이) 멋진, 아주 매력적인 <비격식>","example":"She looked absolutely fetching in her new red dress.","deck":"vocab"},{"id":2703,"word":"compulsive","ipa":"/kəmˈpʌlsɪv/","meaning":"(행동이) 상습적인, 강박적인, 조절이 힘든","example":"He is a compulsive liar who cannot stop making things up.","deck":"vocab"},{"id":2704,"word":"as always","ipa":"","meaning":"늘 그렇듯, 언제나처럼","example":"As always, she arrived exactly ten minutes early.","deck":"vocab"},{"id":2705,"word":"file for ~","ipa":"","meaning":"~을 신청하다, ~을 제기하다","example":"The couple decided to file for divorce after years of arguing.","deck":"vocab"},{"id":2706,"word":"honk","ipa":"/hɑːŋk/","meaning":"경적을 울리다, 빵빵대다 <자동사>","example":"Impatient drivers began to honk the moment the light turned green.","deck":"vocab"},{"id":2707,"word":"insinuate","ipa":"/ɪnˈsɪnjueɪt/","meaning":"에둘러서 말하다, 암시하다, 넌지시 말하다","example":"Are you trying to insinuate that I stole the money?","deck":"vocab"},{"id":2708,"word":"have an affair","ipa":"","meaning":"바람을 피다","example":"He was caught having an affair with his coworker.","deck":"vocab"},{"id":2709,"word":"transmit","ipa":"/trænsˈmɪt/","meaning":"전도하다, 전달하다, 통과시키다 <전문 용어>","example":"Copper wires transmit electricity very efficiently.","deck":"vocab"},{"id":2710,"word":"no offense.","ipa":"","meaning":"악의는 없었다, 기분 나빠하지마","example":"No offense, but that haircut really doesn't suit you.","deck":"vocab"},{"id":2711,"word":"shift","ipa":"/ʃɪft/","meaning":"(견해, 태도, 방식을) 바꾸다 <타동사>","example":"The company had to shift its strategy after the market changed.","deck":"vocab"},{"id":2712,"word":"tap water","ipa":"/ˈtæp ˌwɔːtər/","meaning":"수돗물","example":"In this city, the tap water is perfectly safe to drink.","deck":"vocab"},{"id":2713,"word":"cryptocurrency","ipa":"/ˈkrɪptoʊˌkɜːrənsi/","meaning":"암호화폐 <암호화된 디지털 화폐인 비트코인, 이더리움 등>","example":"He invested his savings in cryptocurrency and lost half of it.","deck":"vocab"},{"id":2714,"word":"hit the nail on the head","ipa":"","meaning":"정곡을 찌르다, 정확히 맞는 말을 하다","example":"You really hit the nail on the head with that observation.","deck":"vocab"},{"id":2715,"word":"seductive","ipa":"/sɪˈdʌktɪv/","meaning":"마음을 끄는, 유혹적인","example":"The advertisement made an easy fortune sound very seductive.","deck":"vocab"},{"id":2716,"word":"be all over ~","ipa":"","meaning":"~에게 성화를 부리다, 계속 잔소리하다","example":"My mother is always all over me about cleaning my room.","deck":"vocab"},{"id":2717,"word":"line","ipa":"/laɪn/","meaning":"(특히 특정한 목적을 갖고 하는) 말, 작업 멘트 <비격식적>","example":"He used a cheesy pickup line that made her laugh out loud.","deck":"vocab"},{"id":2718,"word":"nimble","ipa":"/ˈnɪmbəl/","meaning":"(동작이) 날렵한, 민첩한, 빠른","example":"The nimble cat leaped effortlessly onto the narrow ledge.","deck":"vocab"},{"id":2719,"word":"soothing","ipa":"/ˈsuːðɪŋ/","meaning":"진정시켜 주는, 달래는, 위로하는, 누그러뜨리는","example":"The soothing music helped the baby fall asleep quickly.","deck":"vocab"},{"id":2720,"word":"nonetheless","ipa":"/ˌnʌnðəˈlɛs/","meaning":"그럼에도 불구하고, 그런데도","example":"The task was difficult; nonetheless, she completed it on time.","deck":"vocab"},{"id":2721,"word":"a ton of","ipa":"","meaning":"수없이 많은","example":"There are a ton of reasons why this plan could fail.","deck":"vocab"},{"id":2722,"word":"creepy","ipa":"/ˈkriːpi/","meaning":"소름 끼치는, 오싹하게 하는, 으스스한","example":"The abandoned house looked creepy in the pale moonlight.","deck":"vocab"},{"id":2723,"word":"many","ipa":"/ˈmɛni/","meaning":"대부분의 사람들, 일반 대중들 <복수 취급>","example":"Many believe that honesty is the best policy.","deck":"vocab"},{"id":2724,"word":"in one's favor","ipa":"","meaning":"~에 찬성하여, ~을 지지하여","example":"The final decision was made entirely in his favor.","deck":"vocab"},{"id":2725,"word":"capital","ipa":"/ˈkæpɪtəl/","meaning":"(사업에 필요한 돈이나 기타 재산 등의) 자본","example":"They needed more capital to expand their small business.","deck":"vocab"},{"id":2726,"word":"room","ipa":"/ruːm/","meaning":"여유, 여지","example":"There's still plenty of room for improvement in your essay.","deck":"vocab"},{"id":2727,"word":"pull ~ off","ipa":"","meaning":"(힘든 것을) 해내다, 성사시키다","example":"I doubted she could pull the deal off, but she did.","deck":"vocab"},{"id":2728,"word":"monopolize","ipa":"/məˈnɑːpəlaɪz/","meaning":"독점하다","example":"One company tried to monopolize the entire smartphone market.","deck":"vocab"},{"id":2729,"word":"involuntary","ipa":"/ɪnˈvɑːlənteri/","meaning":"자기도 모르게 하는, 부지불식간의","example":"Blinking is an involuntary reflex we rarely notice.","deck":"vocab"},{"id":2730,"word":"door","ipa":"/dɔːr/","meaning":"가능성, 길, 기회, 방법, 문호, 관문","example":"This scholarship opened the door to a brighter future.","deck":"vocab"},{"id":2731,"word":"legacy","ipa":"/ˈlɛgəsi/","meaning":"(과거의) 유산","example":"The artist left behind a rich legacy of paintings.","deck":"vocab"},{"id":2732,"word":"initiate","ipa":"/ɪˈnɪʃieɪt/","meaning":"개시되게 하다, 착수시키다 <격식>","example":"The government plans to initiate a new health program next year.","deck":"vocab"},{"id":2733,"word":"flourish","ipa":"/ˈflɜːrɪʃ/","meaning":"번영하다, 번창하다","example":"The small café began to flourish after the glowing review.","deck":"vocab"},{"id":2734,"word":"renowned","ipa":"/rɪˈnaʊnd/","meaning":"유명한, 명성 있는","example":"She is a renowned scientist known for her cancer research.","deck":"vocab"},{"id":2735,"word":"appoint","ipa":"/əˈpɔɪnt/","meaning":"(직위, 직책 등에) (~에) ~를 임명하다","example":"The board decided to appoint her as the new chairperson.","deck":"vocab"},{"id":2736,"word":"confess","ipa":"/kənˈfɛs/","meaning":"~을 고백하다, ~을 인정하다 <타동사>","example":"He finally confessed his mistake to his boss.","deck":"vocab"},{"id":2737,"word":"ignorance is bliss","ipa":"","meaning":"모르는 게 약이다","example":"Sometimes ignorance is bliss, so I don't read the news.","deck":"vocab"},{"id":2738,"word":"amphitheater","ipa":"/ˈæmfɪˌθiːətər/","meaning":"(실내의) 원형 강의실, 원형 홀","example":"The lecture was held in a large amphitheater full of students.","deck":"vocab"},{"id":2739,"word":"layoff","ipa":"/ˈleɪˌɔːf/","meaning":"정리 해고","example":"The factory announced a major layoff due to falling profits.","deck":"vocab"},{"id":2740,"word":"subsidiary","ipa":"/səbˈsɪdieri/","meaning":"자회사 <모회사의 지배를 받는 회사>","example":"The tech giant acquired a small subsidiary in Europe.","deck":"vocab"},{"id":2741,"word":"infest","ipa":"/ɪnˈfɛst/","meaning":"(곤충이나 쥐 같은 동물이) 들끓다, 우글거리다","example":"Cockroaches began to infest the neglected kitchen.","deck":"vocab"},{"id":2742,"word":"eon","ipa":"/ˈiːɑːn/","meaning":"이온 <지질학에서 10억 년을 뜻함>","example":"These rocks formed over an eon of geological change.","deck":"vocab"},{"id":2743,"word":"possibly","ipa":"/ˈpɑːsəbli/","meaning":"도저히, 아무리 해도 <특히 can't, couldn't가 쓰인 부정문에서 씀>","example":"I can't possibly finish all this work by tomorrow.","deck":"vocab"},{"id":2744,"word":"attribute","ipa":"/ˈætrɪbjuːt/","meaning":"(사람이나 사물의) 특성, 속성, 자질","example":"Patience is her most valuable attribute as a teacher.","deck":"vocab"},{"id":2745,"word":"attribute","ipa":"/əˈtrɪbjuːt/","meaning":"~을 ~의 결과로 보다, 덕분으로 보다","example":"She attributes her success to years of hard work.","deck":"vocab"},{"id":2746,"word":"as for ~","ipa":"","meaning":"~에 대해서 말하자면","example":"As for the budget, we can discuss that tomorrow.","deck":"vocab"},{"id":2747,"word":"same-day","ipa":"/ˈseɪm ˌdeɪ/","meaning":"(배송, 업무 처리 등이) 당일의","example":"The store offers same-day delivery within the city.","deck":"vocab"},{"id":2748,"word":"compete","ipa":"/kəmˈpiːt/","meaning":"(시합, 경기 등에) 참가하다","example":"She trained hard to compete in the national championship.","deck":"vocab"},{"id":2749,"word":"complaint","ipa":"/kəmˈpleɪnt/","meaning":"항의, 불평","example":"The customer filed a formal complaint about the poor service.","deck":"vocab"},{"id":2750,"word":"handful","ipa":"/ˈhændfʊl/","meaning":"몇 안 되는 수","example":"Only a handful of people showed up to the meeting.","deck":"vocab"},{"id":2751,"word":"stream","ipa":"/striːm/","meaning":"개울, 시내","example":"We cooled our feet in the clear mountain stream.","deck":"vocab"},{"id":2752,"word":"mocking","ipa":"/ˈmɑːkɪŋ/","meaning":"비웃는, 조롱하는, 조소하는 듯한","example":"She gave him a mocking smile after his silly remark.","deck":"vocab"},{"id":2753,"word":"apocalypse","ipa":"/əˈpɑːkəlɪps/","meaning":"종말, 대재앙, 파멸, 대참사","example":"The film depicts a bleak apocalypse caused by nuclear war.","deck":"vocab"},{"id":2754,"word":"rejuvenate","ipa":"/rɪˈdʒuːvəneɪt/","meaning":"다시 젊어 보이게 하다, 활기를 되찾게 하다","example":"A short vacation can rejuvenate a tired mind.","deck":"vocab"},{"id":2755,"word":"decency","ipa":"/ˈdiːsənsi/","meaning":"예의, 정중함, 진실됨 <대부분 영한사전에 \"체면, 품위\"라고 나옴>","example":"At least he had the decency to apologize afterward.","deck":"vocab"},{"id":2756,"word":"reusable","ipa":"/riˈjuːzəbəl/","meaning":"재사용할 수 있는","example":"She carries a reusable bottle to reduce plastic waste.","deck":"vocab"},{"id":2757,"word":"wish ~ luck","ipa":"","meaning":"~의 행운을 빌다","example":"I wished her luck before the big interview.","deck":"vocab"},{"id":2758,"word":"contemplation","ipa":"/ˌkɑːntəmˈpleɪʃən/","meaning":"사색, 명상","example":"He sat by the lake in quiet contemplation for hours.","deck":"vocab"},{"id":2759,"word":"lesion","ipa":"/ˈliːʒən/","meaning":"병변, 병소","example":"The doctor examined the lesion on the patient's skin.","deck":"vocab"},{"id":2760,"word":"smudge","ipa":"/smʌdʒ/","meaning":"(사물의 표면에 뭔가 묻은) 자국, 얼룩","example":"There was a greasy smudge on the camera lens.","deck":"vocab"},{"id":2761,"word":"precarious","ipa":"/prɪˈkɛriəs/","meaning":"(상황이) 불안정한, 위태로운","example":"The company's finances are in a precarious state right now.","deck":"vocab"},{"id":2762,"word":"remembrance","ipa":"/rɪˈmɛmbrəns/","meaning":"추억, 기억","example":"They planted a tree in remembrance of their late friend.","deck":"vocab"},{"id":2763,"word":"assertiveness","ipa":"/əˈsɜːrtɪvnəs/","meaning":"자기주장이 강함","example":"Her assertiveness helped her win the negotiation.","deck":"vocab"},{"id":2764,"word":"hook ~ up","ipa":"","meaning":"~에게 (~을) 구해주다 <상대에게 가치 있는 것을 자신이 가진 인맥이나 자원으로 구해준다는 뜻>","example":"My friend can hook you up with a great mechanic.","deck":"vocab"},{"id":2765,"word":"off of ~","ipa":"","meaning":"~에서","example":"She grabbed the book off of the top shelf.","deck":"vocab"},{"id":2766,"word":"spectator","ipa":"/ˈspɛkteɪtər/","meaning":"(스포츠 경기 등의) 관중","example":"Every spectator jumped up when the home team scored.","deck":"vocab"},{"id":2767,"word":"a penny for your thoughts","ipa":"","meaning":"무슨 생각을 하고 있나 <생각에 잠긴 사람에게 하는 질문>","example":"You've been quiet all evening. A penny for your thoughts?","deck":"vocab"},{"id":2768,"word":"feminine","ipa":"/ˈfɛmənɪn/","meaning":"여성형 단어 <문법 용어>","example":"In French, the word for table is feminine.","deck":"vocab"},{"id":2769,"word":"proof","ipa":"/pruːf/","meaning":"시험 인화 <사진 확인 및 선택을 위해 시험 삼아 인화한 것>","example":"The photographer showed us the proofs before printing the album.","deck":"vocab"},{"id":2770,"word":"tricky","ipa":"/ˈtrɪki/","meaning":"(하기, 다루기) 힘든, 까다로운, 곤란한","example":"Parallel parking can be quite tricky for new drivers.","deck":"vocab"},{"id":2771,"word":"chuckle","ipa":"/ˈtʃʌkəl/","meaning":"킬킬 웃다, 낄낄대다, 키득대다","example":"He couldn't help but chuckle at the silly joke.","deck":"vocab"},{"id":2772,"word":"commemorate","ipa":"/kəˈmɛməreɪt/","meaning":"(중요 인물, 사건을) 기념하다","example":"The monument was built to commemorate the fallen soldiers.","deck":"vocab"},{"id":2773,"word":"fuzz","ipa":"/fʌz/","meaning":"솜털, 잔털, 보풀","example":"The peach was covered in a soft layer of fuzz.","deck":"vocab"},{"id":2774,"word":"deputy","ipa":"/ˈdɛpjəti/","meaning":"부~, 대리","example":"The deputy manager handled the meeting in her boss's absence.","deck":"vocab"},{"id":2775,"word":"wobble","ipa":"/ˈwɑːbəl/","meaning":"(불안정하게) 흔들리다, 떨리다","example":"The old table began to wobble whenever we leaned on it.","deck":"vocab"},{"id":2776,"word":"unambiguously","ipa":"/ˌʌnæmˈbɪgjuəsli/","meaning":"명백하게","example":"The instructions stated unambiguously that no refunds were allowed.","deck":"vocab"},{"id":2777,"word":"litter","ipa":"/ˈlɪtər/","meaning":"(물건들이 장소를) 어지럽히다, 어수선하게 하다","example":"Empty cans and papers littered the entire park.","deck":"vocab"},{"id":2778,"word":"patch things up","ipa":"","meaning":"(~와) 화해하다","example":"After the argument, they finally managed to patch things up.","deck":"vocab"},{"id":2779,"word":"scorn","ipa":"/skɔːrn/","meaning":"경멸, 멸시","example":"She looked at the cheating student with utter scorn.","deck":"vocab"},{"id":2780,"word":"fertilizer","ipa":"/ˈfɜːrtɪlaɪzər/","meaning":"비료","example":"The farmer spread fertilizer across the field before planting.","deck":"vocab"},{"id":2781,"word":"sensible","ipa":"/ˈsɛnsəbəl/","meaning":"분별 있는, 분별력 있는, 합리적인","example":"Wearing sensible shoes for a long hike is a wise choice.","deck":"vocab"},{"id":2782,"word":"grasp","ipa":"/græsp/","meaning":"완전히 이해하다, 파악하다","example":"It took me a while to grasp the complex theory.","deck":"vocab"},{"id":2783,"word":"get canned","ipa":"","meaning":"해고되다","example":"He got canned after showing up late too many times.","deck":"vocab"},{"id":2784,"word":"mess around with ~","ipa":"","meaning":"~을 만지작거리다, ~을 함부로 손대다","example":"Don't mess around with the wiring unless you know what you're doing.","deck":"vocab"},{"id":2785,"word":"somber","ipa":"/ˈsɑːmbər/","meaning":"침울한","example":"The funeral had a somber and quiet atmosphere.","deck":"vocab"},{"id":2786,"word":"barrage","ipa":"/bəˈrɑːʒ/","meaning":"(질문 등의) 세례","example":"The reporters unleashed a barrage of questions at the mayor.","deck":"vocab"},{"id":2787,"word":"fissure","ipa":"/ˈfɪʃər/","meaning":"(암석, 지면 등의) 길게 갈라진 틈, 균열","example":"A deep fissure opened in the ground after the earthquake.","deck":"vocab"},{"id":2788,"word":"up for ~","ipa":"","meaning":"해 볼 마음이 있는, 생각이 있는","example":"Are you up for a hike this weekend?","deck":"vocab"},{"id":2789,"word":"thrive","ipa":"/θraɪv/","meaning":"번창하다, 번영하다, 번성하다","example":"Small businesses can thrive when the local economy is strong.","deck":"vocab"},{"id":2790,"word":"intriguing","ipa":"/ɪnˈtriːgɪŋ/","meaning":"아주 흥미로운 <이상하거나 호기심을 자극한다는 뜻>","example":"The scientist made an intriguing discovery about deep-sea life.","deck":"vocab"},{"id":2791,"word":"oversee","ipa":"/ˌoʊvərˈsiː/","meaning":"(작업, 활동이 제대로 이뤄지는지) 감독하다","example":"She was hired to oversee the entire construction project.","deck":"vocab"},{"id":2792,"word":"to name a few","ipa":"","meaning":"몇 가지만 예를 들자면","example":"The city has museums, parks, and theaters, to name a few.","deck":"vocab"},{"id":2793,"word":"substantiate","ipa":"/səbˈstænʃieɪt/","meaning":"입증하다","example":"He couldn't substantiate his claims with any real evidence.","deck":"vocab"},{"id":2794,"word":"give in","ipa":"","meaning":"(~에게) 항복하다","example":"After hours of pleading, the negotiators refused to give in.","deck":"vocab"},{"id":2795,"word":"crawl","ipa":"/krɔːl/","meaning":"(엎드린 자세로) 기다, 기어가다","example":"The baby learned to crawl across the living room floor.","deck":"vocab"},{"id":2796,"word":"clench","ipa":"/klɛntʃ/","meaning":"(주먹을) 꽉 쥐다","example":"He began to clench his fists in anger.","deck":"vocab"},{"id":2797,"word":"bachelor's degree","ipa":"/ˈbætʃələrz dɪˌgriː/","meaning":"학사 학위","example":"She earned a bachelor's degree in economics last year.","deck":"vocab"},{"id":2798,"word":"hammock","ipa":"/ˈhæmək/","meaning":"해먹 <나무 등에 달아매는 그물, 천 등으로 된 침대>","example":"He dozed off in a hammock between two palm trees.","deck":"vocab"},{"id":2799,"word":"Haste makes waste","ipa":"","meaning":"서두르면 일을 그르친다, 급히 먹는 밥이 체한다, 급할수록 돌아가라","example":"Take your time with the report; haste makes waste.","deck":"vocab"},{"id":2800,"word":"flustered","ipa":"/ˈflʌstərd/","meaning":"허둥대는, 갈팡질팡하는","example":"She got flustered when the interviewer asked an unexpected question.","deck":"vocab"},{"id":2801,"word":"flop","ipa":"/flɑp/","meaning":"완전히 실패하다, 대실패 하다","example":"The movie was a huge flop at the box office.","deck":"vocab"},{"id":2802,"word":"loneliness","ipa":"/ˈloʊnlinəs/","meaning":"고독, 외로움","example":"Living alone, she often struggled with deep loneliness.","deck":"vocab"},{"id":2803,"word":"deportation","ipa":"/ˌdiˌpɔrˈteɪʃən/","meaning":"(보통 범법자, 불법 체류자의) 강제 추방","example":"The immigrant faced deportation after his visa expired.","deck":"vocab"},{"id":2804,"word":"solitude","ipa":"/ˈsɑləˌtud/","meaning":"혼자인 상태, 혼자 살기, 고독","example":"He enjoyed the peace and solitude of the mountains.","deck":"vocab"},{"id":2805,"word":"mint condition","ipa":"/mɪnt kənˈdɪʃən/","meaning":"완벽한 상태, 민트급 <특히 수집품, 골동품 등이 마치 갓 만들어진 것처럼 아주 좋은 상태>","example":"This vintage comic book is still in mint condition.","deck":"vocab"},{"id":2806,"word":"tickle","ipa":"/ˈtɪkəl/","meaning":"(약간 불편하게) 간질간질하다","example":"The wool sweater made my neck tickle all day.","deck":"vocab"},{"id":2807,"word":"modify","ipa":"/ˈmɑdəˌfaɪ/","meaning":"수식하다, 한정하다 <문법 용어>","example":"Adjectives usually modify nouns in an English sentence.","deck":"vocab"},{"id":2808,"word":"ruminate","ipa":"/ˈruməˌneɪt/","meaning":"심사숙고하다, 곰곰이 생각하다","example":"She likes to ruminate on big decisions before acting.","deck":"vocab"},{"id":2809,"word":"swanky","ipa":"/ˈswæŋki/","meaning":"호화로운","example":"They celebrated at a swanky restaurant downtown.","deck":"vocab"},{"id":2810,"word":"arsenal","ipa":"/ˈɑrsənəl/","meaning":"무기 공장, 무기고","example":"The old arsenal stored weapons for the entire region.","deck":"vocab"},{"id":2811,"word":"breed","ipa":"/brid/","meaning":"~을 야기하다, ~을 불러오다, ~의 원인이 되다","example":"Poverty can breed crime in neglected neighborhoods.","deck":"vocab"},{"id":2812,"word":"stereotype","ipa":"/ˈstɛriəˌtaɪp/","meaning":"고정 관념을 형성하다, 정형화하다","example":"It is unfair to stereotype people based on their accent.","deck":"vocab"},{"id":2813,"word":"stereotype","ipa":"/ˈstɛriəˌtaɪp/","meaning":"고정 관념, 정형화된 이미지","example":"That movie relies on a tired stereotype of scientists.","deck":"vocab"},{"id":2814,"word":"fishy","ipa":"/ˈfɪʃi/","meaning":"수상한, 수상쩍은 <비격식적인 표현>","example":"Something about his story sounded really fishy to me.","deck":"vocab"},{"id":2815,"word":"strive","ipa":"/straɪv/","meaning":"있는 힘을 다하여 노력하다, 분투하다","example":"We must strive to improve a little every single day.","deck":"vocab"},{"id":2816,"word":"immune system","ipa":"/ɪˈmjun ˈsɪstəm/","meaning":"면역 체계","example":"Vitamin C helps strengthen your immune system.","deck":"vocab"},{"id":2817,"word":"indispensable","ipa":"/ˌɪndɪˈspɛnsəbəl/","meaning":"없어서는 안 될, 필수적인","example":"Her advice proved indispensable during the crisis.","deck":"vocab"},{"id":2818,"word":"repel","ipa":"/rɪˈpɛl/","meaning":"(자석, 전극 등이) 밀어내다 <전문 용어>","example":"Two magnets with the same pole repel each other.","deck":"vocab"},{"id":2819,"word":"commence","ipa":"/kəˈmɛns/","meaning":"~을 시작하다","example":"The ceremony will commence at exactly noon tomorrow.","deck":"vocab"},{"id":2820,"word":"stuffed","ipa":"/stʌft/","meaning":"잔뜩 먹은, 포식을 한, 배가 너무 부른","example":"After the huge dinner, I felt completely stuffed.","deck":"vocab"},{"id":2821,"word":"deficit","ipa":"/ˈdɛfəsɪt/","meaning":"적자 <경제 용어>","example":"The government is trying to reduce the budget deficit.","deck":"vocab"},{"id":2822,"word":"flatten","ipa":"/ˈflætən/","meaning":"파괴하다, 짜부라뜨리다","example":"The tornado could flatten every house in its path.","deck":"vocab"},{"id":2823,"word":"come along","ipa":"","meaning":"도착하다, 생기다, 나타나다","example":"A better job opportunity may come along soon.","deck":"vocab"},{"id":2824,"word":"reserve","ipa":"/rɪˈzɜrv/","meaning":"따로 잡아 두다, 남겨 두다, 따로 지정하다","example":"I will reserve two seats for us at the concert.","deck":"vocab"},{"id":2825,"word":"impeach","ipa":"/ɪmˈpitʃ/","meaning":"(공무원 등을) 탄핵하다","example":"Congress voted to impeach the corrupt official.","deck":"vocab"},{"id":2826,"word":"blast off","ipa":"","meaning":"(지상에서) 솟아오르다, 발사되다","example":"The rocket will blast off at dawn tomorrow.","deck":"vocab"},{"id":2827,"word":"hide out","ipa":"","meaning":"(자신을 찾으려는 사람을 피해서) 숨다","example":"The thieves tried to hide out in an abandoned barn.","deck":"vocab"},{"id":2828,"word":"hypocritical","ipa":"/ˌhɪpəˈkrɪtɪkəl/","meaning":"위선적인, 위선의, 위선자인","example":"It is hypocritical to preach honesty while lying constantly.","deck":"vocab"},{"id":2829,"word":"plug","ipa":"/plʌg/","meaning":"(구멍을 마개 같은 것으로) 막다, 틀어막다","example":"He used a cork to plug the hole in the barrel.","deck":"vocab"},{"id":2830,"word":"lettuce","ipa":"/ˈlɛtəs/","meaning":"양상추, 상추","example":"Add some crisp lettuce to make the sandwich fresh.","deck":"vocab"},{"id":2831,"word":"deport","ipa":"/dɪˈpɔrt/","meaning":"강제 추방하다","example":"Authorities decided to deport him back to his country.","deck":"vocab"},{"id":2832,"word":"meteorology","ipa":"/ˌmitiəˈrɑlədʒi/","meaning":"기상학","example":"She studied meteorology to become a weather forecaster.","deck":"vocab"},{"id":2833,"word":"stab ~ in the back","ipa":"","meaning":"~의 등에 칼을 꽂다, ~의 뒤통수를 치다, ~를 배신하다","example":"I trusted him, but he stabbed me in the back.","deck":"vocab"},{"id":2834,"word":"truce","ipa":"/trus/","meaning":"휴전","example":"The two sides finally agreed to a temporary truce.","deck":"vocab"},{"id":2835,"word":"quandary","ipa":"/ˈkwɑndəri/","meaning":"진퇴양난","example":"She was in a real quandary about which offer to accept.","deck":"vocab"},{"id":2836,"word":"disconcert","ipa":"/ˌdɪskənˈsɜrt/","meaning":"불안하게 만들다, 당황스럽게 만들다","example":"His sudden questions can disconcert even calm speakers.","deck":"vocab"},{"id":2837,"word":"irritate","ipa":"/ˈɪrəˌteɪt/","meaning":"짜증 나게 하다, 거슬리게 하다","example":"The constant noise began to irritate everyone in the office.","deck":"vocab"},{"id":2838,"word":"in dispute","ipa":"","meaning":"논쟁 중인, 의견 일치가 되지 않은","example":"The ownership of the land is still in dispute.","deck":"vocab"},{"id":2839,"word":"indecision","ipa":"/ˌɪndɪˈsɪʒən/","meaning":"(결정을 못 내리고) 망설임","example":"His endless indecision cost the team a great opportunity.","deck":"vocab"},{"id":2840,"word":"aroma","ipa":"/əˈroʊmə/","meaning":"(기분 좋은) 향기, 방향","example":"The aroma of fresh coffee filled the whole kitchen.","deck":"vocab"},{"id":2841,"word":"needy","ipa":"/ˈnidi/","meaning":"애정을 과도하게 요구하는, 너무 매달리는, 애정에 굶주린","example":"He became clingy and needy after the breakup.","deck":"vocab"},{"id":2842,"word":"untucked","ipa":"/ˌʌnˈtʌkt/","meaning":"(셔츠를 바지 속으로) 집어 넣지 않은","example":"He wore his shirt untucked with faded jeans.","deck":"vocab"},{"id":2843,"word":"condone","ipa":"/kənˈdoʊn/","meaning":"용납하다","example":"The school will not condone any form of cheating.","deck":"vocab"},{"id":2844,"word":"overbuild","ipa":"/ˌoʊvərˈbɪld/","meaning":"~을 너무 사치스럽게 짓다","example":"Developers tend to overbuild luxury homes in that area.","deck":"vocab"},{"id":2845,"word":"futile","ipa":"/ˈfjutəl/","meaning":"헛된, 소용없는","example":"All their efforts to save the building were futile.","deck":"vocab"},{"id":2846,"word":"just so you know","ipa":"","meaning":"그냥 참고로 말하는데, 혹시나 해서 그러는데","example":"Just so you know, the meeting was moved to Friday.","deck":"vocab"},{"id":2847,"word":"dis","ipa":"/dɪs/","meaning":"경멸하다","example":"Do not dis my friends in front of everyone.","deck":"vocab"},{"id":2848,"word":"fluke","ipa":"/fluk/","meaning":"요행수, 요행","example":"Winning the lottery was a total fluke, nothing more.","deck":"vocab"},{"id":2849,"word":"fund-raising","ipa":"/ˈfʌndˌreɪzɪŋ/","meaning":"모금, 기금 모금, 자금 조달","example":"The charity organized a fund-raising dinner last night.","deck":"vocab"},{"id":2850,"word":"sprinkle","ipa":"/ˈsprɪŋkəl/","meaning":"뿌리다","example":"Sprinkle some sugar over the warm pancakes.","deck":"vocab"},{"id":2851,"word":"reddish","ipa":"/ˈrɛdɪʃ/","meaning":"발그레한, 불그스름한","example":"The evening sky turned a soft reddish color.","deck":"vocab"},{"id":2852,"word":"couture","ipa":"/kuˈtʊr/","meaning":"유명 디자이너 제품, 고급 여성복 <프랑스어에서 유래>","example":"She wore a stunning couture gown to the gala.","deck":"vocab"},{"id":2853,"word":"villain","ipa":"/ˈvɪlən/","meaning":"악당, 악한, 악인","example":"Every great story needs a memorable villain.","deck":"vocab"},{"id":2854,"word":"mercurial","ipa":"/mərˈkjʊriəl/","meaning":"변덕스러운","example":"His mercurial moods made him hard to work with.","deck":"vocab"},{"id":2855,"word":"waterworks","ipa":"/ˈwɔtərˌwɜrks/","meaning":"눈물","example":"She turned on the waterworks to win their sympathy.","deck":"vocab"},{"id":2856,"word":"think ~ over","ipa":"","meaning":"(특히 결정을 내리기 전에) ~을 심사숙고하다","example":"Take your time and think the offer over carefully.","deck":"vocab"},{"id":2857,"word":"congressional","ipa":"/kənˈgrɛʃənəl/","meaning":"의회의","example":"The scandal triggered a congressional investigation.","deck":"vocab"},{"id":2858,"word":"commit","ipa":"/kəˈmɪt/","meaning":"(일, 활동 등에) (~에) 전념하다, 헌신하다","example":"She decided to commit fully to her new career.","deck":"vocab"},{"id":2859,"word":"commit","ipa":"/kəˈmɪt/","meaning":"(~을 하기로) 확실하게 약속하다 <주로 수동태나 재귀 용법으로 씀>","example":"He committed to finishing the project by Friday.","deck":"vocab"},{"id":2860,"word":"punctual","ipa":"/ˈpʌŋktʃuəl/","meaning":"시간을 지키는, 시간을 엄수하는","example":"She is always punctual and never misses a meeting.","deck":"vocab"},{"id":2861,"word":"crumble","ipa":"/ˈkrʌmbəl/","meaning":"(건물이나 땅이) 허물어지다, 무너지다","example":"The ancient walls began to crumble after the earthquake.","deck":"vocab"},{"id":2862,"word":"freakishly","ipa":"/ˈfrikɪʃli/","meaning":"이상할 정도로 대단히","example":"He is freakishly tall for his age.","deck":"vocab"},{"id":2863,"word":"parable","ipa":"/ˈpɛrəbəl/","meaning":"우화 <도덕적 또는 영적 교훈을 주는 짧은 이야기>","example":"The teacher told a parable about kindness and greed.","deck":"vocab"},{"id":2864,"word":"nothing short of ~","ipa":"","meaning":"거의 ~이나 다름없는, ~라고 해도 과언이 아닌","example":"Her recovery was nothing short of a miracle.","deck":"vocab"},{"id":2865,"word":"reassurance","ipa":"/ˌriəˈʃʊrəns/","meaning":"안심시키기 <셀 수 없는 명사>","example":"The nervous patient needed constant reassurance.","deck":"vocab"},{"id":2866,"word":"flock","ipa":"/flɑk/","meaning":"모이다, 떼 지어 가다, 떼 지어 오다","example":"Tourists flock to the beach every summer.","deck":"vocab"},{"id":2867,"word":"suck up","ipa":"","meaning":"(~에게) 아부하다, 알랑거리다","example":"He always tries to suck up to the boss.","deck":"vocab"},{"id":2868,"word":"happen to","ipa":"","meaning":"(의문문이나 조건문에서 쓰여) 혹시","example":"Do you happen to know where the station is?","deck":"vocab"},{"id":2869,"word":"hands down","ipa":"","meaning":"명백히, 확실히, 말할 것도 없이","example":"She is hands down the best player on the team.","deck":"vocab"},{"id":2870,"word":"bliss","ipa":"/blɪs/","meaning":"더없는 행복","example":"Lying on the warm beach felt like pure bliss.","deck":"vocab"},{"id":2871,"word":"itinerary","ipa":"/aɪˈtɪnəˌrɛri/","meaning":"여행 일정표","example":"Our travel itinerary includes three cities in five days.","deck":"vocab"},{"id":2872,"word":"tank","ipa":"/tæŋk/","meaning":"(스포츠 경기 등을) 일부러 지다, 포기하다","example":"The boxer was accused of trying to tank the fight.","deck":"vocab"},{"id":2873,"word":"enlarge","ipa":"/ɛnˈlɑrdʒ/","meaning":"(사진, 문서 등을) 확대하다 <주로 수동태로 씀>","example":"Can you enlarge this photo so we can see the faces?","deck":"vocab"},{"id":2874,"word":"sabotage","ipa":"/ˈsæbəˌtɑʒ/","meaning":"(고의적으로) 방해하다","example":"A jealous rival tried to sabotage the entire project.","deck":"vocab"},{"id":2875,"word":"displease","ipa":"/dɪsˈpliz/","meaning":"불쾌하게 만들다, 불만스럽게 만들다 <격식 있는 표현>","example":"His rude remarks displease nearly everyone present.","deck":"vocab"},{"id":2876,"word":"meditative","ipa":"/ˈmɛdəˌteɪtɪv/","meaning":"깊은 생각에 잠긴, 명상적인 <격식>","example":"She sat in a quiet, meditative mood by the lake.","deck":"vocab"},{"id":2877,"word":"hatchet","ipa":"/ˈhætʃɪt/","meaning":"(한 손으로 잡을 수 있는 작은) 손도끼","example":"He used a small hatchet to chop the kindling.","deck":"vocab"},{"id":2878,"word":"embed","ipa":"/ɛmˈbɛd/","meaning":"(종군 기자, 사진 기자 등을) 파견하다","example":"The army decided to embed reporters with the troops.","deck":"vocab"},{"id":2879,"word":"atone","ipa":"/əˈtoʊn/","meaning":"속죄하다 <격식>","example":"He worked hard to atone for his past mistakes.","deck":"vocab"},{"id":2880,"word":"rut","ipa":"/rʌt/","meaning":"틀에 박힌 생활","example":"After years in the same job, he felt stuck in a rut.","deck":"vocab"},{"id":2881,"word":"standing ovation","ipa":"/ˈstændɪŋ oʊˈveɪʃən/","meaning":"기립박수","example":"The moving performance earned a long standing ovation.","deck":"vocab"},{"id":2882,"word":"binge drinking","ipa":"/ˈbɪndʒ ˌdrɪŋkɪŋ/","meaning":"폭음","example":"Binge drinking is a serious problem on many campuses.","deck":"vocab"},{"id":2883,"word":"demote","ipa":"/dɪˈmoʊt/","meaning":"~의 계급을 떨어뜨리다, 강등시키다","example":"The manager threatened to demote him for poor performance.","deck":"vocab"},{"id":2884,"word":"fume","ipa":"/fjum/","meaning":"(화가 나서) 씩씩대다","example":"She sat there fuming after the unfair decision.","deck":"vocab"},{"id":2885,"word":"recoil","ipa":"/rɪˈkɔɪl/","meaning":"움츠러들다","example":"She recoiled in horror at the gruesome sight.","deck":"vocab"},{"id":2886,"word":"school","ipa":"/skul/","meaning":"깔아뭉개다, 패배시키다 <특히 상대방에게 굴욕감을 주는 방식으로>","example":"He totally schooled his opponent in the debate.","deck":"vocab"},{"id":2887,"word":"territorial","ipa":"/ˌtɛrɪˈtɔriəl/","meaning":"텃세를 부리는, 세력권을 주장하는","example":"Dogs can be very territorial about their own yard.","deck":"vocab"},{"id":2888,"word":"club soda","ipa":"/ˈklʌb ˈsoʊdə/","meaning":"탄산수","example":"She ordered a club soda with a slice of lime.","deck":"vocab"},{"id":2889,"word":"preoccupation","ipa":"/priˌɑkjəˈpeɪʃən/","meaning":"(~에) 사로잡힘, 집착, 심취, 몰두","example":"His preoccupation with money worried his close friends.","deck":"vocab"},{"id":2890,"word":"inheritance","ipa":"/ɪnˈhɛrətəns/","meaning":"유산, 유전, 유전되는 것","example":"She used her inheritance to buy a small house.","deck":"vocab"},{"id":2891,"word":"come at a price","ipa":"","meaning":"대가가 따르다","example":"Fame often comes at a price you do not expect.","deck":"vocab"},{"id":2892,"word":"monument","ipa":"/ˈmɑnjəmənt/","meaning":"기념비적인 건축물, 역사적인 건축물","example":"The cathedral is a monument to medieval craftsmanship.","deck":"vocab"},{"id":2893,"word":"hustler","ipa":"/ˈhʌslər/","meaning":"사기꾼","example":"The street hustler tricked tourists out of their money.","deck":"vocab"},{"id":2894,"word":"bug","ipa":"/bʌg/","meaning":"괴롭히다 <비격식>","example":"Stop bugging me while I am trying to work.","deck":"vocab"},{"id":2895,"word":"enroll","ipa":"/ɛnˈroʊl/","meaning":"(강좌, 학교 등에) (~에) 등록하다","example":"She decided to enroll in a night cooking class.","deck":"vocab"},{"id":2896,"word":"vanquish","ipa":"/ˈvæŋkwɪʃ/","meaning":"(경쟁, 전쟁 등에서) 완파하다, 완패시키다 <문어체>","example":"The hero vowed to vanquish his enemies once and for all.","deck":"vocab"},{"id":2897,"word":"hiccup","ipa":"/ˈhɪkəp/","meaning":"딸꾹질","example":"A sudden hiccup interrupted her in the middle of speaking.","deck":"vocab"},{"id":2898,"word":"defy","ipa":"/dɪˈfaɪ/","meaning":"반항하다, 저항하다, 거역하다","example":"The rebellious teen continued to defy his parents.","deck":"vocab"},{"id":2899,"word":"jiggle","ipa":"/ˈdʒɪgəl/","meaning":"(위아래, 양옆으로 빠르게) 흔들다","example":"You have to jiggle the key to open that old lock.","deck":"vocab"},{"id":2900,"word":"floss","ipa":"/flɔs/","meaning":"치실질을 하다","example":"The dentist reminded me to floss every single night.","deck":"vocab"},{"id":2901,"word":"sexual harassment","ipa":"/ˈsɛkʃuəl həˈræsmənt/","meaning":"성희롱","example":"The company has a strict policy against sexual harassment.","deck":"vocab"},{"id":2902,"word":"dreamboat","ipa":"/ˈdrimˌboʊt/","meaning":"매력 넘치는 사람, 매력적인 사람 <비격식적인 구식 표현>","example":"Back in school, everyone thought he was a real dreamboat.","deck":"vocab"},{"id":2903,"word":"stand up for ~","ipa":"","meaning":"~을 옹호하다","example":"You should always stand up for your own beliefs.","deck":"vocab"},{"id":2904,"word":"favor","ipa":"/ˈfeɪvər/","meaning":"(계획, 방식, 체제 등을) 선호하다","example":"Most voters favor the new environmental plan.","deck":"vocab"},{"id":2905,"word":"bottom line","ipa":"/ˈbɑtəm ˈlaɪn/","meaning":"핵심, 요점","example":"The bottom line is that we simply need more time.","deck":"vocab"},{"id":2906,"word":"visionary","ipa":"/ˈvɪʒəˌnɛri/","meaning":"선견지명이 있는, 예지력 있는 <호감>","example":"She was a visionary leader far ahead of her time.","deck":"vocab"},{"id":2907,"word":"distinguished","ipa":"/dɪˈstɪŋgwɪʃt/","meaning":"저명한, 성공한, 고명한","example":"He is a distinguished professor of ancient history.","deck":"vocab"},{"id":2908,"word":"beehive","ipa":"/ˈbiˌhaɪv/","meaning":"벌집","example":"The children watched bees swarm around the beehive.","deck":"vocab"},{"id":2909,"word":"over the course of ~","ipa":"","meaning":"(기간 또는 활동을 하는) ~동안","example":"She changed a lot over the course of the year.","deck":"vocab"},{"id":2910,"word":"sure","ipa":"/ʃʊr/","meaning":"분명히 ~할","example":"That reckless plan is sure to cause serious trouble.","deck":"vocab"},{"id":2911,"word":"fundamental","ipa":"/ˌfʌndəˈmɛntəl/","meaning":"핵심적인, 필수적인","example":"Trust is a fundamental part of any real friendship.","deck":"vocab"},{"id":2912,"word":"altogether","ipa":"/ˌɔltəˈgɛðər/","meaning":"완전히, 전적으로","example":"The trip was altogether more expensive than expected.","deck":"vocab"},{"id":2913,"word":"suggest","ipa":"/səgˈdʒɛst/","meaning":"(사물을 주어로) 시사하다, 암시하다","example":"The evidence suggests that the theory is correct.","deck":"vocab"},{"id":2914,"word":"suggest","ipa":"/səgˈdʒɛst/","meaning":"(사람을 주어로) 넌지시 말하다, 비치다 <간접적으로 뜻을 나타냄>","example":"Are you suggesting that I made a mistake?","deck":"vocab"},{"id":2915,"word":"as of","ipa":"","meaning":"~현재로, ~부로","example":"As of today, the new rules are in effect.","deck":"vocab"},{"id":2916,"word":"blow","ipa":"/bloʊ/","meaning":"(좋은 기회를 실수해서) 망치다, 날려버리다","example":"Do not blow this rare chance to impress them.","deck":"vocab"},{"id":2917,"word":"perk","ipa":"/pɜrk/","meaning":"특전, 혜택, 복지 <사내 시설, 법인 차량 등 주로 근무조건과 관련된 것>","example":"Free gym membership is a nice perk of this job.","deck":"vocab"},{"id":2918,"word":"placid","ipa":"/ˈplæsɪd/","meaning":"차분한, 얌전한","example":"The lake was calm and placid at sunrise.","deck":"vocab"},{"id":2919,"word":"whine","ipa":"/waɪn/","meaning":"징징대다, 우는 소리를 하다","example":"The tired kids began to whine about being bored.","deck":"vocab"},{"id":2920,"word":"commencement","ipa":"/kəˈmɛnsmənt/","meaning":"학위 수여식, 졸업식","example":"She gave the commencement speech at her old college.","deck":"vocab"},{"id":2921,"word":"withdraw","ipa":"/wɪðˈdrɔ/","meaning":"(계좌에서 돈을) 인출하다","example":"I need to withdraw some cash from the bank.","deck":"vocab"},{"id":2922,"word":"cop","ipa":"/kɑp/","meaning":"(~을) 인정하다, 시인하다","example":"He finally copped to breaking the kitchen window.","deck":"vocab"},{"id":2923,"word":"stark","ipa":"/stɑrk/","meaning":"완전한, 순전한","example":"The report was a stark reminder of the danger.","deck":"vocab"},{"id":2924,"word":"deplore","ipa":"/dɪˈplɔr/","meaning":"개탄하다, 개탄스럽게 생각하다 <격식>","example":"Many citizens deplore the rising level of violence.","deck":"vocab"},{"id":2925,"word":"ambush","ipa":"/ˈæmbʊʃ/","meaning":"매복, 매복 공격","example":"The soldiers were caught in a deadly ambush.","deck":"vocab"},{"id":2926,"word":"reinforcement","ipa":"/ˌriɪnˈfɔrsmənt/","meaning":"(군대, 경찰 등의) 증원 부대, 지원군 (복수형으로 씀)","example":"The troops called for reinforcements at dawn.","deck":"vocab"},{"id":2927,"word":"reinforcement","ipa":"/ˌriɪnˈfɔrsmənt/","meaning":"보강, 강화","example":"The old bridge needed extra reinforcement to hold the weight.","deck":"vocab"},{"id":2928,"word":"fella","ipa":"/ˈfɛlə/","meaning":"남자 <친구를 부르는 호칭으로 쓰기도 함>","example":"He is a friendly fella who always helps his neighbors.","deck":"vocab"},{"id":2929,"word":"stock","ipa":"/stɑk/","meaning":"(특정한 가문, 계급, 민족 등의) 후손, 혈통 <문어체. 구식 표현>","example":"She comes from good farming stock in the countryside.","deck":"vocab"},{"id":2930,"word":"protagonist","ipa":"/proʊˈtægənɪst/","meaning":"(연극, 영화, 책 속의) 주인공","example":"The protagonist of the novel is a young orphan.","deck":"vocab"},{"id":2931,"word":"gobble ~ down","ipa":"","meaning":"~을 게걸스럽게 먹어치우다","example":"The hungry kids gobbled down their lunch in minutes.","deck":"vocab"},{"id":2932,"word":"penchant","ipa":"/ˈpɛntʃənt/","meaning":"(~에 대한) 애호, 강한 선호, (~하는) 경향 <어떤 것을 아주 좋아하는 것>","example":"She has a penchant for expensive Italian shoes.","deck":"vocab"},{"id":2933,"word":"turn out","ipa":"","meaning":"되다, 되어 가다","example":"Everything will turn out fine in the end.","deck":"vocab"},{"id":2934,"word":"can not help but","ipa":"","meaning":"~하지 않을 수 없다","example":"I can not help but admire her quiet courage.","deck":"vocab"},{"id":2935,"word":"pitchy","ipa":"/ˈpɪtʃi/","meaning":"음정이 살짝 틀린","example":"His singing was a little pitchy during the chorus.","deck":"vocab"},{"id":2936,"word":"aspiration","ipa":"/ˌæspəˈreɪʃən/","meaning":"열망, 포부, 염원","example":"Her greatest aspiration is to become a surgeon.","deck":"vocab"},{"id":2937,"word":"conserve","ipa":"/kənˈsɜrv/","meaning":"보호하다, 보존하다","example":"We must conserve water during the long dry season.","deck":"vocab"},{"id":2938,"word":"produce","ipa":"/ˈproʊdus/","meaning":"농산물 <채소, 과일 등 농업 생산물과 자연에서 얻은 산물을 이름>","example":"The market sells fresh produce from local farms.","deck":"vocab"},{"id":2939,"word":"act","ipa":"/ækt/","meaning":"(국회를 통과한) 법률","example":"Congress passed the new health care act last month.","deck":"vocab"},{"id":2940,"word":"virtual","ipa":"/ˈvɜrtʃuəl/","meaning":"사실상의, 거의 ~과 다름없는","example":"The election was a virtual certainty from the very start.","deck":"vocab"},{"id":2941,"word":"show ~ off","ipa":"","meaning":"~을 자랑하다","example":"He loves to show off his new sports car.","deck":"vocab"},{"id":2942,"word":"passionate","ipa":"/ˈpæʃənət/","meaning":"열정적인, 열렬한","example":"She is passionate about protecting the environment.","deck":"vocab"},{"id":2943,"word":"iconic","ipa":"/aɪˈkɑnɪk/","meaning":"~의 상징이 되는, 우상의","example":"The Eiffel Tower is an iconic symbol of Paris.","deck":"vocab"},{"id":2944,"word":"blow one's mind","ipa":"","meaning":"놀라게 하다, 충격을 주다","example":"The amazing magic show completely blew my mind.","deck":"vocab"},{"id":2945,"word":"stinker","ipa":"/ˈstɪŋkər/","meaning":"말썽꾸러기, 골칫덩어리 <말썽꾸러기 어린아이를 애정 어리게 이르는 말>","example":"That little stinker hid my keys again.","deck":"vocab"},{"id":2946,"word":"excursion","ipa":"/ɪkˈskɜrʒən/","meaning":"(보통 단체로 짧게 하는) 여행","example":"The class went on a day excursion to the museum.","deck":"vocab"},{"id":2947,"word":"soak ~ up","ipa":"","meaning":"~을 빨아들이다, 흡수하다","example":"She sat on the beach to soak up the warm sunshine.","deck":"vocab"},{"id":2948,"word":"superstitious","ipa":"/ˌsupərˈstɪʃəs/","meaning":"미신을 믿는, 미신적인","example":"He is superstitious and never walks under ladders.","deck":"vocab"},{"id":2949,"word":"patron","ipa":"/ˈpeɪtrən/","meaning":"(특정 상점, 식당 등의) 고객 <격식>","example":"The restaurant treats every patron with great care.","deck":"vocab"},{"id":2950,"word":"abortion","ipa":"/əˈbɔrʃən/","meaning":"낙태, 임신중절, 임신중절수술","example":"The debate over abortion remains deeply divisive.","deck":"vocab"},{"id":2951,"word":"lyricist","ipa":"/ˈlɪrəsɪst/","meaning":"작사가","example":"The famous lyricist wrote songs for many big stars.","deck":"vocab"},{"id":2952,"word":"come out with ~","ipa":"","meaning":"~을 내놓다, 공개하다, 출간하다","example":"The band will come out with a new album soon.","deck":"vocab"},{"id":2953,"word":"get the better of ~","ipa":"","meaning":"~로서는 주체하지 못할 정도가 되다, ~로서는 감당하지 못하다","example":"His curiosity got the better of him in the end.","deck":"vocab"},{"id":2954,"word":"flat","ipa":"/flæt/","meaning":"아파트 <영국식 표현>","example":"They rented a small flat in central London.","deck":"vocab"},{"id":2955,"word":"after all","ipa":"","meaning":"따지고 보면, 어쨌든, 결국 <설명, 이유를 덧붙일 때 씀>","example":"You were right after all about the bad weather.","deck":"vocab"},{"id":2956,"word":"voter fraud","ipa":"/ˈvoʊtər frɔd/","meaning":"부정 선거","example":"There was no evidence of voter fraud in the election.","deck":"vocab"},{"id":2957,"word":"alleged","ipa":"/əˈlɛdʒd/","meaning":"(증거 없이) 주장된, 제기된","example":"The alleged thief was released for lack of proof.","deck":"vocab"},{"id":2958,"word":"rebellious","ipa":"/rɪˈbɛljəs/","meaning":"(규칙, 일반 통념 등에 대해) 반항적인","example":"As a teenager, she was wild and rebellious.","deck":"vocab"},{"id":2959,"word":"dawn on ~","ipa":"","meaning":"~에게 분명해지다, ~이 깨닫게 되다","example":"It finally dawned on me that he was joking.","deck":"vocab"},{"id":2960,"word":"round out","ipa":"","meaning":"완성하다, 마무르다","example":"A great dessert helped round out the meal nicely.","deck":"vocab"},{"id":2961,"word":"plunge","ipa":"/plʌndʒ/","meaning":"뛰어들다, 돌입하다, 갑자기 하기 시작하다","example":"The company plunged into a risky new venture.","deck":"vocab"},{"id":2962,"word":"plunge","ipa":"/plʌndʒ/","meaning":"(빠르고 힘차게) 뛰어들다, 몸을 던지다","example":"He plunged into the icy river to save the dog.","deck":"vocab"},{"id":2963,"word":"rattle","ipa":"/ˈrætəl/","meaning":"덜그럭거리다 <자동사>","example":"The old windows rattle whenever a truck passes.","deck":"vocab"},{"id":2964,"word":"legitimate","ipa":"/lɪˈdʒɪtəmət/","meaning":"합법적인, 적법한","example":"She had a legitimate reason for missing the exam.","deck":"vocab"},{"id":2965,"word":"evade","ipa":"/ɪˈveɪd/","meaning":"(생각, 기억 등이) 떠오르지 않다 <격식 있는 표현>","example":"His name evades me at the moment.","deck":"vocab"},{"id":2966,"word":"who be ~ to ~","ipa":"","meaning":"~가 뭔데 ~를 해?, ~가 무슨 권리로 ~를 해?","example":"Who are you to tell me how to live?","deck":"vocab"},{"id":2967,"word":"snuggle","ipa":"/ˈsnʌgəl/","meaning":"~을 껴안다, 끌어안다","example":"The child loves to snuggle her teddy bear at night.","deck":"vocab"},{"id":2968,"word":"heir","ipa":"/ɛr/","meaning":"계승자, 상속인, 후계자","example":"He is the rightful heir to the family fortune.","deck":"vocab"},{"id":2969,"word":"ample","ipa":"/ˈæmpəl/","meaning":"(남을 정도로) 충분한, 풍부한","example":"There is ample room for everyone in the hall.","deck":"vocab"},{"id":2970,"word":"fling","ipa":"/flɪŋ/","meaning":"(특히 화가 나서 거칠게) 내던지다, 내팽개치다","example":"In anger, she flung the book across the room.","deck":"vocab"},{"id":2971,"word":"fond","ipa":"/fɑnd/","meaning":"(물건이나 취미 등을) 좋아하는, 즐기는","example":"He is very fond of old jazz records.","deck":"vocab"},{"id":2972,"word":"rage","ipa":"/reɪdʒ/","meaning":"격렬한 분노, 격노","example":"He could barely control his rage after the insult.","deck":"vocab"},{"id":2973,"word":"incoherent","ipa":"/ˌɪnkoʊˈhɪrənt/","meaning":"제대로 말을 못 하는, 앞뒤가 안 맞는 말을 하는","example":"He was so drunk that he became completely incoherent.","deck":"vocab"},{"id":2974,"word":"weed","ipa":"/wid/","meaning":"잡초를 뽑다","example":"She spent the morning weeding the vegetable garden.","deck":"vocab"},{"id":2975,"word":"stupidity","ipa":"/stuˈpɪdəti/","meaning":"어리석음, 우둔함","example":"His stupidity nearly got them all into trouble.","deck":"vocab"},{"id":2976,"word":"inescapable","ipa":"/ˌɪnɪˈskeɪpəbəl/","meaning":"피할 수 없는, 무시할 수 없는, 벗어날 수 없는","example":"The conclusion was clear and utterly inescapable.","deck":"vocab"},{"id":2977,"word":"misfire","ipa":"/ˌmɪsˈfaɪr/","meaning":"(계획, 농담 등이) 실패하다 <의도한 결과를 얻지 못하고 어긋나다>","example":"The joke misfired and no one even smiled.","deck":"vocab"},{"id":2978,"word":"fatality","ipa":"/feɪˈtæləti/","meaning":"(재난, 질병 등으로 인한) 사망자","example":"The crash resulted in one fatality and several injuries.","deck":"vocab"},{"id":2979,"word":"rehearsal","ipa":"/rɪˈhɜrsəl/","meaning":"리허설, 예행연습","example":"The band had a final rehearsal before the concert.","deck":"vocab"},{"id":2980,"word":"cuddle","ipa":"/ˈkʌdəl/","meaning":"(누워서, 특히 긴 시간 동안) 껴안다","example":"They love to cuddle on the couch during movies.","deck":"vocab"},{"id":2981,"word":"assert","ipa":"/əˈsɜrt/","meaning":"(단호하게) 자기주장을 하다","example":"She learned to assert herself in tough meetings.","deck":"vocab"},{"id":2982,"word":"rank","ipa":"/ræŋk/","meaning":"(특정 단체, 조직의) 구성원, 회원","example":"He rose quickly through the ranks of the party.","deck":"vocab"},{"id":2983,"word":"talking head","ipa":"/ˈtɔkɪŋ hɛd/","meaning":"TV에 얼굴 내놓고 말하는 사람 <아나운서, 토론 참석자 등>","example":"The talking heads on the news argued all evening.","deck":"vocab"},{"id":2984,"word":"open the floor","ipa":"","meaning":"발언권을 부여하다, 질문을 받다","example":"The chairman will now open the floor for questions.","deck":"vocab"},{"id":2985,"word":"expedition","ipa":"/ˌɛkspəˈdɪʃən/","meaning":"원정대, 탐험대","example":"The expedition set out to explore the frozen north.","deck":"vocab"},{"id":2986,"word":"outlet","ipa":"/ˈaʊtlɛt/","meaning":"콘센트 <주로 미국에서 쓰는 표현>","example":"Plug the lamp into the outlet by the door.","deck":"vocab"},{"id":2987,"word":"dodge","ipa":"/dɑdʒ/","meaning":"(몸을) 잽싸게 피하다","example":"He managed to dodge the flying ball just in time.","deck":"vocab"},{"id":2988,"word":"scale","ipa":"/skeɪl/","meaning":"비늘","example":"A fish's body is covered with shiny scales.","deck":"vocab"},{"id":2989,"word":"taunt","ipa":"/tɔnt/","meaning":"놀리다, 비웃다, 조롱하다","example":"The bullies would taunt him about his old shoes.","deck":"vocab"},{"id":2990,"word":"blemish","ipa":"/ˈblɛmɪʃ/","meaning":"(피부나 사물의 표면에 있는) 흠, 잡티","example":"She covered the small blemish on her cheek with makeup.","deck":"vocab"},{"id":2991,"word":"momentous","ipa":"/moʊˈmɛntəs/","meaning":"중대한","example":"The signing of the treaty was a momentous occasion.","deck":"vocab"},{"id":2992,"word":"walk all over ~","ipa":"","meaning":"~를 함부로 대하다","example":"Do not let your coworkers walk all over you.","deck":"vocab"},{"id":2993,"word":"ill will","ipa":"/ˈɪl ˈwɪl/","meaning":"(남에 대한) 악감정","example":"She bears no ill will toward her old rival.","deck":"vocab"},{"id":2994,"word":"allegiance","ipa":"/əˈlidʒəns/","meaning":"(정당, 종교, 통치자 등에 대한) 충성, 헌신","example":"The soldiers swore allegiance to their new king.","deck":"vocab"},{"id":2995,"word":"transaction","ipa":"/trænˈzækʃən/","meaning":"거래, 매매","example":"The bank recorded every transaction on the account.","deck":"vocab"},{"id":2996,"word":"aggravate","ipa":"/ˈægrəˌveɪt/","meaning":"~를 짜증나게 만들다, 화나게 하다","example":"His constant complaining began to aggravate me.","deck":"vocab"},{"id":2997,"word":"caption","ipa":"/ˈkæpʃən/","meaning":"캡션을 쓰다, 설명을 달다, 해설을 붙이다","example":"She captioned the photo with a funny remark.","deck":"vocab"},{"id":2998,"word":"loom","ipa":"/lum/","meaning":"흐릿하게 보이다, 어렴풋이 나타나다","example":"A dark figure loomed in the misty doorway.","deck":"vocab"},{"id":2999,"word":"pragmatist","ipa":"/ˈprægmətɪst/","meaning":"실용주의자, 실익주의자, 실무가","example":"As a pragmatist, she focused on practical solutions.","deck":"vocab"},{"id":3000,"word":"staycation","ipa":"/steɪˈkeɪʃən/","meaning":"스테이케이션 <집이나 집 근처에서 보내는 휴가>","example":"We saved money by taking a relaxing staycation.","deck":"vocab"},{"id":3001,"word":"derogate","ipa":"/ˈdɛrəˌɡeɪt/","meaning":"~을 폄하하다 <격식 있는 표현>","example":"Critics often derogate his early work as shallow and unoriginal.","deck":"vocab"},{"id":3002,"word":"kinship","ipa":"/ˈkɪnʃɪp/","meaning":"친밀함, 친밀감, 연대감, 동류의식","example":"She felt a deep kinship with the other volunteers at the shelter.","deck":"vocab"},{"id":3003,"word":"rebuke","ipa":"/rɪˈbjuk/","meaning":"비난","example":"The manager issued a stern rebuke to the late employee.","deck":"vocab"},{"id":3004,"word":"drudgery","ipa":"/ˈdrʌdʒəri/","meaning":"따분하고 고된 일","example":"He longed to escape the daily drudgery of factory work.","deck":"vocab"},{"id":3005,"word":"growl","ipa":"/ɡraʊl/","meaning":"(동물, 특히 개가) 으르렁거리다","example":"The dog began to growl as the stranger approached the gate.","deck":"vocab"},{"id":3006,"word":"plump","ipa":"/plʌmp/","meaning":"통통한, 포동포동한, 토실토실한","example":"The baby had plump little cheeks that everyone wanted to pinch.","deck":"vocab"},{"id":3007,"word":"damp","ipa":"/dæmp/","meaning":"(흔히 불쾌감을 줄 정도로) 축축한, 눅눅한","example":"The basement felt cold and damp after the heavy rain.","deck":"vocab"},{"id":3008,"word":"ignite","ipa":"/ɪɡˈnaɪt/","meaning":"불이 붙다, 점화되다","example":"A single spark can ignite the dry grass in seconds.","deck":"vocab"},{"id":3009,"word":"pitch","ipa":"/pɪtʃ/","meaning":"권유, 주장, 홍보","example":"Her sales pitch convinced the investors to fund the startup.","deck":"vocab"},{"id":3010,"word":"replica","ipa":"/ˈrɛplɪkə/","meaning":"(실물을 모방하여 만든) 복제품, 모형(模型)","example":"The museum displays a perfect replica of the ancient statue.","deck":"vocab"},{"id":3011,"word":"go nuts","ipa":"","meaning":"미치다","example":"The kids will go nuts when they see the new playground.","deck":"vocab"},{"id":3012,"word":"breathtakingly","ipa":"/ˈbrɛθˌteɪkɪŋli/","meaning":"(너무 아름답거나 놀라워서) 숨 막힐 정도로","example":"The view from the summit was breathtakingly beautiful at sunrise.","deck":"vocab"},{"id":3013,"word":"exaggerate","ipa":"/ɪɡˈzædʒəˌreɪt/","meaning":"과장하다","example":"He tends to exaggerate his achievements when talking to strangers.","deck":"vocab"},{"id":3014,"word":"violate","ipa":"/ˈvaɪəˌleɪt/","meaning":"(법, 합의 등을) 위반하다, 어기다 <격식>","example":"Anyone who violates the contract will face legal consequences.","deck":"vocab"},{"id":3015,"word":"cliché","ipa":"/kliˈʃeɪ/","meaning":"진부한 것, 진부한 사람 <이전에 자주 보았던 것이어서 진부하게 느껴지는 표현>","example":"Saying love conquers all has become a tired cliché.","deck":"vocab"},{"id":3016,"word":"vomiting","ipa":"/ˈvɑmɪtɪŋ/","meaning":"구토, 토하기","example":"The patient reported nausea and vomiting after eating the seafood.","deck":"vocab"},{"id":3017,"word":"diarrhea","ipa":"/ˌdaɪəˈriə/","meaning":"설사 <대변이 비정상적으로 묽은 것>","example":"The child suffered from diarrhea for two days after the trip.","deck":"vocab"},{"id":3018,"word":"tranquility","ipa":"/træŋˈkwɪləti/","meaning":"평온","example":"She found perfect tranquility while meditating by the quiet lake.","deck":"vocab"},{"id":3019,"word":"substance abuse","ipa":"/ˈsʌbstəns əˌbjus/","meaning":"약물 남용 <알코올 남용도 포함>","example":"The clinic offers counseling for people struggling with substance abuse.","deck":"vocab"},{"id":3020,"word":"asylum","ipa":"/əˈsaɪləm/","meaning":"망명","example":"The refugees sought asylum in a neighboring country.","deck":"vocab"},{"id":3021,"word":"cliff","ipa":"/klɪf/","meaning":"(흔히 바닷가) 절벽","example":"The hikers stood near the edge of the steep cliff.","deck":"vocab"},{"id":3022,"word":"gratitude","ipa":"/ˈɡrætɪˌtud/","meaning":"고마움, 감사, 사의","example":"She expressed her gratitude to everyone who supported her recovery.","deck":"vocab"},{"id":3023,"word":"sneer","ipa":"/snɪr/","meaning":"비웃듯이 말하다, 조롱하듯이 말하다","example":"He would always sneer at ideas he considered beneath him.","deck":"vocab"},{"id":3024,"word":"on the flip side","ipa":"","meaning":"반면에, 다른 한편으로는","example":"The job pays well; on the flip side, the hours are brutal.","deck":"vocab"},{"id":3025,"word":"even-tempered","ipa":"/ˈivən ˈtɛmpərd/","meaning":"(성격이) 침착한, 차분한","example":"Our teacher stayed even-tempered even when the students misbehaved.","deck":"vocab"},{"id":3026,"word":"amicable","ipa":"/ˈæmɪkəbəl/","meaning":"(싸움 같은 것을 하지 않고) 원만한, 우호적인","example":"The former partners reached an amicable settlement after the divorce.","deck":"vocab"},{"id":3027,"word":"ring ~ up","ipa":"","meaning":"~가 내야 할 금액을 금전 등록기에 입력하다, 계산하다","example":"The cashier will ring up your groceries in a moment.","deck":"vocab"},{"id":3028,"word":"goody-two-shoes","ipa":"/ˈɡʊdi tu ˌʃuz/","meaning":"범생이, 도덕군자인 척하는 사람 <극도로 도덕적이고 모범적으로 행동하는 사람>","example":"Everyone teased her for being a goody-two-shoes who never broke rules.","deck":"vocab"},{"id":3029,"word":"what is more","ipa":"","meaning":"한술 더 떠서, 더욱이, 게다가","example":"The plan is expensive, and what is more, it might fail.","deck":"vocab"},{"id":3030,"word":"reason","ipa":"/ˈrizən/","meaning":"근거, 이유 <셀 수 없는 명사>","example":"There is no reason to panic about the minor delay.","deck":"vocab"},{"id":3031,"word":"arena","ipa":"/əˈrinə/","meaning":"(원형) 경기장, 공연장","example":"Thousands of fans packed the arena for the championship game.","deck":"vocab"},{"id":3032,"word":"tinkle","ipa":"/ˈtɪŋkəl/","meaning":"쉬하다, 오줌 누다","example":"The toddler said he needed to tinkle before the long car ride.","deck":"vocab"},{"id":3033,"word":"shrine","ipa":"/ʃraɪn/","meaning":"(비유적으로) 성지 같은 곳, 성지","example":"Fans turned his childhood home into a shrine after his death.","deck":"vocab"},{"id":3034,"word":"dexterous","ipa":"/ˈdɛkstərəs/","meaning":"손재주가 있는, 솜씨 좋은","example":"The surgeon's dexterous hands moved swiftly during the delicate operation.","deck":"vocab"},{"id":3035,"word":"opinionated","ipa":"/əˈpɪnjəˌneɪtɪd/","meaning":"자기주장이 강한, 자기 의견을 고집하는, 독선적인","example":"My uncle is so opinionated that he argues about everything at dinner.","deck":"vocab"},{"id":3036,"word":"take one's mind off ~","ipa":"","meaning":"~을 잠깐 잊게 해 주다","example":"A good movie can take your mind off your worries.","deck":"vocab"},{"id":3037,"word":"child abuse","ipa":"/tʃaɪld əˌbjus/","meaning":"아동 학대","example":"The teacher reported suspected child abuse to the authorities immediately.","deck":"vocab"},{"id":3038,"word":"inherently","ipa":"/ɪnˈhɪrəntli/","meaning":"본디, 타고나서, 본질적으로","example":"Some tasks are inherently dangerous no matter how careful you are.","deck":"vocab"},{"id":3039,"word":"disparage","ipa":"/dɪˈspærɪdʒ/","meaning":"폄하하다 <격식 있는 표현>","example":"It's unfair to disparage her efforts when she tried so hard.","deck":"vocab"},{"id":3040,"word":"pouch","ipa":"/paʊtʃ/","meaning":"(캥거루 같은 동물의) 새끼 주머니","example":"The kangaroo carried its tiny joey in her warm pouch.","deck":"vocab"},{"id":3041,"word":"secluded","ipa":"/sɪˈkludɪd/","meaning":"한적한, 외딴, 외진, 외진 곳에 있는, 호젓한","example":"They rented a secluded cabin far from the busy city.","deck":"vocab"},{"id":3042,"word":"hypnosis","ipa":"/hɪpˈnoʊsɪs/","meaning":"최면, 최면 상태","example":"She quit smoking after several sessions of hypnosis with a therapist.","deck":"vocab"},{"id":3043,"word":"landslide","ipa":"/ˈlændˌslaɪd/","meaning":"산사태","example":"Heavy rains triggered a massive landslide that blocked the mountain road.","deck":"vocab"},{"id":3044,"word":"rabid","ipa":"/ˈræbɪd/","meaning":"광견병에 걸린","example":"The rabid raccoon was foaming at the mouth near the barn.","deck":"vocab"},{"id":3045,"word":"premise","ipa":"/ˈprɛmɪs/","meaning":"(주장의) 전제 <격식 있는 표현>","example":"His entire argument rests on a false premise.","deck":"vocab"},{"id":3046,"word":"abstain","ipa":"/əbˈsteɪn/","meaning":"(~을) 자제하다, 삼가다","example":"He decided to abstain from alcohol for the entire month.","deck":"vocab"},{"id":3047,"word":"premises","ipa":"/ˈprɛmɪsɪz/","meaning":"부지, 지역, 구내","example":"Smoking is strictly prohibited anywhere on the company premises.","deck":"vocab"},{"id":3048,"word":"take the coward's way out","ipa":"","meaning":"자살하다, 극단적인 선택을 하다","example":"Instead of facing his debts, he took the coward's way out.","deck":"vocab"},{"id":3049,"word":"portrait","ipa":"/ˈpɔrtrɪt/","meaning":"인물 사진 <특히 어깨 윗부분까지만 나온 사진>","example":"The artist painted a striking portrait of the elderly woman.","deck":"vocab"},{"id":3050,"word":"sham","ipa":"/ʃæm/","meaning":"가짜, 엉터리, 속임수, 야바위","example":"The entire election turned out to be a complete sham.","deck":"vocab"},{"id":3051,"word":"pushover","ipa":"/ˈpʊʃˌoʊvər/","meaning":"만만한 사람, 호락호락한 사람","example":"Don't think the new manager is a pushover; she's tough.","deck":"vocab"},{"id":3052,"word":"leafy","ipa":"/ˈlifi/","meaning":"잎이 무성한","example":"They strolled down a quiet, leafy street in the suburbs.","deck":"vocab"},{"id":3053,"word":"therapeutic","ipa":"/ˌθɛrəˈpjutɪk/","meaning":"치료상의, 치료법의","example":"Many people find gardening deeply therapeutic after a stressful week.","deck":"vocab"},{"id":3054,"word":"immersive","ipa":"/ɪˈmɜrsɪv/","meaning":"몰입형의, 에워싸는 듯한 <컴퓨터 시스템이나 영상이 3차원처럼 실감 나는>","example":"The new video game offers a stunningly immersive virtual world.","deck":"vocab"},{"id":3055,"word":"venom","ipa":"/ˈvɛnəm/","meaning":"(뱀 등의) 독, 독액","example":"The snake's venom can be fatal without immediate treatment.","deck":"vocab"},{"id":3056,"word":"notwithstanding","ipa":"/ˌnɑtwɪθˈstændɪŋ/","meaning":"~에도 불구하고 <관련된 명사 뒤에 쓰이기도 함>","example":"Notwithstanding the bad weather, the outdoor concert went ahead.","deck":"vocab"},{"id":3057,"word":"shoddy","ipa":"/ˈʃɑdi/","meaning":"부당한, 부정직한","example":"The contractor did shoddy work and the roof soon leaked.","deck":"vocab"},{"id":3058,"word":"colloquial","ipa":"/kəˈloʊkwiəl/","meaning":"(단어나 언어가) 구어의, 일상적인 대화체의","example":"The textbook includes colloquial expressions used in everyday conversation.","deck":"vocab"},{"id":3059,"word":"drag","ipa":"/dræɡ/","meaning":"질질 끌리다","example":"Her long coat began to drag along the muddy ground.","deck":"vocab"},{"id":3060,"word":"supercilious","ipa":"/ˌsupərˈsɪliəs/","meaning":"거만한, 건방진, 남을 얕보는","example":"The waiter gave us a supercilious look when we ordered water.","deck":"vocab"},{"id":3061,"word":"cut it","ipa":"","meaning":"통하다, 먹히다, 먹어주다 <뭔가를 해 나가는 데 필요한 기준을 충족하다>","example":"If you can't meet deadlines, you won't cut it here.","deck":"vocab"},{"id":3062,"word":"dispatch","ipa":"/dɪˈspætʃ/","meaning":"(특별한 목적을 위해) ~을 보내다, 파견하다","example":"The company will dispatch a technician to fix the problem tomorrow.","deck":"vocab"},{"id":3063,"word":"discord","ipa":"/ˈdɪskɔrd/","meaning":"불화, 다툼 <격식>","example":"Years of discord finally tore the once-close family apart.","deck":"vocab"},{"id":3064,"word":"come up","ipa":"","meaning":"(사람이 말을 하기 위해 누구에게) 다가오다","example":"A stranger came up to me and asked for directions.","deck":"vocab"},{"id":3065,"word":"dire","ipa":"/ˈdaɪər/","meaning":"엉망인, 형편없는, 수준 이하인 <비격식>","example":"The service at that restaurant was absolutely dire last night.","deck":"vocab"},{"id":3066,"word":"discretion","ipa":"/dɪˈskrɛʃən/","meaning":"신중함","example":"Please handle this sensitive matter with the utmost discretion.","deck":"vocab"},{"id":3067,"word":"summon","ipa":"/ˈsʌmən/","meaning":"(감정, 생각, 용기 등을) 내다, 불러일으키다","example":"She had to summon all her courage to speak publicly.","deck":"vocab"},{"id":3068,"word":"summon","ipa":"/ˈsʌmən/","meaning":"(회의를) 소집하다 (격식)","example":"The chairman decided to summon an emergency meeting of the board.","deck":"vocab"},{"id":3069,"word":"bustle","ipa":"/ˈbʌsəl/","meaning":"바삐 움직이다, 서두르다","example":"Waiters bustle around the crowded restaurant during the dinner rush.","deck":"vocab"},{"id":3070,"word":"mass","ipa":"/mæs/","meaning":"대중, 일반 대중 <복수형으로 씀>","example":"The politician's speech was designed to appeal to the masses.","deck":"vocab"},{"id":3071,"word":"pander","ipa":"/ˈpændər/","meaning":"(~에) 영합하다 <이득을 얻기 위해 상대가 원하는 것을 모두 들어주다>","example":"Politicians often pander to voters just before an election.","deck":"vocab"},{"id":3072,"word":"inflammation","ipa":"/ˌɪnfləˈmeɪʃən/","meaning":"(신체 부위의) 염증","example":"The doctor prescribed medicine to reduce the inflammation in his knee.","deck":"vocab"},{"id":3073,"word":"be of help","ipa":"","meaning":"힘이 되다, 도움이 되다","example":"Please let me know if I can be of help.","deck":"vocab"},{"id":3074,"word":"turf","ipa":"/tɜrf/","meaning":"자기 지역, 근거지, 텃밭 <특정한 사람이나 그룹이 스스로의 영역으로 여기는 곳>","example":"The gang fiercely defended its turf from rival groups.","deck":"vocab"},{"id":3075,"word":"way too","ipa":"","meaning":"너무너무, 너무 심하게, 너무 과도하게, 너무 지나치게","example":"This coffee is way too hot to drink right now.","deck":"vocab"},{"id":3076,"word":"clever","ipa":"/ˈklɛvər/","meaning":"기발한, 재치 있는","example":"She came up with a clever solution to the tricky puzzle.","deck":"vocab"},{"id":3077,"word":"conclusion","ipa":"/kənˈkluʒən/","meaning":"(연설, 글 등의) 결말, 마무리 <주로 단수형으로 씀>","example":"The essay's conclusion neatly summarized all the main arguments.","deck":"vocab"},{"id":3078,"word":"white oil","ipa":"/waɪt ˌɔɪl/","meaning":"미네랄 오일 (무색·무취·무미의 광물성 기름, 제약·미용 등에 쓰임)","example":"The pharmacist used white oil as a base for the ointment.","deck":"vocab"},{"id":3079,"word":"fetch","ipa":"/fɛtʃ/","meaning":"(가서) 가지고 오다, 데리고 오다, 불러오다","example":"Could you please fetch my glasses from the bedroom?","deck":"vocab"},{"id":3080,"word":"sanitary","ipa":"/ˈsænɪˌtɛri/","meaning":"위생적인, 깨끗한","example":"The kitchen must be kept sanitary to pass the health inspection.","deck":"vocab"},{"id":3081,"word":"as in","ipa":"","meaning":"~에서처럼, ~에서 그렇듯, ~의 경우에서와 같이","example":"I mean bass, as in the fish, not the instrument.","deck":"vocab"},{"id":3082,"word":"bar exam","ipa":"/ˈbɑr ɪɡˌzæm/","meaning":"변호사 자격 시험","example":"She spent months studying to pass the difficult bar exam.","deck":"vocab"},{"id":3083,"word":"invaluable","ipa":"/ɪnˈvæljəbəl/","meaning":"매우 유용한, 귀중한","example":"Her advice proved invaluable during my first year of teaching.","deck":"vocab"},{"id":3084,"word":"fanatic","ipa":"/fəˈnætɪk/","meaning":"(~에) 광적인 사람","example":"My brother is a total fitness fanatic who exercises daily.","deck":"vocab"},{"id":3085,"word":"crow","ipa":"/kroʊ/","meaning":"(수탉이 특히 이른 새벽에) \"꼬끼오\"하고 울다","example":"The rooster began to crow loudly at the break of dawn.","deck":"vocab"},{"id":3086,"word":"keep a lid on ~","ipa":"","meaning":"~을 비밀로 하다, ~을 감춰 두다","example":"We need to keep a lid on these rumors for now.","deck":"vocab"},{"id":3087,"word":"sobriety","ipa":"/səˈbraɪəti/","meaning":"술에 취하지 않은 상태, 맨 정신","example":"He proudly celebrated one full year of sobriety last weekend.","deck":"vocab"},{"id":3088,"word":"teem with ~","ipa":"","meaning":"(사람, 동물 등이) 바글거리다","example":"The pond teems with frogs and fish every spring.","deck":"vocab"},{"id":3089,"word":"over here","ipa":"","meaning":"이쪽으로, 여기에, 여기에서","example":"Come over here so I can show you the map.","deck":"vocab"},{"id":3090,"word":"vicious","ipa":"/ˈvɪʃəs/","meaning":"지독한, 극심한","example":"She suffered a vicious headache that lasted the entire afternoon.","deck":"vocab"},{"id":3091,"word":"scope","ipa":"/skoʊp/","meaning":"샅샅이 살피다, 자세히 살피다 (비격식)","example":"Let me scope out the neighborhood before we decide to move.","deck":"vocab"},{"id":3092,"word":"pottery","ipa":"/ˈpɑtəri/","meaning":"도예","example":"She took a pottery class to learn how to make bowls.","deck":"vocab"},{"id":3093,"word":"pacify","ipa":"/ˈpæsɪˌfaɪ/","meaning":"~에 평화를 가져오다","example":"The troops were sent to pacify the war-torn region.","deck":"vocab"},{"id":3094,"word":"neutralize","ipa":"/ˈnutrəˌlaɪz/","meaning":"제압하다, 무력화하다","example":"Security guards quickly moved to neutralize the armed intruder.","deck":"vocab"},{"id":3095,"word":"spinning wheel","ipa":"/ˈspɪnɪŋ ˌwil/","meaning":"물레 (솜·털 등의 섬유를 자아서 실을 만드는 재래식 기구)","example":"Grandmother spun wool into thread on an old spinning wheel.","deck":"vocab"},{"id":3096,"word":"steep","ipa":"/stip/","meaning":"너무 비싼, 터무니없는, 너무 높은 (비격식)","example":"Twenty dollars for a single coffee seems a bit steep.","deck":"vocab"},{"id":3097,"word":"bargain","ipa":"/ˈbɑrɡɪn/","meaning":"협상하다, 흥정하다","example":"Tourists love to bargain with vendors at the local market.","deck":"vocab"},{"id":3098,"word":"fungal","ipa":"/ˈfʌŋɡəl/","meaning":"균류에 의한, 곰팡이에 의한","example":"The doctor diagnosed a fungal infection on his left foot.","deck":"vocab"},{"id":3099,"word":"remission","ipa":"/rɪˈmɪʃən/","meaning":"(병의) 차도, 경감","example":"After months of treatment, her cancer went into remission.","deck":"vocab"},{"id":3100,"word":"lawsuit","ipa":"/ˈlɔˌsut/","meaning":"소송, 고소, 소송건 (주로 민사소송을 가리킴)","example":"The company faced a costly lawsuit over the defective product.","deck":"vocab"},{"id":3101,"word":"finishing move","ipa":"/ˈfɪnɪʃɪŋ ˌmuv/","meaning":"(특히 일대일 전투 비디오 게임에서) 필살기","example":"He defeated his opponent with a spectacular finishing move.","deck":"vocab"},{"id":3102,"word":"go forth","ipa":"","meaning":"나가다, 출발하다 (비유적으로도 쓰임)","example":"Go forth and share this message with the whole world.","deck":"vocab"},{"id":3103,"word":"break a leg!","ipa":"","meaning":"(공연 등에 앞서) 잘해! 행운을 빌어! (발표나 공연 등을 앞두고 하는 말)","example":"Break a leg tonight; I know your performance will be amazing!","deck":"vocab"},{"id":3104,"word":"tenacious","ipa":"/təˈneɪʃəs/","meaning":"집요한, 완강한, 결연한, 끈기 있는","example":"Her tenacious spirit helped her overcome every obstacle.","deck":"vocab"},{"id":3105,"word":"disability","ipa":"/ˌdɪsəˈbɪləti/","meaning":"(신체적, 정신적) 장애","example":"The building was redesigned to accommodate people with a disability.","deck":"vocab"},{"id":3106,"word":"unrest","ipa":"/ʌnˈrɛst/","meaning":"(사회, 정치적인) 불안, 불만","example":"Political unrest spread rapidly across the entire nation.","deck":"vocab"},{"id":3107,"word":"depose","ipa":"/dɪˈpoʊz/","meaning":"물러나게 하다, 퇴위시키다, 폐위시키다","example":"The rebels planned to depose the corrupt king.","deck":"vocab"},{"id":3108,"word":"proportion","ipa":"/prəˈpɔrʃən/","meaning":"(전체의, 전체에서 차지하는) 부분, 비율","example":"A large proportion of the students passed the final exam.","deck":"vocab"},{"id":3109,"word":"hold","ipa":"/hoʊld/","meaning":"(대소변, 신체 분비물, 숨 등을) 참다","example":"He could barely hold his breath underwater for a minute.","deck":"vocab"},{"id":3110,"word":"burn ~ to a crisp","ipa":"","meaning":"새까맣게 태우다, 숯덩이로 만들다","example":"I forgot the toast and burned it to a crisp.","deck":"vocab"},{"id":3111,"word":"acupuncture","ipa":"/ˈækjʊˌpʌŋktʃər/","meaning":"침술","example":"She tried acupuncture to relieve her chronic back pain.","deck":"vocab"},{"id":3112,"word":"autism","ipa":"/ˈɔˌtɪzəm/","meaning":"자폐증","example":"Early therapy can help children diagnosed with autism thrive.","deck":"vocab"},{"id":3113,"word":"trunk","ipa":"/trʌŋk/","meaning":"(코끼리의) 코","example":"The elephant lifted the heavy log easily with its powerful trunk.","deck":"vocab"},{"id":3114,"word":"credential","ipa":"/krɪˈdɛnʃəl/","meaning":"자격, 적격, 적성 (주로 복수형으로 씀)","example":"Her impressive credentials made her the top candidate for the job.","deck":"vocab"},{"id":3115,"word":"cost an arm and a leg","ipa":"","meaning":"큰 돈이 들다","example":"The designer handbag cost an arm and a leg.","deck":"vocab"},{"id":3116,"word":"flip","ipa":"/flɪp/","meaning":"(기계의 버튼 등을) 탁 누르다, 탁 돌리다","example":"Just flip the switch to turn on the ceiling light.","deck":"vocab"},{"id":3117,"word":"lay off","ipa":"","meaning":"그만하다, 그만해! (목적어 없이 주로 누군가를 비난하거나 괴롭히는 것을 멈추라는 뜻)","example":"Lay off him; he's already apologized for his mistake.","deck":"vocab"},{"id":3118,"word":"interrogate","ipa":"/ɪnˈtɛrəˌɡeɪt/","meaning":"신문하다, 추궁하다","example":"The detectives began to interrogate the suspect late that night.","deck":"vocab"},{"id":3119,"word":"sculptor","ipa":"/ˈskʌlptər/","meaning":"조각가","example":"The famous sculptor carved the marble figure over many years.","deck":"vocab"},{"id":3120,"word":"farce","ipa":"/fɑrs/","meaning":"웃음거리","example":"The trial quickly turned into a complete farce.","deck":"vocab"},{"id":3121,"word":"gasp","ipa":"/ɡæsp/","meaning":"숨이 턱 막히다, 숨을 \"헉\" 하고 들이쉬다","example":"The audience gasped when the magician vanished into thin air.","deck":"vocab"},{"id":3122,"word":"predation","ipa":"/prɪˈdeɪʃən/","meaning":"(동물의) 포식","example":"Many small birds die from predation by hawks and owls.","deck":"vocab"},{"id":3123,"word":"stand a chance","ipa":"","meaning":"(~을 할) 가능성이 있다","example":"Our team doesn't stand a chance against the champions.","deck":"vocab"},{"id":3124,"word":"tempted to ~","ipa":"","meaning":"~하고 싶은, ~하도록 유혹당하는, 끌리는","example":"I was tempted to skip work and stay in bed.","deck":"vocab"},{"id":3125,"word":"split the bill","ipa":"","meaning":"(비용을) 각자 부담하다, 더치페이하다","example":"After dinner, we decided to split the bill evenly.","deck":"vocab"},{"id":3126,"word":"misconception","ipa":"/ˌmɪskənˈsɛpʃən/","meaning":"오해","example":"It's a common misconception that bats are completely blind.","deck":"vocab"},{"id":3127,"word":"involvement","ipa":"/ɪnˈvɑlvmənt/","meaning":"관련, 관여, 개입, 연루","example":"His involvement in the scandal ended his political career.","deck":"vocab"},{"id":3128,"word":"speaking of which","ipa":"","meaning":"말이 나왔으니 말인데","example":"Speaking of which, have you finished the report yet?","deck":"vocab"},{"id":3129,"word":"reservation","ipa":"/ˌrɛzərˈveɪʃən/","meaning":"(계획, 생각 등에 대한) 의구심","example":"She had serious reservations about signing the risky contract.","deck":"vocab"},{"id":3130,"word":"demolition","ipa":"/ˌdɛməˈlɪʃən/","meaning":"(건물의) 철거, 파괴","example":"The old factory is scheduled for demolition next month.","deck":"vocab"},{"id":3131,"word":"dismiss","ipa":"/dɪsˈmɪs/","meaning":"떨쳐 버리다, 머릿속에서 지워버리다","example":"Try to dismiss those negative thoughts and focus on today.","deck":"vocab"},{"id":3132,"word":"lucky break","ipa":"/ˈlʌki ˌbreɪk/","meaning":"행운, 운(運)","example":"Landing that audition was a real lucky break for her.","deck":"vocab"},{"id":3133,"word":"aeronautics","ipa":"/ˌɛrəˈnɔtɪks/","meaning":"항공학, 항공술","example":"He studied aeronautics because he dreamed of designing airplanes.","deck":"vocab"},{"id":3134,"word":"forearm","ipa":"/ˈfɔrˌɑrm/","meaning":"팔뚝","example":"He rolled up his sleeve to reveal a tattoo on his forearm.","deck":"vocab"},{"id":3135,"word":"ailment","ipa":"/ˈeɪlmənt/","meaning":"(그렇게 심각하지 않은) 질병","example":"Grandpa complains about some minor ailment almost every week.","deck":"vocab"},{"id":3136,"word":"retaliate","ipa":"/rɪˈtæliˌeɪt/","meaning":"보복하다, 앙갚음하다","example":"The country threatened to retaliate against the sudden trade sanctions.","deck":"vocab"},{"id":3137,"word":"fussy","ipa":"/ˈfʌsi/","meaning":"안달복달하는, 까다로운, 야단스런","example":"My daughter is a fussy eater who refuses most vegetables.","deck":"vocab"},{"id":3138,"word":"revenue","ipa":"/ˈrɛvəˌnu/","meaning":"(회사, 기관, 정부의) 매출, 수입, 세입 (회계에서는 매출액)","example":"The company's annual revenue grew by twenty percent last year.","deck":"vocab"},{"id":3139,"word":"stay alert","ipa":"","meaning":"(~에 대해) 경계를 게을리하지 않다","example":"Drivers must stay alert during long nighttime journeys.","deck":"vocab"},{"id":3140,"word":"to one's surprise","ipa":"","meaning":"놀랍게도","example":"To my surprise, the shy student gave a brilliant speech.","deck":"vocab"},{"id":3141,"word":"miss out","ipa":"","meaning":"(참석하지 못해 유익하거나 즐거운 것을) 놓치다","example":"Don't miss out on the early-bird discount this weekend.","deck":"vocab"},{"id":3142,"word":"pay off","ipa":"","meaning":"성공하다, 성과를 올리다, 결실을 보다","example":"All her hard work finally began to pay off.","deck":"vocab"},{"id":3143,"word":"foreign affairs","ipa":"/ˈfɔrɪn əˌfɛrz/","meaning":"대외 문제, 국제 관계","example":"He was appointed the new minister of foreign affairs.","deck":"vocab"},{"id":3144,"word":"flay","ipa":"/fleɪ/","meaning":"껍질을 벗기다, 가죽을 벗기다","example":"The hunters would flay the animal before preparing the meat.","deck":"vocab"},{"id":3145,"word":"rampant","ipa":"/ˈræmpənt/","meaning":"걷잡을 수 없는, 만연하는, 횡행하는","example":"Corruption was rampant throughout the entire government.","deck":"vocab"},{"id":3146,"word":"perpetually","ipa":"/pərˈpɛtʃuəli/","meaning":"끊임없이, 영구히, 영속적으로","example":"He seems perpetually tired despite sleeping eight hours a night.","deck":"vocab"},{"id":3147,"word":"extravagance","ipa":"/ɪkˈstrævəɡəns/","meaning":"사치, 사치품","example":"A weekend spa trip felt like an unaffordable extravagance.","deck":"vocab"},{"id":3148,"word":"bruise","ipa":"/bruz/","meaning":"멍, 타박상","example":"She noticed a large purple bruise on her shin.","deck":"vocab"},{"id":3149,"word":"avoid ~ like the plague","ipa":"","meaning":"~를 기를 쓰고 피하다","example":"He avoids crowded parties like the plague.","deck":"vocab"},{"id":3150,"word":"content","ipa":"/kənˈtɛnt/","meaning":"(자기가 가진 것에) 만족하는","example":"She felt perfectly content with her simple, quiet life.","deck":"vocab"},{"id":3151,"word":"erupt","ipa":"/ɪˈrʌpt/","meaning":"(화산, 용암 등이) 분출하다","example":"Scientists warned that the volcano could erupt at any moment.","deck":"vocab"},{"id":3152,"word":"go out with ~","ipa":"","meaning":"사귀다, 데이트하다","example":"She's been going out with her classmate for three months.","deck":"vocab"},{"id":3153,"word":"captivity","ipa":"/kæpˈtɪvəti/","meaning":"감금, 억류","example":"The rescued tiger had spent its whole life in captivity.","deck":"vocab"},{"id":3154,"word":"lava","ipa":"/ˈlɑvə/","meaning":"용암","example":"Molten lava flowed down the mountainside toward the village.","deck":"vocab"},{"id":3155,"word":"pedigree","ipa":"/ˈpɛdɪˌɡri/","meaning":"(사람의) 가계, 가문, 혈통","example":"He comes from a long pedigree of respected scholars.","deck":"vocab"},{"id":3156,"word":"dispensable","ipa":"/dɪˈspɛnsəbəl/","meaning":"없어도 되는, 불필요한","example":"In a crisis, luxuries suddenly become entirely dispensable.","deck":"vocab"},{"id":3157,"word":"gag","ipa":"/ɡæɡ/","meaning":"(~을) 토할 것 같다","example":"The awful smell made her gag as she opened the fridge.","deck":"vocab"},{"id":3158,"word":"linger","ipa":"/ˈlɪŋɡər/","meaning":"(예상보다 오래) 남다, 계속되다","example":"The smell of fresh coffee seemed to linger all morning.","deck":"vocab"},{"id":3159,"word":"dashing","ipa":"/ˈdæʃɪŋ/","meaning":"(물건이) 멋진, 근사한","example":"He wore a dashing new suit to the wedding.","deck":"vocab"},{"id":3160,"word":"consensual","ipa":"/kənˈsɛnʃuəl/","meaning":"(성관계 등이) 합의한, 합의에 의한","example":"The law clearly distinguishes consensual relationships from coercion.","deck":"vocab"},{"id":3161,"word":"go on ~ing","ipa":"","meaning":"(뭔가를 멈추지 않고) 계속하다","example":"She went on talking for hours without noticing the time.","deck":"vocab"},{"id":3162,"word":"discard","ipa":"/dɪˈskɑrd/","meaning":"(불필요한 것을) 버리다, 폐기하다 (격식 있는 표현)","example":"Please discard any food that has passed its expiration date.","deck":"vocab"},{"id":3163,"word":"upcycle","ipa":"/ˈʌpˌsaɪkəl/","meaning":"업사이클 하다, 새활용 하다 (버려지는 물건을 완전히 새로운 것으로 재탄생시킴)","example":"She loves to upcycle old jeans into stylish handbags.","deck":"vocab"},{"id":3164,"word":"stable","ipa":"/ˈsteɪbəl/","meaning":"마구간","example":"The farmer led the tired horse back into the stable.","deck":"vocab"},{"id":3165,"word":"national anthem","ipa":"/ˈnæʃənəl ˈænθəm/","meaning":"국가(國歌)","example":"The crowd stood and sang the national anthem before the match.","deck":"vocab"},{"id":3166,"word":"camouflage","ipa":"/ˈkæməˌflɑʒ/","meaning":"위장하다, 감추다","example":"The soldiers used leaves and mud to camouflage their position.","deck":"vocab"},{"id":3167,"word":"tragic","ipa":"/ˈtrædʒɪk/","meaning":"(사건, 상황 등이) 비극적인","example":"The tragic accident claimed the lives of three young people.","deck":"vocab"}];
